// ==========================================
// ★ K 의 방 — S등급 직업 갈림길 · 은신
// 암살자 · 자객 · 그림자술사 · 첩자 · 좀도둑
// 은신: 여기 것들은 귀와 코로 사냥한다 — 안 보이는 것만으로는 모자란다
// ==========================================

// ── 암살자 (assassin) · 무력 ──
kJob('assassin', 'S', [

{ at:'S', t:'어둠 — 내쉬는 숨',
  x:`여기 어둠은 빛이 적은 게 아니다. 빛이 없다.<br><br>
    여기 것들은 눈으로 사냥하지 않는다. 귀로 한다. 들숨은 조용하다. 날숨이 소리다.<br>
    암살자는 남의 숨을 세며 살았다. 문 너머의 숨, 이불 속의 숨. 제 숨을 줄여 본 적은 많지 않다.<br><br>
    앞쪽 어둠에서 무언가가 듣고 있다. 숨 쉬는 것이 지나가기를.`,
  o:[
    { l:'① 날숨을 반 모금씩 나눠 쉬며 지난다.', k:'hide', dc:23, wake:1,
      ok:`내쉬는 숨을 반으로 갈랐다. 반 모금 내쉬고, 걷고, 나머지 반을 내쉰다.<br><br>숨이 소리의 크기 아래로 내려갔다. 앞쪽의 것이 고개를 꺾는 기척이 났다. 듣는 쪽을 바꾸는 것이다. 이쪽이 아니라 뒤쪽으로.<br><br>숨은 쉬는 것이 아니라 쓰는 것이다. 한 모금씩, 아껴서. 그걸 몸이 익혔다.`,
      ng:`반 모금까지는 됐다. 목에 가래가 걸렸다.<br><br>삼키는 소리가 났다. 꼴깍. 작은 소리다. 여기서는 작은 소리가 없다.<br>앞쪽의 것이 한달음에 왔다. 벽에 몸을 붙이고 그것이 이쪽 얼굴 높이의 공기를 오래 핥는 동안 숨을 끊고 서 있었다. 가슴이 터질 뻔했다.`,
      win:{ exp:20, dream:3 }, lose:{ hp:-26, mind:-16 } },
    { l:'② 숨을 끊고 한 번에 건넌다.', k:'steady', dc:24,
      ok:`크게 들이쉬고 숨을 잠갔다. 걸었다. 스물, 서른 걸음.<br><br>어둠을 다 지나 모퉁이를 돌고 나서야 숨을 풀었다. 벽에 입을 대고, 소리를 벽에 먹이면서.<br><br>뒤쪽 어둠은 끝까지 조용했다. 조용한 게 제일 무섭다는 걸 여기서 배운다.`,
      ng:`서른 걸음째에 숨이 터졌다. 입을 막았지만 코로 터졌다.<br><br>어둠 전체가 이쪽으로 돌아앉는 소리가 났다. 여럿이다.<br>남은 길을 뛰었다. 뛰는 소리는 이미 아무래도 좋았다. 모퉁이를 돌 때 등 뒤에서 바람이 닿았다. 손톱 같은 바람이었다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-30, spirit:-18 } }
  ] },

{ at:'S', t:'통로 — 쇠 소리',
  x:`걸을 때마다 몸 어딘가에서 쇳소리가 난다. 버클, 고리, 칼집 끝.<br><br>
    평소에는 들리지도 않는 소리다. 여기서는 종소리다.<br>
    여기 것들은 쇳소리를 배웠다. 쇳소리 나는 것 속에는 살이 들어 있다는 걸.<br><br>
    통로 바닥에 떨어진 장비 조각들이 그 증거다. 버클만 남고 주인은 없다.`,
  o:[
    { l:'① 선 자리에서 쇠란 쇠를 다 싸맨다.', k:'hide', dc:23,
      ok:`천을 찢어 버클마다 감았다. 고리는 뺐다. 칼집 끝은 손바닥으로 쥘 수 있게 고쳐 맸다.<br><br>그 자리에서 제자리뛰기를 했다. 한 번, 두 번. 소리가 없다.<br><br>일행 것도 하나씩 봐 줬다. 다섯 사람이 뛰어도 소리가 없을 때까지. 오래 걸렸다. 여기서는 오래 걸리는 쪽이 빠른 쪽이다.`,
      ng:`다 감았다고 생각했다. 세 걸음에 등 뒤에서 딸랑, 했다.<br><br>배낭 안쪽 깊이 둔 숟가락이었다. 챙긴 기억도 없는 것.<br>어둠 저쪽에서 똑같은 소리가 답했다. 딸랑. 흉내다. 이리 오라는 소리다. 숟가락을 버리고 반대로 갔다. 한참 소름이 안 가셨다.`,
      win:{ exp:18, dream:2 }, lose:{ mind:-15, spirit:-16 } },
    { l:'② 무력을 실어 소리 나는 구간을 한 번에 뛰어넘는다.', k:'evade', dc:24, cost:{ might:28 },
      ok:`무너진 철골 구간이다. 밟으면 울린다. 안 밟으면 된다.<br><br>무력을 다리에 모았다. 세 걸음 달려 몸을 띄웠다. 철골 너머 흙바닥에 어깨부터 말아 떨어졌다.<br><br>소리는 옷이 바닥을 쓰는 소리뿐이었다. 그건 바람 소리와 같다. 바람은 사냥당하지 않는다.`,
      ng:`뛰었다. 발끝이 마지막 철골을 스쳤다.<br><br>저음이 길게 울렸다. 종처럼. 통로 끝까지.<br>구르자마자 일행을 벽감으로 밀어 넣고 입을 막았다. 무언가 철골 위를 왔다 갔다 하는 소리가 오래 났다. 쇠 위에서는 그것도 소리가 났다. 네 발. 손가락이 긴 네 발.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-28, mind:-14 } }
  ] },

{ at:'S', t:'칼 — 묵은 피 냄새',
  x:`바람이 등 뒤에서 앞으로 분다. 앞쪽 어둠이 코를 들었다.<br><br>
    이쪽 냄새가 아니다. 칼 냄새다. 칼집 속에서 묵은 피 냄새가 샌다. 몇 년 치가.<br>
    먹여 살려 준 칼이다. 그 칼이 지금 이쪽 자리를 외치고 있다.<br><br>
    여기 것들한테 묵은 피는 밥 냄새다.`,
  o:[
    { l:'① 칼을 기름천에 감아 재운다.', k:'hide', dc:24, wake:1,
      ok:`칼을 뽑아 기름천에 세 번 감았다. 매듭을 안으로 숨겼다. 등에 비스듬히, 뽑는 데 한 숨 걸리게 맸다.<br><br>냄새가 죽었다. 앞쪽 어둠이 코를 내렸다.<br>한 숨 늦게 뽑는 칼은 반쯤 없는 칼이다. 그런데 빈손이 된 몸이 오히려 가볍다. 손이 칼보다 먼저 있었다는 걸 잊고 살았다.<br><br>칼을 재우고도 암살자인 법. 그걸 여기서 처음 해 봤다.`,
      ng:`감는 사이 바람이 바뀌었다. 풀어 둔 칼이 바람을 정통으로 받았다.<br><br>어둠 속에서 돌 구르는 소리가 났다. 달려오는 소리는 원래 저렇게 들린다.<br>감다 만 칼을 쥐고 일행과 함께 옆 갈래로 꺾었다. 그것이 아까 그 자리의 냄새를 오래 파헤치는 소리를 들으며 걸었다. 손이 떨렸다. 칼 쥔 손이 떨린 건 처음이다.`,
      win:{ exp:20, dream:3 }, lose:{ mind:-16, spirit:-18 } },
    { l:'② 냄새가 어디서 새는지 코로 찾는다.', k:'sense', dc:23,
      ok:`칼을 코앞에 대고 한 뼘씩 맡았다. 날은 깨끗하다. 냄새는 피홈에 살았다. 홈 바닥에 묵은 때.<br><br>돌가루로 홈을 밀고 불에 한 번 그슬렸다. 쇠 냄새만 남았다. 쇠 냄새는 여기 바닥에 깔린 냄새다. 바닥 냄새는 아무도 안 쫓는다.<br><br>칼에 코를 대 본 것도 처음이었다. 제 연장 냄새도 모르고 썼다.`,
      ng:`홈을 밀다 손가락을 벴다. 새 피 한 방울이 날 위에 섰다.<br><br>묵은 피 위에 새 피. 밥 냄새 위에 더운밥 냄새다.<br>천으로 날을 감싸 쥐고 그 자리를 떴다. 뒤에서 무언가 혀로 바닥을 훑는 소리가 따라왔다. 벤 손가락이 밤새 욱신거렸다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-26, mind:-14 } },
    { l:'③ 냄새를 미끼로 건다 — 칼집을 두고 물러나 기다린다.', k:'break', dc:25,
      doom:{ title:'미끼 곁의 것들', what:'미끼를 지키던 턱에 물려 어둠으로 끌려갑니다', dc:19, sec:45,
        text:`칼집을 길 가운데 두고 바람 아래쪽에 엎드렸다. 왔다. 낮고 길다. 칼집에 코를 박는다.<br><br>목덜미를 노리고 들어갔다. 꽂혔다. 깊이. 그런데 그것이 소리를 안 낸다. 소리는 양옆에서 났다.<br>셋이서 온 것이다. 미끼를 무는 놈과 무는 놈을 지키는 놈들.<br><br>어깨와 허리를 양쪽에서 물렸다. 들렸다. 발이 바닥에서 떨어진다. 어둠 안쪽으로 끌려간다. 칼은 죽은 놈에게 꽂힌 채다.`,
        dieText:`길 가운데 칼집만 남았다.<br><br>며칠 뒤에 지나는 사람이 있다면 그렇게 볼 것이다. 버클만 남고 주인은 없는 자리.<br>그 사람도 거기서 걸음을 늦출 것이다. 그게 이 미끼의 쓸모다. 이제 저쪽 것이 됐지만.`,
      },
      ok:`칼집을 두고 바람 아래 엎드렸다. 하나가 왔다. 그리고 멈췄다. 양옆 어둠을 기다린다.<br><br>셋이구나. 엎드린 채 반대로 기었다. 미끼는 버렸다. 미끼가 아깝지 않은 날이 미끼를 놓아도 되는 날이다.<br><br>한참 뒤 뒤에서 칼집 씹히는 소리가 났다. 가죽값으로 목숨을 샀다. 싸게 샀다.`,
      win:{ exp:22, dream:3 } }
  ] },

{ at:'S', t:'쉬는 자리 — 여섯째 숨',
  x:`일행 다섯이 잔다. 암살자가 불침번이다.<br><br>
    숨을 센다. 하나, 둘, 셋, 넷, 다섯. 그리고 여섯.<br>
    여섯째 숨은 천장 쪽에서 난다. 다섯 사람 숨의 박자를 그대로 따라 쉰다. 들키지 않으려고.<br><br>
    숨을 흉내 내서 다가오는 것. 이쪽이 평생 하던 일이다. 저것은 그걸 타고나서 한다.`,
  o:[
    { l:'① 숨 박자를 짚어 그것의 자리를 잰다.', k:'gaze', dc:23,
      ok:`여섯째 숨만 골라 들었다. 흉내는 늘 반 박자 늦다. 흉내 낼 숨을 들어야 하니까.<br><br>반 박자 늦는 숨을 따라 올라갔다. 천장 배관 위. 셋째 사람 바로 위다.<br>칼을 재운 채 그 밑에 가 앉았다. 밤새. 내려오려면 이쪽을 지나야 한다. 그걸 저쪽도 알았다. 새벽에 배관이 한 번 울고 비었다.`,
      ng:`박자를 짚는데 여섯째 숨이 멈췄다. 이쪽이 듣는 걸 들은 것이다.<br><br>숨이 사라지니 자리도 사라졌다. 어디서 내려올지 모른 채 밤을 샜다.<br>새벽에 보니 넷째 사람 머리맡 바닥에 물기가 둥글게 고여 있었다. 입김 자국이다. 아주 가까이서 오래 들여다본.`,
      win:{ exp:18, dream:3 }, lose:{ mind:-18, spirit:-20 } },
    { l:'② 잠든 사람을 숨소리 안 바꾸고 하나씩 깨운다.', k:'hide', dc:24, wake:1,
      ok:`어깨를 흔들면 숨이 바뀐다. 숨이 바뀌면 저것이 안다.<br><br>손바닥을 가슴에 얹고 숨 박자에 맞춰 눌렀다. 자는 몸이 눌림을 먼저 알고 눈을 뜬다. 숨은 그대로 둔 채. 다섯을 그렇게 깨웠다. 입술에 손가락, 천장에 눈짓.<br>다섯이 자는 숨을 쉬면서 하나씩 기어 나갔다. 여섯째 숨은 빈 바닥 위에서 혼자 다섯 사람 몫을 흉내 내고 있었다.<br><br>숨을 안 깨우고 사람을 깨우는 손. 재우는 손만 있던 이쪽에 깨우는 손이 생겼다.`,
      ng:`넷째까지 깨웠다. 다섯째가 눈을 뜨며 숨을 삼켰다. 흡, 하고.<br><br>천장에서 무게가 떨어졌다. 빈 넷째 자리로. 바닥이 울렸다.<br>어둠 속에서 다섯이 엉켜 구르며 문까지 갔다. 무언가 발꿈치를 스쳤다. 신발 뒤축이 한 입 베어 물린 듯 사라져 있었다.`,
      win:{ exp:20, dream:3 }, lose:{ hp:-28, spirit:-16 } }
  ] },

{ at:'S', t:'행렬 — 맨 뒤의 자리',
  x:`여기 것들은 행렬의 맨 뒤를 끊어 간다.<br><br>
    앞은 건드리지 않는다. 소리가 나니까. 맨 뒤는 없어져도 한참 모른다.<br>
    바닥의 긁힌 자국들이 다 같은 방향이다. 뒤에서 앞으로. 끌려간 자국이다.<br><br>
    누가 맨 뒤에 서느냐. 아무도 말을 안 꺼낸다.`,
  o:[
    { l:'① 맨 뒤에 내가 선다 — 뒤로 걸으며.', k:'steady', dc:24,
      ok:`맨 뒤에 섰다. 몸을 돌려 뒤로 걸었다. 어둠에 얼굴을 준 채.<br><br>맨 뒤를 끊는 것들은 등을 끊는다. 얼굴은 안 끊는다. 얼굴에는 눈이 있으니까.<br>어둠 속에서 두 번, 무언가 다가오다 멈췄다. 눈이 마주쳤다는 뜻이다. 보이지 않아도 마주친 건 안다.<br><br>통로를 다 지날 때까지 뒤로 걸었다. 종아리가 터질 것 같았다. 아무도 안 없어졌다.`,
      ng:`뒤로 걷다 발꿈치가 돌에 걸렸다. 넘어졌다.<br><br>넘어진 것은 등을 보인 것이다. 어둠이 확 가까워졌다.<br>구르면서 칼을 그었다. 긴 것이 베였다. 비명 대신 딱딱 이 부딪치는 소리를 내며 물러갔다. 손등에 그것의 침이 닿은 자리가 부어올랐다.`,
      win:{ exp:18, dream:3 }, lose:{ hp:-32, mind:-15 } },
    { l:'② 행렬 밖으로 빠져 맨 뒤의 뒤를 밟는다.', k:'hide', dc:25,
      doom:{ title:'뒤의 뒤', what:'행렬 뒤를 밟던 자리에서 물려 가 어둠으로 끌려갑니다', dc:19, sec:45,
        text:`행렬에서 소리 없이 빠졌다. 맨 뒤 사람의 열 걸음 뒤. 끊으러 오는 놈의 자리를 이쪽이 차지했다.<br><br>차지했다고 생각했다. 그 자리의 원래 주인이 이쪽 열 걸음 뒤에 있었다.<br>목덜미에 입김이 닿는 순간 알았다. 맨 뒤는 자리가 아니다. 어디에 서든 맨 뒤는 생긴다.<br><br>어깨를 물렸다. 끌린다. 행렬은 앞에서 걸어간다. 아무도 한참 모를 것이다. 그게 맨 뒤라는 자리다.`,
        dieText:`행렬이 모퉁이에서 수를 셌다. 하나 모자란다.<br><br>되돌아간 길에는 긁힌 자국만 있었다. 뒤에서 앞으로.<br>맨 뒤를 지키러 간 사람이 맨 뒤가 됐다. 여기서는 흔한 셈이다.`,
      },
      ok:`행렬에서 빠져 열 걸음 뒤를 밟았다. 오래지 않아 왔다. 낮게, 맨 뒤 사람의 발소리에 제 발소리를 포개며.<br><br>그것의 뒤에는 아무것도 없었다. 뒤를 밟히는 줄 모르는 등이었다. 사냥하는 것들은 제 뒤를 안 센다.<br>달려들기 직전의 뒷다리 힘줄을 끊었다. 소리가 나기 전에 목을 마저 끊었다.<br><br>행렬은 아무것도 모르고 걸었다. 그래도 된다. 모르게 지키는 게 이쪽 일이다.`,
      win:{ exp:22, dream:3, item:'짐승 고기' } }
  ] },

{ at:'S', t:'갈림목 — 고인 냄새',
  x:`길이 둘로 갈린다. 바람이 없는 갈림목에 냄새가 고여 있다.<br><br>
    왼쪽은 냄새가 묵었다. 오른쪽은 비리고 날것이다.<br>
    묵은 냄새는 지나간 자리. 날 냄새는 있는 자리. 사냥감들은 그렇게 읽는다.<br><br>
    이쪽은 평생 쫓는 쪽이었다. 쫓기는 쪽의 코를 이제 배운다.`,
  o:[
    { l:'① 혀로 공기를 받아 묵은 쪽을 고른다.', k:'sense', dc:23,
      ok:`입을 벌리고 공기를 혀에 얹었다. 짐승들이 하는 대로.<br><br>왼쪽 공기는 먼지 맛이 섞였다. 오래 비었다는 맛. 오른쪽은 혀가 먼저 오그라들었다. 쇠 맛, 피 맛, 그리고 더운 맛.<br>왼쪽으로 일행을 꺾었다. 오른쪽 어둠 속에서 무언가 씹는 소리가 벽을 타고 흘러왔다. 식사 중이었다. 식사를 방해 안 한 것이 오늘 제일 잘한 일이다.`,
      ng:`혀에 얹었는데 둘 다 같은 맛이 났다.<br><br>고인 냄새는 섞인다. 갈림목은 냄새의 저수지다. 여기서는 코도 혀도 거짓말을 한다.<br>반쯤 찍어 왼쪽으로 갔다. 반은 맞았다. 지나간 자리였다. 지나가면서 흘린 것들이 바닥에 있었다. 밟았다. 물컹했고, 신발에서 밤새 그 냄새가 났다. 그 냄새가 나는 동안은 이쪽이 미끼였다.`,
      win:{ exp:18, dream:2 }, lose:{ mind:-15, spirit:-16 } },
    { l:'② 갈림목의 묵은 냄새를 몸에 바른다.', k:'hide', dc:24,
      ok:`바닥의 먼지와 벽의 곰팡을 손에 묻혀 목과 소매에 발랐다. 겨드랑이, 오금. 더운 냄새가 나는 자리마다.<br><br>사람 냄새가 장소 냄새 밑으로 가라앉았다. 일행에게도 발라 줬다. 다들 얼굴을 찡그렸다. 찡그리면서 발랐다.<br><br>향수를 바르던 손이다. 표적의 집 냄새와 같아지려고. 여기서도 같은 일이다. 이 복도의 냄새가 이쪽 향수다.`,
      ng:`곰팡을 바르는데 손바닥이 따가웠다. 곰팡이 아니었다. 무언가의 알이 슨 자리였다.<br><br>털어 냈지만 늦었다. 손바닥에 두드러기가 줄지어 올라왔다. 가렵다. 긁으면 소리가 난다. 긁지도 못했다.<br>밤새 손을 주무르며 걸었다. 안 긁는 것도 수련이면 오늘 크게 했다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-26, spirit:-15 } }
  ] },

{ at:'S', t:'내려닫이 문 — 쇳덩이',
  x:`지나온 길을 내려닫이 문이 막게 되어 있다. 들어 올려진 채 녹슨 쇳덩이.<br><br>
    고정쇠를 빼면 떨어진다. 떨어지면 닫힌다. 닫히는 소리가 이 구역 전체에 종을 칠 것이다.<br>
    안 닫으면 뒤가 열려 있다. 뒤에서 오는 것들에게.<br><br>
    닫되, 소리 없이. 쇳덩이는 그런 부탁을 안 듣는다.`,
  o:[
    { l:'① 무력으로 받아 천천히 내린다.', k:'steady', dc:24, cost:{ might:30 },
      ok:`고정쇠를 빼는 순간 문 밑에 어깨를 넣었다. 무게가 통째로 얹힌다.<br><br>무력을 등줄기에 세우고 한 뼘씩 내렸다. 무릎, 허리, 어깨 순서로 접으며. 마지막 한 뼘은 손가락으로 받았다.<br>쇠가 바닥에 입 맞추는 소리. 그게 다였다.<br><br>문 너머에서 무언가 바닥 냄새를 맡으며 지나가는 소리가 났다. 문이 있는 줄도 모르고.`,
      ng:`반쯤 내렸을 때 녹슨 경첩이 울었다. 끼이이.<br><br>길고 가는 소리. 어둠이 제일 잘 듣는 소리다.<br>남은 반을 그냥 놓고 뛰었다. 쾅. 종을 쳤다. 문 너머에서 쇠를 긁는 소리가 밤새 났다. 문은 버텼다. 어깨는 문보다 먼저 상했다.`,
      win:{ exp:20, dream:3 }, lose:{ hp:-30, mind:-14 } },
    { l:'② 옷가지로 줄 브레이크를 만들어 내린다.', k:'fix', dc:23,
      ok:`겉옷을 꼬아 줄을 만들고 문 위 고리에 반 바퀴 감았다. 반 바퀴가 브레이크다.<br><br>줄을 조금씩 풀었다. 문이 한 치씩 내려온다. 천이 타는 냄새가 났다. 소리는 안 났다.<br><br>닫힌 문에 등을 대고 잠깐 앉았다. 겉옷은 못 쓰게 됐다. 겉옷값에 이만한 값이면 남는 장사다.`,
      ng:`반쯤 내려왔을 때 천이 끊어졌다.<br><br>쾅. 벽이 울고 천장에서 먼지가 쏟아졌다.<br>먼지 속에서 일행을 끌고 뛰었다. 등 뒤 문을 무언가 쿵, 쿵, 들이받는 소리가 따라왔다. 문은 닫혔다. 닫긴 닫았다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-27, mind:-15 } },
    { l:'③ 닫지 않는다 — 닫힌 것처럼 꾸민다.', k:'hide', dc:24, wake:1,
      ok:`닫힌 문은 말을 한다. 사냥감이 이 안에 있다고. 여기 것들도 그 말을 읽는 눈치다.<br><br>문은 열어 둔 채 문 앞 바닥의 발자국만 지웠다. 먼지를 긁어모아 문지방에 고르게 뿌렸다. 오래 아무도 안 지난 문처럼.<br>뒤따라온 것이 문 앞에서 멈추는 소리가 났다. 냄새는 나는데 자국이 없다. 그것이 한참 서성이다 돌아갔다.<br><br>흔적을 지우는 건 늘 하던 일이다. 흔적을 꾸미는 건 다른 일이다. 지나가지 않은 것처럼 지나가는 법을 하나 얻었다.`,
      ng:`먼지를 뿌리는데 재채기가 터지려 했다. 코를 쥐어 삼켰다.<br><br>삼킨 소리가 콧속에서 삑, 울렸다. 작다. 작아도 소리다.<br>문 너머 어둠이 우뚝 섰다. 긴 들숨 소리. 냄새를 통째로 마시는 소리다. 일행을 밀어 넣고 그 자리를 떴다. 밤새 콧잔등이 얼얼했다.`,
      win:{ exp:20, dream:3 }, lose:{ mind:-16, spirit:-17 } }
  ] },

{ at:'S', t:'사냥꾼 사냥',
  x:`한 시간째 따라붙는 놈이 있다. 서두르지 않는다. 일행이 지치기를 기다린다.<br><br>
    간격을 안 좁힌다. 소리를 안 낸다. 급소가 아니면 안 문다.<br>
    이쪽이 평생 해 온 일을 네 발로 하는 놈이다.<br><br>
    동업자는 동업자가 잡아야 한다. 암살자는 걸음을 늦춰 행렬에서 녹아 나왔다.`,
  o:[
    { l:'① 놈의 뒤로 돌아 들어간다.', k:'hide', dc:25,
      doom:{ title:'동업자', what:'목덜미를 물려 사냥길 밖으로 끌려갑니다', dc:20, sec:40,
        text:`크게 원을 그려 놈의 바람 아래로 들어갔다. 보였다. 낮은 등, 접힌 뒷다리. 일행만 보는 등이다.<br><br>마지막 다섯 걸음을 줄였다. 넷, 셋. 놈의 꼬리가 바닥을 한 번 쓸었다.<br>그건 신호였다. 이쪽이 아는 수신호 같은. 놈은 혼자 사냥하지 않았다.<br><br>목덜미에 위에서 무게가 떨어졌다. 둘째 놈. 처음부터 나무 위에서 이쪽을 따라온 놈이다. 물려서 끌려간다. 사냥길 밖으로. 동업자들의 저녁 자리로.`,
        dieText:`일행을 따라붙던 기척이 사라졌다.<br><br>일행은 한숨 돌렸을 것이다. 따돌렸다고.<br>따라붙던 것은 저녁거리가 생겨서 돌아갔을 뿐이다. 수를 세는 건 늘 한 박자 늦다.`,
      },
      ok:`크게 돌아 바람 아래로 들어가다 멈췄다. 놈의 꼬리가 바닥을 쓸었다. 한 번, 간격을 두고 또 한 번.<br><br>신호다. 받는 놈이 있다는 뜻이다. 고개를 안 들고 눈만 올렸다. 나무 위, 둘째 놈.<br>위엣놈부터 끝냈다. 떨어지는 몸을 소리 안 나게 받아 내리고, 신호가 끊겨 돌아보는 아래 놈의 목을 마저 그었다.<br><br>동업자 둘. 연장은 이쪽이 좋았다. 그 차이뿐이다.`,
      win:{ exp:24, dream:3, item:'짐승 고기' } },
    { l:'② 치지 않는다 — 일행과 놈 사이에 선다.', k:'bond', dc:23,
      ok:`일행에게 손짓을 보냈다. 속도 유지. 뒤돌아보기 금지.<br><br>이쪽은 일행과 놈 사이의 어둠에 섰다. 놈이 간격을 좁히면 이쪽이 반 걸음 나선다. 물러나면 이쪽도 물러난다.<br>사이에 무언가 있다는 것만 알게 했다. 그게 뭔지 모르게. 모르는 것 너머의 밥은 비싸다. 놈은 한 시간을 더 재다가 떨어져 나갔다.`,
      ng:`사이에 서 있는데 놈이 멈췄다. 그리고 이쪽을 향해 앉았다.<br><br>기다리겠다는 자세다. 이쪽이 지칠 때까지. 사이에 선 사람부터.<br>버티기를 바꿔 일행 속으로 돌아갔다. 놈은 새벽까지 따라오다 사라졌다. 눈을 못 붙였다. 눈꺼풀이 쇳덩이 같았다.`,
      win:{ exp:18, dream:2 }, lose:{ mind:-17, spirit:-18 } }
  ] },

{ at:'S', t:'빈 바닥 — 쓸고 가는 귀',
  x:`가릴 것 하나 없는 넓은 바닥이다. 건너야 한다.<br><br>
    어둠 속에서 무언가가 주기적으로 바닥을 쓸고 지나간다. 귀를 바닥에 대고 끄는 것이다.<br>
    바닥은 그놈의 고막이다. 그 위를 걸어야 한다.<br><br>
    쓸고, 아홉을 세고, 다시 쓴다. 아홉이 이쪽 몫이다.`,
  o:[
    { l:'① 아홉 안에 갈 수 있는 만큼만 간다.', k:'hide', dc:24, wake:1,
      ok:`쓸기가 지나가자 걸었다. 여섯 걸음. 멈춰 몸을 눕혔다. 쓸기가 돌아온다. 바닥이 등 밑에서 미세하게 운다.<br><br>몸이 바닥 소리에 섞이려면 서 있으면 안 된다. 눕는다. 바닥의 일부가 된다. 쓸기가 지나가면 또 여섯 걸음.<br>다섯 번 만에 건넜다. 일행도 같은 박자로 하나씩 건네 받았다.<br><br>남의 박자 틈에 제 걸음을 끼워 넣는 것. 그 틈이 아홉이든 셋이든, 틈은 틈이다. 틈을 세는 버릇이 뼈에 앉았다.`,
      ng:`여섯 걸음째에 발밑에서 돌 부스러기가 굴렀다.<br><br>쓸기가 박자를 깨고 돌아왔다. 빠르게. 엎드린 등 위로 바람이 지나갔다. 비린 바람.<br>그것이 부스러기 자리를 오래 더듬는 동안 숨을 끊고 엎드려 있었다. 바닥이 이렇게 차가운 줄 처음 알았다.`,
      win:{ exp:20, dream:3 }, lose:{ hp:-26, spirit:-16 } },
    { l:'② 먼 데 돌을 던지고 한 번에 가로지른다.', k:'evade', dc:25,
      ok:`돌을 반대편 구석으로 던졌다. 딱. 쓸기가 그쪽으로 몰렸다.<br><br>그사이 일행과 함께 낮게 달렸다. 발바닥 전체로, 굴리듯이.<br>건너편에 닿고 돌아보니 쓸기가 돌 떨어진 자리를 파고 있었다. 돌 하나에 바닥이 한 뼘 패었다. 저게 사람 자리였으면, 하는 생각은 하지 않기로 했다.`,
      ng:`돌이 생각보다 가까이 떨어졌다. 쓸기가 돌아오는 길에 일행 소리를 잡았다.<br><br>흩어져 뛰었다. 바닥 전체가 울렸다. 맨 뒤 사람의 배낭이 찢겨 나갔다. 등가죽 대신.<br>건너긴 건넜다. 배낭에 있던 사흘 치 먹을 것이 바닥에 남았다. 그건 못 주우러 간다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-30, mind:-15 } }
  ] },

{ at:'S', t:'제 피 — 한 방울',
  x:`팔뚝의 상처가 벌어졌다. 피가 한 방울, 바닥에 떨어졌다.<br><br>
    여기서 피 한 방울은 길의 시작점이다. 여기 것들은 핏길을 거슬러 읽는다. 끝에는 피 주인이 있다.<br>
    닦는다고 지워지는 냄새가 아니다.<br><br>
    암살자는 남의 피로 길을 만들어 봤다. 제 피는 처음이다.`,
  o:[
    { l:'① 떨어진 자리를 태우고 상처를 봉한다.', k:'fix', dc:23,
      ok:`핏방울 자리에 불씨를 얹었다. 탄내가 피내를 덮었다. 탄내는 여기 흔한 냄새다.<br><br>상처는 천을 대기 전에 송진을 녹여 발랐다. 피 냄새는 마개를 해야지 뚜껑을 덮으면 샌다.<br>피 묻은 천은 버리지 않고 기름천에 싸서 품에 넣었다. 버린 천은 이쪽 명함이다. 명함은 함부로 돌리는 게 아니다.`,
      ng:`불씨가 바닥의 기름때를 타고 번졌다. 확.<br><br>빛이다. 여기서 빛은 소리보다 멀리 간다.<br>발로 비벼 껐다. 어둠 저쪽에서 여럿이 일제히 방향을 트는 기척이 났다. 봉하다 만 상처를 쥐고 뛰었다. 피는 뛰면 더 난다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-28, mind:-14 } },
    { l:'② 피로 거짓 길을 긋고 봉한다.', k:'hide', dc:24,
      ok:`어차피 난 피다. 쓰기로 했다.<br><br>천에 피를 받아 일행이 안 갈 쪽으로 열 걸음마다 한 점씩 찍었다. 점점 진하게. 다친 것이 숨어드는 모양으로. 막다른 구석에 천을 통째로 두고 왔다.<br>그리고 상처를 봉했다. 길은 끊겼다. 끊긴 길의 끝은 저 구석이다.<br><br>밤에 그 구석에서 여럿이 다투는 소리가 났다. 빈 천 한 장을 두고. 오래 다퉜다.`,
      ng:`점을 찍으며 물러나는데 발소리가 왔다. 너무 빨리.<br><br>거짓 길을 그릴 시간이 없었다. 길은 반쯤 그리다 만 채 진짜 이쪽을 가리키고 있었다.<br>봉한 상처 위로 식은땀이 흘렀다. 땀도 냄새다. 밤새 세 번 자리를 옮겼다. 세 번 다 따라왔다. 새벽에야 끊었다.`,
      win:{ exp:20, dream:3 }, lose:{ hp:-26, spirit:-18 } }
  ] },

{ at:'S', t:'쉬는 자리 — 열린 손',
  x:`교대하고 앉았다. 칼을 내려놓으려는데 손이 안 놓는다.<br><br>
    들어온 뒤로 한 번도 안 놓은 손이다. 손가락이 자루에 눌어붙었다.<br>
    쥔 손은 소리를 낸다. 긴장한 몸은 숨이 짧다. 짧은 숨은 들린다.<br><br>
    여기서는 손에 든 칼보다 열린 손이 조용하다.`,
  o:[
    { l:'① 칼을 손 닿는 바닥에 눕히고 빈손으로 쉰다.', k:'steady', dc:23, wake:1,
      ok:`손가락을 하나씩 뗐다. 칼을 무릎 옆 바닥에, 자루가 손에 오는 방향으로 눕혔다.<br><br>빈손이 되자 어깨가 내려갔다. 어깨가 내려가자 숨이 길어졌다. 긴 숨은 어둠에 섞인다.<br>칼은 바닥에 있다. 반 뼘. 그 반 뼘이 멀게 느껴지지 않는 날이 올 줄 몰랐다.<br><br>쥐지 않고도 쥔 것과 같은 손. 쉬는 것이 허술해지는 게 아니라는 걸 손이 배웠다.`,
      ng:`손가락을 떼다 쥐가 났다. 손이 갈고리처럼 굳었다.<br><br>신음을 삼키느라 이를 물었다. 이 가는 소리가 났다. 작게.<br>어둠 어디선가 같은 소리가 답했다. 드르륵. 흉내인지 이빨인지 모른다. 모르는 채로 밤을 샜다. 손은 새벽에야 풀렸다.`,
      win:{ exp:18, dream:3, mind:6 }, lose:{ mind:-16, spirit:-15 } },
    { l:'② 굳은 손을 더운 물수건으로 풀어 준다.', k:'heal', dc:23,
      ok:`물을 조금 데워 천에 적셨다. 김이 안 나게, 미지근하게.<br><br>손등부터 손가락 사이까지 감쌌다. 굳은 심줄이 하나씩 풀린다.<br>풀린 손으로 일행 것도 봐 줬다. 칼 쥐는 직업이 둘 더 있었다. 다들 손이 갈고리였다. 말없이 손만 내밀었다.`,
      ng:`물 데우는 불씨를 너무 키웠다. 빛이 벽에 어른거렸다.<br><br>얼른 껐다. 어른거린 건 몇 숨 안 된다.<br>그 몇 숨 사이에 벽 너머에서 돌아앉는 소리가 났다. 밤새 벽 너머가 조용하지 않았다. 손은 풀렸는데 잠을 설쳤다.`,
      win:{ exp:16, dream:2, hp:7 }, lose:{ mind:-14, spirit:-15 } }
  ] },

{ at:'S1', t:'표본실 — 유리 가루',
  x:`표본실 바닥에 깨진 병 유리가 깔렸다. 눈처럼.<br><br>
    밟으면 운다. 자그락. 선반 사이 어둠에서 창백한 것들이 그 소리를 기다린다.<br>
    병들은 거의 다 깨졌다. 안에 있던 것들이 지금 선반 사이에 있다는 뜻이다.<br><br>
    유리 위를 소리 없이. 눈 위를 걷던 겨울 일이 생각났다.`,
  o:[
    { l:'① 발날로 서서 유리를 가르며 걷는다.', k:'hide', dc:24, wake:1,
      ok:`발바닥으로 밟으면 유리가 겹으로 운다. 발날을 세워 내리면 유리가 옆으로 밀리며 눕는다.<br><br>한 걸음에 세 호흡. 발날로 길을 갈라 다진 자리를 뒤에 오는 일행이 밟았다.<br>선반 사이의 창백한 것이 고개를 두 번 틀었다. 소리를 찾는 고개다. 못 찾았다.<br><br>눈길, 자갈길, 마른 잎. 바닥마다 밟는 법이 따로 있었다. 유리의 법이 오늘 더해졌다.`,
      ng:`발날로 열 걸음을 갔다. 열한 걸음째 유리 밑에 병뚜껑이 숨어 있었다.<br><br>쨍. 유리가 아니라 쇠였다.<br>선반 사이에서 창백한 것이 미끄러져 나왔다. 관절이 사람과 반대로 접히는 팔. 일행이 던진 돌이 반대쪽 유리를 울려 줄 때까지 숨도 못 쉬고 서 있었다. 발날이 후들거렸다.`,
      win:{ exp:20, dream:3 }, lose:{ hp:-26, mind:-16 } },
    { l:'② 겉옷을 깔아 길을 만든다.', k:'fix', dc:23,
      ok:`겉옷 두 벌을 유리 위에 폈다. 밟고, 지나면 걷어 앞에 다시 편다.<br><br>천이 유리를 눌러 재웠다. 다섯이 다 건넜다.<br>겉옷은 유리 가루투성이가 됐다. 입을 수는 없다. 둘둘 말아 선반 밑에 밀어 넣었다. 다음 사람은 길이 있는 줄도 모를 것이다. 그래야 길이다.`,
      ng:`천을 걷다가 유리 몇 조각이 천에 끌려 울렸다. 자그락.<br><br>선반 위에서 긴 것이 넘겨다봤다. 창백하고, 눈 자리가 매끈하다. 눈이 없는 얼굴이 정확히 이쪽을 향했다.<br>천을 버리고 물러났다. 마지막 두 걸음은 맨 유리를 밟았다. 발바닥이 아니라 심장이 밟히는 소리가 났다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-28, mind:-15 } }
  ] },

{ at:'S1', t:'통풍관 — 주인 있는 길',
  x:`벽 아래 통풍관 뚜껑이 열려 있다. 사람 하나 길 만한 관.<br><br>
    좁고 어두운 길은 늘 이쪽 길이었다. 남들이 못 가는 길로 가는 게 이 장사다.<br>
    관 입구 쇠에 긁힌 자국이 있다. 안쪽으로도, 바깥쪽으로도. 드나든 자국이다.<br><br>
    여기서는 좁고 어두운 길마다 먼저 든 주인이 있다.`,
  o:[
    { l:'① 그래도 관으로 간다 — 배로 기어서.', k:'hide', dc:25,
      doom:{ title:'관 속의 주인', what:'발목을 잡혀 통풍관 안쪽으로 끌려 들어갑니다', dc:19, sec:40,
        text:`배를 깔고 들어갔다. 팔꿈치로 반 뼘씩. 숨은 관 바닥에 깔아 쉬었다.<br><br>갈림 관에서 비린 바람이 훅 끼쳤다. 앞이 아니다. 뒤다. 주인은 집에 들어온 것을 입구에서부터 따라온다.<br>발목에 손이 감겼다. 손가락이 너무 길고 너무 많다.<br><br>끌린다. 안쪽으로. 관이 꺾이는 데마다 어깨가 쇠에 긁힌다. 긁힌 자국이 왜 안팎으로 나 있는지 이제 안다. 끌려 들어간 것들이 바깥쪽으로 긁은 것이다.`,
        dieText:`통풍관 입구에 새 긁힌 자국이 늘었다.<br><br>바깥쪽으로, 깊게, 열 손가락.<br>다음 지나는 팀이 있다면 그 자국을 읽고 관을 피할 것이다. 그 정도 쓸모는 남겼다.`,
      },
      ok:`배를 깔다 멈췄다. 관 바닥 먼지에 끌린 자국이 있다. 바깥쪽으로. 손가락 자국이다. 사람 손가락.<br><br>들어간 사람이 끌려 나온 길이라는 뜻이다. 이 관은 길이 아니다. 목구멍이다.<br>소리 없이 물러나 뚜껑을 반쯤 닫아 뒀다. 반쯤. 주인이 눈치 못 채게.<br><br>좁은 길이 다 이쪽 길은 아니다. 여기서는 길도 가려 받아야 한다.`,
      win:{ exp:22, dream:3 } },
    { l:'② 관에 귀를 대고 주인의 숨을 먼저 센다.', k:'sense', dc:23,
      ok:`관 입구 쇠에 귀를 댔다. 쇠는 먼 숨도 나른다.<br><br>났다. 길고 느린 숨. 자는 숨이다. 거리는 멀다. 그리고 숨이 둘이다. 한 관에 둘.<br>관은 버리고 복도로 갔다. 복도가 세 배 멀다. 세 배 멀고 열 배 낫다. 지나며 관 뚜껑마다 돌을 괴어 표시해 뒀다. 일행 모두 읽을 수 있는 표시로.`,
      ng:`귀를 대는데 관 속 숨이 멎었다.<br><br>이쪽 귀가 쇠에 닿는 소리를 저쪽이 들은 것이다. 쇠는 양쪽으로 나른다.<br>관에서 귀를 떼고 뒷걸음질했다. 관 안쪽에서 쇠 긁는 소리가 빠르게 다가오다 입구에서 멎었다. 긴 손가락 하나가 뚜껑 틈으로 나와 공기를 재고 들어갔다. 그동안 다섯이 벽에 붙어 돌이 됐다.`,
      win:{ exp:18, dream:2 }, lose:{ mind:-18, spirit:-16 } }
  ] },

{ at:'S1', t:'숙주 — 아직 걷는 사람',
  x:`복도를 연구복 입은 사람이 걷는다. 같은 자리를 돌면서.<br><br>
    가슴이 숨과 다른 박자로 들썩인다. 안에 다른 것이 들었다. 깃든 것이다.<br>
    저 가슴을 칼로 열면 안 된다. 깃든 것의 피는 산이다. 쇠도 녹인다.<br><br>
    암살자는 아프지 않게 보내는 법을 안다. 그게 필요한 사람이 저기 걷고 있다.`,
  o:[
    { l:'① 무력을 실어 목만, 한 번에.', k:'break', dc:25, cost:{ might:35 },
      ok:`등 뒤에서 들어갔다. 가슴은 안 건드린다. 목. 한 번.<br><br>무력을 팔 하나에 다 모았다. 베는 순간 다른 손으로 몸을 받았다. 소리 없이 바닥에 눕혔다.<br>가슴 속 것이 당황해서 두드리는 게 손바닥에 느껴졌다. 집이 멈춘 것이다. 두드림은 곧 잦아들었다. 깃든 것은 죽은 집에서는 못 산다.<br><br>연구복 주머니에 가족 사진이 있었다. 엎어서 가슴에 얹어 주고 일어섰다.`,
      ng:`목을 쳤다. 깊었지만 한 번에 끝나지 않았다.<br><br>쓰러지는 몸의 가슴에서 깃든 것이 비명을 질렀다. 사람 목이 아니라 가슴이 지르는 비명.<br>복도 양끝에서 응답이 왔다. 몸을 마저 눕혀 드리고 뛰었다. 손목에 산 핏방울이 하나 튀어 장갑을 뚫었다. 지금도 거기만 탄다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-34, spirit:-16 } },
    { l:'② 도는 길의 빈 호를 골라 스쳐 지난다.', k:'hide', dc:24,
      ok:`도는 길에는 반드시 등을 보이는 호가 있다. 세 바퀴를 세어 그 호를 쟀다.<br><br>그가 모퉁이 쪽을 보는 여덟 걸음 동안 반대 호를 지났다. 깃든 것이 더운 것을 느낀다는 말이 있어 벽에 몸을 비껴 붙였다.<br>지나치며 그의 얼굴을 봤다. 입이 작게 움직이고 있었다. 집에 가야지, 집에 가야지. 걸음이 한동안 무거웠다.`,
      ng:`호를 재는데 그가 갑자기 돌기를 멈췄다.<br><br>가슴이 이쪽을 향해 부풀었다. 깃든 것이 더운 것을 찾은 것이다.<br>그가 걸어온다. 눈은 감긴 채. 가슴이 앞장서서. 벽을 타고 비켜나 전력으로 구간을 벗어났다. 등 뒤에서 그가 다시 돌기 시작하는 소리가 났다. 집에 가야지, 하면서.`,
      win:{ exp:18, dream:2 }, lose:{ mind:-19, spirit:-20 } },
    { l:'③ 멀리서 도는 길 전체를 읽는다.', k:'gaze', dc:23,
      ok:`선반 그늘에서 세 바퀴를 지켜봤다. 그는 돌다가 꼭 한 자리에서 멈칫한다. 잠긴 문 앞.<br><br>문에는 긁힌 자국. 그의 손톱 자국이다. 안 열리는 문을 깃든 것이 자꾸 열려고 한다. 저 문 안쪽에 깃든 것이 가고 싶은 데가 있다.<br>그 문과 반대로 길을 잡았다. 깃든 것이 모이는 쪽을 등지는 길로. 일행에게 문의 위치를 손짓으로 박아 줬다.`,
      ng:`지켜보는데 그가 걸음을 늦췄다. 그리고 이쪽 그늘을 향해 섰다.<br><br>눈 감긴 얼굴이 웃었다. 사람 웃음이 아니다. 가슴이 웃을 때 얼굴이 따라 웃는 웃음.<br>그늘에서 그늘로 세 번 옮기고서야 그가 다시 돌기 시작했다. 그 웃음이 눈에 박혀 안 빠진다.`,
      win:{ exp:18, dream:3, spirit:6 }, lose:{ mind:-17, spirit:-18 } }
  ] },

{ at:'S1', t:'산 — 베는 각',
  x:`작은 것 하나가 선반 뒤에서 달려들었다. 베었다. 반사였다.<br><br>
    핏방울이 칼날 위에서 끓었다. 날이 반 치 녹아내렸다. 바닥에 떨어진 피는 돌을 파고들었다.<br>
    여기 것들의 피는 산이다. 벤다는 건 그 비를 뒤집어쓴다는 뜻이다.<br><br>
    못 베는 칼잡이가 된 건가. 아니면 다르게 베어야 하나.`,
  o:[
    { l:'① 흘리는 각을 찾는다 — 얕게, 흐르는 결대로.', k:'break', dc:24, wake:1,
      ok:`죽은 것을 뒤집어 놓고 연구했다. 피가 솟는 각, 흐르는 결.<br><br>세로로 깊게 찌르면 솟는다. 가로로 얕게, 힘줄만 끊으면 피가 제 몸을 타고 바닥으로 흐른다. 이쪽으로는 안 온다.<br>베고, 베인 것이 제 피 쪽으로 쓰러지게 마지막에 반 걸음 비켜 준다. 춤 같은 걸음이다.<br><br>깊이 찌르는 것만 알던 칼이 얕게 끊는 법을 배웠다. 죽이는 데 깊이가 꼭 필요한 건 아니었다.`,
      ng:`각을 시험할 둘째 놈이 왔을 때 손이 옛 버릇대로 깊이 들어갔다.<br><br>피가 솟았다. 몸을 틀었지만 소매에 받았다. 천이 연기를 내며 녹았다.<br>소매를 통째로 뜯어 버렸다. 팔뚝에 지렁이 같은 화상이 남았다. 버릇은 머리보다 손에 오래 산다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-30, mind:-14 } },
    { l:'② 아예 안 벤다 — 몸을 틀어 선반에 받는다.', k:'evade', dc:24,
      ok:`달려드는 놈의 궤도에서 반 보 비켜서며 어깨로 선반을 밀었다.<br><br>놈이 선반 모서리에 제 속도로 받혔다. 떨어진 유리병 하나가 놈 위에서 깨졌다. 병 속 약품이 제 몫을 했다.<br>이쪽 칼은 집에서 안 나왔다. 피도 한 방울 안 튀었다. 선반이 벤 셈 치기로 했다.`,
      ng:`비켜서는데 바닥 유리가 미끄러웠다. 반 보가 한 보가 됐다.<br><br>놈의 발톱이 허벅지를 긁고 지나갔다. 발톱에도 그 피가 발라져 있었는지 긁힌 자리가 탄다.<br>선반에 받힌 놈이 비틀대는 사이 물을 부어 씻어 냈다. 물이 아까웠다. 살이 더 아까웠다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-32, mind:-14 } }
  ] },

{ at:'S1', t:'기밀문 — 숨 쉬는 문',
  x:`기밀문이 주기적으로 혼자 돈다. 치익 — 바람 빠지는 소리, 그리고 쿵.<br><br>
    치익 하는 동안은 어떤 소리도 묻힌다. 쿵은 구역 전체를 부른다.<br>
    문 너머가 가야 할 쪽이다. 문이 열리는 짧은 동안에 다섯이 지나야 한다.<br><br>
    문은 숨을 쉰다. 그 숨에 맞춰야 한다.`,
  o:[
    { l:'① 치익에만 움직이고 쿵에는 돌이 된다.', k:'hide', dc:24,
      ok:`치익. 둘이 문틈을 지났다. 쿵. 전원 정지. 선 모양 그대로.<br><br>어둠 속에서 뭔가 쿵 소리에 다가왔다가, 움직이는 게 없자 돌아갔다. 치익. 둘 더. 쿵. 정지.<br>마지막 치익에 이쪽이 지났다. 문의 숨이 이쪽 편이었다. 문에게 고마워한 건 처음이다.`,
      ng:`세 번째 치익이 짧았다. 문도 늙었다.<br><br>마지막 사람이 문틈에 끼었다. 배낭이 걸렸다. 쿵이 오기 전에 배낭 끈을 끊고 사람만 당겨 뺐다.<br>쿵. 문이 배낭을 물고 닫혔다. 어둠이 그 소리에 모여드는 기척을 문 너머로 들으며 걸었다. 배낭은 제물이 됐다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-26, mind:-15 } },
    { l:'② 무력으로 문을 반쯤 잡아 긴 치익을 만든다.', k:'steady', dc:25, cost:{ might:32 },
      ok:`도는 문짝 틈에 어깨를 넣고 무력으로 버텼다. 문이 닫히다 멈췄다. 치이이익 — 바람이 길게 샌다.<br><br>그 긴 숨 안에 다섯이 다 지났다. 바람 소리가 모든 발소리를 먹었다.<br>마지막에 어깨를 빼며 몸을 굴렸다. 쿵. 문이 닫혔다. 어깨에 문짝 자국이 시퍼렇게 남았다. 시퍼런 것으로 끝나면 싼 값이다.`,
      ng:`버티는데 문이 생각보다 셌다. 어깨가 밀린다.<br><br>반쯤 잡은 문이 덜컹, 덜컹, 끊어 울었다. 고장 난 소리. 고장 난 소리는 쿵보다 멀리 간다.<br>손을 놓고 다 같이 틈으로 쏟아져 들어갔다. 문이 등 뒤에서 쿵 닫혔다. 어깨가 한쪽 내려앉은 채로 한참 걸었다.`,
      win:{ exp:20, dream:3 }, lose:{ hp:-33, mind:-14 } }
  ] },

{ at:'S1', t:'알 방',
  x:`옆 홀이 덥고 축축하다. 바닥에 가죽 주머니 같은 것들이 줄지어 서 있다.<br><br>
    주머니가 숨을 쉰다. 천천히 부풀었다 가라앉는다. 수십 개가 같은 박자로.<br>
    맞은편 문까지 주머니 사이로 좁은 길이 나 있다. 누가 다니는 길이라는 뜻이다.<br><br>
    더운 것이 지나가면 주머니들이 그쪽으로 기운다고, 죽은 연구자의 벽 낙서가 말해 줬다.`,
  o:[
    { l:'① 주머니 사이 길을 숨 죽여 지난다.', k:'hide', dc:25,
      doom:{ title:'알 방', what:'알 방 안쪽, 벽의 둥지로 끌려가 붙여집니다', dc:20, sec:38,
        text:`길 가운데서 양옆 주머니가 이쪽으로 기울었다. 체온이다. 줄일 만큼 줄였는데도.<br><br>제일 가까운 주머니 꼭지가 꽃처럼 열렸다. 넷으로.<br>안에서 긴 것이 튀었다. 빠르다. 눈으로 못 쫓는 빠르기.<br><br>목을 감겼다. 숨이 막힌다. 바닥에 끌린다. 벽 쪽으로. 벽에는 끈끈한 것으로 사람 모양 자리가 여럿 패어 있다. 빈자리가 하나 이쪽 크기다.`,
        dieText:`벽의 자리가 하나 찼다.<br><br>알 방의 주머니들이 다시 같은 박자로 숨을 쉰다. 하나가 새로 늘었다.<br>제일 새것인 주머니의 박자가 어딘지 사람 숨 같다.`,
      },
      ok:`길에 들기 전에 숨으로 몸을 식혔다. 긴 날숨 열 번. 손끝이 차가워질 때까지.<br><br>식은 몸으로 지나는 동안 주머니들은 숨만 쉬었다. 기울지 않았다.<br>맞은편 문에서 돌아보니 길 복판에 쥐만 한 것이 뛰어들고 있었다. 주머니들이 일제히 그쪽으로 기울고, 하나가 열렸다. 그 뒤는 안 봤다.<br><br>더운 것이 못 가는 길을 식은 것은 간다. 몸을 식히는 법이 하나 생겼다.`,
      win:{ exp:24, dream:3 } },
    { l:'② 돌아간다 — 추운 바깥 복도로.', k:'steady', dc:24,
      ok:`알 방은 알 방 주인 것이다. 길이 아무리 질러가도.<br><br>바깥 복도로 돌았다. 깨진 외벽으로 찬 바람이 드는 복도. 세 배 길고, 손끝이 곱았다.<br>복도 끝에서 알 방 반대쪽 출구와 만났다. 덜덜 떨면서도 다섯이 다 멀쩡했다. 멀쩡한 게 남는 장사다.`,
      ng:`찬 복도 중간에 외벽 구멍으로 바람이 드나드는 자리가 있었다. 바람에 섞여 이쪽 냄새가 안으로 들었다.<br><br>알 방 쪽 벽 너머에서 무언가 벽을 따라 같이 걷는 소리가 났다. 복도 끝까지.<br>끝에서 소리가 멎었다. 벽 하나를 사이에 두고 한참 서로 서 있었다. 먼저 움직인 건 이쪽이 아니다. 그쪽이 흥미를 잃었다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-27, spirit:-16 } }
  ] },

{ at:'S1', t:'배양 병 — 마주 본 눈',
  x:`안 깨진 병이 하나 남아 있다. 사람 키만 한 병. 안에 그것이 떠 있다.<br><br>
    죽은 줄 알았다. 지나가는데 그것의 손가락이 유리를 톡, 톡, 두드렸다.<br>
    자물쇠를 재 보는 손놀림이다. 이쪽이 문 앞에서 하는 것과 같은.<br>
    그것이 이쪽을 본다. 이쪽이 그것을 보듯이. 재고 있다.`,
  o:[
    { l:'① 재미없는 몸이 된다 — 사냥꾼의 걸음을 버린다.', k:'hide', dc:23,
      ok:`사냥하는 것들은 사냥꾼을 먼저 외운다. 위험한 순서대로.<br><br>걸음에서 날을 뺐다. 발끝을 열고, 무게중심을 올리고, 시선을 흘렸다. 짐꾼의 걸음. 아무것도 아닌 몸.<br>병 속 손가락이 두드리기를 멈췄다. 시선이 이쪽을 지나 뒤의 일행에게 갔다. 재미없는 것은 안 외운다.<br><br>지나고 나서 등에 식은땀이 났다. 외워질 뻔한 것이다. 저것의 머릿속 명단에.`,
      ng:`걸음을 바꿨는데 늦었다. 병 속 눈이 이쪽만 따라온다.<br><br>고개를 돌려도 유리에 비쳐 보인다. 눈이 안 깜빡인다.<br>홀을 다 지날 때까지 따라왔다. 나가는 문에서 마지막으로 돌아봤을 때, 그것이 유리에 손바닥을 대고 있었다. 기억했다는 뜻 같았다. 밤에 그 손바닥이 꿈에 나왔다.`,
      win:{ exp:18, dream:3 }, lose:{ mind:-18, spirit:-17 } },
    { l:'② 더 배우기 전에 병째 끝낸다.', k:'break', dc:25,
      ok:`병 받침의 금 간 자리를 봐 뒀다. 칼자루로 한 번, 체중으로 한 번.<br><br>병이 아래로 주저앉으며 액이 바닥 배수구로 빠졌다. 그것이 마른 바닥에 접혔다. 액 밖에서는 종이처럼 약했다.<br>목을 한 번에 끝냈다. 피는 액에 씻겨 묽어서 바닥만 조금 긁었다.<br><br>자물쇠 재던 손가락이 멎었다. 저 손이 밖으로 나온 다음이었다면 몇이 죽었을지 모른다.`,
      ng:`받침을 쳤는데 병이 통째로 넘어갔다. 홀 전체에 유리와 액이 쏟아졌다.<br><br>그것이 액을 뒤집어쓴 채 일어섰다. 젖은 바닥 위에서는 저쪽이 빨랐다.<br>일행 전원이 달라붙어 겨우 끝냈다. 둘이 긁혔다. 홀은 난장판이 됐고, 그 소리를 듣고 온 것들을 피해 두 시간을 돌아갔다.`,
      win:{ exp:20, dream:2 }, lose:{ hp:-35, mind:-16 } }
  ] },

{ at:'S2', t:'울타리 — 같은 일 하는 것들',
  x:`전기 울타리 너머에서 그것들이 일하고 있다.<br><br>
    한 마리가 울타리를 발끝으로 민다. 물러난다. 다른 놈이 다섯 칸 옆을 민다. 물러난다.<br>
    한 바퀴를 그렇게 돈다. 약한 데를 찾는 것이다. 매일, 순서를 바꿔 가며.<br><br>
    남의 집 담을 재던 몸이라 안다. 저건 일이다. 저것들은 일을 할 줄 안다.`,
  o:[
    { l:'① 저것들의 점검표를 읽는다 — 건너뛰는 칸을 찾는다.', k:'gaze', dc:23, wake:1,
      ok:`세 바퀴를 지켜봤다. 저것들이 안 미는 칸이 하나 있다. 기둥 옆 둘째 칸.<br><br>그 칸 풀숲에 오래된 뼈가 하나 걸려 있다. 울타리가 세게 문 자국. 저것들은 거길 외웠다. 외운 데는 다시 안 간다.<br>그 칸이 울타리에서 제일 성한 칸이고, 저것들 눈에서 제일 먼 칸이다. 일행을 그 칸으로 건넸다.<br><br>남의 점검표를 훔쳐 읽은 셈이다. 적이 공들여 만든 지도는 뒤집어 읽으면 이쪽 지도다.`,
      ng:`세 바퀴째에 미는 순서가 바뀌었다. 점검표를 새로 쓴 것이다.<br><br>읽은 것이 다 헛것이 됐다. 저것들은 제 점검표를 훔쳐 읽는 것까지 계산한다.<br>물러나는데 한 놈이 울타리 너머에서 이쪽 풀숲을 오래 봤다. 바람도 없는데 풀이 흔들린 자리를. 밤새 울타리 밖으로 그놈이 따라 걷는 소리가 났다.`,
      win:{ exp:20, dream:3 }, lose:{ mind:-17, spirit:-18 } },
    { l:'② 점검 중인 놈들의 등 뒤 박자로 울타리를 따라간다.', k:'hide', dc:24,
      ok:`미는 놈이 물러날 때마다 모든 눈이 미는 자리로 쏠린다. 그 몇 숨이 이쪽 몫이다.<br><br>밀 때 걷고, 물러나면 풀이 됐다. 울타리 바깥 풀숲을 그렇게 반 바퀴 돌았다.<br>놈들의 일이 이쪽 발걸음을 재 줬다. 일 열심히 하는 놈들 옆이 제일 안전하다. 일에 코를 박고 있으니까.`,
      ng:`반 바퀴쯤에서 점검이 뚝 멈췄다. 전부 코를 들었다.<br><br>바람이 등 뒤에서 울타리 쪽으로 바뀐 것이다. 이쪽 냄새가 배달됐다.<br>풀숲에 엎드려 숨을 끊었다. 놈들이 울타리에 나란히 붙어 이쪽 어둠을 재는 눈 여덟 개를 한참 세었다. 바람이 다시 바뀌고서야 풀렸다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-26, spirit:-18 } }
  ] },

{ at:'S2', t:'양치밭 — 물결',
  x:`허리까지 잠긴 양치밭이다. 물 위로 고사리 잎이 지붕처럼 덮였다.<br><br>
    걸으면 물결이 간다. 물결은 잎을 흔든다. 흔들린 잎은 멀리서도 보인다.<br>
    밭 건너편 둔덕에 낮은 그림자들이 엎드려 있다. 흔들리는 잎을 기다리는 자세다.<br><br>
    바람이 불면 밭 전체가 흔들린다. 바람은 가끔 분다.`,
  o:[
    { l:'① 바람이 흔들 때만 흔들리며 간다.', k:'hide', dc:24, wake:1,
      ok:`바람을 기다렸다. 왔다. 밭 전체가 쏴아 눕는다.<br><br>그 속에서 걸었다. 이쪽이 만드는 물결이 바람 물결에 먹힌다. 바람이 자면 이쪽도 잔다. 고사리 사이에 서서, 고사리처럼.<br>둔덕의 그림자들은 바람이 분 수만큼만 움직인 밭을 봤다. 수상한 건 없었다.<br><br>바람을 입는 법. 숨을 곳이 없으면 흔들림 속에 숨는다. 멈춘 것 사이에선 멈추고, 움직이는 것 사이에선 같이 움직이고.`,
      ng:`바람이 생각보다 짧았다. 바람 끝에 이쪽 물결이 한 발 삐져나왔다.<br><br>둔덕의 그림자 하나가 벌떡 섰다. 목이 길다. 그 목이 좌우로 천천히 흔들리며 밭을 읽는다.<br>고사리 뿌리 사이에 코까지 잠그고 엎드렸다. 긴 목이 물가까지 내려와 한참 밭 냄새를 맡고 올라갔다. 물이 찼다. 뼛속까지.`,
      win:{ exp:20, dream:3 }, lose:{ hp:-28, spirit:-16 } },
    { l:'② 일행을 사슬로 묶어 한 몸 물결로 간다.', k:'steady', dc:23,
      ok:`다섯이 따로 걸으면 물결이 다섯이다. 밧줄로 허리를 이어 한 줄로 걸었다.<br><br>앞 사람의 물결 안에 뒷사람이 들어간다. 다섯 물결이 큰 하나가 됐다. 큰 물결 하나는 큰 짐승 하나다.<br>둔덕의 그림자들이 고개만 들고 보냈다. 큰 것 하나는 저것들도 셈을 해 보는 것이다. 셈이 끝나기 전에 밭을 나왔다.`,
      ng:`가운데 사람이 물밑 뿌리에 걸려 넘어졌다. 물보라가 솟았다.<br><br>물보라는 물결이 아니다. 비명이다.<br>둔덕에서 그림자 둘이 미끄러져 내려왔다. 전원 잠수. 고사리 뿌리를 쥐고 버텼다. 머리 위로 긴 다리가 두 번 지나갔다. 물을 먹은 사람이 둘. 그래도 다섯이 나왔다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-30, mind:-15 } }
  ] },

{ at:'S2', t:'물목 — 업고 건너기',
  x:`밭이 끝나고 물목이다. 가슴 깊이. 열두 걸음 너비.<br><br>
    다친 일행 하나가 혼자 못 건넌다. 헤엄은 물장구고, 물장구는 종소리다.<br>
    물목 아래쪽 깊은 물에서 이따금 큰 물비늘이 돈다.<br><br>
    업고 건너면 한 번의 물결로 끝난다. 무게는 두 사람 몫이지만.`,
  o:[
    { l:'① 무력으로 업고 한 호흡에 지난다.', k:'evade', dc:24, cost:{ might:30 },
      ok:`다친 사람을 업고 끈으로 맸다. 무력을 하체에 몰았다.<br><br>물에 드는 것부터가 반이다. 발끝부터, 기름에 들듯이. 물속에서는 달리지 않고 밀었다. 열두 걸음을 한 호흡으로.<br>나온 자리 물결이 곧 잠잠해졌다. 아래쪽 물비늘은 제자리에서 돌고 있었다. 두 사람 무게가 한 사람 물결이면 저쪽 셈이 안 맞는다. 안 맞는 셈은 쫓지 않는다.`,
      ng:`아홉 걸음째에 업힌 사람이 물을 먹고 콜록였다.<br><br>작은 기침. 물 위에서는 작지 않다.<br>아래쪽 물비늘이 멎었다. 남은 세 걸음을 던지듯 건넜다. 뭍에 오르는 발꿈치 뒤에서 물이 크게 한 번 갈라졌다 닫혔다. 뒤는 안 봤다. 보면 늦는다.`,
      win:{ exp:20, dream:3 }, lose:{ hp:-30, mind:-14 } },
    { l:'② 밧줄을 먼저 건네고 물밑으로 당겨 건넌다.', k:'bond', dc:23,
      ok:`이쪽이 먼저 건너 밧줄을 나무뿌리에 감았다. 일행은 줄을 쥐고 물밑으로, 당기는 힘으로만 건너왔다.<br><br>팔다리를 안 저으니 물결이 없다. 숨은 갈대 대롱으로.<br>다친 사람이 마지막으로 건너왔다. 줄을 걷고 보니 줄에 이빨 자국이 하나 나 있었다. 어느 참엔가 물밑에서 누가 줄을 재 본 것이다. 사람인 줄 알았으면 물었을 자국이다.`,
      ng:`셋째 사람 차례에 줄이 뿌리째 뽑혔다.<br><br>사람이 물 가운데 떴다. 허우적이면 끝이다. 이쪽이 도로 뛰어들어 멱살을 쥐고 물밑으로 끌었다.<br>둘이 물귀신처럼 기어 나왔다. 아래쪽 물비늘이 물목 초입까지 와 있었다. 못 본 척하고 조용히, 빠르게 떴다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-28, spirit:-16 } }
  ] },

{ at:'S2', t:'몰이 — 양옆의 것들',
  x:`한 시간째 길이 이상하다. 왼쪽에서 바스락하면 오른쪽이 조용하고, 오른쪽이 바스락하면 왼쪽이 조용하다.<br><br>
    쫓기는 게 아니다. 몰리는 거다. 양옆에서 번갈아 소리를 내서 길을 꺾게 만든다.<br>
    이 길 끝에는 저것들이 바라는 자리가 있을 것이다. 트인 진흙 벌 같은.<br><br>
    몰이는 사냥의 끝 수다. 끝 수에는 끝 수로.`,
  o:[
    { l:'① 가시양치 틈으로 빠져 왼쪽 몰이꾼을 끊는다.', k:'hide', dc:25,
      doom:{ title:'몰이꾼', what:'덤불 속에서 물려 가 사냥 무리 쪽으로 끌려갑니다', dc:19, sec:42,
        text:`가시양치 틈새로 몸을 접어 몰이 줄 밖으로 나갔다. 왼쪽 바스락 자리로 돌아 들어갔다.<br><br>있었다. 어깨 낮은 놈 하나. 등이 이쪽이다.<br>다섯 걸음에서 알았다. 저 등은 듣는 등이다. 몰이꾼의 일은 소리 내기와 — 소리 듣기.<br><br>놈이 돌지도 않고 뒷발로 찼다. 가슴에 받고 덤불에 박혔다. 목덜미 옷깃을 물렸다. 끌려간다. 몰이 줄 안쪽으로. 몰던 것들이 모이는 가운데로.`,
        dieText:`몰이가 끝났다. 소리들이 잦아들었다.<br><br>일행은 길이 조용해졌다고 생각했을 것이다.<br>몰이는 몫이 생기면 끝난다. 그날 몫은 하나로 충분했다.`,
      },
      ok:`가시양치 틈으로 빠져 왼쪽으로 돌았다. 몰이꾼이 보였다. 바스락 소리는 녀석의 꼬리가 냈다. 몸은 반대쪽을 향한 채.<br><br>소리 내는 놈은 제 소리에 반쯤 귀가 먼다. 그 반을 썼다. 꼬리가 덤불을 긁는 순간에만 다가가 숨통을 접었다.<br>왼쪽 소리가 죽자 몰이가 흐트러졌다. 오른쪽 것들이 왼쪽을 부르러 간 사이, 일행을 데리고 몰이 줄을 거슬러 빠졌다.<br><br>몰이의 약점은 몰이꾼이다. 사냥의 약점은 언제나 사냥꾼 쪽에 있다.`,
      win:{ exp:24, dream:3 } },
    { l:'② 저것들이 안 미는 방향을 찾는다.', k:'sense', dc:24,
      ok:`소리를 지도로 그렸다. 왼쪽 소리, 오른쪽 소리, 그리고 정면의 침묵.<br><br>침묵 쪽이 함정이다. 몰이는 조용한 쪽으로 몰아넣는다. 뒤도 막혔을 것이다. 남는 건 소리와 소리의 사이. 비스듬한 뒤.<br>그 사이로 일행을 꺾었다. 몰이꾼 둘 사이 스무 걸음 틈을, 저것들이 소리 낼 차례를 세며 지났다. 몰이가 빈 그물을 접는 소리를 등 뒤로 들었다.`,
      ng:`지도를 반대로 읽었다. 조용한 정면으로 꺾을 뻔한 것을 일행이 잡아끌었다.<br><br>정면 진흙 벌에 커다란 발자국이 물을 머금고 있었다. 갓 디딘 자국.<br>소리 사이 틈으로 빠지긴 했다. 틈이 닫히기 반 걸음 전이었다. 뒤에서 가시양치가 우르르 눕는 소리가 났다. 밤새 등이 식지 않았다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-27, mind:-16 } },
    { l:'③ 전원 정지 — 몰이가 제풀에 식을 때까지.', k:'steady', dc:24,
      ok:`몰이는 움직이는 것을 몬다. 바위 그늘에 다섯이 포개 앉아 돌이 됐다.<br><br>양옆 바스락 소리가 점점 초조해졌다. 가까워졌다가, 교차했다가, 서로를 몰았다.<br>한 식경 뒤에 소리가 빠졌다. 몰이는 품이 드는 사냥이다. 셈이 안 맞으면 저쪽이 먼저 접는다. 다리에 쥐가 났지만 산 다리다.`,
      ng:`버티는 중에 막내 다리에 쥐가 났다. 발이 돌을 긁었다.<br><br>양옆 소리가 뚝 멎었다. 최악의 침묵이다.<br>그늘에서 뛰쳐나와 달렸다. 몰이고 뭐고 없는 전력 질주. 등 뒤 양옆에서 낮은 것들이 따라붙다가 가시양치 벽에서 떨어져 나갔다. 다들 토할 때까지 뛰었다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-31, spirit:-15 } }
  ] },

{ at:'S2', t:'큰 것 — 둥근 무늬',
  x:`웅덩이 물낯에 둥근 무늬가 돋는다. 가만히, 일정하게.<br><br>
    걸음이다. 아주 무거운 것의 걸음이 땅을 타고 물에 찍힌다. 몸은 안 보인다. 양치 숲 어딘가다.<br>
    무늬가 둥글고 클수록 가깝다. 지금은 손바닥만 하다.<br><br>
    건너야 할 얕은 물이 백 걸음. 무늬가 접시만 해지면 돌아 나올 수 없는 거리다.`,
  o:[
    { l:'① 무늬가 돋는 박자 사이로 백 걸음을 쪼갠다.', k:'hide', dc:24,
      ok:`무늬와 무늬 사이가 네 호흡이다. 그 네 호흡이 저것의 한 걸음.<br><br>저것이 발을 드는 순간 이쪽도 걷고, 발이 땅에 앉을 때 이쪽도 섰다. 큰 걸음 밑에 작은 걸음을 깔았다. 땅울림이 이쪽 발소리를 먹는다.<br>백 걸음을 스물다섯 번에 나눠 건넜다. 건너고 나서 보니 물무늬가 접시만 해져 있었다. 마지막 몇 걸음은 저것의 걸음 속에서 걸은 것이다.`,
      ng:`스무 걸음쯤에서 무늬가 뚝 끊겼다.<br><br>저것이 멈춘 것이다. 멈춘 이유는 하나다. 무언가 들었다.<br>물 가운데 서서 네 호흡, 여덟 호흡, 숨만 쉬었다. 무늬가 다시 돋기 시작했을 때 — 조금 더 커져 있었다. 이쪽으로 온 것이다. 남은 팔십 걸음을 평생처럼 걸었다.`,
      win:{ exp:20, dream:3 }, lose:{ mind:-19, spirit:-18 } },
    { l:'② 무늬가 작을 때 깊은 쪽을 질러 헤엄친다.', k:'evade', dc:26,
      doom:{ title:'깊은 물', what:'물 밑으로 빨려 들어가 가라앉습니다', dc:20, sec:38,
        text:`얕은 길은 길다. 깊은 물을 가로지르면 반이다. 무늬가 손바닥일 때 미끄러져 들었다.<br><br>반쯤 건넜을 때 물이 당겼다. 물살이 아니다. 물이 어디론가 들이켜지고 있다.<br>아래에 입이 있다. 큰 것은 양치 숲에만 있는 게 아니었다. 물에도 큰 것이 산다.<br><br>발목부터 빨려 든다. 물낯이 멀어진다. 손을 뻗었다. 물 위 손바닥만 한 무늬가 마지막으로 보였다. 저 무늬 주인은 차라리 작은 것이었다.`,
        dieText:`웅덩이 물낯이 한 번 크게 솟았다 가라앉았다.<br><br>그 뒤로 둥근 무늬가 다시 돋는다. 가만히, 일정하게.<br>물가 양치 잎에 물방울이 앉아 오래 흔들렸다. 그게 전부였다.`,
      },
      ok:`깊은 물에 들기 전에 돌을 하나 던져 봤다. 돌이 가라앉으며 — 중간에 방향을 꺾었다.<br><br>물속에 흐름이 있다. 삼키는 흐름. 저 밑에 뭐가 입을 벌리고 있는 것이다.<br>헤엄은 접었다. 얕은 길로 돌았다. 다리가 두 배로 아픈 것이 물 밑보다 백배 낫다.<br><br>질러가는 길이 늘 빠른 길은 아니다. 여기서는 특히.`,
      win:{ exp:22, dream:3 } }
  ] },

{ at:'S2', t:'낡은 승강기 — 덜컹 소리',
  x:`숲 가운데 녹슨 철탑이 섰고 그 밑에 낡은 승강기가 매달려 있다. 나가는 길이다.<br><br>
    바람이 불 때마다 승강기 철창이 덜컹, 운다. 오래 운 소리라 여기 것들은 쳐다도 안 본다.<br>
    그 덜컹이 유일한 덮개다. 승강장까지 트인 쉰 걸음.<br><br>
    바람은 이쪽 사정을 안 봐준다.`,
  o:[
    { l:'① 덜컹에 걸음을 포개 쉰 걸음을 끊어 간다.', k:'hide', dc:23,
      ok:`바람을 기다렸다. 덜컹. 네 걸음. 덜컹덜컹. 여덟 걸음.<br><br>소리에 포갠 걸음은 소리가 아니다. 들어도 승강기 소리다. 여기 것들 귀에 승강기 소리는 돌 소리와 같다. 아무것도 아닌 소리.<br>쉰 걸음을 아홉 번에 나눠 다 건넜다. 마지막 덜컹은 이쪽이 승강장 발판을 밟는 소리와 겹쳤다. 그것까지 계산한 건 아니다. 바람이 도왔다.`,
      ng:`여섯 걸음째에 바람이 죽었다. 벌판 한가운데서.<br><br>엎드렸다. 풀이 무릎밖에 안 온다. 등이 그대로 드러난 채 바람을 기다렸다.<br>멀리서 낮은 것 하나가 벌판을 가로질러 갔다. 이쪽을 못 보고. 바람이 다시 불 때까지의 시간을 평생 셀 것 같다. 백서른둘까지 셌다.`,
      win:{ exp:18, dream:3 }, lose:{ hp:-25, spirit:-17 } },
    { l:'② 먼저 가서 철창을 묶어 소리부터 고친다.', k:'fix', dc:24,
      ok:`혼자 먼저 건너가 철창 떨리는 자리에 가죽끈을 감았다. 덜컹이 둔탁한 턱, 소리로 바뀌었다.<br><br>탈 때 울리면 그게 종이다. 타기 전에 종을 떼어 둔 것이다.<br>일행이 건너와 탔다. 철창이 사람 무게에 끽 소리 한 번 내고 말았다. 끈 하나 값이다.`,
      ng:`감는 중에 철창이 손 밑에서 크게 한 번 울렸다. 평소와 다른 소리.<br><br>여기 것들은 소리를 외운다. 다른 소리는 새 소리고, 새 소리는 조사 대상이다.<br>숲 가장자리에 낮은 그림자가 둘 나타나 승강장을 오래 봤다. 철창 밑에 숨어 바람 일곱 번을 보냈다. 손바닥에 녹이 박혔다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-26, mind:-15 } }
  ] },

{ at:'S2', t:'둥지 곁 — 잠든 숨',
  x:`승강기 권양기 손잡이가 빠져 있다. 쇠붙이를 물어 가는 버릇이 있는 것들 짓이다.<br><br>
    놈들의 둥지는 바위 틈이다. 안에서 포개 자는 숨소리가 난다. 쇠붙이들은 둥지 바닥에 깔렸다. 반짝이는 것을 깔고 자는 것이다.<br>
    손잡이 없이는 승강기가 안 돈다.<br><br>
    잠든 것들 틈에서 쇠붙이 하나. 도둑질로 치면 제일 질 나쁜 종류다.`,
  o:[
    { l:'① 잠든 틈새로 손을 넣어 손잡이만 뽑아 온다.', k:'hide', dc:25,
      doom:{ title:'안 자던 하나', what:'목덜미를 물려 둥지 안쪽으로 끌려 들어갑니다', dc:20, sec:36,
        text:`포갠 숨을 셌다. 여섯. 틈새로 몸을 접어 넣었다. 쇠붙이 더미에서 손잡이가 보인다. 꼬리 하나 밑에.<br><br>꼬리를 깃털 들 듯 들고 손잡이를 뺐다. 뺐다 — 그 순간 둥지 안쪽 어둠에서 눈이 떠졌다.<br>일곱째. 숨을 안 쉬고 자는 척하던 놈. 보초다. 이것들은 보초를 세운다.<br><br>목덜미를 물렸다. 둥지 안쪽으로 끌려 들어간다. 잠들었던 여섯이 하나씩 눈을 뜬다. 쇠붙이 더미 위로.`,
        dieText:`둥지 바닥에 반짝이는 것이 몇 점 늘었다.<br><br>단추, 버클, 그리고 칼 한 자루.<br>그것들은 반짝이는 것을 깔고 잔다. 오늘 밤 잠자리가 어제보다 높아졌다.`,
      },
      ok:`포갠 숨을 셌다. 여섯 — 아니, 숨 없는 몸이 하나 더 있다. 일곱째. 가슴이 안 움직인다. 보초는 숨을 죽이고 선다. 이쪽이 그러듯이.<br><br>보초의 눈꺼풀이 이쪽을 향해 있다. 틈새로 드는 바람 반대쪽으로 돌아 보초의 등 쪽 틈으로 손을 바꿨다.<br>손잡이는 꼬리 밑이 아니라 더미 가장자리 것을 골랐다. 덜 좋은 자리의 덜 반짝이는 것. 아무도 아쉬워 않을 것.<br><br>맨 좋은 것을 안 집는 손. 그게 안 들키는 손이다.`,
      win:{ exp:24, dream:3 } },
    { l:'② 보초 숨을 먼저 찾아 무력으로 조용히 접는다.', k:'break', dc:25, cost:{ might:38 },
      ok:`둥지 입구 그늘에 숨 없는 몸 하나가 앉아 있었다. 보초. 자는 척이 이쪽 눈엔 보인다. 숨 죽이는 건 이쪽 전공이다.<br><br>등 뒤로 돌아 목을 감았다. 무력으로 조였다. 소리가 나는 목이 아니라 소리가 나려는 목을. 천천히 재웠다. 영영.<br>잠든 여섯은 보초가 사라진 줄 모른다. 손잡이를 뽑고, 보초를 제자리에 앉혀 두고 나왔다. 아침까지는 앉아 있을 것이다.`,
      ng:`조이는 손 밑에서 놈이 꼬리로 바닥을 쳤다. 탁.<br><br>잠든 숨 여섯이 한꺼번에 끊겼다. 다 깬 것이다.<br>목은 마저 접었지만 둥지가 일어섰다. 손잡이만 낚아채 뛰었다. 바위 틈이 좁아 놈들이 한 마리씩밖에 못 나온 덕에 살았다. 어깨를 긁혔다. 발톱이 깊었다.`,
      win:{ exp:20, dream:3 }, lose:{ hp:-34, mind:-14 } },
    { l:'③ 둥지 밖 진창에서 빠진 다른 쇠붙이를 찾는다.', k:'luck', dc:23,
      ok:`물어 가는 놈들은 흘리기도 한다. 둥지로 드는 길목 진창을 손가락으로 훑었다.<br><br>반 식경 만에 쇠막대 하나. 권양기 구멍에 맞는 굵기다. 손잡이 대용으로 넉넉하다.<br>진창을 훑은 김에 물가 미나리 닮은 순도 한 줌 뜯었다. 요리사가 보면 반길 것이다. 둥지는 둥지대로 자게 뒀다. 서로 좋은 일이다.`,
      ng:`진창을 훑는데 손끝에 쇠가 아니라 이빨이 닿았다. 턱뼈다. 큰 턱뼈.<br><br>놀라 뒤로 주저앉았다. 철퍽. 진창 소리가 컸다.<br>둥지 쪽 숨소리 하나가 끊겼다 이어졌다. 진창에 엎드려 한참을 기다렸다. 쇠막대는 결국 찾았다. 온몸이 진흙인 채로.`,
      win:{ exp:16, dream:2, item:'산나물' }, lose:{ hp:-26, mind:-14 } }
  ] }

]);

// ── 자객 (killer) · 내공 ──
kJob('killer', 'S', [

{ at:'S', t:'어둠 — 살기 없는 사냥',
  x:`자객은 살기로 앞을 읽는다. 치려는 것은 치기 전에 새어 나온다. 사람도, 짐승도.<br><br>
    여기 것들은 새는 게 없다. 미워서 죽이는 게 아니라 먹으려고 죽이기 때문이다.<br>
    밥상 앞의 마음에는 살기가 없다.<br><br>
    읽을 것이 없는 어둠. 눈 감고 걷는 것과 같다. 다른 글자를 배워야 한다.`,
  o:[
    { l:'① 살기 대신 고요를 읽는다 — 소리가 비는 자리를.', k:'sense', dc:23, wake:1,
      ok:`어둠은 원래 소리로 차 있다. 물 듣는 소리, 벌레, 바람.<br><br>그 소리가 비는 자리가 있다. 소리들이 피해 가는 구멍. 벌레는 먹는 것 옆에서 안 운다.<br>고요의 구멍을 짚어 가며 길을 꺾었다. 구멍 하나가 천천히 따라오다 멈추는 것까지 읽혔다.<br><br>살기를 읽던 귀가 살기의 빈자리를 읽는다. 글자가 없는 게 아니었다. 여백이 글자였다.`,
      ng:`고요를 짚는데 어느 순간 사방이 다 고요해졌다.<br><br>전부가 구멍이면 읽을 수 없다. 벌레가 일제히 그친 것이다. 그건 하나가 아니라 여럿이 들어왔다는 뜻이었다.<br>벽에 등을 대고 일행과 뭉쳐 그 고요가 지나가기를 기다렸다. 지나가는 데 백 숨이 걸렸다. 등이 다 젖었다.`,
      win:{ exp:20, dream:3 }, lose:{ mind:-17, spirit:-18 } },
    { l:'② 이쪽도 밥상 앞 마음이 된다.', k:'hide', dc:24,
      ok:`칼을 쥔 마음을 내려놓았다. 미움도, 경계도. 걸으면서 저녁 지을 생각을 했다.<br><br>마음이 고요하면 몸이 고요하다. 숨이 길어지고 발이 가벼워진다. 짐승은 긴장한 것부터 문다. 긴장은 소리가 나기 때문이다.<br>어둠 속 무언가의 곁을 그 마음으로 지났다. 그것도 밥상 앞 마음이었고, 서로의 밥이 아니었다. 그렇게 스쳐 보냈다.`,
      ng:`내려놓는다고 놓았는데 손이 칼자루 위에 있었다.<br><br>몸이 마음을 못 따라온 것이다. 쥔 손의 긴장이 어깨로, 숨으로 올라왔다.<br>어둠 속 그것이 이쪽 숨의 각을 들었다. 한참 이쪽을 돌며 재다가 갔다. 저쪽 셈이 안 맞아서 산 것이지 이쪽이 잘해서 산 게 아니다.`,
      win:{ exp:18, dream:2 }, lose:{ mind:-16, spirit:-20 } }
  ] },

{ at:'S', t:'바닥 — 맥 울림',
  x:`바닥이 통돌이다. 울림이 멀리 간다.<br><br>
    발소리는 죽일 수 있다. 문제는 그 아래다. 심장이 뛸 때마다 몸이 미세하게 울고, 그 울림이 발바닥을 타고 돌에 스민다.<br>
    여기 것들은 돌에 턱을 대고 그걸 듣는다.<br><br>
    심장을 발에서 떼어 내야 한다.`,
  o:[
    { l:'① 내공으로 맥 울림을 허리 위로 거둬 올린다.', k:'steady', dc:24, cost:{ qi:28 },
      ok:`기를 단전에서 가슴으로 올려 맥의 울림을 상체에 가뒀다. 허리 아래는 빈 나무토막처럼.<br><br>발바닥이 돌에 닿아도 스미는 것이 없다. 걸음마다 기를 고쳐 쥐어야 해서 이마에 땀이 맺혔다.<br>바닥 어딘가에 턱을 댄 것이 있다면, 오늘 돌에서 사람을 못 읽었을 것이다.`,
      ng:`서른 걸음까지는 가뒀다. 서른하나에서 기가 흐트러졌다.<br><br>참았던 맥이 한꺼번에 발로 쏟아졌다. 쿵. 돌이 들었다.<br>멀리서 돌을 긁으며 다가오는 소리가 났다. 일행을 흙바닥 쪽으로 밀어 올리고 마지막에 건넜다. 흙은 울림을 먹는다. 돌 위 긁는 소리가 밤새 오갔다.`,
      win:{ exp:20, dream:3 }, lose:{ hp:-28, mind:-14 } },
    { l:'② 심장 박자와 반대 박자로 걷는다.', k:'hide', dc:24,
      ok:`맥이 뛸 때 발을 들고, 맥과 맥 사이에 내렸다.<br><br>울림 두 개가 겹치면 커지고 어긋나면 서로 깎는다. 몸의 울림과 걸음의 울림이 서로를 지웠다.<br>박자를 나눠 주니 일행도 따라 했다. 다섯 심장, 다섯 걸음이 돌 위에서 서로를 지우며 지나갔다. 돌은 끝까지 아무 말도 안 들었다.`,
      ng:`반대 박자로 스무 걸음, 그러다 심장이 빨라졌다. 무서우면 빨라진다.<br><br>박자가 따라잡혔다. 겹쳤다. 겹친 울림이 돌로 쿵 내려갔다.<br>그대로 정지. 돌에 턱 대는 소리가 어둠 저쪽에서 났다. 심장더러 천천히 뛰라고 비는 동안, 심장은 더 빨리 뛰었다. 몸이 말을 안 듣는 밤이었다.`,
      win:{ exp:18, dream:2 }, lose:{ mind:-18, spirit:-16 } }
  ] },

{ at:'S', t:'통로 — 열 걸음에 한 숨',
  x:`긴 통로다. 양쪽 벽에 구멍이 줄지어 뚫렸다. 뭐가 사는 구멍인지는 모른다.<br><br>
    구멍마다 공기가 드나든다. 숨을 쉬면 이쪽 공기가 저 구멍들로 흘러든다.<br>
    냄새가 아니라 숨 자체가 배달되는 길이다.<br><br>
    자객의 토납은 숨을 길게 늘인다. 얼마나 늘일 수 있는지 오늘 알게 된다.`,
  o:[
    { l:'① 토납으로 열 걸음에 한 숨만 쉰다.', k:'steady', dc:24,
      ok:`들숨 한 번을 배 밑바닥까지 눌러 담고 열 걸음을 걸었다. 날숨은 입술 틈으로 실처럼.<br><br>공기가 거의 안 흔들린다. 구멍들은 조용했다.<br>통로 끝에서 날숨을 길게 풀었다. 통로 밖으로. 뒤돌아보니 구멍 몇 개에서 가는 더듬이 같은 것들이 나와 허공을 재고 있었다. 늦게 온 숨 자국을 더듬는 것이다. 주인 없는 자국을.`,
      ng:`여덟 걸음째에 목이 간지러웠다. 아홉에서 기침이 코로 샜다.<br><br>제일 가까운 구멍이 숨을 들이켰다. 길게. 이쪽 숨을 통째로 마시는 소리.<br>구멍들이 차례로 깨어났다. 전원이 남은 통로를 반 숨으로 뛰었다. 등 뒤에서 젖은 것들이 바닥에 떨어지는 소리가 이어졌다. 돌아보지 않았다.`,
      win:{ exp:20, dream:3 }, lose:{ hp:-27, mind:-15 } },
    { l:'② 바람이 통로를 지날 때 바람에 숨을 실어 보낸다.', k:'evade', dc:23,
      ok:`통로에 이따금 외풍이 지나간다. 그때만 숨을 쉬었다.<br><br>바람에 실린 숨은 바람 냄새가 된다. 바람은 구멍들의 오랜 이웃이다. 아무도 이웃을 사냥하지 않는다.<br>바람의 박자에 숨을 포개 통로를 다 지났다. 바람이 안 불 때는 걷기만 했다. 걷기만 하는 몸은 생각보다 조용하다.`,
      ng:`바람을 기다리는데 바람이 안 왔다. 숨은 차오르고.<br><br>참다못해 벽 쪽으로 가늘게 내쉬었다. 하필 그 벽의 구멍 앞이었다.<br>구멍 속에서 젖은 것이 이쪽 입술 높이까지 밀려 나왔다가 들어갔다. 맛을 본 것이다. 입술이 밤새 부르텄다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-26, spirit:-16 } }
  ] },

{ at:'S', t:'쉬는 자리 — 운기 곁의 것',
  x:`쉬는 참에 가부좌를 틀었다. 흐트러진 기를 돌린다.<br><br>
    기가 도는 몸은 미지근한 등불 같다. 눈에는 안 보여도, 다른 것이 보는 눈에는.<br>
    두 바퀴째에 알았다. 어둠 속에서 무언가가 다가와 앉아 있다. 불을 쬐듯이.<br><br>
    운기를 끊으면 내상이다. 계속 돌리면 등불이 계속 켜져 있다.`,
  o:[
    { l:'① 기를 가늘게 줄여 등불을 숨불로 낮춘다.', k:'steady', dc:23, wake:1,
      ok:`돌리는 기를 끊지 않고 가늘게 했다. 강물을 실개천으로. 한 바퀴 도는 데 세 배가 걸리는 대신 새어 나가는 온기가 없다.<br><br>어둠 속 그것이 고개를 갸웃하는 기척이 났다. 불이 꺼진 게 아니라 잦아든 것이라 어리둥절한 것이다. 한참 앉아 있다가 갔다.<br><br>크게 돌리는 것만 운기인 줄 알았다. 가늘게, 오래, 들키지 않게 — 그런 운기가 있었다. 여기가 가르쳐 줬다.`,
      ng:`줄이다가 기가 한 번 출렁였다. 등불이 펄럭인 셈이다.<br><br>그것이 성큼 다가앉았다. 숨이 목덜미에 닿는 거리.<br>기를 실처럼 줄인 채 그것의 숨을 목에 받으며 끝까지 돌렸다. 운기가 끝나고도 한참을 그대로 앉아 있었다. 그것이 흥미를 잃고 떠날 때까지. 등에 소름이 가시는 데 반나절 걸렸다.`,
      win:{ exp:20, dream:3, spirit:6 }, lose:{ mind:-18, spirit:-17 } },
    { l:'② 운기를 마저 하며 그것의 자리를 귀로 잰다.', k:'gaze', dc:24,
      ok:`기는 기대로 돌리고 귀는 귀대로 열었다. 그것의 무게가 바닥을 누르는 자리, 숨이 도는 길이.<br><br>왼쪽 다섯 걸음, 앉은키 큰 것 하나. 움직임 없음. 구경꾼이다.<br>운기를 마치고 눈을 떴을 때 그 자리를 정확히 봤다. 그것이 움찔했다. 보이는 줄 몰랐던 것이다. 서로 모르는 척하며 물러났다. 그런 밤도 있다.`,
      ng:`귀를 여는데 그것이 자리를 옮겼다. 소리 없이. 어디로 갔는지 놓쳤다.<br><br>모르는 게 제일 나쁘다. 운기 반, 경계 반이 되어 기가 설익었다.<br>끝내고 일어서는데 어지러웠다. 설익은 기가 속을 긁는다. 그것은 새벽에 천장 쪽에서 내려와 제 갈 길로 갔다. 천장은 짚어 보지도 않았었다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-26, mind:-16 } }
  ] },

{ at:'S', t:'살기 한 줄기 — 미끼',
  x:`갈래목에 여럿이 모여 있다. 지나가려면 흩어 놓아야 한다.<br><br>
    예전 같으면 살기를 한 줄기 흘렸다. 짐승은 살기를 피하니까.<br>
    여기 것들이 살기를 어떻게 받는지는 모른다. 피할지, 모일지.<br><br>
    모르는 패는 작게 먼저 던져 보는 법이다.`,
  o:[
    { l:'① 실만큼만 흘려 저것들의 반응을 본다.', k:'gaze', dc:24,
      ok:`살기를 머리카락 한 올만큼 떼어 갈래목 왼쪽으로 흘렸다.<br><br>모였다. 피하는 게 아니라 모인다. 저것들에게 살기는 경고가 아니라 냄새다. 쳐 본 적 있는 것들의 냄새.<br>알았으니 됐다. 살기를 거두고 오른쪽 길로 일행을 돌렸다. 저것들은 왼쪽 허공을 한참 뒤졌다. 한 올 값을 톡톡히 했다.`,
      ng:`한 올을 흘렸는데 저것들이 모이다가 — 멈췄다. 그리고 한 올이 흘러나온 줄기를 거슬러 보기 시작했다.<br><br>살기는 흘린 자리가 아니라 흘린 몸에 뿌리가 있다. 저것들은 뿌리를 찾을 줄 알았다.<br>살기를 급히 끊었다. 끊긴 자리에서 저것들이 오래 서성였다. 그동안 바위처럼 서 있었다. 심줄이 당겨 쥐가 났다.`,
      win:{ exp:18, dream:3 }, lose:{ mind:-17, spirit:-19 } },
    { l:'② 살기를 뭉쳐 멀리 심는다 — 거기 큰 것이 있는 듯이.', k:'hide', dc:25,
      doom:{ title:'심은 살기', what:'살기 줄기를 거슬러 온 것들에게 잡혀 끌려갑니다', dc:19, sec:44,
        text:`살기를 주먹만큼 뭉쳐 갈래목 너머 빈 홀에 심었다. 큰 짐승 하나가 웅크린 모양으로.<br><br>저것들이 우르르 그쪽으로 몰렸다. 됐다 — 싶은 순간, 둘이 안 갔다.<br>안 간 둘이 고개를 이쪽으로 돌렸다. 뭉친 살기에는 줄기가 남는다. 심은 손까지.<br><br>둘이 줄기를 타고 왔다. 빠르다. 양팔을 하나씩 물렸다. 끌려간다. 나머지가 몰려간 빈 홀 쪽으로. 미끼가 있던 자리로 미끼 주인이 배달된다.`,
        dieText:`빈 홀의 뭉친 살기가 천천히 흩어졌다.<br><br>주인 잃은 살기는 오래 못 간다.<br>갈래목에 다시 여럿이 모였다. 아까보다 하나 는 것 같기도 하다.`,
      },
      ok:`뭉치기 전에 줄기부터 끊는 법을 챙겼다. 살기를 뭉쳐 — 던지고 — 손목을 꺾어 줄기를 비틀어 태웠다.<br><br>빈 홀에 큰 짐승 하나가 생겼다. 뿌리 없는 짐승이.<br>저것들이 전부 그리로 몰렸다. 갈래목이 비었다. 일행이 지나는 데 스무 숨. 빈 홀에서 저것들이 허공을 문 소리가 스무 숨 내내 났다.<br><br>미끼는 던지는 것보다 줄 끊는 게 어렵다. 그걸 몸이 외웠다.`,
      win:{ exp:22, dream:3 } },
    { l:'③ 미끼 없이 — 저것들 사이 빈 결을 걸어서 지난다.', k:'hide', dc:25,
      ok:`모인 것들에게도 결이 있다. 서로의 꼬리가 안 닿는 금, 눈길이 안 겹치는 부채꼴.<br><br>그 결을 눈으로 그리고, 결 사이로 걸었다. 빠르지도 느리지도 않게. 결은 저것들이 움직일 때마다 바뀐다. 세 번 멈추고 두 번 돌았다.<br>한가운데를 지나는 동안 아무것도 이쪽을 안 봤다. 서로가 서로의 눈가리개였다.`,
      ng:`결 사이로 반쯤 들어갔을 때 한 놈이 자리를 틀었다. 결이 통째로 바뀌었다.<br><br>길이 사라졌다. 저것들 한가운데 선 채로.<br>바뀐 결이 다시 열릴 때까지 쉰 숨을 그 자리에 서 있었다. 한 놈의 꼬리가 발등을 두 번 쓸고 갔다. 꼬리 주인은 이쪽을 바위로 알았을 것이다. 바위도 식은땀을 흘린다는 걸 오늘 알았다.`,
      win:{ exp:20, dream:3 }, lose:{ mind:-19, spirit:-20 } }
  ] },

{ at:'S', t:'체온 — 식은 몸',
  x:`앞쪽 길목을 지키는 것이 있다. 눈이 없다. 콧구멍이 얼굴의 반이다.<br><br>
    저것은 더운 것을 맡는다. 땀, 숨, 살갗의 온기. 사람은 걸어 다니는 화로다.<br>
    화로를 끄면 된다. 자객의 내공은 몸의 불을 올리기도, 내리기도 한다.<br><br>
    내리는 쪽은 오래 안 해 봤다. 내린 불은 다시 올리기 어렵다.`,
  o:[
    { l:'① 내공으로 살갗의 불을 끈다.', k:'steady', dc:24, cost:{ qi:30 }, wake:1,
      ok:`기를 안으로 말아 살갗에서 뗐다. 체온이 속으로 가라앉는다. 손끝, 발끝, 낯가죽이 차례로 식었다.<br><br>겉은 돌, 속은 화로. 그 몸으로 길목을 지났다. 콧구멍 반쪽짜리 얼굴이 이쪽을 향해 벌름거리다 말았다. 돌 냄새에서 멈춘 것이다.<br>지나고 나서 기를 풀자 온기가 살갗으로 돌아왔다. 바늘로 쑤시듯 아팠다. 아픈 만큼 산 것이다.<br><br>불을 숨기는 운기. 올리고 내리는 것만 알던 기가 감추는 법을 배웠다.`,
      ng:`살갗을 식히는데 한 군데가 말을 안 들었다. 아까 다친 어깨. 상처는 뜨겁다.<br><br>온몸이 돌인데 어깨만 숯불이었다. 벌름거리던 콧구멍이 정확히 어깨 높이에서 멎었다.<br>일행이 반대쪽에서 더운 물수건을 흔들어 준 덕에 빠졌다. 수건은 길목 것이 가져갔다. 씹는 소리가 오래 났다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-28, mind:-14 } },
    { l:'② 더 더운 것을 만들어 코를 그쪽에 판다.', k:'fix', dc:23,
      ok:`불씨 돌 두 개를 천에 싸서 비볐다. 돌이 데워진다. 사람 체온보다 조금 높게.<br><br>데운 돌을 길목 반대편 바람 위쪽에 뒀다. 콧구멍이 그쪽으로 돌았다. 더 더운 것이 먼저다.<br>저것이 돌을 더듬는 동안 바람 아래로 지났다. 돌은 곧 식을 것이다. 식은 돌에 흥미 잃을 때쯤 이쪽은 두 구역 밖이다.`,
      ng:`돌을 비비는 소리가 생각보다 났다. 사각, 사각.<br><br>콧구멍이 돌기 전에 귓구멍이 먼저 돌았다. 눈이 없다고 귀도 없는 게 아니었다.<br>돌을 던져 두고 물러났다. 저것이 소리 자리와 온기 자리 사이에서 헷갈려 하는 동안 멀리 돌았다. 두 배 걸은 다리가 저녁 내 무거웠다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-26, mind:-15 } }
  ] },

{ at:'S', t:'동료의 피 — 손가락 지혈',
  x:`일행 하나가 어깨를 베였다. 피가 흐른다.<br><br>
    천으로 눌러도 스며 나온다. 스며 나오는 만큼 냄새가 번진다.<br>
    여기서 피 냄새는 저녁 종이다. 벌써 어둠 몇 군데가 코를 들었다.<br><br>
    자객은 피를 멈추는 혈을 안다. 찌르는 혈 옆에는 늘 막는 혈이 있다.`,
  o:[
    { l:'① 어깨 위 세 혈을 눌러 피부터 잠근다.', k:'heal', dc:23,
      ok:`쇄골 밑, 겨드랑이, 팔꿈치 안. 세 혈을 차례로 눌렀다. 혈로 가는 길목을 조인 것이다.<br><br>피가 눈에 띄게 줄었다. 그 틈에 천을 감고 송진으로 겉을 봉했다. 냄새 마개까지.<br>혈 자리는 한 식경 뒤에 풀어 줬다. 너무 오래 잠그면 팔이 죽는다. 잠그는 것도 푸는 것도 때가 있다. 찌르던 손가락이 오늘은 살리는 쪽으로 일했다.`,
      ng:`혈을 짚는데 그 사람이 아픔에 몸을 틀었다. 혈이 어긋났다.<br><br>어긋난 혈은 피를 더 부른다. 천이 금세 붉어졌다.<br>결국 천 세 장을 버리고야 잡았다. 버린 천은 불에 태웠다. 타는 동안 피 냄새가 더 퍼졌다. 그 밤 어둠이 유난히 부산했다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-25, mind:-15 } },
    { l:'② 피 묻은 것들을 모아 바람 아래 묻는다.', k:'fix', dc:23,
      ok:`피 묻은 천, 피 떨어진 돌까지 다 모았다. 바람 아래쪽으로 쉰 걸음, 돌무더기 밑에 묻었다.<br><br>묻은 자리 위에 고약한 곰팡 돌을 얹었다. 피 냄새 위에 곰팡 냄새. 뚜껑이다.<br>밤에 그 돌무더기 쪽에서 파헤치는 소리가 났다. 쉰 걸음 밖에서. 쉰 걸음이 목숨 값이었다.`,
      ng:`묻으러 가는 길에 천에서 피가 한 방울 더 떨어졌다. 모르고 지나쳤다.<br><br>그 한 방울이 다리가 됐다. 묻은 자리에서 쉬는 자리까지 점선이 이어진 셈이다.<br>새벽에 쉬는 자리 가장자리에서 킁킁대는 소리에 다 깼다. 횃불을 확 밝혀 쫓았다. 빛이 드는 걸 알면서도 그 수밖에 없었다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-26, spirit:-16 } }
  ] },

{ at:'S', t:'너무 조용한 방',
  x:`방 하나를 지나야 한다. 문턱에서부터 소리가 죽는다.<br><br>
    발소리도, 옷깃 소리도, 안에서는 솜에 싸인 듯 먹먹하다.<br>
    소리를 먹는 방. 그런데 방 한가운데에 그것이 앉아 있다. 소리가 없는 데서 사는 것이.<br>
    저것의 귀에 이 방은 조용하지 않을 것이다. 남는 소리가 하나 있다. 심장.`,
  o:[
    { l:'① 맥을 늦춰 심장 소리를 바닥까지 낮추고 지난다.', k:'hide', dc:25,
      doom:{ title:'소리 먹는 방', what:'방 한가운데 것에게 잡혀 소리 없이 끌려갑니다', dc:20, sec:40,
        text:`단전의 기로 심장을 감쌌다. 북에 솜을 채우듯. 맥이 느려진다. 둥 — 둥 —<br><br>반쯤 지났을 때 그것의 고개가 이쪽으로 돌았다. 느린 맥도 맥이다. 이 방에서는 그게 천둥이다.<br>일어서는 것이 안 보였다. 소리가 없으니 빠르기도 없다. 그냥 어느새 앞에 있었다.<br><br>팔을 잡혔다. 비명을 질렀는데 방이 먹었다. 일행은 이쪽이 사라진 것만 안다. 소리 없이 끌려간다. 방의 어두운 구석, 소리가 제일 깊이 죽는 자리로.`,
        dieText:`방을 건너간 일행이 수를 셌다. 하나 빈다.<br><br>방 안을 들여다봐도 어둠뿐이다. 불러도 소리가 방 안으로 안 들어간다.<br>그 방은 전에도 그런 식으로 몇을 먹었을 것이다. 조용하게. 그 방답게.`,
      },
      ok:`단전의 기로 심장을 감쌌다. 맥이 가라앉는다. 둥 — 둥 — 그리고 알았다. 이 방에서 심장은 지워서 될 게 아니다. 바꿔치기해야 한다.<br><br>품의 회중시계를 꺼내 태엽을 감아 방 문턱 안쪽에 놓았다. 똑, 딱, 똑, 딱.<br>그것의 고개가 시계로 돌았다. 작고 일정한 맥. 그것이 시계를 들여다보는 동안 벽을 따라 지났다. 다섯 모두.<br><br>방을 나와서 시계 소리가 뚝 멎는 걸 들었다. 시계 값으로 다섯. 헐값이다.`,
      win:{ exp:24, dream:3 } },
    { l:'② 방에 안 들어간다 — 벽 너머로 길을 찾는다.', k:'sense', dc:23,
      ok:`방을 먹여 살리는 건 뭘까. 소리를 먹는 방이면, 소리가 드는 틈이 있어야 한다.<br><br>벽을 따라 돌며 손바닥으로 공기를 쟀다. 방 뒤쪽 벽 틈으로 바람이 샌다. 사람 하나 지나는 틈.<br>틈으로 다섯이 꿰어 지났다. 방 한가운데 것은 제 어둠에 앉은 채였다. 방은 저것의 그릇이다. 그릇 가장자리로 돌면 된다.`,
      ng:`벽 틈을 찾아 반 바퀴 돌았을 때, 틈에서 나오는 바람이 멎었다.<br><br>틈 안쪽에 뭐가 들어찬 것이다. 내다보는 것이.<br>물러나 방 반대편 긴 길로 돌았다. 두 시진을 더 걸었다. 두 시진 내내 벽 너머에서 뭔가가 벽을 사이에 두고 나란히 걷는 기척이 났다.`,
      win:{ exp:18, dream:2 }, lose:{ mind:-18, spirit:-18 } }
  ] },

{ at:'S', t:'잔해 밭 — 빈 무게',
  x:`무너진 잔해가 밭을 이뤘다. 밟는 자리마다 삐걱이고 구른다.<br><br>
    돌 하나가 구르면 잔해 전체가 도미노로 운다. 그 소리를 기다리는 것들이 잔해 밑에 산다.<br>
    들린 철판 밑, 기둥 틈. 소리가 나면 거기서 나온다.<br><br>
    몸을 바람 수준으로 비워야 지나는 길이다.`,
  o:[
    { l:'① 내공으로 무게를 비워 잔해 위를 걷는다.', k:'evade', dc:24, cost:{ qi:27 },
      ok:`기를 발끝으로 몰아 몸을 끌어올렸다. 무게가 반으로, 반의 반으로.<br><br>삐걱이는 판 위를 눈 얹히듯 디뎠다. 판은 울지 않았다. 잔해 밑 어둠들이 입을 벌린 채 기다리는 위를, 그 입들 모르게 지났다.<br>건너편 흙에 내려서자 무게가 돌아왔다. 무릎이 후들거렸다. 빈 무게는 공짜가 아니다. 그래도 소리보다 싸다.`,
      ng:`반쯤 건넜을 때 기가 바닥났다. 무게가 한꺼번에 돌아왔다.<br><br>철판이 쿵 울렸다. 잔해 전체가 도미노로 따라 울었다.<br>밑에서 올라오는 것들을 등지고 뛰었다. 판에서 판으로, 이제는 소리고 뭐고 없이. 마지막 판에서 발목을 접질렸다. 일행이 양팔을 꿰어 날랐다.`,
      win:{ exp:20, dream:3 }, lose:{ hp:-30, mind:-14 } },
    { l:'② 안 흔들리는 돌만 눈으로 먼저 깔아 길을 잇는다.', k:'gaze', dc:24,
      ok:`큰 돌이라고 안 구르는 게 아니다. 세 점이 땅에 닿은 돌이 안 구른다.<br><br>세 점 돌만 눈으로 이어 길을 그렸다. 열여덟 개. 그 열여덟 개만 밟았다.<br>일행에게는 밟을 돌마다 침 묻힌 돌가루로 점을 찍어 줬다. 다섯이 같은 열여덟 걸음으로 건넜다. 잔해 밑 어둠은 끝까지 어둠이었다.`,
      ng:`열여덟 개 중 아홉째가 거짓말을 했다. 세 점인 줄 알았는데 두 점이었다.<br><br>돌이 반 바퀴 굴렀다. 와르르. 밑에서 뭔가 철판을 들치는 소리.<br>남은 돌 아홉 개를 세 걸음처럼 건넜다. 등 뒤 잔해 틈마다 긴 팔들이 나와 허공을 쓸었다. 한 뼘 차이였다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-28, spirit:-15 } }
  ] },

{ at:'S', t:'맥박 — 따라 뛰는 맥',
  x:`한참 걷다 알았다. 맥이 이상하다.<br><br>
    이쪽 심장이 뛰면 반 박자 뒤에 어디선가 같은 울림이 따라 뛴다. 벽인지 바닥인지 모를 데서.<br>
    무언가 제 맥을 이쪽 맥에 맞추고 있다. 맥이 겹치면 못 듣는다. 제 심장 소리에 숨어 다가오는 것이다.<br><br>
    자객이 쓰는 수다. 당하는 건 처음이다.`,
  o:[
    { l:'① 맥을 한 박자 비틀어 저쪽 맥을 드러낸다.', k:'hide', dc:24, wake:1,
      ok:`내공으로 심장을 반 박자 눌렀다 놓았다. 엇박. 이쪽 맥이 비틀리는 순간 저쪽 맥이 허공에 혼자 남았다.<br><br>둥. 왼쪽 벽 안. 간격 세 걸음.<br>벽에서 떨어져 걸으며 엇박을 유지했다. 저쪽이 다시 맞추려고 맥을 올렸다 내렸다 하는 게 느껴졌다. 못 맞췄다. 박자를 쥔 쪽이 이기는 놀이다.<br><br>맥은 숨는 데도 쓰고 들추는 데도 쓴다. 심장이 연장이 된 날이다.`,
      ng:`엇박을 넣었는데 저쪽이 바로 따라왔다. 반 박자 비튼 것까지 그대로.<br><br>이쪽보다 귀가 좋은 것이다. 박자 싸움은 귀 좋은 쪽이 이긴다.<br>박자 대신 거리를 벌렸다. 뛰어서. 맥 겹치기는 간격이 벌어지면 못 한다. 벽 안의 울림이 끊길 때까지 한 식경을 뛰었다. 옆구리가 결렸다.`,
      win:{ exp:20, dream:3 }, lose:{ hp:-26, mind:-16 } },
    { l:'② 멈춰 서서 맥이 겹치는 자리를 일행에게 알린다.', k:'bond', dc:23,
      ok:`손짓으로 일행을 세웠다. 전원 정지. 심장만 뛰는 시간.<br><br>다섯 심장이 각자 뛰자 따라 뛰는 놈이 헷갈리기 시작했다. 다섯 박자를 한 번에 못 탄다.<br>헷갈린 울림이 벽 안에서 제 박자를 드러냈다. 전원이 그 자리를 안 채로 벽에서 먼 쪽으로 줄을 바꿨다. 아는 위협은 반만 위협이다.`,
      ng:`세우고 보니 막내 심장이 너무 빨랐다. 겁먹은 심장은 북이다.<br><br>따라 뛰던 놈이 그 북으로 갈아탔다. 벽 울림이 막내 쪽으로 옮겨 간다.<br>막내를 가운데 세우고 전원이 둘러싼 채 구역을 빠져나왔다. 벽 안의 것은 벽이 끝나는 데까지 따라왔다. 막내는 그날 밤 잠을 못 잤다.`,
      win:{ exp:16, dream:2 }, lose:{ mind:-17, spirit:-17 } }
  ] },

{ at:'S', t:'쉬는 자리 — 바닥 숨',
  x:`교대까지 한 시진. 눈을 붙여야 한다.<br><br>
    잠든 몸은 숨이 커진다. 뒤척이고, 이를 갈고, 코를 곤다. 잠이 제일 시끄럽다.<br>
    여기서는 자는 소리가 저녁 종이다.<br><br>
    자객의 토납은 깨어 있을 때 것이다. 잠든 뒤의 숨은 누가 다스리나.`,
  o:[
    { l:'① 바닥 숨을 몸에 새기고 잔다.', k:'steady', dc:23, wake:1,
      ok:`눕기 전에 토납을 백 번 돌려 숨길을 바닥까지 눌러 놓았다. 깊고, 가늘고, 코로만.<br><br>몸은 길든 대로 잔다. 백 번 간 길로 숨이 스스로 다녔다.<br>깨 보니 일행이 신기해했다. 자는지 죽었는지 몰랐다고. 숨소리가 없었다고.<br><br>깨어서 다스리던 숨이 잠 속까지 따라왔다. 수련이 몸에 앉으면 잠도 수련이 된다.`,
      ng:`숨길을 눌러 놓고 잤는데 꿈이 문제였다.<br><br>쫓기는 꿈. 꿈속에서 뛰니 숨이 뛰었다. 제 숨소리에 제가 깼다.<br>깨니 일행 불침번이 이쪽 입을 손으로 막고 있었다. 천장을 눈으로 가리키면서. 천장 배관 위에 뭔가 앉아 있다 갔다고 했다. 그 뒤로는 눕고도 한잠도 못 잤다.`,
      win:{ exp:18, dream:3, hp:6 }, lose:{ mind:-16, spirit:-16 } },
    { l:'② 일행의 숨도 하나씩 눌러 주고 잔다.', k:'heal', dc:23,
      ok:`코 고는 사람 둘의 턱 밑 혈을 지그시 눌러 숨길을 틔웠다. 고는 소리가 실숨으로 바뀌었다.<br><br>이 가는 사람 턱 관절도 풀어 줬다. 다섯이 다 가는 숨으로 잠들었다.<br>어둠 속에서 다섯 사람 숨이 하나로 포개졌다. 포개진 숨은 한 사람 숨이다. 큰 것 하나가 자는 소리. 여기서는 그게 제일 안전한 소리다.`,
      ng:`혈을 누르다 한 사람이 잠결에 소리를 질렀다. 억, 하고.<br><br>짧았지만 질렀다. 전원이 깼다.<br>그 뒤 반 시진을 무기 쥐고 어둠만 봤다. 아무것도 안 왔다. 안 온 게 더 무서운 밤이 있다. 잠은 다 설쳤다.`,
      win:{ exp:16, dream:2, mind:6 }, lose:{ mind:-15, spirit:-16 } }
  ] },

{ at:'S1', t:'표본실 — 찾는 것들',
  x:`천장 배관을 타고 그것들이 다닌다. 손바닥만 하고 꼬리가 길다.<br><br>
    깃들 집을 찾는 것들이다. 더운 맥을 찾아 내려와 얼굴에 붙는다. 벽의 마른 연구자들이 그 끝을 보여 준다.<br>
    저것들은 맥을 본다. 뛰는 맥을.<br><br>
    맥이 안 뛰는 것에는 안 내려온다. 죽은 집에는 세 안 든다.`,
  o:[
    { l:'① 맥을 땅 밑까지 낮춰 죽은 집이 된다.', k:'hide', dc:24, wake:1,
      ok:`걸으면서 맥을 낮췄다. 겨울 뱀의 맥까지. 눈은 뜨고, 발은 걷고, 심장만 긴 잠에 들었다.<br><br>천장의 것들이 이쪽 위에서 두 번 멈췄다. 내려올까 말까. 안 내려왔다. 비어 보이는 집에 세 들러 오는 놈은 없다.<br>통로 끝에서 맥을 올렸다. 피가 돌며 손끝이 저렸다.<br><br>걸으면서 맥을 재우는 법. 앉아서만 하던 것을 길 위에서 하게 됐다. 몸이 한 뼘 깊어졌다.`,
      ng:`맥을 낮추고 반쯤 지났을 때 발밑에 유리 조각이 밟혔다. 통증에 맥이 튀었다.<br><br>한 번 튄 맥은 종이다. 천장에서 두 마리가 실처럼 내려왔다.<br>구르면서 떨쳐 냈다. 한 마리가 소매에 꼬리를 감고 안 떨어져서 소매째 찢어 버렸다. 맨팔이 밤새 시렸다. 소매보다 맥 관리가 아쉬운 밤이었다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-27, mind:-15 } },
    { l:'② 천장의 것들이 모이는 맥을 거꾸로 읽는다.', k:'gaze', dc:23,
      ok:`저것들이 유난히 모여 도는 배관 구역이 있다. 맥을 보는 것들이 모인다는 건 — 그 밑에 큰 맥이 있다는 뜻이다.<br><br>그 구역 바닥을 멀리서 봤다. 바닥 배수구가 안쪽으로 젖어 있다. 아래층에 크고 더운 것이 산다.<br>그 위를 피해서 길을 그렸다. 저것들이 지도를 그려 준 셈이다. 세 들 집 찾는 것들은 목 좋은 데를 안다.`,
      ng:`읽으러 고개를 들고 있는 시간이 길었다. 선 것은 눈에 띈다.<br><br>배관의 것 하나가 이쪽 맥을 보고 실을 늘였다. 머리 위 한 뼘까지.<br>옆 사람이 멱살을 당겨 줘서 피했다. 실 끝이 어깨를 스쳤다. 스친 자리가 밤새 가려웠다. 긁지도 못하고.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-26, spirit:-16 } }
  ] },

{ at:'S1', t:'숙주 — 두 맥',
  x:`앞을 막은 넓은 방에 연구복 입은 사람들이 서 있다. 셋. 미동도 없다.<br><br>
    멀리서 기로 재니 맥이 여섯이다. 몸마다 둘씩. 사람 맥 하나, 그 밑에 빠르고 작은 맥 하나.<br>
    깃든 것들이다. 사람 맥은 느리고 고르다. 자는 맥. 깃든 맥이 집을 재워 놓은 것이다.<br><br>
    재워 놓고 — 기다린다. 더운 것이 지나가기를.`,
  o:[
    { l:'① 멀리서 여섯 맥의 박자를 다 읽고 길을 그린다.', k:'sense', dc:24,
      ok:`여섯 맥을 하나씩 짚었다. 깃든 맥 셋 중 둘은 느긋하고 하나가 급하다. 급한 맥이 깨어 있는 보초다.<br><br>보초 깃든 몸은 문 쪽. 느긋한 둘은 창 쪽. 길은 창 쪽 둘 사이다.<br>잠든 깃든 것 사이로 일행을 한 명씩 흘려보냈다. 급한 맥이 한 번 더 급해질 때마다 전원 정지. 방을 다 지나는 데 백 숨이 걸렸다. 여섯 맥은 끝까지 제자리였다.`,
      ng:`맥을 읽는 중에 급한 맥 하나가 뚝 멎었다.<br><br>죽은 게 아니다. 숨은 것이다. 읽히는 걸 안 것이다.<br>어느 몸에 들었는지 모르게 됐다. 셋 다 피해서 방 바깥 배관 턱으로 돌았다. 녹슨 턱이 발밑에서 두 번 울었다. 울 때마다 연구복 셋의 고개가 한 뼘씩 돌았다. 눈 감은 채로.`,
      win:{ exp:20, dream:3 }, lose:{ mind:-19, spirit:-18 } },
    { l:'② 깃든 맥만 점혈로 재운다 — 한 몸씩.', k:'break', dc:25,
      doom:{ title:'깨어난 집', what:'숙주의 팔에 안겨 안쪽 어둠으로 끌려갑니다', dc:19, sec:42,
        text:`첫째 몸 뒤로 붙어 가슴 밑 깃든 맥 자리에 손가락을 꽂았다. 작은 맥이 멎었다. 됐다.<br><br>둘째 몸으로 옮기는데 첫째 몸이 — 돌아섰다. 깃든 것이 멎자 재워 뒀던 사람 맥이 깬 것이다.<br>깬 것은 사람이 아니었다. 사람 모양으로 깃든 것이 오래 쓴 집이었다.<br><br>두 팔이 이쪽을 안았다. 뼈가 울리게. 그대로 방 안쪽 어둠으로 걸어간다. 집이 손님을 모시는 걸음으로. 안쪽에는 더 큰 맥이 기다린다.`,
        dieText:`방의 연구복은 다시 셋이 됐다.<br><br>셋 다 미동 없이 서 있다. 맥은 — 여덟이다.<br>몸마다 둘씩, 그리고 새 몸 하나에 둘. 새 몸의 사람 맥이 아직 고르지 않다. 길드는 중이다.`,
      },
      ok:`첫째 몸 뒤로 붙다가 멈췄다. 가슴 밑 작은 맥이 — 이쪽 손의 기를 마중 나왔다. 빨아들이려고.<br><br>점혈로 재울 맥이 아니다. 기를 먹는 맥이다. 손가락을 거뒀다.<br>대신 품의 마지막 육포를 기로 데워 방 반대 구석에 던졌다. 더운 맥 흉내. 세 몸이 일제히 그쪽으로 돌았다.<br><br>그 등 뒤로 일행을 빼냈다. 깃든 것은 손대지 않는 게 수다. 손대는 건 이 방 주인에게 미루기로 했다.`,
      win:{ exp:22, dream:3 } },
    { l:'③ 몸들이 바라보는 부채꼴 밖으로만 돈다.', k:'hide', dc:25,
      ok:`선 채 잠든 것들도 향이 있다. 가슴이 향한 쪽. 깃든 것은 가슴으로 본다.<br><br>세 가슴의 부채꼴을 그리고 그 바깥 띠로만 돌았다. 벽에 붙어, 반 걸음씩.<br>마지막 구간에서 셋째 몸의 가슴이 천천히 돌기 시작했다. 시계처럼. 도는 속도보다 반 걸음 빠르게 돌아 문을 나왔다. 등 뒤로 가슴 셋이 모두 문 쪽을 향해 멎는 기척이 났다. 늦은 배웅이었다.`,
      ng:`부채꼴 밖으로 도는데 바닥 턱에 무릎이 닿았다. 둔탁한 소리.<br><br>세 가슴이 한 번에 이쪽을 향했다. 눈은 감긴 채 가슴만.<br>벽에 붙어 돌이 됐다. 세 몸이 각자 한 걸음씩 다가오다 — 멈췄다. 더 안 왔다. 식은 것은 밥이 아니라서. 그렇게 반 시진을 벽으로 살았다.`,
      win:{ exp:20, dream:2 }, lose:{ mind:-18, spirit:-20 } }
  ] },

{ at:'S1', t:'통풍관 — 좁은 토납',
  x:`가야 할 구역이 무너져 통풍관이 유일한 길이다. 가슴이 눌리는 좁기.<br><br>
    좁은 데서는 숨이 운다. 가슴이 펴지지 못해 숨이 짧아지고, 짧은 숨은 관을 울린다.<br>
    관은 나팔이다. 숨 한 번이 구역 전체로 퍼진다.<br><br>
    관에 들기 전에 숨부터 고쳐야 한다.`,
  o:[
    { l:'① 배로만 쉬는 숨으로 바꿔 관을 긴다.', k:'steady', dc:24,
      ok:`가슴을 포기하고 배로만 쉬었다. 토납의 밑동 숨. 가슴은 바닥에 붙인 채 배만 한 치 부풀었다 꺼진다.<br><br>관이 울지 않았다. 팔꿈치 소리는 소매에 흙을 발라 죽였다.<br>다섯이 다 그 숨으로 지났다. 관을 나와 가슴을 펴자 갈비뼈가 우두둑 울었다. 그건 울어도 되는 자리에서 울었다.`,
      ng:`배 숨으로 반을 갔는데 관이 좁아졌다. 배도 못 부풀리는 좁기.<br><br>숨이 목으로 올라왔다. 목 숨은 운다. 흐윽, 흐윽.<br>관 저쪽 끝에서 무언가가 관에 머리를 넣는 소리가 났다. 울림으로 알았다. 남은 구간을 토할 듯이 기어 반대 뚜껑을 차고 나왔다. 전원이 나오고 뚜껑을 돌로 눌렀다. 밤새 그 관이 안에서 둥둥 울었다.`,
      win:{ exp:20, dream:3 }, lose:{ hp:-28, mind:-16 } },
    { l:'② 관 전체를 먼저 두드려 울림 지도를 만든다.', k:'sense', dc:23,
      ok:`들기 전에 관 바깥을 손끝으로 짚어 갔다. 울림이 둔한 데는 흙이 쌓인 데. 둔한 구간이 숨 쉬어도 되는 구간이다.<br><br>둔한 데 세 군데를 외워 두고 들어갔다. 숨은 그 세 군데서만 몰아쉬었다.<br>울림 지도 덕에 다섯이 숨 한 번 안 울리고 건넜다. 관도 두드려 보고 건너는 물건이다.`,
      ng:`두드려 보는 그 소리가 문제였다. 똑, 똑.<br><br>관 안에서 똑, 똑, 답이 왔다.<br>관은 접었다. 무너진 구역을 손으로 파서 넘었다. 반나절이 갔다. 손톱 두 개가 뒤집혔다. 관 속의 무엇과 악수하는 것보다는 나았다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-27, mind:-14 } }
  ] },

{ at:'S1', t:'산성 피 — 기막',
  x:`앞서 가던 일행이 작은 것을 밟아 터뜨렸다. 피가 튄다. 산이.<br><br>
    바닥에 떨어진 것은 돌을 끓이고, 벽에 묻은 것은 벽을 탄다.<br>
    튀는 쪽에 일행 얼굴이 있다.<br><br>
    생각보다 손이 먼저 나갔다.`,
  o:[
    { l:'① 내공을 손바닥에 펴서 핏방울을 받아 넘긴다.', k:'steady', dc:25, cost:{ qi:35 },
      ok:`손바닥에 기를 한 겹 폈다. 기름 먹인 가죽처럼.<br><br>날아오는 방울들을 손바닥 기막으로 받아 옆으로 흘렸다. 베듯이, 쓸듯이. 방울이 기막 위에서 한 번 끓고 바닥으로 미끄러졌다.<br>일행 얼굴에는 한 방울도 안 닿았다. 손바닥이 얼얼했다. 기막 너머로도 열은 온다. 열만 왔으면 된 것이다.`,
      ng:`기막을 폈는데 한 방울이 막 가장자리를 넘었다.<br><br>손목에 닿았다. 지진다. 이를 물고 소리를 삼켰다.<br>삼킨 덕에 조용하긴 했다. 손목에 동전만 한 화상이 남았다. 일행 얼굴은 지켰으니 남는 거래다. 손목은 그렇게 치기로 했다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-30, mind:-14 } },
    { l:'② 일행을 낚아채 방울 그늘 밖으로 함께 구른다.', k:'evade', dc:24,
      ok:`튀는 피에는 부채꼴이 있다. 터진 각도의 반대가 그늘이다.<br><br>일행 멱살을 쥐고 그늘 쪽으로 같이 굴렀다. 머리 위로 방울들이 지나가 벽에 박혔다. 벽이 치익 울었다.<br>구른 자리에서 둘 다 한참 누워 있었다. 벽에 뚫린 구멍 수를 세면서. 아홉 개였다. 아홉 개 중 하나도 살에 안 박혔다.`,
      ng:`구르는 방향이 반 뼘 어긋났다. 방울 하나가 일행 어깨 천을 스쳤다.<br><br>천이 녹아 살까지 닿기 전에 어깨 천을 통째로 찢어 던졌다.<br>살은 발개진 정도로 막았다. 천 조각은 바닥에서 연기가 되도록 끓었다. 저게 살이었으면, 하는 생각은 서로 입 밖에 안 냈다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-29, spirit:-15 } }
  ] },

{ at:'S1', t:'기밀문 — 귀가 우는 문',
  x:`기밀문 안팎의 공기 무게가 다르다. 문틈을 지날 때 귀가 먹먹해지다 뻥 뚫린다.<br><br>
    뚫릴 때 다들 저도 모르게 침을 삼키거나 코를 쥔다. 꿀꺽. 흡.<br>
    문 너머 어둠은 그 소리를 기다린다. 문을 지나는 것들이 꼭 내는 소리라서.<br><br>
    귀를 미리 달래 놓으면 소리도 없다.`,
  o:[
    { l:'① 일행 귓속 압을 혈로 미리 맞춰 준다.', k:'heal', dc:23,
      ok:`문에 들기 전에 한 사람씩 귀 밑과 턱 뒤 혈을 눌러 귓길을 열어 놨다.<br><br>문틈을 지날 때 먹먹함이 바로 흘러나갔다. 삼킬 침도, 쥘 코도 없었다.<br>다섯이 다 소리 없이 지났다. 문 너머 어둠이 헛물켜는 기척이 났다. 기다리던 소리가 안 와서.`,
      ng:`넷째 사람 혈이 덜 눌렸다. 문틈에서 그 사람 귀가 뻥 뚫리며 — 꿀꺽.<br><br>어둠이 그 소리를 받았다.<br>문 바로 안쪽 벽에 다섯이 붙어 어둠이 문 앞을 세 번 오가는 걸 들었다. 네 번째는 안 왔다. 넷째 사람이 밤새 미안해했다. 혈 짚은 손이 미안할 일이다.`,
      win:{ exp:18, dream:3 }, lose:{ mind:-17, spirit:-16 } },
    { l:'② 바람 새는 소리 속에 숨어 문턱을 넘는다.', k:'hide', dc:24,
      ok:`문이 돌 때 치익, 바람이 운다. 그 울음의 한복판에 몸을 넣었다.<br><br>바람 소리는 넓은 소리다. 사람 소리는 그 안에서 바늘이다. 넓은 천에 바늘을 숨기듯 지났다.<br>다섯 번의 치익에 다섯이 건넜다. 문이 다섯 번 숨 쉬는 동안 어둠은 문소리만 들었다. 늘 듣던 소리만.`,
      ng:`셋째 치익이 중간에 끊겼다. 문이 녹슬어 반만 운 것이다.<br><br>바람 소리 밖으로 발소리 반 걸음이 알몸으로 샜다.<br>문 너머 어둠이 바닥을 쓸며 다가왔다. 문짝 뒤에 붙어 그것이 문틈 냄새를 길게 맡는 동안 숨을 잠갔다. 문이 다시 치익 울자 그 소리에 업혀 빠졌다. 문 덕에 살았다. 두 번이나.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-26, spirit:-17 } }
  ] },

{ at:'S1', t:'여왕의 맥',
  x:`벽에 손을 대면 느껴진다. 아주 크고 아주 느린 맥. 건물 전체가 그 맥으로 뛴다.<br><br>
    여왕이다. 어디 있는지는 모른다. 어디에나 있다. 바닥에도, 배관에도, 공기에도.<br>
    여기 것들은 그 맥 속에서 산다. 그 맥과 다른 박자가 그것들 귀에는 불협화음이다.<br><br>
    다른 박자. 이쪽 심장 같은 것.`,
  o:[
    { l:'① 심장을 여왕의 맥에 포갠다.', k:'steady', dc:25, wake:1,
      ok:`벽의 맥을 손바닥으로 받아 외웠다. 둥 — — — 둥. 사이가 아홉 숨인 맥.<br><br>심장을 그 박자의 결 위에 올렸다. 맥을 맞추는 게 아니라 그 큰 맥의 잔물결인 척하는 것이다. 아홉 숨마다 이쪽 맥이 여왕 맥 속에 한 번씩 포개져 지워진다.<br>그 박자로 두 구역을 지났다. 지나는 동안 여기 것들이 이쪽을 제 식구 숨결처럼 스쳐 다녔다.<br><br>큰 맥 속에 작은 맥을 심는 법. 숨는 자리가 꼭 그늘일 필요는 없다. 남의 심장 속도 자리다.`,
      ng:`포개고 두 구역째, 여왕의 맥이 갑자기 빨라졌다.<br><br>무슨 일이 있는 것이다. 이쪽 심장이 못 따라갔다. 박자가 벗겨지며 이쪽 맥이 알몸으로 드러났다.<br>가까운 배관에서 두 마리가 머리를 빼 들었다. 불협화음을 들은 얼굴로. 좁은 틈에 끼어 반 시진을 버텼다. 여왕의 맥이 다시 느려질 때까지. 심장이 녹초가 됐다.`,
      win:{ exp:24, dream:3 }, lose:{ hp:-28, spirit:-18 } },
    { l:'② 맥을 거슬러 여왕의 자리를 짚는다.', k:'gaze', dc:25,
      doom:{ title:'큰 맥', what:'맥에 홀린 채 일꾼들에게 들려 아래로 실려 갑니다', dc:20, sec:38,
        text:`맥이 짙어지는 쪽을 짚으며 걸었다. 아래로, 아래로. 지도에 없는 비탈 통로.<br><br>맥이 커질수록 귀가 아니라 가슴으로 들렸다. 어느 순간 이쪽 심장이 그 맥을 따라 뛰고 있었다. 맞춘 게 아니라 끌려간 것이다.<br>걸음도 끌려갔다. 비탈 아래로. 제 발로, 제 발 아니게.<br><br>어깨에 긴 팔들이 얹혔다. 일꾼들. 놀라지도 않은 손길로 이쪽을 들어 올린다. 맥 쪽으로 실어 나른다. 큰 맥은 제 박자로 오는 것을 제 것으로 안다.`,
        dieText:`비탈 통로 아래에서 큰 맥이 한 번 깊게 뛰었다.<br><br>흡족한 박자였다.<br>건물의 맥이 그날 하루 아주 조금 커졌다. 벽에 손을 대 본 사람만 알 차이로.`,
      },
      ok:`맥이 짙어지는 쪽을 세 구역 짚다가 손을 뗐다. 맥이 가슴을 당기기 시작한 것이다. 듣는 귀가 끌려가는 귀가 되는 경계였다.<br><br>짚은 데까지로 지도를 그렸다. 맥은 북동쪽 아래로 모인다. 여왕은 지하 북동쪽. 가는 길이 아니라 피하는 길을 그리기 위한 지도다.<br>일행에게 북동쪽 내리막을 전부 금지선으로 박아 줬다. 아는 만큼 피한다. 더 아는 건 욕심이었다.`,
      win:{ exp:22, dream:3 } }
  ] },

{ at:'S1', t:'알 — 더운 맥 곁에서',
  x:`지나야 할 창고 구석에 알주머니 여남은 개가 붙어 있다.<br><br>
    알은 귀가 없다. 대신 맥을 느낀다. 더운 맥이 다가가면 주머니 속의 것이 깬다.<br>
    깬 것은 운다. 울음은 어미를 부른다.<br><br>
    다섯 사람 맥 중 넷은 다스릴 줄 모르는 맥이다.`,
  o:[
    { l:'① 일행 손목을 쥐고 맥을 같이 낮춰 지난다.', k:'bond', dc:24,
      ok:`앞사람 손목을 쥐었다. 손목의 기 길로 이쪽의 느린 맥을 흘려 넣었다. 느린 맥은 옮는다. 재울 때 옆에서 느리게 숨 쉬어 주는 것과 같다.<br><br>둘씩 손목을 이어 다섯이 한 줄 느린 맥이 됐다.<br>알주머니들 곁을 지나는 동안 주머니 속 것들은 뒤척이지 않았다. 지나고 손을 놓자 다들 제 맥으로 돌아가며 한꺼번에 하품을 했다. 느린 맥은 졸리다.`,
      ng:`셋째 사람 맥이 안 내려갔다. 겁이 많은 맥이었다.<br><br>그 맥이 지나갈 때 주머니 하나가 꿈틀했다. 속에서 돌아눕는 그림자.<br>전원이 맥이고 뭐고 발끝으로 뛰었다. 주머니는 도로 잠들었다. 운 좋게 설잠이었다. 창고를 나와서 셋째 사람이 제일 크게 숨을 몰아쉬었다. 이제야 울리는 맥으로.`,
      win:{ exp:20, dream:3 }, lose:{ mind:-18, spirit:-16 } },
    { l:'② 알들이 느끼는 반경을 재서 금 밖으로 돈다.', k:'hide', dc:24,
      ok:`데운 돌을 긴 장대 끝에 묶어 알주머니 쪽으로 천천히 밀었다. 주머니가 꿈틀한 거리에서 멈춤. 그게 금이다.<br><br>돌을 거두고 금에서 두 걸음 밖으로 길을 그었다. 벽을 타는 구간이 두 군데.<br>다섯이 금 밖으로만 돌았다. 알은 금 안의 세상만 안다. 금 밖은 알에게 없는 세상이다. 없는 세상에서 걸었다.`,
      ng:`금을 재던 장대가 길었다. 끝이 주머니 하나를 건드렸다.<br><br>주머니가 출렁이고, 속엣것이 벽을 긁었다. 가늘고 급한 소리.<br>어미 울음이 오기 전에 전원이 창고를 가로질러 뛰었다. 금이고 뭐고 없이. 등 뒤 멀리서 묵직한 것이 창고로 내려앉는 소리를 들으며 문을 닫았다. 장대는 두고 왔다. 잘 쓰던 장대였는데.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-27, mind:-15 } }
  ] },

{ at:'S2', t:'울타리 — 철선의 떨림',
  x:`울타리 철선에 손끝을 대면 떨림이 읽힌다.<br><br>
    먼 데서 그것들이 철선을 건드리는 떨림, 바람 떨림, 그리고 아무것도 아닌 떨림.<br>
    살기를 읽던 손이다. 떨림도 결국 같은 글이다. 어디서, 얼마나 세게, 무슨 마음으로.<br><br>
    철선이 이 정원의 신문이다.`,
  o:[
    { l:'① 철선에 손을 얹고 그것들의 위치를 받아 적는다.', k:'sense', dc:23, wake:1,
      ok:`손끝에 기를 모아 철선에 얹었다. 떨림이 손금으로 흘러든다.<br><br>북쪽 먼 데서 꾸준한 떨림 — 점검하는 놈들. 서쪽에 간헐적인 큰 떨림 — 큰 것이 지나며 땅으로 전한 것. 남쪽은 조용하다.<br>남쪽으로 길을 잡았다. 철선이 알려 준 대로였다.<br><br>살기 없는 것들의 살기를 철이 대신 전한다. 읽을 수 없는 상대면 상대가 딛는 세상을 읽으면 된다.`,
      ng:`읽는 중에 철선이 크게 한 번 울었다. 가까이서 누가 세게 당긴 것이다.<br><br>이쪽 손끝의 기도 그 순간 철선을 타고 나갔다. 떨림은 양방향이다.<br>당긴 놈이 철선에 코를 대는 기척이 전해져 왔다. 이쪽 기 냄새를 읽는 것이다. 손을 떼고 그 구역을 떴다. 신문을 같이 보는 사이가 됐다. 달갑지 않은 구독자다.`,
      win:{ exp:20, dream:3 }, lose:{ mind:-18, spirit:-17 } },
    { l:'② 철선을 안 건드리는 저것들 틈에 끼어 따라 걷는다.', k:'hide', dc:24,
      ok:`점검하는 놈들은 철선과 늘 같은 거리를 두고 걷는다. 몸이 외운 거리.<br><br>그 거리의 바깥쪽, 놈들 행렬의 그림자 자리에 끼어 같은 박자로 걸었다. 행렬은 제 안쪽만 살핀다.<br>울타리 반 바퀴를 놈들 등에 업혀 돌았다. 갈라지는 길목에서 소리 없이 떨어져 나왔다. 놈들은 식구가 하나 줄어든 줄도 모를 것이다. 는 줄도 몰랐으니까.`,
      ng:`행렬 박자에 끼어 백 걸음, 맨 뒤 놈이 문득 걸음을 늦췄다.<br><br>행렬은 제 박자가 흔들리면 안다. 이쪽 걸음이 반의반 박자 길었던 것이다.<br>놈이 돌아보기 전에 풀숲에 가라앉았다. 행렬 전체가 멈춰 한참 주위를 재다 다시 걸었다. 풀숲에서 나온 건 반 시진 뒤였다. 다리가 남의 다리 같았다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-26, spirit:-18 } }
  ] },

{ at:'S2', t:'물밑 — 잠긴 숨',
  x:`물가에 그것들이 모여 물을 마신다. 지나는 길은 그 물가뿐이다.<br><br>
    물속으로 질러가는 수가 있다. 물은 냄새를 지우고 모습을 가린다.<br>
    문제는 숨이다. 물낯에 숨 거품이 오르면 끝이다.<br><br>
    토납으로 숨을 가두면 백 숨은 간다. 백 숨 안에 건너야 한다.`,
  o:[
    { l:'① 내공으로 숨을 가두고 바닥을 걸어 건넌다.', k:'steady', dc:25, cost:{ qi:36 },
      ok:`들숨을 단전까지 눌러 담고 물에 들었다. 떠오르지 않게 돌을 하나 안고.<br><br>물 밑바닥을 걸었다. 천천히, 거품 한 알 안 새게. 머리 위로 그것들의 긴 목이 물을 긷는 그림자가 지나갔다.<br>아흔 숨에 건너편 갈대 틈으로 코만 내밀었다. 소리 없이 숨을 갈았다. 물가의 것들은 물만 마셨다. 물속에 뭐가 지나간 줄도 모르고.`,
      ng:`일흔 숨째에 안은 돌이 물밑 바위에 닿았다. 톡.<br><br>물속 소리는 물 위보다 멀리 간다. 긴 목 하나가 물속에 쑥 들어왔다. 세 걸음 옆에.<br>바닥에 엎드려 수초 틈에 끼었다. 목이 물속을 두 번 휘젓고 나갔다. 남은 숨 열로 서른 숨 거리를 기었다. 뭍에 나와 한참 토했다. 물도 숨도.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-30, mind:-15 } },
    { l:'② 물 마시는 틈을 노려 물낯에 뜬 채 흘러 지난다.', k:'hide', dc:26,
      doom:{ title:'물가의 턱', what:'물째 물려 깊은 쪽으로 끌려 들어가 가라앉습니다', dc:20, sec:36,
        text:`통나무처럼 반듯이 떠서 물살에 몸을 실었다. 마시는 놈들 사이로 떠내려가는 나무 한 토막.<br><br>반쯤 지났을 때 물가 맨 끝 놈이 고개를 들었다. 마시던 놈이 아니다. 기다리던 놈이다.<br>물 마시는 자리에는 꼭 하나, 안 마시는 놈이 선다. 그걸 알면서 잊었다.<br><br>턱이 물째 이쪽을 물었다. 통나무가 아닌 건 물면 안다. 깊은 쪽으로 끌려 들어간다. 물낯이 멀어진다. 거품이 마지막 숨만큼 올라갔다.`,
        dieText:`물가의 것들이 마시기를 멈추고 깊은 쪽을 한참 봤다.<br><br>물낯이 잠잠해지자 다시 마셨다.<br>물은 곧 전처럼 맑아졌다. 물은 늘 제일 먼저 시치미를 뗀다.`,
      },
      ok:`뜨기 전에 물가를 한 번 더 셌다. 마시는 놈 여섯 — 그리고 하나는 안 마신다. 고개를 든 채 물낯만 본다. 보초다.<br><br>물낯 길은 접었다. 보초의 눈높이 아래, 물속 바닥 길로 바꿨다.<br>건너편에 닿아 돌아보니 보초는 그대로 물낯을 보고 있었다. 제 일을 아는 놈이었다. 이쪽도 제 일을 알아서 다행이었다.`,
      win:{ exp:22, dream:3 } }
  ] },

{ at:'S2', t:'울음 — 박자 읽기',
  x:`숲 여기저기서 그것들이 운다. 짧게, 길게, 끊어서.<br><br>
    새소리 같지만 새가 아니다. 서로 주고받는 수다. 사냥 무리의 수다.<br>
    자객은 모르는 말도 박자로 읽는다. 문답의 길이, 되풀이, 급해지는 결.<br><br>
    말은 몰라도 마음은 박자에 실려 온다.`,
  o:[
    { l:'① 울음의 박자에서 찾았다는 신호를 가려낸다.', k:'gaze', dc:24, wake:1,
      ok:`반 시진을 들었다. 평소 수다는 묻고 답이 느리다. 긴 울음에 긴 울음.<br><br>딱 한 번, 짧은 울음 둘이 겹치고 사방이 한 숨 조용해졌다. 그리고 전부 그 자리로 몰렸다. 그게 찾았다는 말이다. 짧게 둘, 그리고 침묵.<br>그 뒤로는 그 신호만 지키며 걸었다. 두 번 울렸다. 두 번 다 이쪽 말고 다른 사냥감 자리였다. 남의 흉사가 이쪽 지도가 됐다.<br><br>말 모르는 상대의 말을 박자로 받아 적는 귀. 사람 말만 엿듣던 귀가 숲의 말도 듣게 됐다.`,
      ng:`박자를 받아 적는데 어느 순간 울음들이 뚝 — 그쳤다.<br><br>전부 한꺼번에. 그게 무슨 뜻인지 몰랐다. 모르는 침묵이 제일 나쁘다.<br>움직임을 전부 죽이고 기다렸다. 머리 위로 날개 큰 것이 소리 없이 지나갔다. 땅의 것들이 하늘의 것 때문에 입을 닫은 것이었다. 그 수다 목록에는 없던 장이었다.`,
      win:{ exp:20, dream:3 }, lose:{ mind:-18, spirit:-16 } },
    { l:'② 평소 수다 박자일 때만 움직인다.', k:'hide', dc:24,
      ok:`수다가 느릿느릿 오갈 때는 아무도 사냥 중이 아니다. 그때만 걸었다.<br><br>울음이 빨라지면 정지. 느려지면 다시 걸음. 숲의 수다가 이쪽 신호등이었다.<br>세 구역을 그 신호로 지났다. 사냥 무리와 한 번도 마주치지 않았다. 마주치지 않는 것, 그게 이 장사의 만점이다.`,
      ng:`느린 수다를 믿고 걷는데 발밑에서 마른 가지가 터졌다.<br><br>사방 울음이 그 순간 짧아졌다. 물음표 여럿이 이쪽으로 쏟아졌다.<br>바위 틈에 몸을 꺾어 넣고 숨을 잠갔다. 물음표들이 답을 못 받자 하나둘 흩어졌다. 마지막 놈은 바위 위를 밟고 지나갔다. 무게가 바위를 통해 등뼈로 내려왔다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-27, spirit:-16 } }
  ] },

{ at:'S2', t:'큰 것 — 발밑의 박자',
  x:`땅이 이따금 울린다. 큰 것의 걸음이다. 몸은 숲 너머에 있어 안 보인다.<br><br>
    발바닥에 기를 내려 울림을 받으면 더 많은 게 읽힌다. 걸음의 방향, 무게가 실리는 발, 멈춰서 귀 기울이는 사이.<br>
    저것도 듣는다. 땅으로. 이 정원에서 땅은 모두의 귀다.<br><br>
    같은 귀를 쓰는 사이라면, 박자를 빌릴 수도 있다.`,
  o:[
    { l:'① 큰 것의 걸음 울림에 일행의 걸음을 포갠다.', k:'steady', dc:24, wake:1,
      ok:`울림이 올 때만 다섯이 같이 걸었다. 쿵 — 다섯 걸음. 쿵 — 다섯 걸음.<br><br>큰 울림 속에 작은 울림 다섯이 묻힌다. 땅의 귀에는 큰 것 하나가 걸을 뿐이다.<br>큰 것이 멈추면 다섯도 멈췄다. 저것이 귀 기울이는 동안 숲 전체가 숨을 죽였고, 다섯도 숲이 됐다.<br><br>남의 걸음을 지붕 삼아 걷는 법. 큰 것 곁이 오히려 안전하다는 셈. 여기서만 통하는 셈은 아닐 것이다.`,
      ng:`포개 걷다가 큰 것이 갑자기 방향을 틀었다. 울림이 커진다. 이쪽으로 오는 것이다.<br><br>포개기는 저쪽이 멀 때 얘기다. 가까우면 지붕이 아니라 발바닥이다.<br>직각으로 꺾어 바위 지대로 뛰었다. 등 뒤로 나무 부러지는 소리가 지나갔다. 큰 것은 이쪽을 본 게 아니라 제 길을 간 것이었다. 그 길이 하필 이쪽 길이었을 뿐.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-28, mind:-15 } },
    { l:'② 울림으로 큰 것의 길을 그려 피해 돈다.', k:'sense', dc:23,
      ok:`발바닥 기로 반 시진 치 울림을 받아 적었다. 큰 것은 아무렇게나 걷지 않는다. 물가 — 양지 — 숲 가장자리. 도는 길이 있다.<br><br>그 길을 지도에 겹쳐 그리고, 길과 길 사이 빈 때를 골라 교차 구간을 지났다.<br>한 번은 울림이 예정보다 빨라 바위 뒤에서 한 식경을 보냈다. 지도는 산 것이라 자꾸 고쳐 그려야 한다. 고쳐 그리는 동안은 살아 있다는 뜻이다.`,
      ng:`울림 지도를 그리는데 울림이 둘이 됐다.<br><br>큰 것이 — 둘이다. 하나 몫으로 그리던 지도가 통째로 틀렸다.<br>둘의 길이 겹치는 자리에서 하마터면 마주칠 뻔한 것을, 둘이 서로를 향해 우는 바람에 알고 피했다. 큰 것들의 일은 큰 것들끼리 보게 두고 그 밤은 멀리 돌았다.`,
      win:{ exp:18, dream:2 }, lose:{ mind:-17, spirit:-18 } }
  ] },

{ at:'S2', t:'사냥 자리 — 식지 않은 것',
  x:`길목에 사냥 자리가 있다. 큰 것이 잡아 반쯤 먹고 둔 것.<br><br>
    김이 아직 오른다. 피 냄새가 바닥에 깔려 흐른다.<br>
    먹다 둔 것은 돌아와서 마저 먹는다. 그게 사냥의 법이다.<br>
    지나는 길이 하필 그 상 옆이다.`,
  o:[
    { l:'① 피 냄새의 흐름을 읽어 냄새 바깥 결로 돈다.', k:'hide', dc:24,
      ok:`냄새는 물처럼 흐른다. 낮은 데로, 바람 따라.<br><br>풀씨를 던져 바람 결을 읽고, 피 냄새가 고이는 고랑을 피해 둔덕 쪽 마른 결로 돌았다. 이쪽 냄새가 피 냄새 강에 안 섞이게.<br>상 주인이 돌아오는 울림이 등 뒤에서 났다. 주인은 제 상의 냄새만 맡았다. 상 옆을 지난 마른 냄새 한 줄은 못 맡았다. 강가에서 실개천은 안 보이는 법이다.`,
      ng:`마른 결로 도는데 신발 밑창에 아까 묻은 진흙이 피 고랑에 한 점 떨어졌다.<br><br>이쪽 냄새 한 점이 피 냄새 강에 떴다.<br>상 주인이 돌아와 그 한 점에서 오래 멈췄다. 콧김이 풀을 눕혔다. 둔덕 너머에 엎드린 채, 주인이 상을 다 비우고 그 한 점을 끝까지 못 풀고 떠날 때까지 기다렸다. 반나절이 갔다.`,
      win:{ exp:20, dream:3 }, lose:{ mind:-18, spirit:-17 } },
    { l:'② 상에서 한 점 얻어 간다 — 주인이 오기 전에.', k:'break', dc:25,
      doom:{ title:'상 주인', what:'상째 물려 가 주인의 먹이 자리로 끌려갑니다', dc:20, sec:38,
        text:`칼로 뒷다리 쪽 한 점을 떴다. 빠르게, 깨끗하게.<br><br>뜨는 순간 땅울림이 왔다. 가깝다. 주인은 상을 멀리 두고 다니지 않는다. 그것도 사냥의 법이다.<br>수풀이 갈라지며 그늘이 상 위로 덮였다. 상과, 상 옆의 이쪽 위로.<br><br>목덜미 옷이 통째로 물렸다. 들린다. 상 주인은 상에 온 것을 가리지 않는다. 고기 한 점 쥔 채로 먹이 자리로 실려 간다. 상차림의 일부로.`,
        dieText:`사냥 자리의 상이 비워졌다.<br><br>뼈 몇 대와, 주인 입에 안 맞은 쇠붙이 몇 점이 남았다. 칼 한 자루도.<br>칼은 녹이 슬 때까지 거기 있을 것이다. 다음 지나는 사람이 교훈으로 줍기 좋게.`,
      },
      ok:`칼을 대기 전에 땅에 손바닥을 붙였다. 울림 없음. 주인은 멀다. 물 마시러 간 참일 것이다.<br><br>뒷다리 쪽 한 점을 떴다. 상이 흐트러지지 않게, 먹던 자리 반대쪽에서. 주인은 제가 먹던 자리만 외운다.<br>기름천에 싸서 품에 넣고 그 자리를 떴다. 요리사가 보면 눈이 커질 고기다. 큰 것이 잡은 것은 큰 것만 먹으라는 법은 — 사실 있다. 오늘만 어겼다.`,
      win:{ exp:20, dream:2, item:'짐승 고기' } }
  ] },

{ at:'S2', t:'낡은 승강기 — 우는 줄',
  x:`승강기 권양 줄이 바람에 운다. 웅 — 웅 —<br><br>
    줄의 울음은 철탑을 타고 땅으로 내려간다. 땅은 모두의 귀다.<br>
    사람이 매달리면 줄은 다른 소리로 운다. 무게의 소리. 여기 것들이 모르는 새 소리.<br>
    새 소리는 조사 대상이다. 타는 동안이 제일 위험하다.`,
  o:[
    { l:'① 내공으로 줄의 떨림을 눌러 잡고 일행을 태운다.', k:'steady', dc:25, cost:{ qi:38 },
      ok:`줄에 양손을 얹고 기를 흘려 떨림을 받았다. 떨림이 손으로 들어와 몸에서 죽는다. 사람이 피뢰침이 된 셈이다.<br><br>일행이 타고 오르는 동안 줄은 평소 울음만 울었다. 웅 — 웅 — 무게 소리는 전부 이쪽 몸이 삼켰다.<br>마지막에 이쪽이 뛰어올라 탔다. 삼킨 떨림에 이가 밤새 시큰거렸다. 이빨값으로 다섯이 탔다. 헐값이다.`,
      ng:`떨림을 받다가 기가 꺾였다. 줄이 한 번 크게 텅 — 울었다.<br><br>숲 가장자리 풀들이 일제히 누웠다. 낮은 것들이 달려오는 길이다.<br>전원 승강기로 뛰었다. 격자문을 닫는 순간 첫 놈이 철탑 다리를 긁었다. 승강기가 덜컹대며 올랐다. 밑에서 철탑이 한참 긁히는 소리가 올라왔다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-30, mind:-14 } },
    { l:'② 바람이 제일 크게 우는 때에 맞춰 나눠 탄다.', k:'hide', dc:24,
      ok:`바람이 몰려올 때 줄 울음이 커진다. 그 큰 울음에 무게 소리를 묻었다.<br><br>바람 한 자락에 둘, 다음 자락에 둘, 마지막에 하나.<br>줄은 바람 소리만 냈다. 숲의 귀들에게 오늘 승강기는 어제의 승강기였다. 어제와 같은 것은 조사하지 않는다.`,
      ng:`셋째 자락이 늦었다. 바람 빈 틈에 둘이 매달렸다.<br><br>줄이 무게 소리를 알몸으로 냈다. 퉁 — 퉁 —<br>숲에서 긴 목 하나가 솟아 철탑을 봤다. 전원이 바닥에 납작 붙은 채 승강기가 다 오를 때까지 그 목과 눈싸움을 했다. 눈이 없는 쪽이 이기는 싸움이었다. 다행히 저쪽도 눈이 나빴다.`,
      win:{ exp:18, dream:2 }, lose:{ mind:-17, spirit:-18 } }
  ] },

{ at:'S2', t:'둥지 흙더미 — 새끼들의 귀',
  x:`길목에 흙더미 둥지가 있다. 안에서 새끼들이 잔다.<br><br>
    새끼는 어미보다 귀가 밝다. 그리고 뭐든 들리면 운다. 우는 건 어미를 부르는 종이다.<br>
    어미는 멀리 있지 않다. 어미는 늘 멀리 있지 않다.<br><br>
    둥지 곁 스무 걸음이 이 길의 전부다.`,
  o:[
    { l:'① 맥과 숨을 재우고 잠결 수준으로 지난다.', k:'steady', dc:24,
      ok:`새끼 귀에 걸리는 건 깨어 있는 것의 소리다. 맥, 숨, 당긴 심줄.<br><br>전부 잠의 수준으로 내렸다. 자면서 걷는 것처럼. 스무 걸음을 스무 번의 선잠처럼 디뎠다.<br>둥지 속 새끼 하나가 잠꼬대로 끼룩였다. 이쪽 발소리에 운 게 아니라 제 꿈에 운 소리였다. 어미는 안 왔다. 어미도 그 차이는 안다.`,
      ng:`열다섯 걸음째에 무릎 관절이 뚝 울었다. 몸은 재웠는데 뼈가 안 잤다.<br><br>새끼 둘이 깨어 끼룩끼룩 울었다.<br>남은 다섯 걸음을 세 걸음에 건너뛰고 바위 뒤로 굴렀다. 어미의 그늘이 금세 둥지를 덮었다. 어미가 둥지를 한 바퀴 돌고 새끼를 다독여 재우는 동안, 바위 뒤에서 무릎을 원망했다.`,
      win:{ exp:20, dream:3 }, lose:{ hp:-27, mind:-15 } },
    { l:'② 어미가 둥지를 비우는 때를 기다려 지난다.', k:'sense', dc:24,
      doom:{ title:'둥지의 어미', what:'어미에게 물려 둥지 흙더미 속으로 끌려 들어갑니다', dc:19, sec:40,
        text:`땅울림으로 어미의 자리를 쟀다. 멀어진다. 사냥 나가는 울림. 지금이다.<br><br>둥지 곁을 지나는데 새끼 하나가 흙더미 밖으로 머리를 내밀었다. 눈이 마주쳤다.<br>새끼는 안 울었다. 대신 이쪽을 향해 입을 벌렸다. 먹이를 받는 입이었다. 어미 아닌 것이 먹이를 안 주자 — 그때 울었다.<br><br>울림이 돌아왔다. 사냥 나가던 울림이 배는 빠르게. 어미 턱이 이쪽 어깨를 물고 둥지로 끌었다. 새끼들 사이로. 먹이를 달라고 벌린 입들 사이로.`,
        dieText:`둥지 흙더미가 한나절 들썩였다.<br><br>새끼들은 그날 밤 울지 않았다. 배부른 둥지는 조용하다.<br>어미는 다음 날도 사냥을 나갔다. 둥지 곁 길목은 전과 같이 길목이다.`,
      },
      ok:`땅울림으로 어미를 쟀다. 멀어진다 — 그런데 울림이 둘이다. 하나는 멀어지고 하나는 둥지 뒤 수풀에 남아 있다.<br><br>어미가 둘이거나, 아비가 있거나. 어느 쪽이든 둥지는 빈 적이 없다.<br>길목을 접고 둥지 반대편 가시덤불 쪽으로 돌았다. 가시에 옷이 세 군데 찢겼다. 옷으로 끝나는 길이 맞는 길이다.`,
      win:{ exp:22, dream:3 } }
  ] }

]);

// ── 그림자술사 (shadow) · 마력 ──
kJob('shadow', 'S', [

{ at:'S', t:'어둠 — 그림자가 없는 곳',
  x:`그림자술사의 연장은 그림자다. 빛이 있어야 생기는 연장.<br><br>
    여기는 빛이 없다. 그러니 그림자도 없다. 연장 없이 들어온 셈이다.<br>
    한참을 그렇게 걷다가 문득 멈췄다.<br><br>
    그림자가 없는 게 아니다. 여기는 전부가 그림자다. 한 장짜리, 방만 한 그림자.`,
  o:[
    { l:'① 어둠 전체를 한 장의 그림자로 쥐어 본다.', k:'hide', dc:24, wake:1,
      ok:`손끝에 마력을 걸고, 발밑의 제 그림자를 쥐듯 어둠의 가장자리를 쥐었다.<br><br>잡혔다. 무겁다. 방만 한 그림자가 통째로 손에 걸렸다. 접지는 못한다. 다만 그 안에서는 이쪽이 그림자 속의 것이다. 그림자 속의 것은 그림자술사의 식구다.<br>그 식구 자격으로 걸었다. 어둠이 이쪽 발소리를 제 소리로 쳐 줬다.<br><br>그림자가 작아야 쓴다는 생각을 버렸다. 세상에서 제일 큰 그림자 속에 서 있었던 것이다.`,
      ng:`어둠의 가장자리를 쥐는데 — 안에서 마주 쥐었다.<br><br>이 큰 그림자에는 먼저 든 식구들이 있다. 마력 줄을 타고 차가운 것이 손목까지 올라왔다.<br>줄을 끊고 물러났다. 손목에 쥔 자국이 멍으로 남았다. 남의 집 어둠을 함부로 쥐면 안 된다는 걸 손목이 배웠다.`,
      win:{ exp:20, dream:3 }, lose:{ mind:-18, spirit:-20 } },
    { l:'② 품의 등불을 꺼내 작은 그림자부터 되찾는다.', k:'fix', dc:23,
      ok:`등불 심지를 손톱만큼만 올렸다. 발밑에 그림자가 돌아왔다. 연하게, 그러나 이쪽 것이.<br><br>그 작은 그림자를 바늘 삼아 일행 발밑에도 하나씩 떠 줬다. 어두운 데서 제 그림자가 있으면 사람은 덜 무너진다.<br>빛은 손바닥으로 가려 바닥으로만 흘렸다. 바닥을 기는 빛은 멀리서 안 보인다.`,
      ng:`심지를 올리는데 손이 떨려 빛이 한 번 출렁였다.<br><br>출렁인 빛이 벽을 핥았다. 벽 저쪽에서 무언가가 그 빛을 봤다.<br>등불을 품에 묻고 전원이 벽을 등졌다. 어둠 속에서 긴 것이 벽을 따라 두 번 오갔다. 불빛 자리를 재는 걸음이었다. 세 번째는 없었다. 그 세 번째를 밤새 기다렸다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-26, mind:-15 } }
  ] },

{ at:'S', t:'등불 — 여섯 그림자',
  x:`쉬는 참에 등불을 가운데 두고 다섯이 둘러앉았다.<br><br>
    벽에 그림자가 진다. 세어 본다. 여섯.<br>
    다섯 사람에 여섯 그림자. 하나가 남는다. 남는 하나는 아무에게도 안 붙어 있다.<br><br>
    그림자술사의 눈은 그림자부터 센다. 세는 버릇이 오늘 일행을 살렸는지도 모른다.`,
  o:[
    { l:'① 남는 그림자의 주인 자리를 거꾸로 계산한다.', k:'gaze', dc:24,
      ok:`그림자는 빛과 주인을 잇는 선 위에 선다. 여섯째 그림자와 등불을 선으로 이으면 — 주인은 천장 들보 위다.<br><br>고개를 안 들고 마력로 제 그림자를 늘여 들보 밑을 쓸었다. 그림자 끝에 무게가 걸렸다. 있다.<br>일행에게 눈짓 셋. 등불을 중심으로 천천히 자리를 옮겼다. 여섯째 그림자가 벽에서 점점 얇아지다 사라졌다. 들보 위 것이 빛의 각도 밖으로 물러난 것이다. 물러나는 걸 확인하고야 등을 벽에 붙였다.`,
      ng:`선을 계산하는 사이 여섯째 그림자가 벽에서 한 뼘 움직였다.<br><br>주인이 움직이면 그림자가 움직인다. 주인이 내려오고 있다.<br>등불을 차서 껐다. 어둠 속에서 전원이 자리를 바꿨다. 무언가 바닥에 내려서는 소리, 그리고 아까 이쪽이 앉았던 자리를 더듬는 소리가 났다. 어둠이 걷히고 보니 그 자리 흙이 손가락으로 긁혀 있었다.`,
      win:{ exp:20, dream:3 }, lose:{ mind:-18, spirit:-18 } },
    { l:'② 등불을 벽 쪽으로 옮겨 그림자 전부를 길게 눕힌다.', k:'hide', dc:23,
      ok:`등불을 벽에 바짝 붙였다. 그림자들이 반대 벽으로 길게 누우며 서로 겹쳤다.<br><br>겹친 그림자는 못 센다. 여섯이 다섯인지 다섯이 여섯인지, 세던 쪽도 놓친다.<br>겹침 속에서 일행을 한 명씩 구석 사각으로 옮겼다. 마지막에 등불을 거뒀다. 여섯째 그림자 주인은 겹침이 풀렸을 때 빈자리만 받았다.`,
      ng:`등불을 옮기다 그림자들이 벽에서 크게 출렁였다.<br><br>출렁임은 움직임이고, 움직임은 신호다. 여섯째 그림자가 출렁임을 타고 성큼 커졌다.<br>전원이 벽을 등지고 선 채 그림자 하나가 등불 빛 가장자리를 돌며 재는 것을 지켜봤다. 빛 안으로는 끝내 안 들어왔다. 빛이 꺼질 때까지 버티는 쪽을 택한 것이다. 기름을 아끼지 않기로 했다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-25, spirit:-18 } }
  ] },

{ at:'S', t:'정찰 — 먼저 보내는 그림자',
  x:`모퉁이 너머가 수상하다. 고요가 너무 고르게 깔렸다.<br><br>
    사람 눈을 보내면 사람이 간 것이다. 그림자를 보내면 — 그림자만 간 것이다.<br>
    그림자술사는 제 그림자를 심부름 보낼 줄 안다. 보는 것은 못 하지만, 닿는 것은 느낀다.<br><br>
    여기 것들이 그림자를 어떻게 대하는지는 아직 모른다.`,
  o:[
    { l:'① 그림자를 바닥에 깔아 모퉁이 너머로 민다.', k:'hide', dc:25,
      doom:{ title:'그림자를 쥔 것', what:'그림자째 감겨 모퉁이 너머로 끌려 들어갑니다', dc:19, sec:42,
        text:`그림자를 종이처럼 얇게 깔아 모퉁이 너머로 밀었다. 바닥 느낌이 그림자를 타고 돌아온다. 돌, 돌, 젖은 돌 —<br><br>그리고 그림자가 무언가에 밟혔다. 아니, 쥐였다.<br>여기 것들 중에는 그림자를 쥘 줄 아는 것이 있다. 그걸 오늘 배웠다. 너무 가까이서.<br><br>그림자가 감겨 올라간다. 그림자는 발꿈치에 묶여 있다. 몸이 바닥에 넘어지고, 모퉁이 쪽으로 끌려간다. 걷어 낸 종이를 둘둘 말듯이.`,
        dieText:`모퉁이 안쪽은 끝까지 고요했다.<br><br>고요가 너무 고르게 깔린 데는 이유가 있다.<br>거기 사는 것이 소리란 소리를 다 먹어 치우기 때문이다. 그림자도 먹는 줄은 몰랐을 뿐이다.`,
      },
      ok:`그림자를 밀다가 모퉁이 직전에서 세웠다. 그림자 가장자리가 가늘게 떨렸다. 바람도 없는데.<br><br>너머의 공기가 그림자를 핥고 있는 것이다. 맛보는 혀처럼.<br>그림자를 천천히, 자연스럽게 거뒀다. 어둠이 옅어지면 그림자가 줄듯이. 낚아채듯 거두면 산 것인 걸 들킨다.<br><br>모퉁이는 돌지 않고 위층으로 돌았다. 그림자가 혀를 기억하고 있다. 한동안 발꿈치에 바짝 붙어 다녔다.`,
      win:{ exp:22, dream:3 } },
    { l:'② 그림자에 돌을 얹어 무게만 먼저 보낸다.', k:'fix', dc:23,
      ok:`그림자를 멀리 못 보내는 대신 수를 썼다. 그림자 끝에 주먹돌을 얹고, 그림자를 당겨 돌을 모퉁이 너머로 미끄러뜨렸다.<br><br>손 안 대고 던진 돌이다. 던진 소리도 없이, 구르는 소리만.<br>너머에서 무언가 돌을 덮치는 소리가 났다. 묵직한 것이 돌 하나에 통째로 실리는 소리. 저 무게면 사람은 한 입이다. 모퉁이는 버리고 돌아갔다.`,
      ng:`그림자로 돌을 미는데 돌이 반 뼘 못 가 걸렸다.<br><br>당기는 마력이 그림자에서 삐끗 미끄러졌다. 그림자가 채찍처럼 튕기며 바닥을 때렸다. 짝.<br>너머의 고요가 이쪽으로 쏟아져 나왔다. 전원이 왔던 길로 물러났다. 고요는 문턱까지만 따라오고 멈췄다. 제 구역이 있는 고요였다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-26, mind:-16 } },
    { l:'③ 보내지 않는다 — 귀로 너머의 바닥을 읽는다.', k:'sense', dc:23,
      ok:`돌조각을 모퉁이 벽에 대고 귀를 붙였다. 벽은 너머의 바닥과 한 몸이다.<br><br>너머에서 아주 느린 끌림이 반복된다. 쓸고, 쉬고, 쓸고. 숨 쉬는 몸통이 바닥에 닿았다 떨어지는 소리다. 큰 것이 엎드려 있다.<br>엎드린 것은 기다리는 것이다. 기다리는 길목은 길이 아니다. 위층으로 돌았다.`,
      ng:`벽에 귀를 대는데 벽 속에서 무언가가 마주 긁었다. 드륵.<br><br>벽과 한 몸인 건 너머 바닥만이 아니었다. 벽 속에도 세입자가 있다.<br>귀를 떼고 물러났다. 벽 속 긁힘이 이쪽 걸음을 따라 벽을 타고 왔다. 복도가 끝나는 데까지. 귓바퀴가 밤새 얼얼했다. 들은 것은 지워지지 않는다.`,
      win:{ exp:18, dream:2 }, lose:{ mind:-17, spirit:-19 } }
  ] },

{ at:'S', t:'쉬는 자리 — 그림자 홑청',
  x:`일행이 잠든다. 자는 몸은 냄새가 커진다. 땀이 풀리고 숨이 깊어져서.<br><br>
    여기 것들은 코로 잠든 것을 찾는다. 잠든 것은 반쯤 잡힌 것이다.<br>
    그림자는 빛을 막는 천이다. 마력을 더 먹이면 — 다른 것도 막을지 모른다.<br><br>
    해 본 적은 없다. 여기는 해 본 적 없는 걸 하는 데다.`,
  o:[
    { l:'① 마력 먹인 그림자를 홑청처럼 일행 위에 덮는다.', k:'steady', dc:24, cost:{ mana:30 },
      ok:`제 그림자를 벗겨 넓게 폈다. 마력을 날실 삼아 촘촘히 짰다. 다섯 몸 위에 홑청으로 덮었다.<br><br>그림자 밑의 냄새가 그림자 밑에 고였다. 새는 건 가장자리로 실낱만큼.<br>밤에 킁킁대는 것이 두 번 지나갔다. 두 번 다 홑청 가장자리에서 코를 떼고 갔다. 냄새의 꼬리만 있고 몸통이 없으니, 지나간 자리로 안 것이다.<br>새벽에 홑청을 걷어 도로 발밑에 붙였다. 밤새 남을 덮은 그림자가 한결 묵직해져 있었다.`,
      ng:`홑청을 짜는데 마력이 올에서 자꾸 샜다. 피곤한 날의 마력은 올이 굵다.<br><br>덮긴 덮었는데 성긴 데로 냄새가 샜다. 킁킁대는 것이 성긴 자리 위에서 멈췄다.<br>홑청째 마력을 터뜨려 먼지를 일으키고 일행을 깨워 물렸다. 먼지 속에서 그것이 재채기 비슷한 소리를 냈다. 그 소리가 아니었으면 웃을 뻔했다. 웃을 자리가 아니었다.`,
      win:{ exp:20, dream:3 }, lose:{ mind:-17, spirit:-16 } },
    { l:'② 바람 가는 쪽에 젖은 천을 걸어 냄새 길을 꺾는다.', k:'fix', dc:23,
      ok:`냄새는 바람 길로 간다. 바람 길목에 적신 천을 두 장 걸었다.<br><br>젖은 천은 냄새를 붙잡는다. 지나는 바람이 천에서 반쯤 씻겨 나간다.<br>남은 반은 쉬는 자리의 곰팡 냄새에 눌렸다. 밤새 코 밝은 것들이 바람 끝만 쫓다 흩어졌다. 천 두 장 값으로 하룻밤. 그림자 안 쓰고도 되는 날은 아껴 둔다.`,
      ng:`천을 거는데 줄이 늘어져 천이 바닥에 끌렸다. 쓸리는 소리가 났다.<br><br>작은 소리인데 밤에는 크다.<br>소리 쪽으로 온 것이 천을 한참 물고 흔들었다. 천에 밴 손 냄새 때문이다. 천은 포기했다. 그것이 천을 끌고 가는 소리가 멀어진 뒤에야 다들 숨을 돌렸다. 밤새 바람 길목이 허전했다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-25, mind:-15 } }
  ] },

{ at:'S', t:'통로 — 접은 그림자',
  x:`통로에 희미한 비상광이 돈다. 어디서 오는지 모를, 죽다 만 빛.<br><br>
    빛이 있으면 그림자가 있다. 다섯 사람 그림자가 벽에 길게 선다.<br>
    여기 것들 중에는 눈 대신 그림자의 결을 더듬는 것이 있다. 벽에 붙어 벽에 비친 것을 읽는 것이.<br><br>
    몸을 숨겨도 그림자가 서 있으면 선 것이다.`,
  o:[
    { l:'① 다섯 그림자를 접어 발밑에 깔아 둔다.', k:'hide', dc:24, wake:1,
      ok:`제 그림자부터 접었다. 반으로, 또 반으로. 손수건만 하게 접어 발밑에 깔았다.<br><br>일행 것도 한 장씩 접었다. 남의 그림자는 뻣뻣해서 모서리를 마력로 눌러 가며 접어야 했다.<br>벽에는 이제 아무것도 안 선다. 벽을 더듬는 것이 이쪽 구간에서 빈 벽만 읽고 지나갔다.<br><br>그림자를 늘이고 줄이는 건 늘 하던 일이다. 개켜 두는 건 여기서 배웠다. 연장은 개켜 둘 줄도 알아야 연장이다.`,
      ng:`넷째 사람 그림자가 접히다 말고 튕겨 펴졌다. 산 그림자는 주인이 겁먹으면 뻗댄다.<br><br>펴진 그림자가 벽에 큰대자로 섰다. 벽 더듬는 것이 그 자리로 미끄러져 왔다.<br>그림자를 통째로 걷어 품에 안고 주인과 함께 뛰었다. 품 안에서 그림자가 버둥댔다. 겁먹은 그림자는 무겁다. 그것도 여기서 배웠다.`,
      win:{ exp:20, dream:3 }, lose:{ hp:-26, spirit:-17 } },
    { l:'② 비상광 자체를 손바닥만큼 가려 사각을 만든다.', k:'evade', dc:24,
      ok:`빛의 샘을 찾았다. 천장 틈의 죽다 만 발광체. 그 앞에 마력 그림자를 손바닥만큼 띄웠다.<br><br>통로 한 줄기에 사각 기둥이 섰다. 빛이 못 드는 세로 길.<br>그 기둥 속으로 다섯이 줄지어 지났다. 밖에서 보면 빛이 원래 그만큼 죽은 줄 알 것이다. 죽다 만 빛은 어디가 더 죽어도 티가 안 난다.`,
      ng:`손바닥 그림자가 빛샘 앞에서 흔들렸다. 빛이 깜빡, 깜빡, 두 번 울었다.<br><br>깜빡이는 빛은 신호다. 통로 끝 어둠이 신호를 받고 일어섰다.<br>그림자를 거두고 빛을 원래대로 돌렸다. 일어선 것은 한참 빛을 보다가 도로 앉았다. 그동안 다섯은 벽의 이끼처럼 붙어 있었다. 이끼도 땀은 안 흘릴 것이다.`,
      win:{ exp:18, dream:2 }, lose:{ mind:-17, spirit:-17 } }
  ] },

{ at:'S', t:'등불 — 심지 두 눈금',
  x:`앞은 낭떠러지 턱이라 불 없이는 못 간다. 불을 켜면 여기 것들 코에 등불 기름 냄새가 간다.<br><br>
    기름 냄새는 못 지운다. 다만 빛은 다룰 수 있다.<br>
    빛이 크면 그림자가 짙다. 짙은 그림자는 멀리서도 읽힌다. 움직이는 짙은 것들 — 그게 행렬의 광고판이다.<br><br>
    심지 눈금 하나 차이가 목숨 눈금이다.`,
  o:[
    { l:'① 심지를 두 눈금만 — 그림자가 안 서는 밝기를 찾는다.', k:'gaze', dc:23,
      ok:`심지를 올렸다 내렸다 하며 벽을 봤다. 세 눈금이면 그림자가 선다. 한 눈금이면 발밑이 안 보인다.<br><br>두 눈금. 바닥만 겨우 보이고, 그림자는 설 힘이 없는 밝기.<br>그 밝기로 턱길을 다 지났다. 벽에는 아무것도 서지 않았고, 발은 한 번도 안 헛디뎠다. 빛에도 결이 있다. 결을 읽는 눈이 그림자술사의 밑천이다.`,
      ng:`두 눈금을 찾는 사이 불이 한 번 세 눈금으로 튀었다.<br><br>벽에 다섯 그림자가 성큼 섰다. 광고판이 켜졌다 꺼진 셈이다.<br>턱길을 서둘러 건너는데 아래쪽 어둠에서 돌 구르는 소리가 따라왔다. 벽의 광고를 보고 온 손님이다. 턱이 좁아 못 올라온 덕에 광고비는 안 치렀다.`,
      win:{ exp:18, dream:3 }, lose:{ mind:-16, spirit:-16 } },
    { l:'② 등불을 뒤로 들려 그림자를 이미 온 길로 눕힌다.', k:'hide', dc:24,
      ok:`맨 뒤 사람에게 등불을 들리고 전원이 그 앞에 섰다. 그림자가 전부 앞이 아니라 — 아니, 뒤가 아니라 지나온 길로 눕는다.<br><br>가는 쪽 어둠에는 빛도 그림자도 안 간다. 온 길에만 다섯 그림자가 어른댄다.<br>무언가 그 그림자들을 쫓아 지나온 길을 거슬러 갔다. 비어 가는 길을. 그림자는 미끼로도 쓴다. 몸값 없는 미끼다.`,
      ng:`뒤로 들린 등불이 맨 뒤 사람 눈을 가렸다. 그 사람이 돌부리를 찼다.<br><br>등불이 흔들려 그림자 다섯이 벽에서 춤을 췄다.<br>춤추는 그림자는 광고 중에서도 제일 큰 광고다. 불을 끄고 전원이 턱에 엎드렸다. 아래 어둠이 한참 수런댔다. 턱이 높은 걸 저쪽이 아쉬워하는 소리였기를 바란다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-26, mind:-15 } }
  ] },

{ at:'S', t:'미끼 그림자 — 걷는 사람 모양',
  x:`앞 구역을 지키는 것이 비킬 생각이 없다. 돌아갈 길도 없다.<br><br>
    눈이 아니라 귀와 코로 지키는 놈이다. 그래도 몸이 큰 것이 지나가면 공기가 흔들린다. 그 흔들림은 읽는다.<br>
    그림자로 사람 모양을 세워 공기째 흔들며 걸릴 수 있다. 마력이 많이 드는 큰 인형이다.<br><br>
    인형극은 인형이 아니라 줄이 들키는 놀음이다.`,
  o:[
    { l:'① 그림자 사람을 세워 반대쪽 길로 걸린다.', k:'hide', dc:25, cost:{ mana:32 },
      doom:{ title:'줄 끝의 손', what:'그림자 줄을 당기는 손째 잡혀 끌려갑니다', dc:19, sec:40,
        text:`그림자를 사람 크기로 일으켰다. 마력을 속까지 채워 공기가 밀리게. 반대쪽 길로 한 걸음, 두 걸음.<br><br>지키던 놈이 그쪽으로 돌았다. 됐다 — 싶을 때 놈이 인형을 지나쳤다.<br>인형이 아니라 줄을 따라온 것이다. 마력 줄은 공기 속에 긴 지문을 남긴다. 그 지문을 코로 읽는 놈이었다.<br><br>줄 끝의 손목을 물렸다. 인형이 풀썩 꺼지고, 몸이 끌려간다. 인형극 줄잡이가 무대로 끌려 나가는 꼴로.`,
        dieText:`구역을 지키던 것이 제자리로 돌아갔다.<br><br>바닥에 그림자 한 장이 주인 없이 남았다. 사람 모양으로 누운 채.<br>그림자는 빛이 바뀔 때마다 조금씩 옅어지다가, 다음 날에는 그냥 바닥이었다.`,
      },
      ok:`인형을 세우기 전에 줄부터 고쳤다. 마력 줄을 곧게 잇지 않고 바닥 틈과 벽 모서리로 꺾어 돌렸다. 지문을 끊어 가며.<br><br>그림자 사람이 반대쪽 길을 걸었다. 공기가 밀리고, 지키던 놈이 통째로 따라갔다.<br>놈이 인형을 덮치는 소리를 등 뒤로 들으며 구역을 지났다. 인형은 이빨 사이에서 연기처럼 풀렸을 것이다. 맛없는 저녁이다.<br><br>줄을 꺾어 쓰는 법. 인형극은 줄 감추기가 전부라는 걸 스승 없이 배웠다.`,
      win:{ exp:24, dream:3 } },
    { l:'② 인형 대신 공기만 — 긴 바람을 마력로 민다.', k:'evade', dc:24,
      ok:`사람 모양은 품이 든다. 공기 흔들림만 베끼면 반값이다.<br><br>마력을 넓적한 판으로 펴서 반대쪽 길의 공기를 천천히 밀었다. 큰 것이 지나가는 밀도로.<br>지키던 놈이 그 바람을 쫓아갔다. 바람은 쫓아도 끝이 없다. 놈이 바람 끝을 찾는 동안 구역을 지났다. 바람 인형은 줄도 없다. 들킬 것이 없는 인형이다.`,
      ng:`공기를 미는 판이 중간에 꺾였다. 바람이 사람 걸음 박자로 끊겨 버렸다.<br><br>걸음 박자 나는 바람. 그건 바람이 아니라 광고다.<br>놈이 바람과 이쪽 사이에서 고개를 갸웃대는 사이 벽 틈으로 일행을 밀어 넣었다. 틈에서 두 시진을 보냈다. 놈은 두 시진 내내 그 자리를 안 비켰다. 성실한 놈이었다.`,
      win:{ exp:18, dream:2 }, lose:{ mind:-18, spirit:-17 } }
  ] },

{ at:'S', t:'남의 그림자 — 큰 것의 밑',
  x:`길 한복판으로 큰 것이 지나간다. 피할 틈이 없다. 벽에 붙어도 닿을 거리다.<br><br>
    그런데 저것의 발밑에 그림자가 있다. 희미한 빛에도 깔리는, 집채만 한 그림자가.<br>
    제 그림자 속은 아무도 안 본다. 등잔 밑이 어두운 게 아니라, 제 그림자 밑은 제 것이라 안 보는 것이다.<br><br>
    남의 그림자에 세 들 수 있는 것은 그림자술사뿐이다.`,
  o:[
    { l:'① 큰 것의 그림자 속으로 미끄러져 들어가 같이 걷는다.', k:'hide', dc:25, wake:1,
      ok:`큰 것의 그림자 가장자리에 제 그림자를 포갰다. 포개지면 섞인다. 섞이면 한집이다.<br><br>그림자 속으로 몸을 넣었다. 서늘하고, 비리고, 넓다. 큰 것이 걸으면 그림자가 걷고, 그림자가 걸으면 이쪽도 걸었다.<br>길 한복판을 큰 것과 함께 지났다. 저것은 제 발밑에 세입자가 든 줄 평생 모를 것이다.<br><br>그림자는 만드는 것만이 아니다. 빌리는 것이기도 하다. 세상 모든 그림자가 빈방으로 보이기 시작했다.`,
      ng:`그림자에 드는 순간 큰 것이 걸음을 멈췄다.<br><br>그림자가 멈추면 세입자도 멈춰야 한다. 못 멈췄다. 반 걸음이 그림자 밖으로 샜다.<br>큰 것이 코를 바닥에 내렸다. 제 그림자 냄새를 맡는 코. 그림자 반대편 가장자리로 구르듯 빠져나와 바위 뒤에 붙었다. 큰 것은 제 발밑을 한참 의심하다 갔다. 저것도 등잔 밑을 배운 날이다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-27, spirit:-18 } },
    { l:'② 큰 것이 다 지나가도록 벽 틈에서 숨을 죽인다.', k:'steady', dc:23,
      ok:`벽 틈에 다섯이 세로로 끼었다. 숨은 반으로, 눈은 감고. 눈빛도 빛이라는 말이 여기서는 미신이 아니다.<br><br>큰 것이 지나갔다. 한 발, 한 발, 벽이 울 때마다 틈의 먼지가 어깨에 내렸다.<br>꼬리 끝이 틈 앞을 쓸고 가는 바람이 마지막이었다. 먼지를 털지 않고 그대로 반 식경을 더 서 있었다. 큰 것들은 가끔 되돌아온다. 오늘 것은 안 왔다.`,
      ng:`틈에 끼는데 막내 배낭이 걸려 삐걱했다.<br><br>큰 것의 걸음이 틈 앞에서 멎었다. 콧김이 틈으로 들어왔다. 더운 안개처럼.<br>콧김 세 번. 틈이 좁아 코가 안 들어온 덕에 산 셈이다. 큰 것이 떠나고 전원이 틈에서 쏟아져 나왔을 때, 다들 머리가 콧김에 젖어 있었다. 비린 머리로 한나절을 걸었다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-28, mind:-15 } }
  ] },

{ at:'S', t:'그림자 주머니',
  x:`강을 이루듯 깔린 먼지벌레 떼를 지나야 한다. 밟으면 터지고, 터지면 냄새로 운다.<br><br>
    그 울음이 이 구역 것들의 종이다.<br>
    쓸어 낼 수도, 돌아갈 수도 없다. 들고 갈 수 있는 건 — 들고 가면 된다.<br><br>
    그림자는 깔개도 되고, 입을 벌리면 주머니도 된다.`,
  o:[
    { l:'① 그림자를 벌려 벌레 깔린 길을 통째로 담아 올린다.', k:'hide', dc:25, cost:{ mana:35 },
      ok:`길 너비만큼 그림자를 펴고 마력로 가장자리를 세웠다. 쟁반처럼. 그리고 바닥의 벌레 떼를 흙째 한 겹 떠서 담았다.<br><br>벌레들은 제 바닥이 들린 줄도 몰랐다. 터진 놈 하나 없이.<br>맨돌이 드러난 길로 다섯이 지나고, 그림자 쟁반을 제자리에 내려놓았다. 흙째, 벌레째, 고스란히. 지나간 자국이 없는 길이 등 뒤에 도로 깔렸다.`,
      ng:`쟁반을 드는데 가장자리에서 벌레 둘이 굴러떨어졌다. 톡, 톡. 터졌다.<br><br>울음 냄새가 피어올랐다. 두 놈 몫이라 가늘었지만, 가는 종도 종이다.<br>쟁반째 길가에 내려 두고 뛰었다. 구역 것들이 종소리에 모여드는 기척을 등 뒤로 들었다. 두 마리 몫 저녁이 차려졌으니 이쪽은 빠질 자리였다.`,
      win:{ exp:22, dream:3 }, lose:{ mind:-18, spirit:-16 } },
    { l:'② 벌레가 비는 결을 찾아 외줄로 지난다.', k:'sense', dc:24,
      ok:`떼에도 결이 있다. 벌레들이 안 앉는 가는 금 — 바닥 돌 밑으로 찬 기운이 오르는 줄이다.<br><br>그 금을 눈으로 이어 외줄을 그렸다. 한 발 너비.<br>다섯이 줄타기하듯 지났다. 벌레들은 찬 줄 양옆에서 저희끼리 바글댔다. 떼 속에도 길은 있다. 떼가 싫어하는 자리가 곧 길이다.`,
      ng:`외줄 중간에 금이 끊겼다. 찬 기운이 거기서 죽은 것이다.<br><br>한 발 디딜 데가 없다. 선 채로 멈춘 발밑으로 벌레들이 차오르기 시작했다.<br>마력을 바닥에 쳐 벌레를 사방으로 튕기고 남은 길을 뛰었다. 몇 놈이 터졌다. 울음 냄새를 등에 묻힌 채 반 시진을 돌아 끊었다. 신발은 버렸다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-26, mind:-16 } }
  ] },

{ at:'S', t:'문 밑 — 엎드린 귀',
  x:`문 너머에 뭐가 있는지 알아야 문을 연다.<br><br>
    문틈으로 눈을 대는 건 초짜다. 틈으로는 이쪽 눈빛과 냄새가 먼저 넘어간다.<br>
    그림자는 문 밑을 종이처럼 지난다. 그림자에는 냄새가 없고, 눈빛도 없다.<br><br>
    보는 건 못 한다. 대신 그림자는 제 위에 얹힌 것을 안다.`,
  o:[
    { l:'① 그림자를 문 밑으로 넣어 바닥을 더듬는다.', k:'hide', dc:24,
      ok:`그림자를 혀처럼 얇게 밀어 넣었다. 문 너머 바닥을 한 뼘씩 덮으며 읽었다.<br><br>돌, 돌, 뼈 — 가늘고 긴 뼈 무더기. 그리고 그 너머에 무게. 숨 쉬는 무게가 셋.<br>그림자를 거두고 손가락 셋을 들어 보였다. 일행이 고개를 저었다. 문은 안 열었다. 뼈 무더기 위에 숨 쉬는 셋이면, 그 문은 식당 문이다.`,
      ng:`바닥을 더듬는데 그림자 위로 뭔가 내려앉았다. 무겁지 않다. 발이다. 가늘고 긴 발.<br><br>발이 그림자를 콕콕 찍었다. 바닥과 다른 것이 깔린 걸 안 것이다.<br>그림자를 당겨 뺐다. 문 밑으로 끝자락이 빠져나오는 순간까지 발이 쫓아와 찍었다. 그림자에 구멍이 두 개 났다. 발꿈치가 이틀을 시렸다. 그림자의 구멍은 주인 몸에서 아문다.`,
      win:{ exp:20, dream:3 }, lose:{ hp:-26, spirit:-18 } },
    { l:'② 문짝에 손바닥을 얹어 떨림으로 읽는다.', k:'sense', dc:23,
      ok:`문짝은 북가죽이다. 너머의 일이 떨림으로 찍힌다.<br><br>손바닥에 마력을 얇게 깔고 기다렸다. 긁힘 — 느리게, 둘. 그리고 큰 숨 하나가 문짝을 밀 듯 당길 듯 오간다.<br>자는 숨이 아니다. 문 앞을 도는 숨이다. 문고리에서 손을 떼고 물러났다. 저쪽도 이 문을 열까 말까 하는 중이었다. 양쪽 다 안 여는 걸로 합의가 됐다.`,
      ng:`손바닥을 얹은 채 너무 오래 있었다. 문짝이 이쪽 체온을 먹었다.<br><br>너머의 숨이 문짝에 바짝 붙었다. 더운 자리를 찾은 것이다.<br>손을 떼고 벽 쪽으로 붙는 순간 문짝이 안쪽에서 한 번 크게 울렸다. 두드린 것이다. 노크를. 아무도 대답하지 않았고, 다섯은 뒤도 안 보고 그 복도를 버렸다.`,
      win:{ exp:16, dream:2 }, lose:{ mind:-18, spirit:-16 } }
  ] },

{ at:'S', t:'쉬는 자리 — 닳은 그림자',
  x:`쉬면서 그림자를 바닥에 펴 봤다. 많이 상했다.<br><br>
    가장자리가 올 풀리듯 흐리고, 접었던 금이 희게 남았다. 구멍 자국 둘.<br>
    그림자는 연장이자 살이다. 상한 줄 모르고 쓰면 어느 날 안 돌아온다.<br><br>
    그림자 없는 그림자술사는 칼 없는 자객만도 못하다.`,
  o:[
    { l:'① 어둠을 먹여 그림자를 깁는다.', k:'steady', dc:23, wake:1,
      ok:`쉬는 자리의 어둠을 손으로 걷어 그림자의 풀린 올에 먹였다. 한 올, 한 올.<br><br>그림자가 어둠을 받아 가장자리부터 짙어졌다. 흰 금이 메워지고 구멍이 닫혔다.<br>다 기운 그림자가 발밑에 착 붙었다. 새것처럼은 아니다. 기운 자리는 남는다. 기운 자리가 많은 그림자가 오래 산 그림자다.<br><br>쓰는 법만 알던 연장을 돌보는 법을 배웠다. 돌봐 본 연장이라야 험한 데서 주인을 돌본다.`,
      ng:`어둠을 먹이는데 그림자가 받다 말고 떨었다.<br><br>이 어둠에 섞인 게 있는 것이다. 여기 어둠은 깨끗한 어둠이 아니다.<br>먹이기를 멈추고 뱉게 했다. 그림자가 밤새 미열 나듯 떨었다. 발꿈치가 같이 떨렸다. 다음부터 먹일 어둠은 맛을 보고 먹이기로 했다. 어떻게 보는지는 — 이제부터 궁리할 일이다.`,
      win:{ exp:20, dream:3, spirit:6 }, lose:{ mind:-16, spirit:-17 } },
    { l:'② 그림자를 쉬게 하고 맨몸 기술만 점검한다.', k:'fix', dc:23,
      ok:`그림자를 돌돌 말아 품에 품었다. 오늘 밤은 휴가다.<br><br>그림자 없이 걷는 법, 숨는 법을 오랜만에 맨몸으로 짚었다. 발꿈치 들기, 벽 타기, 숨 나누기.<br>굳은 데가 꽤 있었다. 그림자에 기대느라 몸이 게을러진 것이다. 연장 좋은 장인이 손끝 무뎌지는 줄 모른다더니, 그 말이 이쪽 얘기였다.`,
      ng:`품은 그림자가 한밤에 뒤척였다.<br><br>그림자도 꿈을 꾼다. 여기 와서 험한 것만 봐서 험한 꿈일 것이다.<br>뒤척임이 옷깃을 벗어나 바닥을 쳤다. 탁. 불침번이 기겁해서 하마터면 소리칠 뻔했다. 입을 막고 서로 한참 눈만 껌뻑였다. 잠은 다 갔다.`,
      win:{ exp:16, dream:2, mind:6 }, lose:{ mind:-15, spirit:-15 } }
  ] },

{ at:'S1', t:'표본실 — 병보다 많은 그림자',
  x:`표본 선반에 등을 들이대자 벽에 병 그림자들이 줄지어 선다.<br><br>
    버릇대로 센다. 병이 열하나, 그림자가 열둘.<br>
    병 아닌 것이 병들 사이에 병처럼 서 있다.<br><br>
    어느 그림자가 남는 놈인지, 등불이 흔들려 당장은 모른다.`,
  o:[
    { l:'① 등불을 천천히 돌려 그림자들을 하나씩 걷는다.', k:'gaze', dc:24, wake:1,
      ok:`등불을 호를 그리며 옮겼다. 빛의 각이 돌면 그림자들이 차례로 눕는 방향을 바꾼다.<br><br>병 그림자 열하나는 같은 박자로 돌았다. 열두째는 — 반 박자 늦었다. 산 것의 그림자는 제 주인 눈치를 보느라 늦는다.<br>늦은 그림자의 주인 자리를 거꾸로 짚었다. 셋째 선반, 깨진 병 뒤. 일행이 긴 장대로 선반째 밀어 넘겼고, 그 뒤는 짧았다.<br><br>그림자의 박자로 산 것을 가려내는 눈. 세는 버릇이 읽는 버릇이 됐다.`,
      ng:`등불을 돌리는 중에 열두째 그림자가 사라졌다. 주인이 그림자를 접은 것이다.<br><br>여기엔 그림자를 다룰 줄 아는 것이 이쪽 말고 또 있다.<br>등불을 끄고 전원 벽으로 붙었다. 어둠 속에서 유리병들 사이를 맨발 같은 것이 오래 오갔다. 병은 하나도 안 울렸다. 그게 제일 소름이었다.`,
      win:{ exp:20, dream:3 }, lose:{ mind:-19, spirit:-18 } },
    { l:'② 이쪽 그림자도 병 모양으로 접어 선반 틈에 세운다.', k:'hide', dc:24,
      ok:`맞세기로 했다. 다섯 그림자를 병 모양으로 접어 벽의 병 그림자들 틈에 세웠다. 열둘이 열일곱이 됐다.<br><br>남는 하나는 센 놈이 이제 못 센다. 저쪽 눈에는 병이 갑자기 다섯 늘어난 벽이다.<br>그림자들이 벽에서 서로 눈치를 보는 동안 다섯 몸은 선반 아래 그늘로 지나갔다. 세는 싸움은 셈을 흐리는 쪽이 이긴다.`,
      ng:`병 모양으로 접는데 막내 그림자가 모양을 못 잡고 사람 꼴로 섰다.<br><br>병들 사이에 사람 그림자 하나. 숨은그림찾기 답지를 준 꼴이다.<br>열두째 그림자가 그 사람 꼴을 향해 미끄러졌다. 막내를 반대쪽으로 밀고 그림자를 통째로 걷어 뛰었다. 등 뒤에서 병 몇이 울었다. 빈 벽을 긁는 소리도.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-27, spirit:-17 } }
  ] },

{ at:'S1', t:'경광등 — 도는 그림자',
  x:`복도 천장의 경광이 아직 돈다. 주황 빛이 한 바퀴에 네 숨.<br><br>
    빛이 돌면 그림자도 돈다. 복도의 모든 그림자가 네 숨마다 한 바퀴씩 눕는 방향을 바꾼다.<br>
    서 있는 것의 그림자는 돌고, 도는 빛에 안 도는 그림자는 — 없다. 없어야 한다.<br><br>
    복도 끝에 안 도는 그림자가 하나 있다.`,
  o:[
    { l:'① 도는 그림자들 박자에 제 그림자를 태워 지난다.', k:'hide', dc:25,
      doom:{ title:'안 도는 그림자', what:'그림자부터 밟혀 복도 끝으로 끌려갑니다', dc:20, sec:38,
        text:`네 숨에 한 바퀴. 그림자가 북쪽으로 누울 때 북벽 쪽으로, 남쪽으로 누울 때 남벽 쪽으로. 그림자가 자연스럽게 도는 몸짓으로 걸었다.<br><br>복도 반을 지났을 때 알았다. 끝의 안 도는 그림자가 — 조금씩 길어지고 있다.<br>길어진 끝이 바닥을 타고 와 이쪽 그림자 끝에 닿았다. 닿는 순간 못처럼 박혔다.<br><br>그림자가 밟혔다. 밟힌 그림자는 주인을 세운다. 경광이 돌고, 이쪽 그림자만 안 돈다. 복도 끝에서 그것이 그림자 줄을 당긴다. 감아 올리듯, 천천히.`,
        dieText:`경광이 돈다. 네 숨에 한 바퀴.<br><br>복도의 그림자들이 다 같이 돈다. 이제 안 도는 그림자는 둘이다.<br>하나는 크고, 하나는 사람만 하다. 나란히 서 있다.`,
      },
      ok:`박자에 태우기 전에 끝의 안 도는 그림자부터 쟀다. 안 도는 그림자는 둘 중 하나다. 빛보다 센 놈이거나, 그림자가 아니거나.<br><br>경광이 그쪽을 지날 때 유심히 봤다. 빛이 그 위를 지나는데 바닥 결이 안 비쳤다. 그림자가 아니다. 구멍이다. 바닥이 꺼진 구멍.<br>구멍이면 떨어지는 함정이고, 함정 밑에는 기다리는 입이 있는 법이다. 벽 쪽 배관 턱으로 올라 구멍 위를 건너 지났다. 턱에서 내려다본 구멍 속에서 젖은 것이 뒤척였다.`,
      win:{ exp:22, dream:3 } },
    { l:'② 경광을 그림자로 덮어 복도째 재운다.', k:'break', dc:24, cost:{ mana:36 },
      ok:`그림자를 접시만 하게 띄워 경광 유리에 붙였다. 빛이 안에서만 돌고 밖으로 못 나온다.<br><br>복도가 통째로 어두워졌다. 도는 그림자도, 안 도는 그림자도 다 같이 없어졌다.<br>그 공평한 어둠 속을 벽 짚어 지났다. 복도 끝 그것은 빛이 꺼지자 제 일도 꺼진 듯 움직이지 않았다. 빛에 묶여 사는 것도 있다. 지나고 나서 그림자를 거두자 경광이 다시 돌았다. 아무 일 없던 복도로.`,
      ng:`그림자를 유리에 붙이는데 경광 열에 그림자 가장자리가 오그라들었다.<br><br>빛이 틈으로 새며 복도가 등대처럼 깜빡였다.<br>깜빡이는 복도는 비상이 두 번 걸린 복도다. 끝의 그것이 움직이기 시작했다. 그림자를 포기하고 배관 턱으로 뛰어올라 지났다. 그림자는 한 귀퉁이가 눌어붙은 채 돌아왔다. 탄내가 가시는 데 이틀 걸렸다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-26, spirit:-16 } }
  ] },

{ at:'S1', t:'숙주 — 둘째 그림자',
  x:`마주 오는 복도에서 연구복 둘이 걸어온다. 비켜설 틈은 있다.<br><br>
    문제는 누가 사람이고 누가 집인지다. 겉으로는 똑같이 창백하다.<br>
    경광 빛에 그림자가 눕는다. 하나는 그림자가 한 장. 하나는 — 한 장 밑에 흐린 한 장이 더 있다.<br><br>
    깃든 것도 그림자가 있다. 몸속에 있어도.`,
  o:[
    { l:'① 그림자 두 장인 쪽만 피해 벽 쪽으로 비킨다.', k:'hide', dc:24, wake:1,
      ok:`두 장짜리가 지나는 쪽 반대 벽에 붙었다. 한 장짜리 곁으로.<br><br>한 장짜리 연구원이 스치며 이쪽을 봤다. 산 사람 눈이었다. 겁에 질린, 그래서 아무 말도 못 하는. 두 장짜리는 끝까지 앞만 봤다. 안의 것이 모는 걸음이라.<br>지나고 나서 한 장짜리가 뒤에서 아주 작게 말했다. 7번 말고 9번 문으로. 그 말만 하고 제 갈 길을 갔다.<br><br>그림자 장수로 속을 세는 눈. 겉이 같을 때는 바닥을 보면 된다. 바닥은 거짓말에 재주가 없다.`,
      ng:`그림자 장수를 세는데 경광이 하필 꺼지는 박자였다. 바닥이 캄캄해졌다.<br><br>어느 쪽인지 모른 채 비켰다. 비킨 쪽이 틀렸다.<br>두 장짜리가 스치며 고개만 이쪽으로 꺾었다. 목이 꺾이는 각이 사람 각이 아니었다. 그대로 서로 지나쳤다. 지나치고 열 걸음을 세고 나서야 숨을 쉬었다. 안의 것이 배가 불렀던 모양이다.`,
      win:{ exp:20, dream:3 }, lose:{ mind:-19, spirit:-19 } },
    { l:'② 이쪽 다섯의 그림자를 전부 두 장으로 만든다.', k:'fix', dc:24,
      ok:`거꾸로 가기로 했다. 마력로 흐린 속그림자를 떠서 다섯 발밑에 한 장씩 더 깔았다.<br><br>겉보기에 다섯 다 깃든 몸이다. 두 장짜리 연구복이 스치며 이쪽 바닥을 봤다. 안의 것이 보는 것이다. 식구 수를 세듯.<br>다섯 그림자가 다 두 장인 걸 보고 그냥 갔다. 깃든 것은 깃든 것을 안 먹는다. 집끼리는 안 잡아먹는 법이라서.`,
      ng:`속그림자 다섯 장이 품이 너무 컸다. 셋째 장부터 흐린 게 아니라 짙게 떠졌다.<br><br>겉그림자보다 짙은 속그림자. 그건 깃든 몸이 아니라 뒤집힌 몸이다.<br>두 장짜리가 그 바닥 앞에서 멈춰 고개를 갸웃했다. 안의 것이 셈을 하는 동안 전원이 옆 통로로 빠졌다. 등 뒤에서 연구복이 한참 서 있는 기척이 났다. 셈이 안 맞는 걸 오래 들여다보는 기척이.`,
      win:{ exp:18, dream:2 }, lose:{ mind:-18, spirit:-17 } }
  ] },

{ at:'S1', t:'통풍관 — 그림자 심부름',
  x:`관이 두 갈래다. 한쪽은 밖으로, 한쪽은 안으로 — 어느 쪽인지 모른다.<br><br>
    몸으로 확인하러 들어가기엔 관이 너무 길고 좁다.<br>
    그림자를 보내면 된다. 그림자는 관 바닥을 종이처럼 흐른다.<br><br>
    다만 줄이 길어진다. 줄이 길면 거둬들이는 데도 오래 걸린다.`,
  o:[
    { l:'① 왼쪽 관으로 그림자를 길게 흘려보낸다.', k:'hide', dc:25,
      doom:{ title:'관 속 줄다리기', what:'그림자 줄째 감겨 통풍관 안으로 빨려 들어갑니다', dc:19, sec:40,
        text:`그림자를 실처럼 뽑아 왼쪽 관으로 흘렸다. 열 자, 스무 자. 바닥 느낌이 멀리서 돌아온다. 마른 바람 — 밖이 가깝다.<br><br>거두려는데 줄이 안 온다. 팽팽하다. 스무 자 안쪽 어디서 무언가 그림자 줄을 쥐었다.<br>당겼다. 저쪽이 더 세게 당겼다.<br><br>발이 관 입구에 걸리고, 몸이 관으로 빨려 들어간다. 그림자는 살이다. 끊으면 되는데 — 끊는 법은 아는데 — 아까워서 반 숨 늦었다. 그 반 숨이 관 속이다.`,
        dieText:`왼쪽 관에서 밤새 끌리는 소리가 났다. 안쪽으로, 안쪽으로.<br><br>왼쪽 관이 밖으로 나가는 관이 맞긴 했다.<br>다만 그 관의 주인이 밖보다 가까이 있었을 뿐이다. 길이 맞아도 길이 아닐 수 있다. 여기서는.`,
      },
      ok:`그림자를 흘리기 전에 끊을 자리부터 정했다. 발꿈치에서 한 뼘. 여차하면 거기서 자른다. 자른 만큼은 다시 자란다. 더디지만.<br><br>왼쪽 관으로 스무 자. 마른 바람, 흙먼지, 새 깃털 — 밖이다. 오른쪽 관은 열 자 만에 비린 물기와 더운 숨이 만져져서 바로 거뒀다.<br>왼쪽 관으로 다섯이 기었다. 그림자가 먼저 가 본 길이라 몸이 덜 무서워했다.<br><br>연장을 걸 때는 끊을 자리부터. 그 순서를 몸에 박았다.`,
      win:{ exp:22, dream:3 } },
    { l:'② 양쪽 관에 먼지를 날려 바람 방향을 읽는다.', k:'sense', dc:23,
      ok:`마른 먼지를 한 줌 쥐고 관 입구마다 흘렸다.<br><br>왼쪽 관은 먼지가 안으로 빨려 든다. 밖과 통해 바람이 드는 관. 오른쪽은 먼지가 되밀려 나온다. 안쪽에서 무언가 숨을 내쉬는 관.<br>왼쪽으로 기었다. 바람이 등을 밀어 주는 관은 냄새도 뒤로 실어 간다. 꽁무니 냄새는 쫓는 놈 몫인데, 이 관 뒤에는 쫓는 놈이 없었다.`,
      ng:`먼지를 날리는데 오른쪽 관이 들이쉬는 참이었다. 먼지가 깊이 빨려 들어갔다.<br><br>관 속에서 재채기 비슷한 것이 터졌다. 젖은 소리로.<br>관 둘 다 버리고 무너진 계단을 손으로 파서 넘었다. 한나절이 갔다. 손이 흙투성이가 됐지만, 재채기한 것과 한 관에 드는 것보다는 흙이 낫다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-26, mind:-15 } }
  ] },

{ at:'S1', t:'산성 피 — 그림자 우산',
  x:`천장 배관에 매달려 죽은 것이 있다. 지나는 길 바로 위에서 썩는 중이다.<br><br>
    썩으며 피가 듣는다. 똑. 똑. 바닥 돌이 방울 자리마다 패어 있다.<br>
    천장이라 치울 수도 없고, 길은 그 밑뿐이다.<br><br>
    비면 우산을 쓴다. 산성 비라고 다를 것 없다.`,
  o:[
    { l:'① 그림자를 우산으로 펴 들고 밑을 지난다.', k:'steady', dc:24, cost:{ mana:36 },
      ok:`그림자를 머리 위에 펴고 마력을 겹겹이 먹였다. 기름 먹인 가죽 우산처럼.<br><br>방울이 그림자 위에서 끓다 미끄러져 가장자리 밖으로 흘렀다. 흐르는 자리를 봐 가며 다섯이 우산 밑에 붙어 지났다.<br>지나고 우산을 털었다. 그림자가 몇 군데 얇아졌지만 뚫리진 않았다. 산성 비 우산. 쓸 일이 또 없기를 바라지만, 있으면 또 쓸 수 있다.`,
      ng:`셋째 방울이 하필 굵었다. 우산 한가운데가 움푹 꺼지며 연기가 올랐다.<br><br>그림자가 비명 대신 발꿈치를 당겼다. 아프다는 신호다.<br>우산을 기울여 방울을 흘리고 남은 거리를 뛰었다. 그림자 복판에 동전만 한 구멍이 났다. 구멍 자리만큼 발꿈치가 이틀 저렸다. 우산은 우산인데 비싼 우산이었다.`,
      win:{ exp:20, dream:3 }, lose:{ hp:-28, spirit:-15 } },
    { l:'② 방울 박자를 세어 방울 사이로 지난다.', k:'evade', dc:24,
      ok:`똑 — 여덟 숨 — 똑. 박자가 고르다. 썩는 것도 박자는 지킨다.<br><br>방울이 듣는 순간 출발해서 여덟 숨 안에 방울 자리를 지나기로 했다. 한 명씩.<br>다섯이 다 여덟 숨 안에 지났다. 마지막 사람 등 뒤에서 똑, 아홉째 방울이 빈 바닥을 팠다. 박자를 지켜 준 시체에게 감사할 일인지는 모르겠다.`,
      ng:`넷째 사람 차례에 박자가 깨졌다. 똑, 똑 — 연달아 둘.<br><br>썩는 자리가 넓어진 것이다. 둘째 방울이 그 사람 어깨를 스쳤다.<br>천이 연기를 내며 녹았다. 어깨 천을 찢어 내고 물로 씻었다. 살은 발개진 선에서 막았다. 남은 한 사람은 그냥 멀리 돌았다. 처음부터 다 돌 걸 그랬다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-29, mind:-14 } }
  ] },

{ at:'S1', t:'여왕의 그림자',
  x:`큰 홀 바닥의 반이 어둠에 잠겨 있다. 그냥 어둠이 아니다. 그림자다.<br><br>
    홀 안쪽 깊은 데 있는 무언가의 그림자가 희미한 비상광을 받아 홀 반을 덮은 것이다.<br>
    저만 한 그림자를 세울 몸이면 — 여왕이다.<br>
    그림자술사는 안다. 제 그림자 속은 저도 못 본다. 여왕도 마찬가지일 것이다.`,
  o:[
    { l:'① 여왕의 그림자 속으로 들어 그 안쪽 길로 지난다.', k:'hide', dc:26, cost:{ mana:34 }, wake:1,
      ok:`그림자 가장자리에 제 그림자를 포개고, 스며들었다.<br><br>안은 서늘하고 맥이 뛴다. 그림자에도 주인 맥이 흐른다. 이 큰 그림자의 맥에 제 맥을 묻고, 홀 반을 그 속으로 걸었다.<br>일꾼들이 그림자 가장자리를 오가면서도 안은 안 봤다. 여왕의 그림자 속은 여왕의 것이고, 여왕의 것은 넘보지 않는 법이라서.<br><br>제일 위험한 것의 품이 제일 깊은 사각이다. 알고는 있던 말을 오늘 몸으로 썼다.`,
      ng:`스며들어 반쯤 건넜을 때 그림자가 — 숨을 쉬었다. 늘었다 줄었다.<br><br>여왕이 돌아눕는 것이다. 그림자가 통째로 홀을 쓸며 돈다.<br>쓸려 나가지 않으려고 바닥 틈에 손가락을 걸고 버텼다. 그림자가 지나간 자리에 알몸으로 남는 순간 비상광이 하필 깜빡였고, 그 반 숨의 어둠에 기어서 홀을 빠졌다. 손톱 두 장 값이었다.`,
      win:{ exp:24, dream:3 }, lose:{ hp:-28, spirit:-19 } },
    { l:'② 그림자 가장자리 밖으로, 빛의 띠만 밟아 돈다.', k:'evade', dc:25,
      ok:`그림자 가장자리와 벽 사이에 빛의 띠가 한 자 너비로 남아 있다.<br><br>그 띠만 밟아 홀을 돌았다. 그림자에 닿으면 주인이 알까, 빛에 서면 일꾼이 볼까 — 답은 가장자리다. 어느 쪽 것도 아닌 금.<br>금 위를 외줄 타듯 돌아 홀을 났다. 등 뒤에서 그림자가 한 번 크게 일렁였다. 여왕의 숨이었기를. 다른 뜻이 아니었기를.`,
      ng:`띠를 밟다가 발끝이 그림자 가장자리를 한 치 디뎠다.<br><br>그림자가 그 자리만 소름 돋듯 곤두섰다. 주인에게 가는 신호다.<br>홀 깊은 데서 젖은 것이 크게 움직이는 소리가 났다. 남은 띠를 뛰어 홀을 빠져나왔다. 문턱을 넘는 순간까지 그림자가 발꿈치를 쫓아 곤두서며 따라왔다. 꿈에 나올 광경이었다. 실제로 나왔다.`,
      win:{ exp:20, dream:2 }, lose:{ mind:-19, spirit:-20 } }
  ] },

{ at:'S1', t:'마지막 등 — 끌지 말지',
  x:`구역에 성한 등이 하나 남았다. 그 등 밑만 대낮이고 나머지는 먹물이다.<br><br>
    등 밑은 훤해서 못 지나고, 먹물은 깊어서 못 지난다 — 보통은 그렇게 생각한다.<br>
    그림자술사 눈에는 다르다. 등 하나가 만드는 건 빛 웅덩이 하나와, 세상에서 제일 짙은 그림자 테두리다.<br><br>
    빛이 셀수록 그 가장자리 그림자는 깊다.`,
  o:[
    { l:'① 빛 웅덩이의 가장자리, 제일 짙은 테를 따라 돈다.', k:'hide', dc:24,
      ok:`등 빛이 끝나는 금 바로 바깥, 눈이 빛에 먹혀 아무도 못 보는 띠가 있다.<br><br>빛 쪽에서 보면 그 띠는 먹물보다 검다. 먹물 쪽에서 보면 빛에 눈이 부셔 못 본다. 양쪽 모두의 사각.<br>그 띠를 따라 등 밑 구역을 돌아 지났다. 등불에 모여든 날벌레 같은 것들이 빛 속에서 바글댔지만, 띠는 끝까지 비어 있었다. 세상에서 제일 안전한 길은 가끔 제일 밝은 데 바로 옆에 있다.`,
      ng:`띠를 도는데 등이 수명 다한 소리를 냈다. 지지직.<br><br>빛이 줄며 띠가 통째로 옮겨 갔다. 서 있던 자리가 맨 어둠이 됐다.<br>먹물 속 것들이 새 어둠을 바로 알아챘다. 더듬이 같은 것들이 발목을 스쳤다. 등이 다시 살아나는 반 숨에 띠를 찾아 뛰었다. 등 수명에 목숨을 걸고 돈 셈이다. 다시는 안 할 내기다.`,
      win:{ exp:20, dream:3 }, lose:{ hp:-27, spirit:-17 } },
    { l:'② 등을 꺼서 구역 전체를 공평한 어둠으로 만든다.', k:'break', dc:24,
      ok:`등 밑에 모인 것들은 빛에 길든 것들이다. 끄면 눈뜬장님이 된다.<br><br>그림자를 뻗어 등의 숨통을 쥐고 — 단번에 껐다. 서서히 끄면 눈이 적응한다. 단번이 요령이다.<br>먹물이 된 구역을, 어둠에 길든 이쪽 다섯만 벽 짚어 지났다. 등 밑에 있던 것들이 제자리에서 버둥대는 소리를 양옆으로 들으며. 공평한 어둠은 준비한 쪽의 편이다.`,
      ng:`등을 쥐는 순간 등이 마지막 힘으로 확 밝아졌다. 필라멘트의 유언이다.<br><br>그 한 번의 백광에 다섯 그림자가 벽에 도장처럼 찍혔다.<br>어둠이 내리고, 찍힌 자리를 기억하는 것들이 그리로 몰렸다. 다섯은 이미 반대 벽에 있었다. 몰린 것들이 빈 벽을 다투는 소리를 들으며 구역을 빠졌다. 유언치고 고약했다.`,
      win:{ exp:18, dream:2 }, lose:{ mind:-18, spirit:-16 } }
  ] },

{ at:'S2', t:'잎 그림자 — 얼룩의 법',
  x:`천장 틈으로 드는 빛이 양치 잎을 지나 바닥에 얼룩을 깐다. 흔들리는 얼룩 수천 개.<br><br>
    낮은 것들이 그 얼룩 사이로 다닌다. 얼룩무늬 가죽을 입고. 얼룩 속에서 얼룩은 안 보인다.<br>
    사람 그림자는 얼룩이 아니다. 통짜다. 통짜는 얼룩밭에서 도장처럼 찍힌다.<br><br>
    저쪽 가죽이 되는 수는 없다. 그림자를 가죽으로 만들면 된다.`,
  o:[
    { l:'① 다섯 그림자를 잎 얼룩 무늬로 찢어 흩뜨린다.', k:'hide', dc:25, wake:1,
      ok:`제 그림자를 잎 모양으로 백 조각 냈다. 조각들이 바닥 얼룩에 섞여 흔들린다. 바람 부는 박자로.<br><br>일행 그림자도 한 장씩 찢었다. 아까워하는 사람도 있었지만, 통짜로 얼룩밭에 찍히는 것보다 낫다.<br>얼룩이 된 그림자들을 끌고 밭을 지났다. 낮은 것 하나가 바로 옆을 지나갔다. 서로의 얼룩이 서로를 지나쳤다.<br><br>그림자를 깨뜨려 쓰는 법. 온전한 모양만 연장인 게 아니었다. 조각도 연장이다. 자리가 조각을 원하면.`,
      ng:`찢은 조각들이 바람 박자를 반 박자 놓쳤다.<br><br>잎 얼룩은 다 같이 흔들리는데 이쪽 조각들만 늦게 흔들렸다. 얼룩밭에 결 다른 얼룩 백 개.<br>낮은 것 둘이 그 결을 보고 멈췄다. 조각을 한꺼번에 거둬 통짜로 뭉치고 바위 그늘로 굴렀다. 결 다른 얼룩이 사라진 자리를 둘이 한참 맴돌았다. 그림자 깁는 데 이틀 치 마력이 들었다.`,
      win:{ exp:22, dream:3 }, lose:{ mind:-18, spirit:-18 } },
    { l:'② 얼룩이 제일 굵게 겹치는 그늘 줄기만 밟아 간다.', k:'sense', dc:24,
      ok:`얼룩에도 강과 개울이 있다. 잎이 세 겹 겹치는 자리는 그늘이 강처럼 굵다.<br><br>그 강줄기만 이어 밟았다. 통짜 그림자가 굵은 그늘에 잠겨 안 보인다.<br>강이 끊기는 데서는 바람이 잎을 눕힐 때까지 기다렸다 건넜다. 얼룩밭 전체를 그렇게 지났다. 빛 한 번 안 밟고.`,
      ng:`그늘 강을 따라가는데 해가 — 천장 틈의 빛이 구름에 먹혔다.<br><br>얼룩이 통째로 사라지고 밭이 한 장의 흐린 그늘이 됐다. 길이 사라진 것이다.<br>빛이 돌아올 때까지 그 자리에 섰다. 낮은 것들도 다 같이 멈춰 있었다. 얼룩이 없으면 저쪽 가죽도 소용없는 것이다. 빛이 돌아오고, 서로 모르는 척 제 갈 길을 갔다.`,
      win:{ exp:18, dream:2 }, lose:{ mind:-17, spirit:-16 } }
  ] },

{ at:'S2', t:'물그림자 — 수면 다리미',
  x:`물에 잠긴 길은 물낯이 문제다. 지나가는 것의 그림자가 물속으로 비쳐 든다.<br><br>
    물밑에 사는 것들은 머리 위 물낯을 하늘 삼아 본다. 그 하늘에 그림자가 뜨면 — 올라온다.<br>
    구름 한 점 없는 하늘에 새 다섯 마리가 뜨는 셈이다.<br><br>
    하늘을 흐리면 된다.`,
  o:[
    { l:'① 마력로 물낯에 흐린 막을 깔아 그림자를 지운다.', k:'steady', dc:24, cost:{ mana:31 },
      ok:`마력을 물낯에 한 겹 폈다. 수면이 간유리처럼 흐려진다.<br><br>흐린 하늘에는 그림자가 안 찍힌다. 다섯이 그 위 길을 지나는 동안 물밑 것들의 하늘은 내내 흐렸다.<br>지나고 막을 걷자 물이 도로 맑아졌다. 물밑에서 긴 것이 맑아진 하늘을 올려다보는 그림자가 비쳤다. 날이 개서 올려다본 하늘에는 이미 아무것도 없다.`,
      ng:`막을 까는데 물살이 막을 밀어 한 귀퉁이가 걷혔다.<br><br>그 맑은 귀퉁이로 막내 그림자가 반 장 비쳤다.<br>물밑이 그 자리로 몰렸다. 수면이 끓듯 일었다. 전원이 막 깔린 쪽으로만 뛰어 길을 벗어났다. 등 뒤에서 그 귀퉁이 물이 한 길 솟았다 내렸다. 반 장 그림자 값이 그 정도였다.`,
      win:{ exp:20, dream:3 }, lose:{ hp:-27, mind:-14 } },
    { l:'② 그림자를 미리 걷어 품에 안고 맨몸으로 지난다.', k:'hide', dc:24,
      ok:`물에 들기 전에 다섯 그림자를 걷어 둘둘 말아 품에 안았다.<br><br>그림자 없는 다섯이 물길을 지났다. 물밑 하늘에는 빈 물결만 지나갔다.<br>건너편에서 그림자를 한 장씩 돌려줬다. 다들 제 그림자를 도로 밟고서야 얼굴이 풀렸다. 그림자 없이 걷는 기분은 겪어 본 사람만 안다. 가볍고, 가벼워서 무섭다.`,
      ng:`다섯 장을 품기엔 팔이 모자랐다. 한 장이 반쯤 흘러내려 물낯에 끌렸다.<br><br>물밑에서 그 끌리는 끝을 물었다. 홱.<br>그림자 주인이 앞으로 고꾸라질 뻔한 걸 둘이 붙들고, 이쪽은 그림자를 당겼다. 물속과 줄다리기. 그림자 끝 한 뼘을 떼어 주고야 끝났다. 뗀 자리는 아문다. 주인 발이 보름 시릴 뿐이다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-26, spirit:-18 } }
  ] },

{ at:'S2', t:'울타리 그림자 — 그어진 금',
  x:`울타리 그림자가 땅에 창살 무늬로 깔린다.<br><br>
    낮은 것들이 그 무늬를 안 밟는다. 빙 돌아간다. 울타리에 물린 기억이 무늬에도 묻은 것이다.<br>
    쇠는 못 옮겨도 그림자는 옮긴다. 그림자술사라면.<br><br>
    가짜 울타리를 긋는 붓이 손에 있다.`,
  o:[
    { l:'① 창살 그림자를 떠서 일행 둘레에 울타리 금을 긋는다.', k:'hide', dc:25, wake:1,
      ok:`울타리 그림자를 한 발 너비로 길게 떠냈다. 들킬 것 없는 도둑질이다. 그림자는 줄어든 티가 안 난다.<br><br>떠낸 창살 무늬를 야영 자리 둘레에 둥글게 깔았다. 이음매는 손가락으로 문질러 녹였다.<br>밤새 낮은 것들이 금 밖을 돌았다. 한 놈은 금에 코를 박을 듯 대다가 제 기억에 제가 놀라 물러섰다. 쇠 없이 쇠 울타리를 치는 법. 무서움은 무늬에 산다. 무늬는 옮겨 심을 수 있다.`,
      ng:`금을 긋다 마력이 달려 서쪽 한 뼘이 흐리게 남았다.<br><br>낮은 것들은 흐린 데를 귀신같이 안다. 울타리도 삭은 데부터 미는 것들이다.<br>새벽에 한 놈이 그 한 뼘으로 코를 들이밀었다. 불침번이 소리 안 나는 돌팔매로 쫓았다. 아침까지 그 한 뼘만 지키느라 전원이 반잠을 잤다. 금은 긋다 말면 문이 된다.`,
      win:{ exp:22, dream:3 }, lose:{ mind:-18, spirit:-16 } },
    { l:'② 진짜 울타리 그림자 위로만 걸어 창살을 타고 돈다.', k:'evade', dc:24,
      ok:`창살 그림자 위는 낮은 것들이 안 오는 길이다. 좁지만 비어 있다.<br><br>그림자 창살을 외줄 삼아 밟으며 울타리를 따라 돌았다. 그림자 밖은 저쪽 땅, 그림자 안은 이쪽 길.<br>해가 — 빛이 기울며 창살이 길어지자 길도 같이 길어졌다. 빛이 이쪽 길을 늘여 준 셈이다. 공짜로 받는 길은 오랜만이었다.`,
      ng:`창살 위를 걷는데 구름이 빛을 먹었다. 창살이 한꺼번에 흐려졌다.<br><br>길이 지워지자 낮은 것들의 조심도 지워졌다. 한 놈이 흐려진 금을 성큼 넘어왔다.<br>울타리 철선을 돌로 때려 울렸다. 놈이 그 소리에 기억이 돌아와 물러섰다. 빛이 돌아올 때까지 철선을 두드리며 버텼다. 팔이 빠지는 줄 알았다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-27, mind:-15 } }
  ] },

{ at:'S2', t:'큰 것의 그림자 — 지나가는 지붕',
  x:`트인 벌판을 건너야 하는데 하늘 틈 빛이 하필 좋다. 숨을 그늘 한 점 없다.<br><br>
    벌판 저쪽에서 큰 것이 이쪽 방향으로 비스듬히 걸어온다. 집채만 한 그림자를 끌고.<br>
    위험한 것과 그 위험이 끄는 그늘이 같이 온다.<br><br>
    저 그늘에 올라타면 벌판을 공짜로 건넌다. 발밑이 지옥인 지붕이지만.`,
  o:[
    { l:'① 큰 것의 그림자에 올라 벌판을 같이 건넌다.', k:'hide', dc:26,
      doom:{ title:'지붕 밑의 턱', what:'그림자째 낚여 큰 것의 발치로 끌려갑니다', dc:20, sec:36,
        text:`그림자 꼬리 쪽에 올라탔다. 큰 것이 걸으면 그늘이 걷고, 그늘 속에서 다섯이 걸었다.<br><br>벌판 한가운데서 큰 것이 멈췄다. 그늘도 멈춘다. 다섯도 멈췄다.<br>큰 것이 목을 돌렸다. 제 그림자를 봤다. 제 그림자가 — 오늘따라 무거운 것이다. 그늘을 끄는 느낌은 주인이 제일 잘 안다.<br><br>큰 머리가 그림자 꼬리를 향해 내려온다. 그늘째 퍼 올리는 턱. 다섯 중 제일 뒤에 섰던 이쪽이 그늘과 함께 낚인다. 발치로, 이빨 쪽으로.`,
        dieText:`큰 것이 벌판 가운데서 한참 제 그림자를 들여다봤다.<br><br>그러고는 다시 걸었다. 그림자가 한결 가벼워진 걸음으로.<br>벌판에는 아무 자국도 안 남았다. 큰 것의 발자국 말고는.`,
      },
      ok:`그림자 꼬리는 버리고 — 꼬리는 주인 눈이 닿는 자리다 — 그림자 복판, 배 밑 그늘에 탔다.<br><br>배 밑은 주인도 못 보는 자리다. 목이 아무리 길어도.<br>큰 것의 걸음에 맞춰 벌판을 건넜다. 발 디딜 때마다 땅이 울려 이쪽 발소리는 처음부터 없는 것과 같았다. 벌판 끝에서 그늘이 바위 지대와 겹치는 순간 바위 그늘로 갈아탔다.<br>큰 것은 제 그림자에 다섯이 세 들었던 걸 끝내 몰랐다. 집세는 못 냈다. 낼 방법이 없었다.`,
      win:{ exp:24, dream:3 } },
    { l:'② 그늘에 타지 않고 그늘이 지나간 자국만 밟는다.', k:'sense', dc:24,
      ok:`큰 그늘이 지나간 풀은 잠깐 서늘하다. 서늘한 풀은 몇 숨 동안 냄새가 죽는다.<br><br>그늘 꽁무니에서 스무 걸음 떨어져, 그늘이 식히고 간 길만 밟았다. 냄새 죽은 길은 코 밝은 것들에게 빈 길이다.<br>큰 것 덕에 벌판을 건넜다. 저쪽은 모르는 동행이었다. 모르는 동행이 제일 편한 동행이다.`,
      ng:`스무 걸음이 벌어졌다. 큰 것의 걸음이 생각보다 길었다.<br><br>식은 길이 데워지며 이쪽 냄새가 알몸으로 벌판에 섰다.<br>벌판 가장자리 수풀에서 낮은 것들이 코를 들었다. 남은 거리를 전력으로 뛰었다. 바위 지대에 들고 나서 셌다. 다섯. 다 있었다. 숨은 반나절 뒤에 돌아왔다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-28, mind:-15 } }
  ] },

{ at:'S2', t:'양치 밑 — 그림자 세기',
  x:`양치 숲 그늘 밑에 낮은 것들이 엎드려 쉰다. 몇인지 세어야 길을 그린다.<br><br>
    몸은 얼룩 가죽이라 안 보인다. 그림자는 — 가죽이 못 속인다.<br>
    엎드린 것들의 그림자가 잎 그늘 사이사이 몸보다 짙게 고여 있다.<br><br>
    그림자술사는 그림자로 세상을 센다. 몸이 숨어도 그림자는 출석한다.`,
  o:[
    { l:'① 잎 그늘과 몸 그늘을 갈라 수를 센다.', k:'gaze', dc:24,
      ok:`잎 그늘은 바람에 흔들린다. 몸 그늘은 숨에 흔들린다. 흔들리는 박자가 다르다.<br><br>숨 박자로 흔들리는 그늘만 골라 셌다. 일곱. 머리 방향까지 읽었다. 다섯은 바람 아래로, 둘은 바람 위로 코를 두고 잔다.<br>바람 위 둘의 코가 못 미치는 비탈로 길을 그렸다. 일곱을 다 피해서. 세어 본 일곱은 일곱이 아니다. 지도다.`,
      ng:`세는 중에 여덟째 그늘을 찾았다. 숨 박자인데 — 흔들림이 점점 커진다.<br><br>깨고 있는 것이다.<br>세기를 접고 물러났다. 여덟째가 기지개 켜는 소리가 수풀을 갈랐다. 하나가 깨면 일곱이 깬다. 비탈이고 뭐고 제일 먼 길로 돌았다. 센 보람은 있었다. 몇에게서 도망치는지는 알았으니까.`,
      win:{ exp:20, dream:3 }, lose:{ mind:-18, spirit:-16 } },
    { l:'② 바람이 양치를 눕힐 때 그늘째 섞여 지난다.', k:'hide', dc:24,
      ok:`바람이 오면 잎 그늘이 통째로 쓸린다. 그 쓸림에 다섯 그림자를 섞었다.<br><br>그늘이 쓸리는 방향으로만, 쓸리는 속도로만 걸었다. 엎드린 것들의 귀에 이쪽은 바람이었고, 눈에는 그늘이었다.<br>일곱 그림자 사이를 다섯 그림자가 지나갔다. 열둘 중 누구도 서로를 깨우지 않았다. 숲이 그날 제일 조용한 시간이었다.`,
      ng:`바람이 중간에 죽었다. 쓸리던 그늘이 일제히 서고, 이쪽 다섯만 반 걸음 더 쓸렸다.<br><br>엎드린 것 하나가 귀를 세웠다. 그늘이 선 뒤에 움직인 그늘을 들은 것이다.<br>전원 정지. 귀 세운 놈이 일어나 이쪽 수풀을 반 바퀴 돌았다. 콧김이 뒷목에 닿는 거리까지. 바람이 돌아와 숲 전체가 다시 쓸릴 때까지 다섯은 풀이었다. 뿌리까지 땀에 젖은 풀.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-26, spirit:-18 } }
  ] },

{ at:'S2', t:'낡은 승강기 — 창살 그림자',
  x:`승강기 격자문이 반쯤 열린 채 굳었다. 다섯이 들려면 그 틈을 하나씩 지나야 한다.<br><br>
    틈 앞 공터에 승강기 창살 그림자가 길게 깔렸다. 그리고 그 창살 그림자 위에 — 다른 그림자 하나가 엎드려 있다.<br>
    공터 어디에도 몸은 안 보인다. 그림자만 있다.<br><br>
    몸 없는 그림자는 둘 중 하나다. 그림자가 아니거나, 몸이 아주 잘 숨었거나.`,
  o:[
    { l:'① 엎드린 그림자의 주인 자리를 빛으로 되짚는다.', k:'gaze', dc:25,
      doom:{ title:'공터의 매복', what:'공터 모래 속에서 솟은 것에게 물려 끌려 들어갑니다', dc:20, sec:38,
        text:`그림자와 빛의 각을 이었다. 주인은 — 공터 한복판. 아무것도 없는 모래 바닥.<br><br>없는 게 아니었다. 모래 밑이었다. 모래를 뒤집어쓰고 엎드린 놈의 등이 그림자만 밖에 냈다.<br>각을 재느라 공터로 두 걸음 든 뒤였다.<br><br>모래가 터지며 턱이 솟았다. 종아리를 물렸다. 모래 밑으로 끌려 들어간다. 모래는 소리도 삼킨다. 일행이 들은 건 모래 쏟아지는 소리뿐이다.`,
        dieText:`공터 모래가 한참 들썩이다 가라앉았다.<br><br>창살 그림자 위에 엎드린 그림자가 도로 생겼다. 전보다 조금 배부른 모양으로.<br>승강기 격자문은 반쯤 열린 채 다음 팀을 기다린다. 틈 앞의 공터와 함께.`,
      },
      ok:`그림자와 빛의 각을 공터 밖에서 쟀다. 주인 자리는 공터 한복판 — 맨 모래 바닥이다.<br><br>맨바닥이 주인이면 주인은 바닥 밑이다. 모래 매복.<br>공터를 버리고 승강기 뒤쪽 철탑 다리를 타고 돌아 격자문 틈에 닿았다. 다섯이 다 탄 뒤 창살 사이로 공터를 내려다봤다. 모래가 숨 쉬듯 느리게 오르내리고 있었다. 기다림이 허탕 되는 걸 끝까지 모르는 숨이었다.`,
      win:{ exp:22, dream:3 } },
    { l:'② 돌을 공터에 던져 그림자의 주인을 먼저 일으킨다.', k:'break', dc:24,
      ok:`주먹돌을 공터 복판에 던졌다. 퍽.<br><br>모래가 터지며 넓적한 놈이 솟아 돌을 물었다. 돌인 걸 알고 뱉는 데 세 숨.<br>그 세 숨에 다섯이 공터 가장자리를 돌아 격자문 틈으로 들었다. 놈은 모래를 털며 한참 공터를 돌다 도로 묻혔다. 다음 돌을 기다리는 자세로. 돌은 이제 안 간다.`,
      ng:`돌이 빗나가 창살 그림자 위에 떨어졌다. 모래 밑 놈이 안 속았다.<br><br>대신 돌 소리에 숲 쪽에서 낮은 것 둘이 공터로 나왔다. 셈이 둘 늘었다.<br>낮은 것들과 모래 밑 놈이 서로를 발견하는 북새통에 틈으로 비집어 들었다. 마지막 사람 옷자락이 격자에 찢겼다. 천 조각이 공터에 남았다. 저것들 몫의 수수께끼로.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-28, mind:-14 } }
  ] },

{ at:'S2', t:'빛 기둥 — 천장 틈',
  x:`숲이 끝나는 자리에 천장 틈으로 빛 기둥이 내리꽂힌다. 길은 그 기둥을 지나야 한다.<br><br>
    기둥 속은 대낮이다. 지나는 것의 그림자가 사방 숲 바닥에 수레바퀴처럼 뻗는다.<br>
    숲의 눈이란 눈이 다 그 바퀴를 보게 된다.<br><br>
    빛은 못 끈다. 하늘이 켠 빛이다. 그림자 쪽을 손봐야 한다.`,
  o:[
    { l:'① 그림자를 몸 바로 밑에 못 박아 바퀴를 안 만든다.', k:'hide', dc:25, wake:1,
      ok:`빛 기둥에 들기 직전, 그림자를 접고 접어 발바닥 크기로 만들어 발밑에 못 박았다.<br><br>기둥 속을 지나는 동안 그림자는 발바닥 밑에만 있었다. 한낮의 정오처럼. 사방으로 뻗는 바퀴는 없었다.<br>숲의 눈들에게 이쪽은 그림자 없이 빛 속을 지나는 — 보이되 읽히지 않는 것이었다. 읽히지 않는 것은 쫓기지 않는다. 짐승은 모르는 것에 신중하다.<br><br>정오의 그림자. 빛이 제일 셀 때 그림자가 제일 작다는 것을, 아무 때나 만들 수 있게 됐다.`,
      ng:`못 박은 그림자가 기둥 한복판에서 빛의 무게에 삐져나왔다. 한 가닥이 수레바퀴 살처럼 뻗었다.<br><br>숲 저쪽에서 그 살을 밟는 것이 있었다. 밟히는 느낌이 발꿈치로 왔다.<br>그림자를 뜯어 거두고 남은 기둥을 뛰어 지났다. 밟았던 놈이 기둥 가장자리까지 쫓아와 빛 앞에서 멈췄다. 빛을 싫어하는 놈이었다. 운이 반, 빛이 반이었다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-27, spirit:-17 } },
    { l:'② 빛 기둥 속 떠도는 먼지에 그림자를 풀어 섞는다.', k:'steady', dc:25,
      ok:`빛 기둥 속엔 먼지가 눈처럼 떠돈다. 그림자를 가루로 풀어 그 먼지에 섞었다.<br><br>가루 그림자는 바닥에 바퀴를 못 만든다. 기둥 속을 지나는 동안 이쪽 그림자는 허공에 먼지로 반짝였다.<br>지나고 나서 가루를 불러 모았다. 구할 때는 다 왔는데 — 몇 톨은 끝내 안 왔다. 빛 기둥 속에 이쪽 가루 몇 톨이 지금도 떠돈다. 그건 그냥 두기로 했다. 숲에 두고 가는 명함 치고는 예쁜 편이다.`,
      ng:`가루로 푸는 데까지는 됐다. 모으는 게 문제였다.<br><br>기둥을 다 지나 손을 폈는데 가루가 반만 왔다. 반은 기둥 속에서 서로 뭉쳐 — 작은 새 모양이 되어 날았다. 그림자는 주인 없이 오래 흩어지면 저 하고 싶은 대로 한다.<br>새를 쫓아가 잡느라 기둥을 두 번 더 지났다. 세 번째에 숲의 눈들이 수상해하기 시작해서, 새는 날개만 거두고 몸통은 다음에 받기로 했다. 발꿈치가 반쪽 무게다.`,
      win:{ exp:18, dream:2 }, lose:{ mind:-18, spirit:-19 } },
    { l:'③ 밤을 — 빛이 죽는 때를 기다린다.', k:'luck', dc:23,
      ok:`하늘이 켠 빛은 하늘이 끈다. 틈 가장자리 그늘에 다섯이 앉아 기다렸다.<br><br>구름인지 밤인지, 반 시진 만에 기둥이 흐려지다 죽었다.<br>죽은 기둥 자리를 어둠에 섞여 지났다. 기다림 값으로 공터 가장자리에서 마른 버섯 무더기도 땄다. 요리사 몫이다. 기다리는 일에는 가끔 이자가 붙는다.`,
      ng:`기다리는데 빛이 죽기는커녕 더 밝아졌다. 하늘 틈이 넓어진 것이다.<br><br>그늘 자리가 좁아지며 다섯이 바위 뒤로 포개 앉는 꼴이 됐다.<br>결국 밝은 기둥을 그림자 접기로 하나씩 지났다. 기다린 반 시진은 허탕이 됐다. 허탕 끝의 일은 꼭 처음보다 어렵다. 팔다리가 두 배로 무거웠다.`,
      win:{ exp:16, dream:2, item:'야생 버섯' }, lose:{ mind:-16, spirit:-15 } }
  ] }

]);

// ── 첩자 (agent) · 자원 없음 ──
kJob('agent', 'S', [

{ at:'S', t:'어둠 — 속지 않는 상대',
  x:`첩자의 장사 밑천은 거짓말이다. 신분, 표정, 서류, 목소리.<br><br>
    여기 것들에게는 그 밑천이 한 푼도 안 통한다. 거짓말은 말을 믿는 상대에게나 파는 물건이다.<br>
    저것들은 말을 안 믿는다. 냄새와 소리만 믿는다.<br><br>
    그러면 냄새와 소리로 거짓말을 하면 된다. 종이가 바뀌었을 뿐, 쓰는 일은 같다.`,
  o:[
    { l:'① 저쪽이 믿는 것부터 조사한다 — 믿는 것만 속일 수 있다.', k:'gaze', dc:23, wake:1,
      ok:`반나절을 들여 지나는 것들을 지켜봤다. 무엇에 멈추고, 무엇을 그냥 지나치는지.<br><br>물 듣는 소리는 지나친다. 쇠 소리에는 멈춘다. 제 무리 냄새는 지나치고, 피 냄새에는 모인다. 믿음의 목록이 나왔다.<br>목록의 첫 줄에 적었다. 저것들은 물소리를 안 의심한다.<br><br>속일 상대의 믿음부터 캐는 것. 사람 상대로 늘 하던 뒷조사다. 상대가 사람이 아니어도 순서는 같았다.`,
      ng:`지켜보는 자리가 너무 좋았다. 좋은 자리는 저쪽도 안다.<br><br>지나던 것 하나가 이쪽 바위 그늘을 향해 코를 들었다. 관찰자가 관찰당하는 순간이다.<br>조사를 접고 바위 반대편으로 흘러 나갔다. 목록은 반 줄로 끝났다. 반 줄 얻자고 들킨 자리 하나를 치렀다. 밑지는 장부다.`,
      win:{ exp:20, dream:3 }, lose:{ mind:-17, spirit:-18 } },
    { l:'② 일단 아무것도 아닌 것으로 지나간다.', k:'hide', dc:24,
      ok:`첩자 노릇의 반은 아무것도 아닌 사람 되기다. 눈에 띄는 구석을 전부 지운 몸.<br><br>여기 식으로 바꿨다. 냄새 나는 구석, 소리 나는 구석을 지웠다. 장신구를 빼고, 숨을 줄이고, 걸음에서 목적을 뺐다.<br>목적 없는 걸음은 사냥감 걸음이 아니다. 지나던 것들이 이쪽을 바람 든 먼지만큼도 안 쳤다. 무명(無名)은 어느 나라에서나 통하는 여권이다.`,
      ng:`구석을 지우다 하나를 놓쳤다. 벨트의 쇠 고리.<br><br>딸깍. 한 번. 어둠 속 걸음 하나가 방향을 틀었다.<br>고리를 움켜쥐고 벽 틈에 몸을 구겼다. 그것이 소리 자리를 세 바퀴 돌고 갔다. 여권에 도장 하나가 빠져 있던 셈이다. 출입국은 그 한 장을 꼭 본다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-26, mind:-15 } }
  ] },

{ at:'S', t:'손짓말 — 소리 없는 회의',
  x:`말소리는 못 쓴다. 속삭임도 여기서는 말이다.<br><br>
    일행은 다섯. 급할 때 뜻이 안 통하면 다섯이 다섯 방향으로 뛴다. 그게 전멸의 지름길이다.<br>
    첩자는 손짓말을 안다. 항구에서, 노름판에서, 감옥에서 쓰던 것들.<br><br>
    쓸 만한 것만 추려 오늘 밤 안에 가르쳐야 한다.`,
  o:[
    { l:'① 꼭 필요한 열 마디만 추려 손에 쥐여 준다.', k:'bond', dc:23, wake:1,
      ok:`정지. 엎드려. 와. 가. 위. 아래. 몇 마리. 어느 쪽. 기다려. 뛰어.<br><br>열 마디를 골라 어둠 속에서 손바닥에 손가락으로 눌러 가르쳤다. 눈 없이도 통하게.<br>이튿날 갈림목에서 막내가 이쪽 손바닥에 세 마디를 눌렀다. 위. 둘. 기다려. 천장의 둘이 지나갈 때까지 다섯이 한 몸처럼 멎어 있었다.<br><br>말을 줄이는 게 아니라 말을 바꾸는 것. 첩자의 암호가 처음으로 저 혼자가 아니라 다섯을 살렸다.`,
      ng:`열 마디가 밤새 가르치기엔 많았다. 막내가 와와 가를 바꿔 외웠다.<br><br>다음 날 그 두 마디가 하필 갈림목에서 나왔다. 와, 했는데 가 버렸다.<br>흩어진 둘을 다시 모으는 데 반 시진이 걸렸다. 그동안 어둠이 두 번 스쳐 갔다. 암호는 만드는 것보다 외우게 하는 게 일이라는 걸 또 배웠다.`,
      win:{ exp:18, dream:3 }, lose:{ mind:-16, spirit:-17 } },
    { l:'② 손짓 대신 실을 — 다섯 손목을 신호줄로 잇는다.', k:'fix', dc:23,
      ok:`가는 실로 다섯 손목을 이었다. 한 번 당기면 정지, 두 번이면 전진, 길게 끌면 엎드려.<br><br>어둠 속에서는 손짓도 안 보인다. 실은 보일 필요가 없다.<br>그날 밤 행군에서 실이 여덟 번 당겨졌다. 여덟 번 다 제때 멎고 제때 걸었다. 실 한 타래가 입 다섯 개 몫을 했다.`,
      ng:`실이 모퉁이 돌 때 바위 모서리에 걸렸다. 당긴 적 없는 정지 신호가 전원에게 갔다.<br><br>다섯이 길 한복판에 우뚝 섰다. 하필 트인 자리였다.<br>걸린 실을 푸는 사이 멀리서 긴 울음이 지나갔다. 실은 이후 허리끈에 걸어 바닥에서 띄웠다. 연장은 쓰면서 고치는 물건이다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-25, mind:-15 } }
  ] },

{ at:'S', t:'거짓 발자국',
  x:`뒤에 코 밝은 것이 붙었다. 따돌려야 한다.<br><br>
    첩자는 꼬리 자르는 법을 안다. 거짓 행선지를 흘리고, 진짜 길은 지운다.<br>
    사람 상대라면 가짜 차표 한 장이면 된다. 여기서는 차표가 발자국과 냄새다.<br><br>
    신발 한 짝과 땀 밴 수건 — 쓸 재료는 있다.`,
  o:[
    { l:'① 신발과 수건으로 옆 갈래에 거짓 길을 깐다.', k:'hide', dc:24,
      doom:{ title:'길 끝의 독자', what:'거짓 길을 깔던 손목째 물려 끌려갑니다', dc:19, sec:44,
        text:`옆 갈래에 발자국을 찍으며 들어갔다. 수건은 길 끝에 떨어뜨릴 참이었다.<br><br>길 끝에서 돌아서는데 — 길 끝에 그것이 앉아 있었다.<br>거짓 길은 읽는 놈 등 뒤에 까는 것이다. 그런데 이놈은 따라오던 놈이 아니었다. 길목마다 하나씩 있는 줄 몰랐다.<br><br>수건 쥔 손목을 물렸다. 끌려간다. 제가 깐 거짓 길 위로. 발자국 찍힌 방향과 반대로 끌리면서, 이 길이 누군가에게는 진짜 길이 되는 걸 봤다.`,
        dieText:`옆 갈래에 사람 발자국이 또렷이 남았다.<br><br>들어간 자국은 있는데 나온 자국이 없다.<br>따라오던 코 밝은 것이 그 길로 꺾었다. 길 끝에서 먼저 온 놈과 나눠 가질 것이 있었다.`,
      },
      ok:`갈래 입구에서 먼저 돌을 던져 봤다. 대답 없음. 빈 갈래다. 확인하고 들어가 깔았다.<br><br>발자국은 안쪽으로 점점 깊게 — 지친 걸음으로. 길 끝 바위 틈에 땀 수건을 쑤셔 넣었다. 막다른 데 숨은 모양새로.<br>진짜 길은 물길로 잡아 냄새를 끊었다. 한 시진 뒤 멀리서 바위 틈을 파헤치는 소리가 났다. 수건은 오래 버텨 줬다.<br><br>거짓 길에도 답사가 먼저다. 무대 안 보고 각본만 쓰면 오늘 같은 밤 죽는다.`,
      win:{ exp:22, dream:3 } },
    { l:'② 길을 거꾸로 돌아 따라오는 놈 뒤에 선다.', k:'sense', dc:24,
      ok:`꼬리를 자르는 다른 법 — 꼬리의 꼬리가 되는 것.<br><br>바위 지대에서 크게 원을 그려 이쪽 흔적 위로 되돌아왔다. 따라오던 놈이 이제 앞에 있다. 이쪽 발자국에 코를 박은 채.<br>놈의 뒤를 스무 걸음 떨어져 따라갔다. 놈은 발자국이 끊긴 물가에서 반나절을 헤맸다. 그 꼴을 다 보고 돌아섰다. 쫓기는 줄 알았던 저녁이 미행 연습이 됐다.`,
      ng:`원을 그리다 바람을 등졌다. 이쪽 냄새가 앞질러 배달됐다.<br><br>놈이 발자국에서 코를 들고 곧장 이쪽 바람을 거슬러 왔다.<br>바위 지대라 발자국은 없지만 바람은 어쩔 수 없었다. 벼랑 턱에 매달려 바람이 바뀌기를 기다렸다. 손가락이 펴지지 않을 때쯤 바뀌었다. 바람 보는 눈이 반나절 사이 늙었다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-27, mind:-16 } }
  ] },

{ at:'S', t:'쉬는 자리 — 관찰 수첩',
  x:`쉬는 참마다 수첩을 적는다. 몸에 밴 일이다.<br><br>
    오늘 치를 넘겨 본다. 긴 것 — 모퉁이에서 꼭 멈춤. 코 밝은 것 — 물가를 싫어함. 쓸고 다니는 것 — 아홉을 세고 돌아옴.<br>
    사람 뒤를 밟을 때 쓰던 칸에 짐승이 들어앉았을 뿐, 수첩은 수첩이다.<br><br>
    버릇은 반복이고, 반복은 약점이다. 누구의 것이든.`,
  o:[
    { l:'① 버릇들을 겹쳐 이 구역의 시간표를 짠다.', k:'gaze', dc:23, wake:1,
      ok:`낱장의 버릇들을 한 장에 겹쳤다. 긴 것이 모퉁이에 멈추는 때, 쓸고 다니는 것의 아홉 숨, 코 밝은 것이 물가를 비우는 참.<br><br>겹치자 보였다. 세 버릇이 다 비는 구멍이 하루 두 번 있다. 그 구멍이 이 구역의 통행 시간이다.<br>다음 날 그 시간표로 두 구역을 눈 감고 걷듯 지났다.<br><br>버릇을 모으면 시간표가 된다. 시간표를 쥔 쪽이 그 동네 주인이다. 주인 몰래 주인 노릇 하는 게 첩자 장사다.`,
      ng:`시간표를 믿고 둘째 구멍에 나섰는데 쓸고 다니는 것이 안 비켰다.<br><br>버릇이 바뀐 것이다. 살아 있는 것의 버릇은 산 것이라 자란다.<br>구멍 아닌 시간에 트인 데 선 꼴이 됐다. 벽감까지 뛰어 반 시진을 굳어 있었다. 수첩 귀퉁이에 적었다. 시간표는 사흘마다 다시 짤 것.`,
      win:{ exp:20, dream:3 }, lose:{ mind:-18, spirit:-16 } },
    { l:'② 수첩을 일행에게 소리 없이 돌려 읽힌다.', k:'bond', dc:23,
      ok:`수첩을 펴서 돌렸다. 다섯이 등불 밑에서 차례로 읽었다.<br><br>읽고 나자 질문이 손짓으로 왔다. 긴 것은 왜 모퉁이에서 멈추나. 답을 적었다. 모퉁이 너머를 듣는 것. 그러니 모퉁이 직전이 제일 안전하다.<br>다음 날부터 다섯이 다 같은 눈으로 걸었다. 정보는 나눠야 정보다. 혼자 쥔 정보는 유언이 되기 쉽다.`,
      ng:`돌려 읽는 사이 등불이 수첩 위에서 너무 오래 탔다.<br><br>불빛이 벽에 어른댄 시간만큼 위험이 쌓였다. 벽 너머에서 돌아앉는 기척.<br>등불을 끄고 나머지는 내일 읽기로 했다. 반만 읽은 정보는 반만 못한 법인데, 그날따라 하필 안 읽은 반이 다음 날 필요했다. 운까지는 수첩에 안 적힌다.`,
      win:{ exp:16, dream:2 }, lose:{ mind:-16, spirit:-17 } }
  ] },

{ at:'S', t:'낡은 수법 — 돌 던지기',
  x:`길목을 지키는 것이 있다. 돌을 던져 소리로 꾀는 게 정석이다.<br><br>
    돌을 던졌다. 그것이 소리 쪽으로 — 안 간다. 고개만 까딱하고 제자리다.<br>
    한 번 더 던졌다. 이번에는 아예 안 돌아본다.<br><br>
    학습이다. 여기 오래 산 것들은 돌 소리와 밥 소리를 가린다. 수법이 낡으면 바꿔야 한다. 그게 이 바닥 철칙이다.`,
  o:[
    { l:'① 돌이 아니라 돌 두 개 — 밥이 내는 소리를 짓는다.', k:'hide', dc:24,
      ok:`밥은 어떤 소리를 내나. 다친 것은 한 번 구르고, 긁고, 또 구른다. 박자가 있다.<br><br>돌 두 개를 실로 묶어 던졌다. 떨어져 구르고 — 실이 당겨 — 긁히고 — 또 구른다. 다친 것이 버둥대는 박자.<br>길목의 것이 이번에는 전속력으로 갔다. 학습된 귀는 학습된 것만 거른다. 새 교재는 못 거른다.<br>그 사이 다섯이 길목을 지났다. 교재는 회수 못 했다. 수업료로 쳤다.`,
      ng:`돌 두 개가 공중에서 실이 엉켜 한 덩이로 떨어졌다. 퍽. 그냥 돌 소리.<br><br>길목의 것이 고개도 안 까딱했다. 세 번째 낡은 수법이 된 것이다.<br>그날은 길목을 포기하고 밤새 벼랑 쪽 비탈로 돌았다. 비탈에서 두 번 미끄러졌다. 수법이 낡으면 몸이 품을 문다.`,
      win:{ exp:20, dream:3 }, lose:{ hp:-26, mind:-15 } },
    { l:'② 소리를 접고 냄새로 꾄다 — 육포 한 조각.', k:'luck', dc:23,
      ok:`마지막 육포 반 조각을 바람 위쪽 멀리 던져 두었다.<br><br>길목의 것이 코를 들었다. 소리는 의심해도 냄새는 못 의심한다. 코는 귀보다 늦게 배운다.<br>그것이 육포를 찾아 떠난 사이 길목을 지났다. 육포 반 조각과 길 하나를 바꿨다. 이 동네 시세로는 헐값이다.`,
      ng:`던진 육포가 바람을 잘못 타 길목 바로 앞에 떨어졌다.<br><br>그것이 육포를 그 자리에서 먹었다. 길목을 지킨 채로. 밥상까지 차려 준 꼴이다.<br>배부른 놈은 더 안 움직인다. 결국 먼 길로 돌았다. 육포도 잃고 길도 잃었다. 던지기 전에 바람부터. 기본을 잊으면 기본에 당한다.`,
      win:{ exp:16, dream:2 }, lose:{ mind:-15, spirit:-16 } }
  ] },

{ at:'S', t:'저쪽의 정찰꾼',
  x:`무리에서 한 마리가 떨어져 나와 앞서 다닌다. 작고, 빠르고, 안 싸운다.<br><br>
    보고 돌아가기만 한다. 정찰이다.<br>
    동업자를 알아보는 데는 동업자가 제일 빠르다. 저놈이 보고 가는 것이 무리의 눈이다.<br><br>
    눈을 못 쓰게 하는 법은 둘이다. 감기거나, 헛것을 보이거나. 첩자는 늘 후자를 판다.`,
  o:[
    { l:'① 정찰꾼의 눈에 헛것을 먹인다 — 빈 야영 자국.', k:'hide', dc:24, wake:1,
      ok:`정찰꾼이 돌 시간에 맞춰 가짜 자국을 차렸다. 식은 불자리, 구긴 풀, 일부러 흘린 끈 조각. 사람 다섯이 여기서 자고 서쪽으로 떠난 그림.<br><br>정찰꾼이 와서 읽고 갔다. 꼼꼼한 놈이라 다행이다. 꼼꼼한 눈일수록 좋은 그림에 깊이 속는다.<br>무리가 서쪽을 비우고 몰려갔다. 다섯은 동쪽으로 갔다.<br><br>적의 눈을 뽑는 게 아니라 빌리는 것. 정찰꾼은 오늘 이쪽 소식을 제 무리에 성실히 배달했다. 가짜 소식을.`,
      ng:`가짜 불자리가 너무 식어 있었다. 재가 바람에 다 날린 불자리는 하루 전 그림이다.<br><br>정찰꾼이 읽다 말고 고개를 들었다. 하루 전 자국에 아직 남은 사람 냄새 — 셈이 안 맞는 것이다.<br>놈이 자국 둘레를 넓게 돌기 시작했다. 진짜 냄새의 가장자리를 찾는 돌기. 그림을 포기하고 밤길을 벌었다. 그림은 디테일이 전부다. 알면서 또 당했다.`,
      win:{ exp:22, dream:3 }, lose:{ mind:-18, spirit:-17 } },
    { l:'② 정찰꾼이 못 가 본 땅으로만 길을 잡는다.', k:'sense', dc:23,
      ok:`정찰꾼의 발자국을 사흘 치 거슬러 읽었다. 놈이 도는 길은 넓지만 정해져 있다. 벼랑 밑과 가시덤불 안쪽은 비어 있다.<br><br>정찰 안 간 땅은 무리의 지도에 없는 땅이다. 지도에 없는 데서는 아무도 이쪽을 못 찾는다.<br>가시에 긁히고 벼랑에 매달리는 길이었다. 긁힌 자국은 아물지만 지도에 오른 몸은 못 내린다. 셈은 그렇게 하는 것이다.`,
      ng:`사흘 치를 읽었는데 넷째 날 정찰꾼이 길을 넓혔다. 젊은 놈이라 부지런했다.<br><br>빈 땅인 줄 알고 든 가시덤불에서 놈과 정면으로 마주쳤다.<br>서로 한 숨씩 굳어 있다가 — 놈이 먼저 돌아서 뛰었다. 보고하러. 덤불을 반대로 뚫고 전력으로 거리를 벌었다. 무리가 왔을 때 그 자리에는 가시와 천 조각만 있었다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-28, mind:-15 } }
  ] },

{ at:'S', t:'냄새 옷 — 새 신분',
  x:`첩자는 신분을 갈아입는다. 옷, 말씨, 걸음, 서류.<br><br>
    여기 것들의 눈은 코다. 그러니 신분도 냄새다.<br>
    사람 냄새는 이 동네에서 수배 전단이다. 갈아입어야 한다.<br><br>
    이 구역의 흔한 냄새 — 곰팡, 녹물, 죽은 지 오랜 것. 셋 다 구할 수 있다.`,
  o:[
    { l:'① 구역의 냄새를 세 겹 입어 토박이가 된다.', k:'hide', dc:24,
      ok:`맨 밑에 녹물, 그 위에 곰팡, 겉에 마른 죽은 내. 바닥부터 차례로 입었다. 냄새에도 입는 순서가 있다. 속옷부터 입듯이.<br><br>마지막으로 제 숨을 소매에 뱉어 봤다. 사람 내가 밑에서 안 올라온다.<br>그 몸으로 코 밝은 것 곁을 두 번 지났다. 두 번 다 토박이 취급이었다. 투명 인간보다 나은 건 동네 사람이다. 어느 동네에서나.`,
      ng:`세 겹을 입었는데 속에서 땀이 났다. 땀은 새 냄새다. 세 겹 밑에서 더운 사람 내가 배어 올라왔다.<br><br>코 밝은 것이 이쪽을 스치다 말고 두 번 맡았다. 겉은 토박이인데 속이 수상한 자.<br>검문에 걸리기 전에 샛길로 빠졌다. 냄새 옷도 땀받이가 필요하다. 다음에는 속에 마른 천을 한 겹 더 감기로 했다.`,
      win:{ exp:20, dream:3 }, lose:{ mind:-17, spirit:-18 } },
    { l:'② 일행 전원에게 같은 냄새를 입혀 한 무리로 만든다.', k:'bond', dc:24,
      ok:`혼자 토박이면 넷이 수배자다. 전원에게 같은 세 겹을 입혔다.<br><br>냄새가 같은 다섯은 저쪽 코에 한 덩어리다. 다섯 사람이 아니라 큰 것 하나.<br>구역을 지나는 동안 코 밝은 것들이 이쪽 덩어리를 세지 않았다. 덩어리는 세지 않는다. 지나가는 바위 하나를 누가 세나.`,
      ng:`막내가 곰팡 칠을 반만 했다. 가려워서.<br><br>다섯 덩어리에서 한 줄기만 사람 내가 샜다. 섞인 냄새는 틀린 냄새보다 수상하다.<br>코 밝은 것이 덩어리 둘레를 돌기 시작했다. 샘을 찾는 코. 막내를 가운데 넣고 걸음을 빨리해 바람 센 능선으로 빠졌다. 바람이 수상함을 흩어 줬다. 바람 없었으면 긴 밤이었다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-26, spirit:-16 } }
  ] },

{ at:'S', t:'두드림 — 벽 너머의 답',
  x:`무너진 벽을 사이에 두고 일행 둘과 갈라졌다. 합류 지점을 정해야 한다.<br><br>
    약속한 두드림 암호가 있다. 둘, 셋 — 북쪽 끝. 셋, 둘 — 남쪽 끝.<br>
    벽에 둘, 셋을 두드렸다. 답이 왔다. 둘, 셋.<br><br>
    그리고 반 숨 뒤 — 다른 데서 또 답이 왔다. 둘, 셋. 똑같이.`,
  o:[
    { l:'① 암호를 그 자리에서 바꿔 진짜만 거른다.', k:'gaze', dc:25,
      doom:{ title:'따라 두드리는 것', what:'벽 틈에서 나온 것에게 잡혀 벽 속으로 끌려 들어갑니다', dc:20, sec:40,
        text:`새 신호를 두드렸다. 하나, 쉬고, 넷. 약속에 없는 가락. 진짜 일행이면 어리둥절해서 늦게 답하고, 흉내면 바로 따라 한다.<br><br>한쪽이 바로 답했다. 하나, 쉬고, 넷. 흉내다. 가려냈다 — 생각한 순간, 흉내 쪽 벽이 통째로 밀렸다.<br>흉내는 벽 너머가 아니라 벽 속에 있었다.<br><br>무너진 틈에서 긴 것이 쏟아져 나와 손목을 감았다. 두드리던 그 손목을. 벽 속으로 끌려 들어간다. 벽 속에서 둘, 셋, 둘, 셋, 이쪽 암호가 벽 전체로 울려 퍼진다. 남은 일행을 부르는 소리로.`,
        dieText:`벽 너머 일행 둘이 북쪽 끝에서 한참 기다렸다.<br><br>벽에서 암호가 계속 들렸으니까. 둘, 셋. 둘, 셋.<br>첩자의 암호는 정확했다. 두드리는 것이 첩자가 아니게 된 뒤에도.`,
      },
      ok:`새 신호를 두드렸다. 하나, 쉬고, 넷. 그리고 귀를 벽에 붙이고 답의 결을 들었다.<br><br>한쪽 답은 손가락 마디 소리다. 망설이고, 박자가 사람처럼 설다. 다른 쪽 답은 — 너무 맑다. 돌로 돌을 치는 소리. 그리고 박자가 자로 잰 듯 똑같다. 흉내는 늘 원본보다 정확하다. 그게 흉내의 허점이다.<br>설고 망설이는 쪽으로 돌아가 합류했다. 맑은 쪽 벽은 밤새 혼자 둘, 셋을 두드렸다. 답을 기다리며.`,
      win:{ exp:22, dream:3 } },
    { l:'② 두드림을 끊고 약속한 제2 합류지로 간다.', k:'steady', dc:23,
      ok:`암호가 샜으면 그 암호는 죽은 암호다. 미련 없이 끊었다.<br><br>갈라지기 전에 정해 둔 제2 합류지 — 암호가 오염되면 무조건 거기. 그 약속 하나 믿고 움직였다.<br>제2 지점에 일행 둘이 먼저 와 있었다. 저쪽도 가짜 답을 들었던 것이다. 약속이 암호를 이겼다. 암호는 들려도 약속은 안 들리니까.`,
      ng:`제2 합류지로 가는 길이 하필 쓸고 다니는 것의 구역이었다.<br><br>박자를 재며 건너느라 반 시진이 늦었다. 일행 둘은 그 반 시진 동안 최악을 생각하며 기다렸다.<br>합류하고 보니 둘 다 손이 상해 있었다. 초조해서 벽을 너무 세게 두드린 손이었다. 암호가 죽으면 손가락이 고생한다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-25, mind:-16 } }
  ] },

{ at:'S', t:'길목 — 내가 저쪽이라면',
  x:`넓은 홀에 길이 셋. 어느 길에든 매복이 있을 수 있다.<br><br>
    첩자의 버릇 — 쫓는 쪽의 머리로 생각한다. 내가 여기서 사냥한다면 어디 숨나.<br>
    가운데 길은 넓고 빠르다. 왼쪽은 물이 듣고, 오른쪽은 바람이 돈다.<br><br>
    사냥꾼이라면 — 먹잇감이 고를 길에 숨는다. 먹잇감은 뭘 고르나. 빠른 길이다.`,
  o:[
    { l:'① 사냥꾼의 자리에 서 보고 남는 길을 고른다.', k:'gaze', dc:24,
      ok:`가운데 길 입구에 서서 사냥꾼의 눈으로 안을 봤다. 숨을 자리 — 천장 턱 하나. 완벽한 자리다. 내가 짐승이어도 저기다.<br><br>그래서 가운데는 버렸다. 왼쪽 물소리 길은 소리가 가려 주지만, 가려 주는 길은 저쪽한테도 가림막이다. 남는 건 오른쪽 바람 길.<br>바람 길은 냄새가 쉴 새 없이 씻기는 길이다. 매복은 바람 길에 안 선다. 제 냄새도 씻겨 내려가니까. 오른쪽으로 지났다. 천장 턱 쪽에서 밤새 모래 긁히는 소리가 났다고, 뒤 팀이 전해 줬다.`,
      ng:`사냥꾼 머리로 생각한 것까지는 좋았다. 저쪽이 한 수 위였다.<br><br>오른쪽 바람 길 — 바람이 도는 길은 냄새가 안 쌓이는 대신, 소리가 돈다. 바람을 등지고 앉은 놈한테는 배달 길이다.<br>길 중간에서 기척을 받고 전원이 되돌아 뛰었다. 결국 왼쪽 물소리 길로 물을 뒤집어쓰며 지났다. 젖은 다섯이 밤새 떨었다. 수읽기는 늘 한 수가 모자라서 진다.`,
      win:{ exp:20, dream:3 }, lose:{ hp:-26, mind:-16 } },
    { l:'② 세 길 다 안 믿고 미끼를 먼저 보낸다.', k:'hide', dc:24,
      ok:`배낭 하나에 겉옷을 입혀 끈에 묶고, 가운데 길로 끌었다. 멀리서. 걷는 박자로 끊어 가며.<br><br>천장 턱에서 그늘이 떨어져 배낭을 덮쳤다. 역시 거기였다.<br>그늘이 배낭과 승강이하는 사이 오른쪽 길로 다섯이 지났다. 배낭은 끈을 당겨 반쯤 회수했다. 겉옷은 저쪽 몫이 됐다. 겉옷 한 벌로 매복의 위치와 빠르기까지 샀다. 남는 거래다.`,
      ng:`끈이 중간에 돌 틈에 걸렸다. 배낭이 길 복판에 가만히 섰다.<br><br>걷다가 갑자기 영영 멈추는 먹잇감은 없다. 천장 턱 그늘이 안 속고 — 끈을 따라 눈을 옮겼다.<br>끈을 놓고 오른쪽 길로 뛰었다. 배낭째 바쳤다. 사흘 치 먹을 것이 들어 있었다. 미끼는 끈까지가 미끼라는 걸 비싸게 배웠다.`,
      win:{ exp:18, dream:2 }, lose:{ mind:-17, spirit:-16 } }
  ] },

{ at:'S', t:'거짓 야영지',
  x:`오늘 밤은 어디서든 자야 한다. 문제는 밤새 돌아다니는 코들이다.<br><br>
    자는 다섯은 다섯 접시다. 지키는 하나로는 모자란다.<br>
    첩자의 답 — 자는 자리를 둘로 만든다. 하나는 보여 주는 자리, 하나는 진짜 자리.<br><br>
    보여 주는 자리가 그럴듯할수록 진짜 자리가 깊이 잔다.`,
  o:[
    { l:'① 바람 위에 가짜 야영지를 차리고 바람 아래서 잔다.', k:'hide', dc:24,
      ok:`바람 위쪽 바위 그늘에 가짜를 차렸다. 데운 돌 다섯 개에 겉옷을 씌워 눕히고, 신발 두 짝을 밖에 내놓았다. 사람 내 밴 천도 걸었다.<br><br>진짜 자리는 바람 아래 움푹한 데. 냄새가 바람을 거슬러 못 가는 자리다.<br>밤에 가짜 쪽에서 두 번 소란이 났다. 데운 돌을 뒤지는 소리. 식은 돌에 실망해 떠나는 소리.<br>진짜 자리의 다섯은 그 소리를 자장가로 잤다.`,
      ng:`데운 돌이 밤중에 다 식었다. 가짜가 가짜 티를 냈다.<br><br>헛걸음한 코가 성이 나서 바람 아래를 뒤지기 시작했다. 꼼꼼하게.<br>진짜 자리까지 오기 전에 전원 깨워 이동했다. 밤중의 이사는 짐 반을 흘린다. 아침에 세어 보니 냄비 하나가 없었다. 가짜는 밤새 갈 연료까지 계산해야 한다. 적어 뒀다.`,
      win:{ exp:20, dream:3 }, lose:{ hp:-25, spirit:-17 } },
    { l:'② 아예 안 자는 자리처럼 — 흔적 전부를 지우고 잔다.', k:'steady', dc:24,
      ok:`불 없이, 밥 없이, 말 없이. 바닥에 천을 깔아 몸 자국도 안 남게 했다. 숨 쉬는 돌무더기 다섯.<br><br>코가 두 번 곁을 지나갔다. 두 번 다 안 멈췄다. 흔적 없는 자리는 코에게 빈자리다.<br>새벽에 천을 걷고 자국을 털었다. 다섯이 잤다 간 자리가 아무도 안 잔 자리가 됐다. 떠난 뒤까지가 야영이다.`,
      ng:`불 없는 밤은 추웠다. 새벽에 막내 이가 딱딱 부딪쳤다.<br><br>작은 소리인데 고른 박자라 더 또렷했다. 박자 있는 소리는 산 것의 소리다.<br>코 하나가 방향을 틀어 왔다. 막내 턱을 천으로 감싸고 전원이 바위 틈으로 옮겨 아침을 맞았다. 추위도 흔적이다. 다음부터는 몸 붙여 자기로 했다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-27, mind:-14 } }
  ] },

{ at:'S', t:'쉬는 자리 — 수신인 없는 보고서',
  x:`첩자는 보고로 먹고산다. 캔 것을 적어 올리면 끝 — 이 일의 매듭이다.<br><br>
    여기는 올릴 데가 없다. 캔 것이 수첩에 쌓이기만 한다.<br>
    매듭 없는 일은 사람을 갉는다. 오늘따라 수첩이 무겁다.<br><br>
    그래도 적는다. 적다가 문득 — 이 보고서의 수신인이 떠올랐다.`,
  o:[
    { l:'① 수신인을 바꾼다 — 다음에 올 사람들 앞.', k:'steady', dc:23, wake:1,
      ok:`보고서 머리에 수신인을 적었다. 다음 팀 앞.<br><br>문장을 고쳐 적었다. 암호 없이, 누구나 읽게. 쓸고 다니는 것은 아홉을 센다. 물가는 코 밝은 것이 비우는 때가 하루 두 번. 거짓 길은 답사부터.<br>베낀 한 부를 기름천에 싸서 들머리 돌무더기에 묻었다. 표시는 돌 세 개.<br><br>올릴 데 없는 보고는 물려주는 보고가 된다. 첩자의 일이 처음으로 매듭 대신 씨앗이 됐다.`,
      ng:`베껴 묻을 종이가 모자랐다. 반만 적어 묻었다.<br><br>하필 반 중에 제일 요긴한 줄 — 아홉을 센다 — 가 빠졌다.<br>묻고 나서야 알았다. 파내서 고쳐 쓰기엔 밤이 깊었다. 돌무더기에 돌 하나를 더 얹었다. 미완성 표시. 다음 사람이 그 네 번째 돌의 뜻을 알아주기를. 그것까지는 보고서에 못 적었다.`,
      win:{ exp:18, dream:3, mind:6 }, lose:{ mind:-15, spirit:-16 } },
    { l:'② 오늘 치 기록을 일행 앞에서 소리 없이 복기한다.', k:'bond', dc:23,
      ok:`수첩을 펴고 손짓으로 오늘을 복기했다. 어디서 멈췄고, 왜 멈췄고, 뭘 배웠나.<br><br>다섯이 둘러앉아 고개를 끄덕이고, 가끔 제 손짓을 보탰다. 막내가 이쪽이 놓친 것 하나를 보탰다 — 쓸고 다니는 것은 젖은 날 여덟만 센다.<br>수첩에 적었다. 출처: 막내. 보고서에 남의 공을 적는 건 처음이었다. 나쁘지 않았다.`,
      ng:`복기 중에 다들 꾸벅꾸벅 졸았다. 피곤이 정보를 이겼다.<br><br>중간에 접고 재웠다. 졸며 들은 정보는 안 들은 정보만 못하다. 반쯤 기억나는 길은 사람을 헷갈려 죽인다.<br>다음 날 아침에 처음부터 다시 했다. 아침밥 자리에서, 짧게. 정보에도 배식 시간이 있다는 걸 배웠다.`,
      win:{ exp:16, dream:2, spirit:6 }, lose:{ mind:-15, spirit:-15 } }
  ] },

{ at:'S1', t:'관찰 일지 — 죽은 손 글씨',
  x:`연구동 책상에 일지가 펴져 있다. 먼지가 글씨 골에 쌓였다.<br><br>
    개체는 소리에 3초, 냄새에 30초 반응한다. 급이동 시 천장을 쓴다. 급식구 개방 시각에만 복도가 빈다 —<br>
    죽은 사람들이 목숨으로 산 정보가 공짜로 놓여 있다.<br>
    첩자에게 남의 기록은 금광이다. 다만 금광에는 꼭 주인이 있다.`,
  o:[
    { l:'① 일지를 통째로 외운다 — 가져가지 않고.', k:'gaze', dc:24, wake:1,
      ok:`종이는 바스락대고, 품에 넣으면 냄새가 는다. 기록은 머리에 담는 게 제일 가볍다.<br><br>급식구 개방 시각, 천장 이동 버릇, 30초의 코. 쪽수째 머리에 새겼다. 훈련받은 암기다.<br>일지는 펴진 그대로 뒀다. 먼지 골까지 원래대로. 다음 읽을 사람 몫이다.<br><br>죽은 연구자들의 30초가 이쪽 수첩에 옮겨 적혔다. 정보는 이렇게 상속된다. 핏줄 없이, 글줄로.`,
      ng:`외우는데 뒷장이 궁금해 책장을 넘겼다. 바스락.<br><br>천장에서 쿵, 답이 왔다. 일지 왈 — 소리에 3초.<br>3초 안에 책상 밑에 들어갔다. 천장을 쓸고 지나가는 것의 배가 책상 위를 지났다. 일지가 바람에 덮였다. 마지막 장은 영영 못 읽었다. 제일 중요한 게 꼭 마지막 장에 있는 법인데.`,
      win:{ exp:20, dream:3 }, lose:{ mind:-18, spirit:-16 } },
    { l:'② 일지 글씨가 흐트러지는 지점부터 거꾸로 읽는다.', k:'sense', dc:23,
      ok:`기록은 끝이 진실이다. 글씨가 무너지기 시작하는 쪽부터 읽었다.<br><br>마지막 장 — 급식구가 어제부터 안 열린다. 녀석들이 굶는다. 굶으면 벽을 — 문장 끝이 긁혀 나갔다.<br>굶은 것들은 버릇이 깨진다. 일지의 시간표 중 급식구 항목만 지우고 썼다. 죽은 사람의 마지막 문장이 산 사람 다섯의 길을 고쳤다.`,
      ng:`끝 장을 읽는데 종이에 눌린 자국이 있었다. 글씨 아닌 자국. 발가락 자국.<br><br>뭔가 이 일지를 디디고 지나갔다. 자주. 여기는 길목이다.<br>알아챈 순간 천장에서 먼지가 내렸다. 일지를 두고 책상 밑으로, 다시 문밖으로. 읽던 줄은 끝내 못 읽었다. 길목의 독서는 반 줄씩 끊어 읽는 법이라는 걸 배웠다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-26, mind:-15 } }
  ] },

{ at:'S1', t:'출입증 — 죽은 손',
  x:`기밀문 옆에 판독기가 산다. 아직 전기가 돈다. 출입증을 대면 열린다.<br><br>
    출입증은 복도 끝 의자에 앉은 채 마른 연구원의 목에 걸려 있다.<br>
    문제는 둘. 판독기는 열릴 때 삑 소리를 낸다. 그리고 마른 연구원의 가슴이 — 아주 조금씩 오르내린다.<br><br>
    죽은 몸의 숨이 아니다. 들어 있는 것의 숨이다.`,
  o:[
    { l:'① 숨의 박자를 재고 내쉴 때만 줄을 끊어 걷어 온다.', k:'hide', dc:25,
      doom:{ title:'의자의 것', what:'마른 팔에 안겨 의자 뒤 어둠으로 끌려갑니다', dc:20, sec:38,
        text:`들숨 넷, 날숨 여섯. 날숨에만 손을 썼다. 목줄에 가위를 대고 — 한 번, 두 번.<br><br>세 번째에 줄이 끊기며 출입증이 손에 들어왔다. 그 순간 가슴의 숨이 멎었다.<br>숨어 있던 것이 숨 쉬는 걸 멈출 때는 하나다. 다른 일을 시작할 때.<br><br>마른 팔 둘이 이쪽을 안았다. 뼈 같은 팔인데 힘은 뱀이다. 의자가 뒤로 기울며, 의자 뒤 벽이 — 벽이 아니라 입구였던 어둠이 둘을 받는다. 출입증을 쥔 채 끌려 들어간다. 저 문은 이제 누가 여나.`,
        dieText:`복도 끝 의자에 마른 연구원이 앉아 있다. 목줄은 끊겼고 출입증은 없다.<br><br>가슴은 다시 조금씩 오르내린다. 아까보다 느긋하게.<br>기밀문 판독기만 변함없이 불을 켜 두고 있다. 올 사람을 기다리며.`,
      },
      ok:`숨을 재다가 셈을 바꿨다. 줄을 끊으면 목에서 무게가 사라진다. 들어 있는 것이 그걸 모를 리 없다.<br><br>끊지 않았다. 대신 출입증을 줄에 단 채 뒤집어 판독기까지 — 의자째 끌기로 했다. 의자 다리에 천을 감고, 날숨 여섯에만 한 뼘씩.<br>판독기 앞까지 세 식경. 출입증을 단 채로 댔다. 삑. 문이 열리는 동안 의자의 가슴은 제 박자로 오르내렸다. 제 몸이 열쇠 노릇 한 줄도 모르고.<br>다섯이 문을 지나고, 의자는 문가에 뒀다. 다음 팀 몫의 열쇠로.`,
      win:{ exp:24, dream:3 } },
    { l:'② 삑 소리에 맞춰 멀리서 유리를 깨 소리를 포갠다.', k:'fix', dc:24,
      ok:`판독기 소리는 못 지운다. 그러면 소리 위에 소리를 덮는다.<br><br>일행 하나가 복도 반대편에서 돌을 쥐고 대기. 출입증을 대는 순간에 맞춰 — 삑과 와장창이 한 몸으로 울렸다.<br>소리를 듣고 온 것들은 유리 쪽으로 몰렸다. 삑은 와장창 속에 묻혀 아무도 못 들었다. 문은 열렸고, 다섯은 반대쪽으로 들어갔다. 소리는 지우는 게 아니라 묻는 것이다.`,
      ng:`신호가 반 숨 어긋났다. 삑이 먼저, 와장창이 나중.<br><br>두 소리가 따로 울리니 사건이 둘이 됐다. 양쪽으로 다 몰려왔다.<br>열린 문으로 구르듯 들어가 안에서 닫았다. 문 너머에서 판독기가 뜯기는 소리가 났다. 다음 팀 열쇠 구멍이 사라졌다. 미안한 일이다. 박자 못 맞춘 값을 남이 치르게 생겼다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-27, mind:-15 } }
  ] },

{ at:'S1', t:'방송 — 천장의 목소리',
  x:`시설 방송이 아직 산다. 천장 스피커가 이따금 지직대며 녹음을 튼다.<br><br>
    3구역 소독을 시작합니다. 통로를 비워 주십시오.<br>
    여기 것들은 그 목소리에 반응이 없다. 너무 오래 들어 벽 소리가 된 것이다.<br><br>
    벽에 붙은 방송실이 보인다. 송출 단추들이 살아 있다. 첩자 손에 방송국이 들어왔다.`,
  o:[
    { l:'① 송출 시각표를 읽고 방송 트는 때에 맞춰 이동한다.', k:'gaze', dc:23,
      ok:`방송실 벽에 송출 기록지가 걸려 있다. 정각마다 한 번, 길이는 스무 숨.<br><br>방송은 벽 소리지만, 벽 소리도 소리는 소리다. 스무 숨 동안은 다른 소리가 다 그 밑에 깔린다.<br>정각마다 스무 숨씩 끊어 이동했다. 발소리, 문소리, 숨소리 전부 방송 밑으로. 시설이 제 목소리로 이쪽을 숨겨 줬다. 주인 잃은 집의 마지막 인심이다.`,
      ng:`기록지의 시각표가 낡은 것이었다. 정각 방송이 두 번 걸렀다.<br><br>방송 믿고 내디딘 걸음이 맨 복도에 알몸으로 울렸다.<br>벽감에 끼어 다음 방송까지 한 시진을 기다렸다. 기계의 약속은 기계가 낡은 만큼 헐겁다. 시각표 옆에 적어 뒀다. 두 번에 한 번은 거른다. 다음 사람 몫의 각주다.`,
      win:{ exp:18, dream:3 }, lose:{ mind:-17, spirit:-16 } },
    { l:'② 다른 구역 스피커만 골라 소독 방송을 튼다.', k:'hide', dc:25,
      ok:`송출반 단추는 구역별이다. 가야 할 길은 2구역. 그러니 — 5구역 단추를 눌렀다.<br><br>5구역 천장에서 소독 방송이 울렸다. 벽 소리라도, 새로 시작하는 벽 소리는 다르다. 여기 것들이 귀를 그쪽으로 모았다. 오래 잊었던 소리가 깨어나면 궁금한 것이다.<br>2구역이 비었다. 다섯이 빈 길을 지나는 스무 숨 동안, 5구역에서는 녹음된 목소리가 통로를 비워 달라고 정중히 반복했다. 부탁은 5구역이 받고 통행은 2구역이 했다.`,
      ng:`단추가 낡아 두 개가 같이 눌렸다. 5구역과 — 2구역.<br><br>가야 할 길 머리 위에서 방송이 터졌다. 제 발등에 조명탄을 쏜 셈이다.<br>2구역으로 몰리는 것들을 피해 한 구역을 통째로 돌았다. 돌아가며 방송실 쪽을 봤다. 다시는 안 만질 작정으로. 기계는 첩자의 손맛을 안 탄다. 사람 문고리와 달라서.`,
      win:{ exp:20, dream:3 }, lose:{ hp:-26, mind:-16 } },
    { l:'③ 방송 녹음 사이의 지직거림을 신호로 쓴다.', k:'bond', dc:23,
      ok:`방송 앞뒤로 스피커가 지직댄다. 그 지직은 시설 전체에 같이 퍼진다.<br><br>일행과 약속을 정했다. 지직 — 다음 방송까지 각자 위치 고수. 방송 — 이동. 끝 지직 — 정지.<br>갈라져 수색하던 둘과 말 한마디 없이 박자가 맞았다. 온 시설이 공유하는 소리는 온 시설에서 통하는 시계다. 시계는 늘 적진 것을 쓰는 게 좋다. 이쪽 것은 뺏기면 끝이지만 적진 것은 뺏길 일이 없다.`,
      ng:`지직 신호를 정하고 반나절 — 스피커 하나가 수명이 다해 지직을 멋대로 냈다.<br><br>가짜 정각이 생긴 것이다. 일행 둘이 엇갈려 움직였다.<br>엇갈린 둘이 같은 모퉁이에서 마주쳐 서로에게 기겁했다. 소리 지르기 직전에 서로 알아봤으니 됐다. 낡은 시계는 시계가 아니라 함정이다. 신호는 그날로 손짓말로 돌렸다.`,
      win:{ exp:16, dream:2 }, lose:{ mind:-16, spirit:-17 } }
  ] },

{ at:'S1', t:'격리 규정 — 벽의 붉은 글씨',
  x:`복도 벽마다 붉은 글씨가 남아 있다. 격리 규정이다.<br><br>
    2인 미만 이동 금지. 개방 전 청음 30초. 체액 접촉 시 즉시 보고.<br>
    규정은 죽은 사람들이 피로 고쳐 쓴 지도다. 금지가 많은 벽일수록 거기서 많이 죽었다는 뜻이다.<br><br>
    첩자는 규정을 읽을 때 행간부터 읽는다.`,
  o:[
    { l:'① 규정이 덧쓰인 순서를 읽어 사고 지점을 짚는다.', k:'gaze', dc:24,
      ok:`글씨를 겹으로 읽었다. 처음 글씨는 페인트, 나중 글씨는 급한 붓질, 마지막은 긁어 새긴 것.<br><br>긁어 새긴 규정만 모으면 — 청음 30초로는 모자람. 60초. 환기구 밑 정지 금지. 셋 이상은 냄새가 겹쳐 더 위험 —<br>마지막 규정들은 교본에 없는 것들이다. 죽기 직전의 사람들이 몸으로 고친 개정판.<br>개정판대로 움직였다. 환기구 밑은 안 멈추고, 청음은 60을 셌다. 규정의 행간이 다섯을 데리고 걸었다.`,
      ng:`긁어 새긴 글씨를 읽느라 벽에 너무 오래 붙어 있었다.<br><br>규정 하나를 그새 어긴 것이다 — 한 자리 15초 이상 정지 금지. 그 규정은 못 보고 지나쳤었다. 제일 구석에 제일 작게 새겨져 있었다.<br>천장 쪽에서 긁는 소리가 다가왔다. 독서를 끊고 뛰었다. 규정 읽다 규정 어기는 건 관청에서나 할 일이다.`,
      win:{ exp:20, dream:3 }, lose:{ hp:-26, mind:-16 } },
    { l:'② 규정에 없는 것을 찾는다 — 안 적힌 위험.', k:'sense', dc:24,
      ok:`규정은 겪은 위험만 적는다. 그러니 규정이 빈 곳 — 소리 규정은 많은데 빛 규정이 없다.<br><br>빛에 당한 사람이 없어서가 아니라, 빛을 켤 사람이 일찍 없어졌거나, 여기 것들이 빛에 안 끌리거나. 시험해 볼 가치가 있다.<br>구석에서 등불을 반 눈금 켜 봤다. 아무것도 안 왔다. 여기 것들은 눈이 퇴화한 것들이다. 빛은 자유였다. 벽의 죽은 선배들이 못 남긴 한 줄을 이쪽이 찾아 적었다. 빛은 켜도 됨. 소리만 죽일 것.`,
      ng:`빛 규정이 없는 이유를 시험하다 답을 잘못 찾았다.<br><br>빛에는 안 끌린다. 열에는 끌린다. 등불은 빛이자 열이었다.<br>등피가 데워질 때쯤 천장에서 내려온 것이 등불을 통째로 걷어 갔다. 손잡이를 쥔 손가락을 하마터면 같이 바칠 뻔했다. 벽에 새 규정을 긁어 새겼다. 불은 식혀서 들 것. 피 대신 돌로 새겼으니 선배들보다 싸게 배운 셈이다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-28, mind:-14 } }
  ] },

{ at:'S1', t:'점호 — 안 맞는 숫자',
  x:`통제실 칠판에 마지막 점호가 남아 있다. 생존 11. 날짜는 오래전.<br><br>
    복도에서 지금껏 본 것 — 마른 몸 넷, 걷는 몸 둘, 의자의 하나. 일곱.<br>
    넷이 빈다. 어디서도 못 봤다.<br>
    첩자는 안 맞는 숫자를 그냥 못 넘긴다. 빈 숫자는 꼭 어디선가 이자 붙어 돌아온다.`,
  o:[
    { l:'① 빠진 넷의 행방을 기록에서 캔다.', k:'gaze', dc:24, wake:1,
      ok:`통제실 서랍을 뒤졌다. 당직표, 식량 장부, 그리고 쪽지 한 장 — 넷은 아래로 간다. 승강구는 막겠다. 미안하다.<br><br>아래. 여왕 쪽이다. 넷은 탈출이 아니라 — 뭔가 하러 내려간 것이다. 막겠다는 승강구가 어딘지 장부 뒷면 약도에 있었다.<br>그 승강구만은 피하면 된다. 막은 문 너머에 뭐가 자랐을지 모르니.<br><br>숫자의 빈자리를 끝까지 캐는 버릇. 빈 넷이 지도의 금지 구역 하나가 됐다. 숫자는 캐면 꼭 길이 된다.`,
      ng:`서랍을 뒤지는 소리가 통제실 밖으로 샜다. 서랍은 생각보다 운다.<br><br>복도에서 걷는 몸 하나가 통제실 문 앞에 와 섰다. 문손잡이가 천천히 돌았다.<br>책상 밑에서 쪽지만 겨우 읽었다. 넷은 아래로 — 까지. 뒷장 약도는 못 봤다. 걷는 몸이 물러간 뒤 빈손으로 나왔다. 반쪽 정보는 반쪽 불안이다. 아래쪽 문이란 문이 다 무서워졌다.`,
      win:{ exp:20, dream:3 }, lose:{ mind:-18, spirit:-17 } },
    { l:'② 숫자는 접고 — 지금 돌아다니는 것만 다시 센다.', k:'sense', dc:23,
      ok:`옛 숫자는 옛 숫자다. 지금 이 층을 쓰는 것들을 새로 셌다.<br><br>반나절 잠복으로 셌다. 천장 쓰는 것 둘, 걷는 몸 둘, 작은 것들 — 추정 여섯. 통행량으로 길도 등급을 매겼다. 많이 다니는 복도, 안 다니는 복도.<br>안 다니는 복도만 이어 길을 짰다. 인구 조사는 피난 계획의 어머니다. 어느 도시에서나 그랬다.`,
      ng:`세는 잠복 중에 작은 것 하나가 이쪽 은신처 쪽으로 왔다. 세다가 세어지는 쪽이 됐다.<br><br>움직이면 통계가 다 버려진다. 버텼다. 작은 것이 발 앞 한 뼘까지 왔다가 갔다.<br>잠복을 한 자리 옮겨 마저 셌다. 숫자는 다 얻었는데 무릎이 못 쓰게 뻣뻣해졌다. 통계의 값은 무릎으로 치렀다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-26, spirit:-15 } }
  ] },

{ at:'S1', t:'통풍관 지도 — 표식 남기기',
  x:`벽 패널 뒤에서 시설 통풍관 도면을 찾았다. 관이 거미줄이다.<br><br>
    어느 관이 비었고 어느 관에 주인이 있는지는 도면에 없다. 그건 발로 캐야 한다.<br>
    첩자는 남 좋은 일을 잘 안 한다. 그래도 지도에 표식 다는 일은 — 뒤에 올 사람 목숨이 걸린 일이다.<br><br>
    캔 것은 적는다. 그게 이 직업의 몇 안 되는 선행이다.`,
  o:[
    { l:'① 관 입구마다 청음 60초로 등급을 매겨 표식을 긁는다.', k:'sense', dc:24,
      ok:`관마다 귀를 대고 60을 셌다. 빈 관은 바람 소리가 곧다. 주인 있는 관은 바람이 무언가를 돌아 흐른다.<br><br>입구마다 표식을 긁었다. 동그라미 — 빔. 가위표 — 주인. 물결 — 모름.<br>도면에도 옮겨 그려 기름천에 쌌다. 통제실 책상 — 눈에 제일 잘 띄는 자리에 뒀다.<br>누가 볼지 모른다. 안 볼 수도 있다. 그래도 가위표 하나가 한 사람 살리면 오늘 밤 품값은 나온 것이다.`,
      ng:`여섯째 관에서 60을 세는데 마흔쯤에서 바람이 — 멎었다.<br><br>관 속의 무언가가 숨을 참기 시작한 것이다. 이쪽 청음을 저쪽도 한다.<br>귀를 떼고 소리 없이 물러났다. 그 관은 물결 대신 가위표 셋을 긁었다. 참을 줄 아는 주인이라는 뜻으로. 뒤에 올 사람이 셋의 뜻을 알아채 주기를.`,
      win:{ exp:20, dream:3 }, lose:{ mind:-17, spirit:-18 } },
    { l:'② 작은 것들이 드나드는 관만 골라 쓴다 — 선주민의 길.', k:'hide', dc:24,
      ok:`쥐만 한 것들이 드나드는 관이 셋 있다. 작은 것들은 큰 것 있는 관에 안 든다. 선주민의 등급표다.<br><br>그 셋 중 사람이 길 만한 관 하나를 골라 기었다. 작은 것들과 두 번 마주쳤다. 서로 벽에 붙어 지나쳤다. 세입자끼리의 예의다.<br>관은 식당 뒤로 났다. 선반에 봉한 보급 상자 — 마른 고기가 성했다. 선주민의 길은 먹이로 통한다. 그래서 믿을 만하다.`,
      ng:`작은 것들의 관을 반쯤 기었을 때 작은 것들이 우르르 — 이쪽으로 역류했다.<br><br>도망쳐 오는 것이다. 앞쪽에서 뭔가로부터.<br>같이 돌아서 같이 도망쳤다. 작은 것들과 한 관에서 뒤엉켜 구르며. 관을 나와 뚜껑을 닫고 보니 손등을 작은 발톱들이 긁고 간 자국투성이였다. 선주민 경보는 정확했다. 아픈 게 흠이지만.`,
      win:{ exp:18, dream:2, item:'말린 고기' }, lose:{ hp:-27, mind:-14 } }
  ] },

{ at:'S1', t:'마지막 일지 — 여왕을 본 사람',
  x:`안쪽 사무실, 쓰러진 캐비닛 뒤에서 개인 일지를 찾았다. 다른 일지와 달리 끝까지 글씨가 고르다.<br><br>
    그것은 소리로 못 찾는다. 우리 심장을 듣기 때문이다. 나는 내일 내려간다. 녹음기를 돌려놓고 간다.<br>
    마지막 장에 — 돌아왔다. 봤다. 그것은 우리를 센다. 매일 밤 수를 센다. 하나가 줄면 알아챈다.<br><br>
    그 아래 글씨가 바뀐다. 아주 고른, 자로 잰 글씨로. 당신도 세어지고 있다.`,
  o:[
    { l:'① 일지를 덮고 — 세어지기 전에 수를 흐린다.', k:'hide', dc:25,
      ok:`마지막 줄이 사실이든 협박이든, 대응은 같다. 세기 어려운 수가 되는 것.<br><br>다섯이 뭉쳐 다니던 것을 바꿨다. 둘, 셋으로 갈라 시간 차를 두고 이동. 쉴 때는 다섯이 한 덩이로 포개 눕는다. 멀리서 세면 둘이었다 셋이었다 하나였다 하는 수.<br>그날 밤부터 어딘가에서 세던 것이 셈을 자꾸 틀리기를 바라며 움직였다. 수를 숨기는 건 첩자의 기본기다. 세는 놈이 뭐든.`,
      ng:`수를 흐리자고 갈라져 걷던 둘째 조가 길을 잘못 들었다.<br><br>합류 지점에 한 조가 안 왔다. 반 시진을 — 세어지는 기분으로 기다렸다.<br>둘은 결국 왔다. 길이 아니라 담력이 모자라서 늦은 것이었다. 일지의 마지막 줄을 둘에게는 안 보여 주기로 했다. 겁은 수를 흐리는 게 아니라 발을 흐린다.`,
      win:{ exp:20, dream:3 }, lose:{ mind:-19, spirit:-19 } },
    { l:'② 그가 돌려놓고 갔다는 녹음기를 찾아 내려간 길을 캔다.', k:'gaze', dc:25,
      doom:{ title:'자로 잰 글씨', what:'일지 주인의 걸음으로 걸어 나가 아래로 내려갑니다', dc:20, sec:36,
        text:`일지의 필적을 더듬어 책장 뒤 녹음기를 찾았다. 태엽이 반쯤 남아 있다. 돌렸다.<br><br>사람 심장 소리가 녹음돼 있다. 둥, 둥. 제 심장을 녹음해 두고 간 것이다 — 세는 것에게 수를 맞춰 주려고. 제 몫의 하나를 남겨 두고 내려간 것이다.<br>듣는 사이 녹음 속 심장에 이쪽 심장이 포개졌다. 편하다. 아주 편하다. 생각이 멀어진다.<br><br>정신이 들었을 때 몸은 사무실 밖, 아래로 가는 비탈을 걷고 있었다. 자로 잰 걸음으로. 일지 주인이 걸은 길 그대로. 일행이 비탈 위에서 부르는 소리가 아주 멀다.`,
        dieText:`사무실 일지에 글씨가 한 줄 늘었다.<br><br>아주 고른, 자로 잰 글씨로.<br>한 명 받았다. 수는 맞는다.`,
      },
      ok:`녹음기를 찾았다. 태엽이 반 남았다. — 돌리지 않았다.<br><br>마지막 장의 자로 잰 글씨. 사람 손은 공포 속에서 글씨가 고와지지 않는다. 그 글씨는 사람 글씨가 아니다. 그러면 이 녹음기는 유품이 아니라 미끼다.<br>녹음기는 그대로, 일지만 외워 덮었다. 심장을 듣는 것. 매일 세는 것. 둘 다 수첩에 올랐다.<br>사무실을 나오며 일행에게 손짓했다. 여기서 나는 소리는 뭐든 듣지 말 것. 태엽 소리는 특히.`,
      win:{ exp:24, dream:3 } }
  ] },

{ at:'S2', t:'사육 일지 — 먹이 종',
  x:`관리인 초소 벽에 사육 일지가 걸려 있다. 곰팡이 슬었지만 읽힌다.<br><br>
    급이 시각 — 늦은 오전, 해 질 녘. 급이 전 타종 3회. 녀석들 전원 급이대 집결 후 개방.<br>
    급이대는 정원 북쪽 끝. 종은 초소 처마에 아직 걸려 있다. 줄도 성하다.<br><br>
    배고픈 것들의 몸에 박힌 시계를, 종 하나가 아직 쥐고 있는 셈이다.`,
  o:[
    { l:'① 종을 세 번 치고 — 남쪽으로 전력 이동한다.', k:'hide', dc:24, wake:1,
      ok:`줄을 당겼다. 땡. 땡. 땡.<br><br>정원이 통째로 출렁였다. 사방 수풀에서 낮은 것들이 솟아 북쪽으로 내달린다. 몇 년을 울리지 않았어도 몸의 시계는 안 녹슨다.<br>남쪽이 텅 비었다. 다섯이 빈 남쪽을 평보로 — 아니, 반쯤 뛰어 지났다. 북쪽 급이대에서 빈 여물통 긁는 소리가 멀리 들렸다.<br><br>적의 몸에 박힌 종소리는 적을 움직이는 손잡이다. 손잡이는 당겨 보기 전에는 손잡이인 줄 모른다. 당겨 본 손이 이겼다.`,
      ng:`종이 삭아 있었다. 두 번째에 추가 떨어졌다. 땡, 땡 — 툭.<br><br>두 번은 급이 종이 아니다. 몸의 시계가 두 번에는 반만 움직였다. 반은 북으로, 반은 — 종 치는 것이 뭔지 보러 초소로.<br>초소 뒷벽을 뜯고 빠져 늪 쪽으로 돌았다. 진흙을 뒤집어쓴 덕에 코들은 피했다. 종은 세 번 울려야 종이다. 반쪽 신호는 신호보다 나쁘다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-27, mind:-15 } },
    { l:'② 급이 시각 자체를 피해 시간표를 다시 짠다.', k:'gaze', dc:23,
      ok:`일지를 더 읽었다. 급이 전 반 시진은 전원이 급이대 근처를 배회 — 북쪽이 제일 위험한 때. 급이 직후는 포식으로 전원 둔화 — 이동 최적.<br><br>몇 년을 굶었어도 몸의 시간표는 남는다. 해 질 녘 직후, 녀석들이 습관처럼 북쪽을 서성이다 허탕 치고 처지는 시간에 맞춰 움직였다.<br>허탕의 시간은 식사의 시간만큼 둔하다. 실망도 포만만큼 발을 무겁게 한다. 그 틈으로 두 구역을 건넜다.`,
      ng:`시간표대로 해 질 녘을 기다렸는데 그날따라 하늘 틈이 흐려 해가 안 보였다.<br><br>해 질 녘이 언제인지 이쪽도 저쪽도 몰랐다. 몸시계끼리 어긋난 밤.<br>어중간한 때에 움직이다 서성이는 둘과 마주칠 뻔했다. 양치 둔덕에 엎드려 한 식경. 시간표는 하늘이 맑아야 시간표다. 흐린 날 조항을 수첩에 추가했다.`,
      win:{ exp:18, dream:2 }, lose:{ mind:-17, spirit:-16 } }
  ] },

{ at:'S2', t:'울타리 점검표',
  x:`초소 서랍에서 울타리 점검표를 찾았다. 관리인들의 마지막 기록.<br><br>
    7번 지주 — 누전, 수리 요망. 12번 구간 — 침하. 3번 문 — 경첩 교체 완료.<br>
    그리고 연필로 급히 덧쓴 줄 — 녀석들이 7번만 민다. 아는 것 같다.<br><br>
    저쪽도 점검표를 가졌다는 뜻이다. 머릿속에.`,
  o:[
    { l:'① 양쪽 점검표를 겹쳐 서로 모르는 구간을 찾는다.', k:'gaze', dc:24, wake:1,
      ok:`관리인의 표와 짐승들의 표를 머릿속에 겹쳤다. 관리인이 아는 약점 — 7번, 12번. 짐승이 아는 약점 — 7번.<br><br>12번 침하 구간. 사람은 알고 짐승은 모르는 약점.<br>그 구간은 바닥이 꺼져 철선 밑으로 사람 하나 길 틈이 있었다. 짐승들은 철선만 밀어 봐서 바닥 꺼진 건 모른다. 코가 아니라 기록이 아는 길. 그 틈으로 다섯이 지났다.<br><br>적과 지도를 맞대 보는 법. 서로의 지도에서 안 겹치는 칸 — 거기가 늘 문이다.`,
      ng:`12번으로 갔는데 침하가 그새 더 진행돼 있었다. 틈이 넓어진 것이다.<br><br>넓어진 틈은 이쪽만의 비밀이 아니게 된다. 틈 둘레에 벌써 짐승 발자국이 어지러웠다.<br>녀석들의 점검표가 갱신된 것이다. 12번은 버리고 3번 문 — 경첩 교체 완료, 제일 튼튼한 자리의 빗장을 사람 손으로 따고 지났다. 제일 성한 데가 제일 빈 데라는 역설로 버텼다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-26, mind:-15 } },
    { l:'② 7번 지주를 미끼로 — 저쪽 점검 시간에 맞춰 움직인다.', k:'sense', dc:24,
      ok:`녀석들이 7번만 민다면, 7번을 미는 시간에 다른 모든 구간이 빈다.<br><br>잠복해서 쟀다. 7번 점검은 이른 아침, 넷이서, 한 식경.<br>그 한 식경에 맞춰 반대쪽 12번을 지났다. 녀석들은 7번에서 성실히 일했고 이쪽은 12번에서 성실히 지나갔다. 같은 시간에 서로 다른 데서 일한 것뿐이다. 평화로운 분업이었다.`,
      ng:`잠복 둘째 날, 7번 점검조가 — 다섯이 됐다. 하나가 늘었다.<br><br>새 놈은 일을 안 하고 주변 수풀만 봤다. 점검조에도 보초가 생긴 것이다. 어제 잠복을 들킨 모양이다.<br>잠복 자리를 버리고 멀리 돌았다. 적의 조직도가 하루 만에 바뀌었다. 영리한 적은 관찰당하면 는다. 관찰도 아껴 써야 한다는 걸 적어 뒀다.`,
      win:{ exp:18, dream:2 }, lose:{ mind:-18, spirit:-17 } }
  ] },

{ at:'S2', t:'정찰꾼의 표식',
  x:`무리의 정찰꾼이 다니는 길목마다 나무껍질에 긁은 자국이 있다. 세로 셋, 가로 하나. 자리마다 조금씩 다르다.<br><br>
    표식이다. 저것들은 길에 글을 쓴다.<br>
    읽을 수는 없다. 아직은. 그러나 어느 표식 뒤에 무리가 오고 안 오는지는 — 지켜보면 안다.<br><br>
    남의 글을 훔쳐 읽는 것. 그다음은 남의 글씨로 쓰는 것. 첩자의 정석 순서다.`,
  o:[
    { l:'① 표식과 통행을 짝지어 뜻부터 푼다.', k:'gaze', dc:24, wake:1,
      ok:`이틀을 들여 표식 넷과 그 뒤 통행을 짝지었다. 세로 셋 가로 하나 — 뒤에 무리가 지나감. 세로 둘 — 안 지나감. 가로만 둘 — 그 길 끝에서 사냥이 있었음.<br><br>낱말 셋짜리 사전이 생겼다. 세로 둘 표식이 붙은 길만 이어 걸었다. 짐승의 글이 사람 다섯을 안내했다.<br><br>적의 문자를 푸는 것. 암호 해독과 똑같은 일이었다. 상대가 깃펜 대신 발톱을 쓸 뿐.`,
      ng:`짝짓기 이틀째에 정찰꾼이 어제 긁은 표식을 — 고쳐 긁는 걸 봤다.<br><br>표식이 갱신된다는 건 어제 푼 사전이 오늘 낡는다는 뜻이다.<br>사전의 반을 버리고 다시 짝지었다. 사흘 걸릴 일이 됐다. 살아 있는 언어는 사전이 늘 진다. 그래도 반 낱말이 빈손보다 낫다.`,
      win:{ exp:22, dream:3 }, lose:{ mind:-18, spirit:-16 } },
    { l:'② 세로 둘 — 안 지나감 표식을 이쪽 길목에 위조해 긁는다.', k:'hide', dc:26,
      doom:{ title:'필적 감정', what:'위조 표식 앞에서 기다리던 정찰꾼에게 물려 가 무리로 끌려갑니다', dc:20, sec:38,
        text:`야영지로 드는 길목 나무에 세로 둘을 긁었다. 각도도, 깊이도, 높이도 베꼈다.<br><br>새벽에 정찰꾼이 와서 표식을 봤다. 읽고 — 지나가지 않고 — 앉았다.<br>제가 안 쓴 글을 제 글씨로 만난 것이다. 필적은 제 주인이 제일 잘 안다.<br>정찰꾼은 표식 앞에 앉아 기다렸다. 쓴 놈이 글씨를 보러 오기를. 첩자가 꼭 하는 그 일을.<br><br>확인하러 간 이쪽 어깨에 정찰꾼이 떨어졌다. 작아도 턱은 턱이다. 물려 간다. 무리 쪽으로. 위조범은 어느 동네서나 본보기가 된다.`,
        dieText:`길목의 위조 표식 위에 새 표식이 덧긁혔다.<br><br>가로만 둘 — 이 길 끝에서 사냥이 있었음.<br>이번 것은 진짜다. 정확한 기록이었다.`,
      },
      ok:`긁기 전에 사흘 치 필적을 더 모았다. 정찰꾼의 발톱은 왼쪽이 깊다. 긁고 나서 꼭 한 번 코를 댄다 — 냄새 서명이다.<br><br>글씨만 베끼면 반쪽 위조다. 죽은 정찰꾼 — 암살자가 전에 잡은 놈의 발톱을 얻어 긁고, 그 발 패드로 문질러 서명까지 베꼈다.<br>새벽에 온 정찰꾼이 읽고 — 그냥 갔다. 통과다.<br>야영지 길목은 그날부터 공식적으로 아무도 안 지나는 길이 됐다. 저쪽 지도에서 이쪽 집이 지워졌다.`,
      win:{ exp:24, dream:3 } },
    { l:'③ 표식 자체를 피해 — 글이 없는 길로만 다닌다.', k:'evade', dc:23,
      ok:`표식이 있다는 건 정찰이 다닌다는 뜻이다. 글이 있는 길은 다 저쪽 우편로다.<br><br>표식 없는 길만 골라 걸었다. 가시덤불, 바위 비탈, 물길. 글을 안 쓰는 데는 글 쓸 일이 없는 데 — 아무도 안 오는 데다.<br>험한 만큼 비어 있었다. 우편로를 피하는 것만으로 검문이 사라졌다. 어느 나라에서나 통하는 수다.`,
      ng:`글 없는 길이라 골랐던 바위 비탈에서 새 표식을 만났다. 긁은 지 하루도 안 된 생나무 속살.<br><br>우편로가 늘어난 것이다. 이쪽이 다니기 시작한 길로.<br>누가 누구를 관찰하는 건지 모르게 됐다. 비탈을 버리고 물길로 내려섰다. 물에는 글을 못 쓴다. 아직까지는 그게 유일한 위안이다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-27, mind:-15 } }
  ] },

{ at:'S2', t:'발자국 — 뒤로 걷는 것',
  x:`진흙 벌에 발자국이 책처럼 찍혀 있다. 읽는다.<br><br>
    낮은 것 여섯이 지나갔다. 다섯은 보통 걸음. 하나는 — 자국이 이상하다. 발가락이 뒤를 향했다.<br>
    뒤로 걸은 것이다. 짐승이 뒤로 걸을 이유는 하나뿐이다. 자국의 방향을 속이려고.<br><br>
    저것들도 거짓 길을 깐다. 동업자가 늘었다.`,
  o:[
    { l:'① 뒤로 걸은 자국만 따로 추려 진짜 방향을 읽는다.', k:'sense', dc:24,
      ok:`뒤로 걷는 걸음은 발꿈치가 먼저 눌린다. 자국 여섯 벌 중 꿈치가 깊은 것만 추렸다.<br><br>그 자국의 진행 방향을 뒤집으면 — 다섯은 동쪽으로 보이게 걷고, 하나는 서쪽 수풀로 빠졌다. 서쪽이 진짜다. 매복조가 서쪽에 깔린 것이다.<br>동쪽으로 가는 척 꺾어 북쪽 바위 지대로 돌았다. 거짓 길은 읽을 줄 아는 눈에는 자백서다. 어느 방향이 거짓인지 제 발로 적어 놓은.`,
      ng:`꿈치 깊이를 재다가 비가 왔다. 천장 틈으로 듣는 빗물에 자국들이 풀어졌다.<br><br>책이 젖어 글이 번진 셈이다. 진짜도 거짓도 다 진흙이 됐다.<br>읽기를 포기하고 제일 험한 길로 돌았다. 험한 길은 매복도 싫어하니까. 반나절 뒤 동쪽에서 긴 울음이 났다. 어느 쪽이 거짓이었는지는 끝내 모른다. 모르고 산 것도 산 것이다.`,
      win:{ exp:20, dream:3 }, lose:{ hp:-26, mind:-15 } },
    { l:'② 이쪽도 거짓 자국을 섞어 책을 더럽힌다.', k:'hide', dc:24,
      ok:`읽히는 벌판이면 이쪽 자국도 읽힌다. 그러면 오독할 글을 쓰면 된다.<br><br>신발을 거꾸로 묶어 신고 벌판을 세 줄로 어지럽게 오갔다. 다섯이 열다섯 걸음 수로, 오는 자국과 가는 자국을 뒤섞어서.<br>저쪽 정찰꾼이 와서 그 책을 오래 읽었다. 읽다가 — 포기하고 갔다. 못 읽게 쓰는 것도 글재주다. 난독의 벌판을 등 뒤에 남기고 떠났다.`,
      ng:`거꾸로 묶은 신발이 진흙에 벗겨졌다. 맨발 자국 하나가 벌판 한가운데 또렷이 찍혔다.<br><br>어지러운 글 속에 진짜 서명 하나.<br>정찰꾼은 다른 자국을 다 버리고 맨발만 따라왔다. 물길로 뛰어들어 겨우 끊었다. 신발은 찾아 신었다. 서명은 늘 마지막에 들킨다. 글은 어지러워도 서명은 하나니까.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-28, spirit:-15 } }
  ] },

{ at:'S2', t:'승강기 — 운행 일지와 열쇠',
  x:`승강장 기둥에 운행 일지함이 붙어 있다. 녹슨 함 속에 일지와 — 열쇠가 없다.<br><br>
    일지 마지막 장. 상행 최종 운행. 열쇠는 규정대로 급이대 함에 반납. 녀석들이 승강장을 배회하기 시작함.<br>
    급이대. 정원 북쪽 끝. 짐승들의 식당 한복판에 열쇠가 있다.<br><br>
    규정대로 사는 사람들은 죽을 때도 규정대로 죽는다. 덕분에 열쇠 자리는 안다.`,
  o:[
    { l:'① 급이대 함까지 — 급이 습관이 비는 한낮에 다녀온다.', k:'hide', dc:25,
      ok:`사육 일지가 알려 준 대로, 몸시계가 느슨한 한낮을 골랐다. 녀석들은 한낮에 그늘에서 처진다.<br><br>북쪽 끝까지 그늘 반대편 양지로만 걸었다. 양지는 덥고, 더운 길은 저것들이 한낮에 안 쓴다.<br>급이대 함은 규정대로 잠겨 있었다 — 자물쇠는 좀도둑이 웃으면서 땄다. 열쇠를 품고 같은 길로 돌아왔다. 죽은 관리인의 규정과 산 짐승의 습관을 겹쳐 쓴 길이었다. 양쪽 다 고마운 일이다.`,
      ng:`한낮인데 하필 급이대 그늘에 한 마리가 처져 자고 있었다. 함 바로 옆에.<br><br>함을 여는 녹슨 소리에 놈의 귀가 섰다.<br>함 뒤에 엎드려 한 식경. 놈이 다시 늘어진 뒤에야 열쇠를 꺼냈다. 돌아오는 길은 두 배로 돌았다. 열쇠 하나가 하루를 먹었다. 그래도 열쇠는 열쇠다. 나가는 문의 반쪽이다.`,
      win:{ exp:20, dream:3 }, lose:{ hp:-27, mind:-16 } },
    { l:'② 열쇠 없이 — 일지에서 비상 수동 절차를 찾는다.', k:'gaze', dc:24,
      ok:`운행 일지 앞장을 뒤졌다. 정전 시 비상 절차 — 권양실 수동 크랭크, 제동 해제 레버는 바닥 함.<br><br>열쇠는 시동용이고, 수동은 열쇠가 필요 없다. 사람 팔이 필요할 뿐.<br>바닥 함을 열어 레버를 확인했다. 성하다. 크랭크는 무겁겠지만 다섯이면 돌린다. 북쪽 끝 식당 나들이가 통째로 생략됐다. 서류는 끝까지 읽는 쪽이 덜 걷는다.`,
      ng:`비상 절차 장이 — 뜯겨 있었다. 앞서 누가 가져간 것이다.<br><br>이 승강기로 나가려던 사람이 전에도 있었고, 그 사람은 절차 장을 들고 — 승강장에는 없다. 어디에도 없다.<br>결국 북쪽 열쇠 길이 남았다. 뜯긴 자리만 한참 들여다봤다. 종이 한 장 차이로 하루가 늘었다. 그 사람 몫까지 조심하기로 했다.`,
      win:{ exp:18, dream:2 }, lose:{ mind:-17, spirit:-17 } }
  ] },

{ at:'S2', t:'울음 흉내 — 금단의 패',
  x:`막다른 골짜기. 뒤에는 무리, 앞에는 절벽 비탈 하나.<br><br>
    비탈을 다섯이 오르는 동안 무리가 닿는다. 시간이 필요하다.<br>
    첩자는 목소리를 흉내 낸다. 사람 목소리를. 여기서 통하는 목소리는 하나뿐이다 — 아까 들은, 새끼 잃은 어미의 울음.<br><br>
    짐승 말로 거짓말하기. 틀리면 거짓말쟁이의 혀부터 뽑힐 것이다.`,
  o:[
    { l:'① 새끼 울음을 흉내 내 무리를 골짜기 밖으로 꾄다.', k:'hide', dc:26,
      doom:{ title:'틀린 발음', what:'울음을 수상히 여긴 무리에게 물려 가 둥지 쪽으로 끌려갑니다', dc:20, sec:36,
        text:`들었던 울음을 머리로 백 번 돌리고 — 냈다. 끼륵, 끼르륵. 골짜기 밖 서쪽을 향해.<br><br>무리가 멈췄다. 고개 여섯이 서쪽으로 돌았다 — 그리고 도로 이쪽으로 돌아왔다.<br>끝이 틀린 것이다. 새끼 울음은 끝이 떨어진다. 이쪽 것은 끝이 올라갔다. 사람 버릇이다. 묻는 말은 끝이 오르니까.<br><br>무리가 소리의 주인을 향해 왔다. 거짓말은 통하지 않았고, 거짓말쟁이는 통째로 물려 간다. 둥지 쪽으로. 새끼들 말 공부 교재가 되러.`,
        dieText:`골짜기에 그 울음이 다시 울리는 일은 없었다.<br><br>무리는 비탈 밑을 한참 서성이다 돌아갔다.<br>비탈 위의 넷은 그 울음의 끝이 오르는지 떨어지는지 끝내 구분하지 못했다. 그게 마지막 수업이었다.`,
      },
      ok:`들었던 울음을 머리로 백 번 돌렸다. 끝이 떨어진다. 세 번 꺾인다. 마지막은 숨이 샌다.<br><br>두 손을 모아 냈다. 끼륵, 끼르륵 — 끝을 떨어뜨리고, 숨을 새게.<br>무리가 통째로 서쪽으로 쏟아져 나갔다. 어미 둘이 제일 앞에서.<br>다섯이 비탈을 다 오르는 동안 골짜기는 비어 있었다. 꼭대기에서 잠깐 서쪽에 미안했다. 없는 새끼를 찾아 헤맬 어미들에게. 거짓말쟁이의 가책은 늘 한발 늦게 온다.`,
      win:{ exp:24, dream:3 } },
    { l:'② 흉내는 접고 — 배낭 하나를 비탈 반대편에 던진다.', k:'evade', dc:24,
      ok:`짐승 말은 짐승 것이다. 서툰 외국어보다 확실한 건 물건이다.<br><br>먹을 것 든 배낭을 골짜기 반대편 덤불에 힘껏 던졌다. 무게가 덤불을 흔들고, 냄새가 터졌다.<br>무리가 그쪽으로 몰리는 동안 비탈을 올랐다. 배낭 값은 아프다. 혀 값보다는 싸다.`,
      ng:`배낭이 덤불에 못 미쳐 골짜기 바닥에 떨어졌다. 무리와 비탈 사이에.<br><br>무리가 배낭을 물어뜯는 자리가 하필 비탈 바로 밑이다.<br>머리 위로 올라가는 다섯의 돌가루가 녀석들 등에 떨어졌다. 두 마리가 고개를 들고 비탈을 기어오르려다 미끄러졌다. 꼭대기에 닿았을 때 다들 손끝에 피가 맺혀 있었다. 던지기는 어깨가 아니라 거리 계산이 전부다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-29, mind:-14 } }
  ] },

{ at:'S2', t:'관찰 초소 — 한 장의 유리',
  x:`정원이 내려다보이는 관찰 초소. 바닥에 관찰 기록이 흩어져 있고, 전면은 유리 한 장이다.<br><br>
    기록 왈 — 특수 유리. 안에서는 보이고 밖에서는 거울임.<br>
    창가에 서자 아래 수풀의 낮은 것들이 전부 — 이쪽을 올려다봤다.<br>
    기록의 마지막 장 — 녀석들이 유리 앞에 모인다. 거울 속 저희를 보는 게 아닌 것 같다. 유리 너머를 아는 것 같다.`,
  o:[
    { l:'① 유리에서 물러나 기록만 걷어 그늘에서 읽는다.', k:'hide', dc:24, wake:1,
      ok:`유리가 거울이어도 빛이 바뀌면 유리다. 창가는 버리고 초소 안쪽 그늘에서 기록을 읽었다.<br><br>관찰 기록은 금광이었다. 무리의 서열 — 흰 줄무늬가 우두머리. 큰 것의 순찰로. 급이대 함 — 열쇠 반납 확인이라는 줄까지.<br>초소를 나올 때 유리 쪽은 한 번도 안 지나갔다. 아래 것들은 빈 거울만 밤새 올려다봤을 것이다.<br><br>좋은 전망은 양방향이라는 것. 보기 좋은 자리는 보이기 좋은 자리다. 첩자가 평생 아는 그 말이 여기서도 참이었다.`,
      ng:`그늘에서 읽는데 등불이 유리에 비쳤다. 그늘은 챙기고 반사는 못 챙겼다.<br><br>아래 수풀이 일제히 수런댔다. 거울 속에 불빛 — 유리 너머에 누가 있다는 증거.<br>불을 끄고 기록만 품고 뒷문으로 빠졌다. 초소 밑동을 밤새 뭔가 긁는 소리가 났다고, 불침번이 전했다. 올라올 수 없는 높이인 게 다행이었다. 아직까지는 올라올 수 없는.`,
      win:{ exp:22, dream:3 }, lose:{ mind:-18, spirit:-17 } },
    { l:'② 유리 앞에 서서 — 녀석들이 뭘 아는지 마주 관찰한다.', k:'gaze', dc:25,
      doom:{ title:'유리 너머의 눈', what:'초소로 뛰어든 것들에게 물려 아래 수풀로 끌려 내려갑니다', dc:20, sec:36,
        text:`기록의 마지막 줄을 시험하기로 했다. 유리 앞에 서서 아래를 마주 봤다.<br><br>흰 줄무늬가 수풀에서 나와 유리 바로 밑에 앉았다. 고개를 꺾어 정확히 이쪽 눈을 봤다. 거울이어도, 보였다.<br>놈이 앞발을 들었다 — 유리가 아니라 초소 뒷문 쪽을 가리키듯.<br>뒷문이 부서지는 소리가 그때 났다. 관찰은 미끼였다. 이쪽이 유리에 붙어 있는 동안 둘이 뒤로 돌았던 것이다.<br><br>물려 간다. 초소 계단 아래로, 수풀로. 흰 줄무늬가 유리 밑에서 끝까지 이쪽을 보고 있었다.`,
        dieText:`관찰 초소의 유리는 그대로다. 안에서 보고, 밖에서는 거울.<br><br>그 밑 수풀에 낮은 것들이 전처럼 모여 밤마다 올려다본다.<br>기록의 마지막 장 다음은 아무도 안 썼다. 쓸 사람이 초소에 더 없어서.`,
      },
      ok:`유리 앞에 서되 — 뒷문부터 잠갔다. 관찰당하는 줄 아는 상대 앞에서는 등부터 챙기는 법이다.<br><br>흰 줄무늬가 유리 밑까지 와서 이쪽을 올려다봤다. 거울 너머를 보는 눈. 기록이 맞았다.<br>한 식경을 마주 봤다. 놈이 앞발로 유리를 한 번 짚고 — 돌아갔다. 인사인지 경고인지 모른다.<br>수첩에 적었다. 흰 줄무늬는 유리를 안다. 아는 것끼리는 서로 안 속인다는 것도 — 오늘 알았다.`,
      win:{ exp:24, dream:3 } },
    { l:'③ 유리의 거울 성질을 이용해 — 아래 정원 전체를 지도로 뜬다.', k:'fix', dc:24,
      ok:`초소의 높이는 정원 전체가 한눈이다. 종이를 펴고 보이는 대로 옮겼다. 물길, 울타리, 급이대, 둥지 둔덕, 승강기까지.<br><br>낮은 것들의 이동도 한 식경 치 화살표로 얹었다. 지도 위에 산 것들의 물길이 생겼다.<br>내려와서 그 지도로 걸으니 정원이 반으로 줄었다. 높은 데서 뜬 지도 한 장은 바닥의 하루와 바꾸지 않는다. 초소는 그 한 장 값을 하고 은퇴했다.`,
      ng:`지도를 뜨는 데 욕심을 내 해가 — 빛이 기울 때까지 눌러앉았다.<br><br>기운 빛이 유리의 거울을 반쯤 벗겼다. 아래서 초소 안 그림자들이 보이기 시작한 것이다.<br>수풀이 수런대기 전에 지도 반 장만 들고 내려왔다. 반 장도 지도는 지도다. 다만 북쪽 반이 백지라, 북쪽 열쇠 길이 하필 백지 속이었다. 욕심이 백지를 만들었다.`,
      win:{ exp:18, dream:2 }, lose:{ mind:-17, spirit:-16 } }
  ] }

]);

// ── 좀도둑 (thief) · 무력 ──
kJob('thief', 'S', [

{ at:'S', t:'어둠 — 손버릇',
  x:`어둠 속을 걷는데 주머니가 묵직하다. 기억에 없는 무게다.<br><br>
    꺼내 보니 쇠단추 둘, 삭은 끈, 그리고 — 작은 뼈 하나. 손이 저 혼자 주워 담은 것들이다. 좀도둑의 손은 주인 허락을 안 받는다.<br>
    뼈에서 냄새가 난다. 비리고 묵직한 냄새.<br><br>
    여기서 냄새 나는 걸 지니고 걷는 건 종을 차고 걷는 것과 같다.`,
  o:[
    { l:'① 주머니를 다 털어 손버릇부터 단속한다.', k:'steady', dc:23, wake:1,
      ok:`주머니를 뒤집어 다 버렸다. 뼈는 멀리, 바람 아래로.<br><br>그리고 손에게 새 규칙을 줬다. 여기서는 줍기 전에 코부터. 냄새 나는 건 돈이 아니라 미끼다.<br>반나절 뒤 손이 또 뭔가를 쥐려다 — 멈췄다. 코가 먼저 일했다. 비린내. 손이 저 혼자 물러났다.<br><br>손버릇은 못 고친다. 버릇에 검문소를 세울 수는 있다. 코가 그 검문소가 됐다.`,
      ng:`다 버렸다고 생각했다. 안주머니에 뼈 부스러기가 남아 있었다.<br><br>밤에 그 부스러기 냄새를 맡고 온 것이 배낭을 뒤졌다. 코앞에서.<br>숨도 못 쉬고 엎드려 있는 동안 그것이 배낭을 반쯤 끌고 갔다. 아침에 되찾아 왔지만 바닥이 찢겨 있었다. 부스러기 하나 값이 배낭 하나다. 여기 물가는 그렇다.`,
      win:{ exp:18, dream:3 }, lose:{ hp:-26, mind:-15 } },
    { l:'② 냄새 나는 뼈를 미끼로 바꿔 쓴다.', k:'hide', dc:24,
      ok:`버릴 바에 쓰기로 했다. 뼈를 끈에 묶어 갈 길 반대쪽 돌 틈에 걸어 뒀다.<br><br>걸고 스무 걸음도 못 가 뒤에서 돌 틈 뒤지는 소리가 났다. 코 밝은 것이 벌써 와 있던 것이다. 등골이 서늘했다 — 이쪽 주머니에 그 뼈가 그대로 있었다면.<br>손버릇이 주워 온 게 미끼가 되어 손버릇 주인을 살렸다. 셈이 묘하게 맞았다.`,
      ng:`뼈를 거는데 끈이 삭아 끊어졌다. 뼈가 발등에 떨어져 굴렀다. 달그락.<br><br>어둠 속 무언가가 그 소리에 코를 들었다.<br>뼈를 발로 멀리 차고 반대로 뛰었다. 그것이 뼈 구른 길을 되짚는 소리를 들으며 구역을 빠졌다. 미끼도 장비가 성해야 미끼다. 끈부터 새로 꼬았다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-25, spirit:-16 } }
  ] },

{ at:'S', t:'자물쇠 — 귀 밝은 복도',
  x:`잠긴 철문이 길을 막는다. 자물쇠는 낡았지만 성하다. 좀도둑에게는 반가운 옛 친구다.<br><br>
    문제는 복도다. 귀 밝은 것이 이 복도를 왕복한다. 지금은 먼 쪽 끝에 있다.<br>
    자물쇠 따는 소리 — 찰칵, 쇠 긁힘, 핀 떨어지는 딸깍. 평소엔 자장가, 여기선 나팔이다.<br><br>
    돌아오는 데 백 숨. 그 안에 따거나, 영영 못 따거나.`,
  o:[
    { l:'① 백 숨 안에 — 소리를 걸음에 묻어 가며 딴다.', k:'hide', dc:25,
      doom:{ title:'귀 밝은 것', what:'문 앞에서 목덜미를 물려 복도 끝으로 끌려갑니다', dc:19, sec:42,
        text:`그것의 걸음 소리에 맞춰 핀을 밀었다. 저벅 — 찰칵. 저벅 — 찰칵. 소리를 소리에 묻는 정석.<br><br>마지막 핀에서 그것의 걸음이 — 멎었다. 복도 반대 끝에서. 박자를 빌려주던 걸음이 사라지자 찰칵 소리가 알몸으로 복도에 섰다.<br>걸음이 다시 시작됐다. 아까보다 배는 빠르게. 이쪽으로.<br><br>자물쇠는 반 따진 채다. 문은 안 열리고, 복도는 길고, 뒤는 막혔다. 목덜미가 물리는 순간까지 손은 핀을 놓지 않았다. 장인병이다. 고치지 못하고 끌려간다.`,
        dieText:`철문 자물쇠에 핀 하나가 꽂힌 채 남았다.<br><br>반쯤 돌아간 자물쇠. 반쯤 열린 길.<br>다음에 오는 팀의 좀도둑이라면 한눈에 알 것이다. 선배가 어디까지 했고, 어디서 끝났는지.`,
      },
      ok:`그것의 걸음에 박자를 얹었다. 저벅 — 찰칵. 저벅 — 찰칵. 걸음이 멎으면 손도 멎는다.<br><br>두 번 멎었다. 두 번 다 손이 먼저 멎었다. 박자를 빌릴 때는 빌려주는 쪽을 끝까지 믿으면 안 된다. 반 박자 먼저 멈추는 게 이자다.<br>아흔 숨에 마지막 핀이 내려앉았다. 문을 밀고 다섯이 들어간 뒤 안에서 잠갔다. 복도의 걸음이 문 앞을 지나는 소리가 들렸다. 평소 박자로. 아무것도 모르는 박자로.`,
      win:{ exp:24, dream:3 } },
    { l:'② 따지 않는다 — 경첩 쪽 핀을 빼서 문을 통째로 연다.', k:'fix', dc:24,
      ok:`자물쇠가 성하면 경첩을 본다. 좀도둑 2과목이다. 경첩 핀이 녹슬었지만 위로 빠지는 물건이다.<br><br>기름 한 방울씩 먹여 가며 손가락으로 밀어 올렸다. 소리는 기름이 다 먹었다.<br>핀 둘을 빼자 문이 자물쇠 쪽을 축으로 돌아 열렸다. 지나고 나서 핀을 도로 꽂았다. 자물쇠는 오늘도 제 일을 다 했다고 믿을 것이다. 문이 저를 배신한 줄은 모르고.`,
      ng:`둘째 핀이 반쯤 올라오다 녹에 물려 부러졌다. 뚝.<br><br>작은 소리. 그러나 쇳소리.<br>복도 끝 걸음이 방향을 틀었다. 부러진 핀 반쪽을 포기하고 문틈에 다섯이 차례로 몸을 구겨 넣었다. 마지막 사람 뒤꿈치가 들어가는 것과 그것이 문 앞에 닿는 것이 같은 숨이었다. 문짝이 등 뒤에서 한참 긁혔다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-27, mind:-15 } }
  ] },

{ at:'S', t:'좁은 틈 — 몸 개키기',
  x:`무너진 벽 사이로 한 뼘 반짜리 틈이 났다. 좀도둑의 길이다.<br><br>
    어깨를 빼고, 숨을 비우고, 몸을 개키면 — 이쪽은 지난다. 문제는 뒤의 넷이다. 덩치들은 못 낀다.<br>
    틈 너머에 빗장이 보인다. 이 벽의 성한 문은 안쪽에서 빗장이 걸린 것이다.<br><br>
    한 명이 끼어 들어가 넷에게 문을 열어 주면 된다. 늘 하던 일이다. 방향만 반대다.`,
  o:[
    { l:'① 숨을 비우고 틈을 지나 안에서 빗장을 딴다.', k:'hide', dc:24,
      ok:`숨을 끝까지 뱉고 어깨부터 넣었다. 가슴이 벽에 눌려 숨이 반 모금씩만 든다. 서두르면 긁히고, 긁히면 소리다.<br><br>한 뼘씩, 벽과 벽 사이를 헤엄치듯 지났다. 안쪽에 떨어져 내려 빗장을 쐈다 — 기름 먹인 손으로, 소리 없이.<br>문이 열리고 넷이 들어왔다. 다들 틈과 이쪽을 번갈아 봤다. 사람이 지나간 틈이 맞나 하는 눈으로. 좀도둑의 몸은 반쯤 연장이다. 오늘도 제 몫을 했다.`,
      ng:`반쯤 끼었을 때 가슴주머니의 쇠붙이가 벽을 긁었다. 끼이익.<br><br>틈 속이라 피할 수도 돌아설 수도 없다. 그대로 전진. 긁히는 소리를 끌고 전진.<br>안쪽에 떨어지자마자 빗장을 따고 넷을 들였다. 문을 닫는 등 뒤로 뭔가가 벽 틈에 코를 박는 소리가 났다. 틈은 이제 저쪽도 안다. 주머니 검사를 안 한 값이다.`,
      win:{ exp:20, dream:3 }, lose:{ hp:-26, mind:-15 } },
    { l:'② 무력으로 틈 가장자리 돌을 밀어 넓히고 끼운다.', k:'break', dc:24, cost:{ might:27 },
      ok:`틈 가장자리 돌 하나가 반쯤 떠 있다. 무력을 어깨에 걸고 — 밀지 않고 비틀었다. 미는 건 와르르, 비트는 건 스르륵.<br><br>돌이 제자리에서 반 바퀴 돌아 틈이 어깨 하나만큼 늘었다. 덩치 둘도 낄 너비다.<br>다섯이 다 틈으로 지났다. 지나고 나서 돌을 도로 비틀어 놨다. 길은 쓰고 닫는 것이다. 다음 손님이 이쪽 같은 직업이라는 보장이 없으니까.`,
      ng:`비튼 돌 위의 작은 돌들이 자리를 잃고 흘렀다. 자그르르.<br><br>무너짐은 아니다. 그래도 돌 흐르는 소리는 멀리 간다.<br>소리가 잦아들기를 기다려 서둘러 끼워 지났다. 마지막 사람이 지날 때 위에서 주먹돌 하나가 떨어져 어깨를 때렸다. 무력은 셈이 정확해야 연장이다. 오늘은 한 푼 어긋났다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-29, mind:-14 } }
  ] },

{ at:'S', t:'쉬는 자리 — 전리품 점검',
  x:`쉬는 참에 오늘 주운 것들을 폈다. 끈, 쇠고리, 성한 부싯돌, 접이칼.<br><br>
    그리고 — 처음 보는 것 하나. 털 뭉치에 싸인 작은 덩이. 주운 기억이 없다.<br>
    주운 게 아니면 — 넣어진 것이다. 언제, 어디서.<br><br>
    덩이에서 희미하게 단내가 난다. 이쪽 코에 희미하면, 저쪽 코에는 등대다.`,
  o:[
    { l:'① 언제 들어왔는지 하루를 거꾸로 뒤진다.', k:'gaze', dc:24, wake:1,
      ok:`주머니에 손이 닿을 수 있던 순간을 거꾸로 셌다. 좁은 틈 — 아니다. 물웅덩이 — 아니다. 낮에 스친 덤불 — 거기다.<br><br>덤불을 지날 때 가지 하나가 유난히 몸을 쓸었다. 가지가 아니었던 것이다.<br>저것들 중에 사냥감에 표식을 다는 놈이 있다. 단내 나는 표식을. 그 덤불 길을 지도에서 지우고, 전원 주머니를 뒤졌다. 막내 배낭에서 하나 더 나왔다.<br><br>도둑이 표식을 달면 장물에 달지 몸에 달지 않는다. 저것들은 몸에 단다. 몸이 장물이라서. 소름이 가르침이 됐다.`,
      ng:`거꾸로 세는 데 너무 골몰했다. 덩이를 손에 쥔 채로.<br><br>단내가 손에 뱄다. 그 밤 손 냄새를 맡고 온 것이 쉬는 자리 가장자리를 두 바퀴 돌았다.<br>손을 흙으로 문지르고 재에 묻었다. 사흘을 장갑 끼고 살았다. 수수께끼는 손에 쥐고 풀면 안 된다. 바닥에 놓고 풀어야 한다.`,
      win:{ exp:20, dream:3 }, lose:{ mind:-18, spirit:-16 } },
    { l:'② 덩이를 당장 — 바람 아래 멀리 묻는다.', k:'evade', dc:23,
      ok:`수수께끼는 나중, 처리가 먼저다. 덩이를 집게로 집어 기름천에 싸고, 바람 아래 쉰 걸음 바위 밑에 묻었다.<br><br>밤에 그 바위 쪽에서 파헤치는 소리가 두 번 났다. 쉰 걸음 밖에서.<br>표식을 단 놈은 밤새 빈 바위만 수확했다. 이쪽은 잠을 수확했다. 수수께끼 풀이는 아침에 안전한 머리로 했다. 순서가 목숨이다.`,
      ng:`묻으러 가는 길에 기름천이 풀렸다. 단내가 바람을 탔다.<br><br>묻고 돌아오는 등 뒤로 벌써 수풀 흔들리는 소리가 붙었다.<br>곧장 쉬는 자리로 못 가고 물길을 돌아 냄새를 끊었다. 젖은 신으로 돌아오니 한밤이었다. 버리는 일도 훔치는 일만큼 손이 간다. 여기서는 더 간다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-26, spirit:-15 } },
    { l:'③ 털 뭉치를 풀어 속을 본다 — 알아야 피한다.', k:'luck', dc:23,
      ok:`집게와 돌판 위에서 풀었다. 속은 — 씨앗이었다. 단내 나는 진에 절인 씨앗 뭉치.<br><br>표식이자 모이다. 달린 놈이 어디서 죽든 거기서 이 씨앗이 싹트는 것이다. 사냥과 농사를 한 손에 하는 셈이다.<br>씨앗은 불에 태웠다. 단내가 탄내로 바뀌는 걸 확인하고야 껐다. 알고 나니 덜 무서웠다. 농부는 농부다. 소름 끼치게 부지런한 농부일 뿐.`,
      ng:`푸는데 진이 손가락에 묻었다. 끈적하고, 안 닦인다.<br><br>물로도 재로도 반만 졌다. 단내가 손가락 하나에 숙소를 잡았다.<br>그 손가락을 천으로 감고 사흘을 다녔다. 감은 천 위로도 밤마다 뭔가 킁킁대고 갔다. 호기심의 값은 손가락 하나였다. 싸게 치렀다고 해 두자.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-25, mind:-16 } }
  ] },

{ at:'S', t:'떨어진 짐 — 먼저 간 팀',
  x:`길가에 배낭이 하나 쓰러져 있다. 사람은 없다. 끌린 자국만 어둠으로 이어진다.<br><br>
    먼저 들어온 팀의 것이다. 배낭은 성하다. 안에 뭐가 들었든 주인은 더 못 쓴다.<br>
    좀도둑은 이런 걸 줍는 직업이다. 다만 여기서는 — 떨어진 짐 곁이 제일 위험한 자리다.<br>
    짐을 떨어뜨린 것이 짐 곁에서 기다리는 수가 있다. 한 번 온 밥이 또 온다는 걸 아는 놈이면.`,
  o:[
    { l:'① 곁을 먼저 턴다 — 기다리는 놈이 있는지.', k:'sense', dc:24,
      ok:`배낭에 바로 안 갔다. 둘레 바위와 천장 턱을 눈으로 다 턴 다음, 돌 하나를 배낭에 던졌다.<br><br>반응 없음. 두 번째 돌. 없음. 그제야 갔다.<br>배낭에서 말린 고기 꾸러미와 성한 물통이 나왔다. 주인 이름표는 — 뜯어서 품에 넣었다. 나가면 전할 데가 있을 것이다. 물건은 줍고 이름은 지고 간다. 이 직업에도 예의는 있다.`,
      ng:`둘레를 턴다고 털었는데 바닥을 안 봤다. 배낭 밑 모래가 — 들려 있었다.<br><br>배낭 끈에 손을 대는 순간 모래가 꺼지며 아래서 집게 같은 것이 솟았다.<br>손목 대신 배낭이 물렸다. 배낭을 버리고 굴렀다. 모래 밑 놈이 배낭을 끌고 들어가는 걸 보며 물러났다. 먼저 간 팀 짐은 저놈 저금통이었던 것이다. 빈손이 산 손이다.`,
      win:{ exp:18, dream:2, item:'말린 고기' }, lose:{ hp:-28, mind:-14 } },
    { l:'② 끌린 자국을 읽는다 — 주인이 살았을지.', k:'gaze', dc:24,
      ok:`끌린 자국을 따라 눈으로만 갔다. 자국 폭, 핏방울 간격, 버둥댄 자리.<br><br>핏방울이 — 없다. 버둥댄 자국이 중간에 끊기고, 거기서부터 발자국이 하나 — 사람 발자국이 옆 틈으로 이어진다.<br>주인은 제 발로 빠져나간 것이다. 배낭을 미끼로 내주고. 동업자 수준의 판단이다. 틈 쪽에 작게 휘파람 신호를 넣어 뒀다. 살아 있으면 알아들을 가락으로. 짐은 그 사람 몫으로 남겨 뒀다.`,
      ng:`자국을 읽으며 몇 걸음 따라 들어갔다. 읽기에 좋은 자국은 — 걷기에 나쁜 길이었다.<br><br>자국이 끝나는 어둠에서 씹는 소리가 났다. 아직 식사 중이었다.<br>소리 안 나게 뒷걸음질로 빠졌다. 배낭은 건드리지도 못했다. 읽기는 멀리서, 줍기는 확인 후. 순서표를 다시 외웠다.`,
      win:{ exp:18, dream:3 }, lose:{ mind:-18, spirit:-17 } }
  ] },

{ at:'S', t:'미끼 — 너무 반짝이는 것',
  x:`길 한가운데 은빛 물건이 놓여 있다. 어둠 속에서도 반짝인다. 호루라기 같다.<br><br>
    너무 좋은 자리에, 너무 보기 좋게. 좀도둑의 눈이 바로 읽었다 — 이건 진열이다.<br>
    물건을 진열할 줄 아는 놈이 이 어둠에 산다.<br><br>
    미끼는 무는 게 아니다. 미끼는 — 미끼를 놓은 놈 걸로 되파는 것이다.`,
  o:[
    { l:'① 미끼를 장대로 걷어 다른 길목에 다시 진열한다.', k:'hide', dc:25, wake:1,
      ok:`긴 장대 끝에 끈고리를 달아 호루라기를 걷었다. 손은 한 뼘도 안 들어갔다.<br><br>그리고 그 미끼를 — 놈의 자리에서 안 보이는 옆 길목에 똑같이 보기 좋게 놓았다.<br>밤에 옆 길목에서 소동이 났다. 미끼 주인이 제 미끼를 문 것인지, 다른 놈이 문 것인지. 어느 쪽이든 이쪽 길은 비었다.<br><br>미끼를 옮겨 되파는 법. 장물은 장물끼리 돌리는 게 제일 깨끗하다. 여기서도 통하는 장사 원칙이다.`,
      ng:`장대로 걷다가 호루라기가 돌에 부딪혔다. 삑 — 반쪽짜리 소리가 났다.<br><br>길 양옆 어둠이 동시에 움직였다. 진열한 놈이 둘이었던 것이다. 합자 회사다.<br>장대를 버리고 뒤로 뛰었다. 둘이 빈 길 가운데서 서로를 마주친 소리가 났다. 동업자끼리의 다툼을 등 뒤로 들으며 멀리 돌았다. 남의 동업은 깨지면 이쪽에 이롭다. 그 정도 이득으로 만족했다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-26, mind:-15 } },
    { l:'② 미끼는 두고 — 진열한 놈의 자리만 알아내 피한다.', k:'gaze', dc:24,
      ok:`진열에는 반드시 계산대가 있다. 미끼가 제일 잘 보이면서 덮치기 좋은 자리 — 천장 배관 턱 하나뿐이다.<br><br>그 턱 밑을 피해서 벽 쪽으로 반원을 그려 지났다. 호루라기는 그대로 반짝이게 뒀다.<br>지나고 돌아보니 턱 위 어둠이 아주 조금 움직였다. 계산대의 주인이 자세를 고치는 것이다. 오늘 장사는 공쳤다. 서로 아는 체는 안 했다.`,
      ng:`계산대를 찾는 눈이 너무 오래 위를 훑었다. 위를 보는 고개는 목이 하얗게 드러난다.<br><br>턱 위의 놈이 이쪽 시선을 느꼈다. 보는 것은 보인다.<br>놈이 미끼를 걷어 챙기더니 배관을 타고 이쪽 머리 위로 따라오기 시작했다. 가게를 접고 손님을 쫓기로 한 것이다. 기둥 많은 홀로 꺾어 반 시진을 돌아 뗐다. 목덜미가 밤새 근질거렸다.`,
      win:{ exp:18, dream:2 }, lose:{ mind:-17, spirit:-18 } }
  ] },

{ at:'S', t:'들고 뛰기 — 짐의 셈',
  x:`급히 자리를 떠야 할 때가 온다. 여기서는 하루 한 번은 온다.<br><br>
    들고 뛸 수 있는 무게와 두고 가는 물건 — 좀도둑은 그 셈이 빠르다. 장물 들고 담 넘던 셈이다.<br>
    문제는 일행 짐까지 다섯 몫이라는 것. 뛸 때 소리 나는 짐, 냄새 나는 짐, 목숨 값 하는 짐.<br><br>
    셈을 미리 해 두면 뛸 때는 손만 움직이면 된다.`,
  o:[
    { l:'① 다섯 배낭을 버릴 순서로 다시 꾸린다.', k:'fix', dc:23,
      ok:`배낭마다 세 층으로 다시 쌌다. 맨 바깥 — 버려도 되는 것. 가운데 — 아까운 것. 몸 쪽 — 목숨 값.<br><br>버릴 층은 끈 하나로 통째로 떨어지게 묶었다. 뛰면서 끈만 당기면 미끼 겸 감량이다.<br>이틀 뒤 실제로 뛸 일이 났다. 다섯이 끈을 당기며 뛰었고, 쫓던 것은 떨어진 바깥층을 뒤지느라 섰다. 셈을 미리 한 자와 안 한 자의 차이가 거기서 났다.`,
      ng:`다시 꾸리는 중에 막내 배낭에서 양철 컵이 굴렀다. 챙그랑.<br><br>어둠이 답했다. 재꾸리기를 중단하고 전원 벽 쪽으로.<br>소동이 지난 뒤 마저 쌌다. 짐 정리도 여기선 전투다. 컵은 천에 싸서 가운데 층으로 보냈다. 소리 나는 놈은 어느 조직에서나 가운데 끼워 두는 법이다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-25, mind:-15 } },
    { l:'② 무력으로 두 사람 몫 짐을 받아 지고 뛰는 연습을 한다.', k:'steady', dc:24, cost:{ might:28 },
      ok:`다친 사람이 나오면 그 짐은 누가 지나. 미리 몸으로 셈해 봤다.<br><br>무력을 허리에 걸고 두 몫을 졌다. 뛰고, 돌고, 엎드리고. 무게가 실린 몸의 소리까지 확인했다 — 두 몫을 지면 발소리가 반 박자 무거워진다. 그 반 박자만큼 먼저 출발하면 된다.<br>사흘 뒤 접질린 발목이 하나 나왔고, 그 짐은 셈해 둔 대로 이쪽 등에 얹혔다. 연습한 무게는 안 무섭다.`,
      ng:`두 몫을 지고 도는 연습 중에 짐이 한쪽으로 쏠렸다. 균형을 놓쳐 벽을 짚었다.<br><br>짚은 벽이 속 빈 벽이었다. 퉁 — 북소리가 났다.<br>연습을 접고 자리를 옮겼다. 빈 벽은 지도에 그려 넣었다. 연습하다 들킨 소리는 실전에서 들킬 소리를 하나 지운 것이다. 그렇게 치기로 했다. 허리는 그렇게 안 쳐 줬지만.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-28, mind:-14 } }
  ] },

{ at:'S', t:'문 버팀쇠 — 잡동사니의 값',
  x:`밤 쉴 방을 찾았다. 문은 있는데 빗장이 없다.<br><br>
    빗장 없는 문 뒤에서 자는 건 입 벌리고 자는 것과 같다.<br>
    주머니를 털었다. 쇠고리, 부러진 핀, 삭은 경첩, 접이칼 — 남들이 쓰레기라던 것들.<br><br>
    좀도둑의 주머니는 철물점이다. 영업시간은 목숨이 걸린 밤.`,
  o:[
    { l:'① 잡동사니로 문에 버팀 장치를 짠다.', k:'fix', dc:23,
      ok:`쇠고리를 문틀 옹이에 걸고, 접이칼을 지렛대 삼아 경첩 조각을 문 밑에 쐐기로 박았다. 부러진 핀은 문고리 구멍에 꽂아 돌아가지 않게.<br><br>밖에서 밀면 — 쐐기가 물고, 고리가 당기고, 핀이 버틴다. 삼중 버팀.<br>밤중에 문이 두 번 밀렸다. 두 번 다 한 치도 안 열렸다. 미는 쪽이 포기하는 기척까지 들었다. 쓰레기 넷의 몸값이 다섯 목숨이었다. 이래서 못 버린다.`,
      ng:`쐐기가 문 밑 틈에 안 맞았다. 바닥이 울퉁불퉁해서.<br><br>깎아 맞추는 칼질 소리가 복도로 샜다. 사각, 사각.<br>칼질을 멈추고 문 안쪽에 배낭들을 쌓는 걸로 바꿨다. 밤중에 문이 밀렸고 배낭 벽이 버텼다. 버티긴 버텼는데 맨 위 냄비가 굴러 온 방이 깼다. 다음 방부터는 바닥 먼저 보고 쐐기를 깎기로 했다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-25, mind:-16 } },
    { l:'② 문을 잠그는 대신 — 문이 열리면 울리는 덫을 단다.', k:'hide', dc:24,
      ok:`버팀은 뚫리면 끝이지만, 경보는 뚫리는 순간이 시작이다.<br><br>문고리에 실을 걸고 실 끝에 양철 컵을 매달아 천장 고리에 띄웠다. 문이 한 뼘 열리면 컵이 떨어지는 높이로. 떨어지는 자리에는 — 이쪽 귀만 아는 푹신한 배낭. 챙그랑 대신 툭.<br>새벽에 툭, 소리에 눈을 떴다. 다섯이 이미 무기를 쥐고 있었다. 문틈의 코가 그 침묵을 읽고 물러갔다. 소리 없는 경보가 제일 좋은 경보다. 저쪽은 울린 줄도 모르니까.`,
      ng:`실의 각도가 얕았다. 밤중에 문이 열렸는데 컵이 반 뼘 못 미쳐 허공에 걸렸다.<br><br>경보 없이 문틈에 코가 들어왔다.<br>불침번의 눈이 그나마 빨랐다. 돌을 던져 코를 쫓고 문을 어깨로 밀어 닫았다. 아침에 실 각도를 다시 쟀다. 덫은 설치가 반, 시험이 반이다. 시험 없이 잔 밤이 수업료였다.`,
      win:{ exp:18, dream:3 }, lose:{ hp:-27, spirit:-15 } }
  ] },

{ at:'S', t:'호주머니 — 덜 죽은 몸',
  x:`벽에 기대 마른 몸이 하나 앉아 있다. 먼저 들어온 누군가다.<br><br>
    허리띠에 열쇠 꾸러미, 가슴 주머니에 각진 것 — 부싯깃 통일 것이다. 둘 다 산 사람에게 요긴하다.<br>
    죽은 이의 주머니를 터는 건 이 직업의 오랜 그늘이다. 턴 만큼 이름을 져 주는 게 계산법이고.<br><br>
    다만 여기서는 — 죽은 몸이 다 죽은 몸이 아니다.`,
  o:[
    { l:'① 가슴부터 본다 — 숨이 아주 없는지.', k:'gaze', dc:25,
      doom:{ title:'덜 죽은 몸', what:'마른 팔에 손목을 잡혀 벽 뒤 어둠으로 끌려 들어갑니다', dc:20, sec:38,
        text:`가슴을 봤다. 미동 없음. 목덜미 — 맥 없음. 눈꺼풀 — 마름. 교과서상 완전한 주검.<br><br>허리띠 열쇠에 손을 댔다. 그 순간 마른 손이 이쪽 손목을 쥐었다.<br>숨도 맥도 없이 움직이는 몸. 여기 교과서는 장이 하나 더 있던 것이다 — 들어 있는 것은 제 숙소의 숨과 맥을 끌 수 있다. 손님이 올 때는.<br><br>마른 몸이 일어선다. 벽이 열린다. 벽 뒤는 어둠이다. 손목을 쥔 채 그 어둠으로 걸어 들어간다. 열쇠 꾸러미가 허리에서 찰랑댄다. 저 열쇠는 영영 저 허리 것이다.`,
        dieText:`벽에 기대 마른 몸이 둘 앉아 있다.<br><br>하나는 허리에 열쇠 꾸러미, 하나는 빈 허리.<br>둘 다 가슴이 미동 없다. 교과서상 완전한 주검으로. 다음 손님이 올 때까지는.`,
      },
      ok:`가슴 — 미동 없음. 맥 — 없음. 그런데 입가가 마음에 걸렸다. 마른 몸인데 입가만 — 촉촉하다.<br><br>마른 집에 젖은 문. 안에 세입자가 있다는 문패다.<br>열쇠는 포기했다. 대신 지나가며 긴 장대로 허리띠 버클만 풀었다. 꾸러미가 바닥에 떨어지자 — 마른 손이 번개처럼 그 소리를 낚아챘다. 몸은 그대로인 채 팔만.<br>떨어진 꾸러미 대신 팔이 돌아간 틈의 부싯깃 통을 장대 끝으로 걷어 챙겼다. 반 수확. 손목 값으로는 충분한 장사다.`,
      win:{ exp:24, dream:3 } },
    { l:'② 털지 않는다 — 다만 이름표만 장대로 걷는다.', k:'steady', dc:23,
      ok:`열쇠도 부싯깃도 포기했다. 여기서 덜 죽은 몸의 물건은 다 미끼로 친다.<br><br>다만 목에 건 이름표만 장대 끝 고리로 걷었다. 천천히, 줄이 당겨지지 않게.<br>이름표에 이름과 — 팀 번호가 있었다. 먼저 들어와 안 나간 팀. 나가면 전할 이름이 하나 늘었다. 주머니는 못 졌지만 이름은 졌다. 이 직업의 계산법은 지켰다.`,
      ng:`장대 고리가 이름표 줄을 걸다 놓쳤다. 줄이 목에서 팅, 울렸다.<br><br>마른 몸의 고개가 — 소리 쪽으로 한 치 돌았다. 눈 감은 채.<br>장대를 든 채 뒷걸음질로 물러났다. 고개는 그 각도로 멎어 있었다. 이름은 못 졌다. 대신 그 복도를 지날 다음 사람을 위해 벽에 긁어 뒀다. 앉은 것, 돈다. 만지지 말 것.`,
      win:{ exp:18, dream:2 }, lose:{ mind:-18, spirit:-17 } }
  ] },

{ at:'S', t:'손가락 — 곱은 손',
  x:`추위와 긴장에 손가락이 곱았다. 좀도둑에게 손은 눈이고 혀고 밥줄이다.<br><br>
    곱은 손은 핀을 떨어뜨린다. 떨어진 핀은 소리를 낸다. 소리는 — 그만하자.<br>
    앞에 자물쇠 달린 철문이 하나 더 있다는 전갈이다.<br><br>
    손을 풀어 두는 것도 일이다. 연장 손질이니까.`,
  o:[
    { l:'① 겨드랑이에 손을 묻고 피가 돌 때까지 기다린다.', k:'steady', dc:23,
      ok:`걸으면서 양손을 겨드랑이에 꽂았다. 체온이 제일 오래 남는 금고다.<br><br>손가락 끝이 저릿해지며 피가 돌았다. 다 풀린 걸 확인하는 법도 안다 — 엄지와 새끼로 동전 돌리기. 어둠 속에서 소리 없이 세 바퀴.<br>철문 앞에 섰을 때 손은 한여름이었다. 자물쇠는 두 숨에 내려앉았다. 연장을 데워 간 덕이다.`,
      ng:`겨드랑이에 꽂은 손이 풀리기 전에 철문이 먼저 왔다.<br><br>곱은 손으로 핀을 잡았다. 첫 핀에서 손가락이 떨렸고 — 참고 — 둘째 핀에서 핀을 놓쳤다. 쨍.<br>전원이 벽에 붙어 한 식경을 보냈다. 소리의 주인 자리를 확인하고서야 다시 땄다. 이번엔 손에 입김을 백 번 분 다음에. 연장 관리 소홀은 이 바닥 제일 비싼 벌금이다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-25, mind:-16 } },
    { l:'② 치유 아는 일행에게 손목 혈을 눌러 달라 한다.', k:'bond', dc:23,
      ok:`자존심을 접고 손을 내밀었다. 손목 안쪽을 누르자 손가락 끝까지 뜨끈한 것이 흘렀다.<br><br>남의 손을 빌려 제 손을 고치는 기분은 묘했다. 나쁘지 않게 묘했다.<br>보답으로 그 사람 배낭의 뻑뻑한 버클을 소리 안 나게 손봐 줬다. 손은 손으로 갚는다. 다섯이 서로의 연장이 되는 밤이었다.`,
      ng:`혈을 눌러 주던 중에 이쪽 손이 버릇대로 — 그 사람 주머니 근처로 갔다.<br><br>훔치려던 게 아니다. 손버릇이다. 그래도 들켰다.<br>어색한 침묵이 흘렀다. 사과 대신 그 사람 신발끈을 다시 매 줬다. 풀리지 않는 매듭으로. 신뢰는 자물쇠보다 따기 어렵고, 한 번 떨어뜨리면 소리가 제일 크다.`,
      win:{ exp:16, dream:2, hp:6 }, lose:{ mind:-16, spirit:-16 } }
  ] },

{ at:'S', t:'쉬는 자리 — 돌려놓는 손',
  x:`배낭 바닥에서 일행 막내의 부적 주머니가 나왔다. 사흘 전 손버릇이 저지른 일이다.<br><br>
    막내는 그날부터 운이 나쁘다고 풀이 죽어 있다. 부적 없인 못 자는 사람이었다.<br>
    훔친 걸 들키지 않는 건 기본기다. 돌려놓는 걸 들키지 않는 건 — 윗급 기술이다.<br><br>
    여기 와서 제일 어려운 자물쇠가 이거다.`,
  o:[
    { l:'① 자는 막내의 품에 소리 없이 돌려놓는다.', k:'hide', dc:24, wake:1,
      ok:`막내가 잠들기를 기다렸다. 숨이 고르게 내려앉은 때, 이불깃을 반 치 들고 부적 주머니를 심장 쪽에 밀어 넣었다.<br><br>빼는 손은 바람이면 되지만 넣는 손은 — 체온까지 숨겨야 한다. 손을 미리 식히고 들어갔다.<br>아침에 막내가 소리를 질렀다. 기쁜 소리를. 사흘 만에 처음 웃었다. 배낭이 아니라 품에서 나왔으니 제가 흘린 줄도 모른다.<br><br>넣는 손이 빼는 손을 이긴 날. 좀도둑 십 년에 제일 어려운 기술을 여기서 완성했다. 써먹을 데가 묘하게 — 따뜻한 데뿐이지만.`,
      ng:`이불깃을 드는데 막내가 뒤척였다. 얕은 잠이었다.<br><br>손을 뺄까 넣을까의 반 숨 — 넣고 뺐다. 막내 눈이 반쯤 떠졌다.<br>자는 척 눈을 감았는지, 진짜 잤는지 모른다. 아침에 막내는 부적을 찾고 환해졌는데, 이쪽을 보는 눈이 묘하게 길었다. 알고도 모른 척해 주는 눈 같기도 했다. 그게 제일 맵다.`,
      win:{ exp:20, dream:3, spirit:6 }, lose:{ mind:-16, spirit:-16 } },
    { l:'② 찾은 척한다 — 바위 틈에서 주웠다고.', k:'luck', dc:23,
      ok:`아침 수색 때 바위 틈을 뒤지는 척하다 소리쳤다 — 손짓으로. 이거 네 것 아니냐.<br><br>막내가 달려와 받아 쥐고 바위 틈에 절을 했다. 운이 돌아왔다고.<br>거짓말이 하나 늘고 울상이 하나 줄었다. 남는 장사로 치기로 했다. 바위에게는 미안하다. 공을 가로채 갔다 — 아니, 줬다.`,
      ng:`바위 틈에서 줍는 연기가 서툴렀다. 손이 너무 정확히 그 틈으로 갔다.<br><br>치유 담당이 그 손놀림을 봤다. 수색하는 손이 아니라 꺼내는 손이라는 걸 아는 눈이었다.<br>막내는 기뻐했고, 치유 담당은 말이 없었고, 이쪽은 밥 당번을 자청했다. 사흘치. 연기는 손보다 어렵다. 손은 십 년을 닦았지만 연기는 안 닦았으니까.`,
      win:{ exp:16, dream:2 }, lose:{ mind:-15, spirit:-17 } }
  ] },

{ at:'S1', t:'표본장 — 잠긴 유리문',
  x:`표본장 유리문 안에 봉한 약품 상자와 마른 약초 꾸러미가 성하게 남아 있다.<br><br>
    자물쇠는 장식 수준이다. 문제는 유리다. 낡은 유리는 열 때 운다. 끼이잉 — 유리 우는 소리는 쇠보다 멀리 간다.<br>
    선반 사이 어둠에 창백한 것들이 산다는 건 이제 상식이다.<br><br>
    유리를 안 울리고 여는 법. 좀도둑 3과목이다.`,
  o:[
    { l:'① 경첩에 기름을 먹이고 문을 들면서 연다.', k:'hide', dc:24, wake:1,
      ok:`유리문이 우는 건 경첩이 처져 유리가 틀에 끌리기 때문이다. 경첩에 등잔 기름을 세 방울 먹이고 — 문을 당기지 않고 위로 받쳐 들면서 돌렸다.<br><br>유리가 틀에서 한 올도 안 끌렸다. 소리 없음.<br>약초 꾸러미와 봉한 상자를 걷고, 문을 같은 법으로 닫았다. 표본장은 아무 일 없던 얼굴이다.<br><br>문은 여는 게 아니라 들어 모시는 것. 낡은 문일수록 그렇다. 유리 문짝 하나가 과외 선생이었다.`,
      ng:`기름이 모자랐다. 반쯤 돌았을 때 유리가 울었다. 끼 —<br><br>반의반 소리에서 멈췄다. 문을 연 채로 굳은 동상이 됐다.<br>선반 어둠에서 창백한 것 하나가 머리를 내밀어 한 바퀴 둘러보고 들어갔다. 그 자세로 백 숨을 더 서 있다가 마저 열었다. 이번엔 침까지 발라 가며. 약초는 얻었다. 어깨는 굳은 채로.`,
      win:{ exp:20, dream:3, item:'약초 뭉치' }, lose:{ hp:-26, mind:-15 } },
    { l:'② 유리를 여는 대신 — 뒤판 나사를 푼다.', k:'fix', dc:24,
      ok:`표본장을 벽에서 반 뼘 당겨 보니 뒤판이 나사 넷으로 물려 있다. 접이칼 끝이 나사에 맞았다.<br><br>나사는 소리가 없다. 넷을 풀고 뒤판을 내리니 표본장 속이 뒷문으로 열렸다.<br>앞 유리는 손도 안 댔다. 물건을 걷고 뒤판을 도로 물렸다. 앞으로 들어가지 말고 뒤로 들어가라 — 스승이 살아 있다면 여기서도 같은 말을 했을 것이다.`,
      ng:`셋째 나사가 녹에 물려 있었다. 힘을 더하자 칼끝이 미끄러져 뒤판을 드륵 — 긁었다.<br><br>얇은 판은 북이다. 선반 사이 어둠이 수런댔다.<br>표본장 뒤에 낀 채로 한 식경을 보냈다. 창백한 것이 표본장 앞 유리에 얼굴을 대고 안을 들여다보다 갔다. 유리 너머로 그 얼굴과 — 눈 없는 얼굴과 마주 봤다. 나사 하나 값 치고는 호된 값이다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-27, spirit:-16 } }
  ] },

{ at:'S1', t:'죽은 숙주 — 허리의 꾸러미',
  x:`배양실 바닥에 연구복이 엎어져 있다. 등이 — 터져 있다. 안엣것이 나간 자리다.<br><br>
    나간 집은 빈집이다. 빈집 허리띠에 열쇠 꾸러미가 성하다. 기밀문 두 개 값이다.<br>
    다만 빈집 곁에는 나간 놈이 멀리 안 갔을 수 있다. 갓 터진 자리면 더.<br><br>
    터진 자리의 마른 정도 — 그걸 읽는 눈이 목숨을 가른다.`,
  o:[
    { l:'① 터진 자리부터 읽는다 — 며칠 됐는지.', k:'gaze', dc:25,
      doom:{ title:'빈집 곁', what:'배양조 뒤에서 나온 것에게 발목을 감겨 끌려갑니다', dc:20, sec:38,
        text:`터진 자리의 가장자리를 봤다. 말랐다. 오래됐다. 빈집 확정 — 이라고 읽었다.<br><br>틀린 독해였다. 자리는 오래됐는데, 나간 놈이 — 멀리 안 가고 이 방에서 자랐던 것이다.<br>열쇠에 손을 대는 순간 배양조 뒤에서 그것이 쏟아져 나왔다. 사람 팔 길이의, 이제는 사람 팔 둘레의.<br><br>발목이 감겼다. 끌려간다. 배양조 뒤로, 제 첫 집이 보이는 자리로. 그것은 제가 나온 집 곁을 못 떠나는 것이었다. 집이 그리운 건지, 집이 미끼인 걸 아는 건지.`,
        dieText:`배양실 바닥에 연구복이 둘 엎어져 있다.<br><br>하나는 등이 터졌고, 하나는 성하다. 허리의 열쇠 꾸러미도 성하다.<br>갓 비워진 집일수록 곁에 주인이 있다. 그 문장이 이 방의 교훈으로 남았다. 읽을 사람이 오면.`,
      },
      ok:`터진 자리 가장자리 — 말랐다. 오래됐다. 그런데 바닥에 끌린 자국이 — 자국이 여럿이고, 제일 새것이 오늘 것이다.<br><br>오래된 빈집에 새 발자국. 나간 놈이 아직 드나든다는 뜻이다.<br>방에 들어가지 않고 문가에서 장대 끝 고리로 허리띠째 걷었다. 네 번 실패, 다섯 번째에 걸렸다. 꾸러미를 끌어내는 동안 배양조 뒤 어둠이 한 번 출렁였다.<br>문을 닫고 복도에서 꾸러미를 챙겼다. 방은 방 주인에게. 열쇠는 산 사람에게.`,
      win:{ exp:24, dream:3 } },
    { l:'② 열쇠 말고 — 바닥의 공구 벨트만 발로 끌어 온다.', k:'evade', dc:24,
      ok:`열쇠는 허리에 있지만 공구 벨트는 시신에서 떨어져 문가에 있다. 욕심의 거리와 안전의 거리.<br><br>문지방에 선 채 발끝으로 벨트를 긁어 당겼다. 몸은 방에 한 치도 안 들였다.<br>벨트에서 절단 가위와 드라이버가 나왔다. 열쇠가 여는 문은 두 개지만 공구가 여는 문은 — 세는 법이 없다. 욕심을 반 접으니 수확이 더 크다. 이 장사의 역설이다.`,
      ng:`벨트가 바닥 틈에 걸렸다. 발끝에 힘을 더하자 — 벨트 버클이 바닥을 드르륵 긁었다.<br><br>배양조 뒤 어둠이 일어섰다.<br>벨트를 낚아채며 뒤로 굴렀다. 문을 닫는 손잡이에 뭔가 안쪽에서 부딪히는 무게가 실렸다. 벨트는 얻었다. 가위는 얻는 길에 틀에 부딪혀 날이 나갔다. 반 성한 수확. 여기 시세로는 그래도 흑자다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-28, mind:-14 } }
  ] },

{ at:'S1', t:'통풍관 — 같은 몸집',
  x:`통풍관은 좀도둑의 몸에 맞게 태어난 길이다. 평생 그 덕을 봤다.<br><br>
    여기 통풍관은 — 똑같은 몸집의 것들이 먼저 쓰고 있다. 사람 아이만 한, 창백하고 긴 것들.<br>
    관은 두 가닥. 꼭 지나야 할 구간은 서른 자.<br><br>
    같은 체급의 경기다. 홈그라운드만 저쪽이다.`,
  o:[
    { l:'① 저쪽 관에 돌을 굴려 두 가닥을 비우고 빠르게 긴다.', k:'hide', dc:25,
      ok:`오른 가닥 깊숙이 돌을 굴렸다. 데구루루 — 긴 것들이 그 소리로 모이는 기척이 관 벽을 타고 왔다.<br><br>왼 가닥을 서른 자, 숨 세 번으로 기었다. 팔꿈치와 무릎의 4박자. 평생 긴 가락이다.<br>나와서 뚜껑을 닫고 쐐기를 박았다. 오른 가닥에서 돌을 두드리는 소리가 한참 났다. 돌의 정체를 궁리하는 소리. 궁리해라. 답은 없다.`,
      ng:`돌이 너무 일찍 멎었다. 가까운 데서. 미끼 반경이 짧아진 것이다.<br><br>왼 가닥 열다섯 자쯤에서 앞쪽 어둠에 긴 것 하나가 마주 들어왔다.<br>같은 체급, 좁은 관, 정면. — 뒤로 기는 속도 대결이 됐다. 평생 앞으로만 기었지 뒤로는 처음이었다. 이겼다. 반 자 차이로. 나와서 뚜껑에 쐐기 둘을 박고 주저앉았다. 뒤로 기기, 연습 목록에 올랐다.`,
      win:{ exp:20, dream:3 }, lose:{ hp:-28, mind:-16 } },
    { l:'② 관 바깥 — 배선 홈통을 타고 벽으로 돈다.', k:'evade', dc:24,
      ok:`관이 저쪽 길이면 이쪽은 다른 길을 찾는 게 체급 경기의 정석이다.<br><br>벽 위쪽 배선 홈통 — 폭 두 뼘. 관보다 좁지만 뚜껑이 없는 열린 길이다. 열린 길은 물러날 수 있다.<br>홈통을 모로 타고 서른 자를 돌았다. 밑의 통풍관에서 긴 것들이 오가는 진동이 벽을 타고 느껴졌다. 위층 세입자가 된 기분으로 그 위를 지났다. 층간 소음은 이쪽이 안 냈다.`,
      ng:`홈통 중간에 삭은 구간이 있었다. 디딘 데가 휘며 — 끼긱.<br><br>밑 통풍관의 오감이 그 소리에 쏠렸다. 뚜껑 틈새로 창백한 손가락들이 나와 홈통 쪽 허공을 더듬었다.<br>삭은 구간을 큰대자로 엎드려 무게를 펴고 건넜다. 손가락들이 닿는 높이보다 한 뼘 위를. 그 한 뼘이 그날 밤 꿈에 자로 재듯 나왔다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-27, spirit:-16 } }
  ] },

{ at:'S1', t:'산 — 자물쇠 감정',
  x:`약품고 문 앞. 자물쇠가 — 녹아 있다. 고드름처럼 흘러 굳었다.<br><br>
    산성 피가 닿은 자리다. 이 복도에서 싸움이 있었던 것이다.<br>
    녹은 자물쇠는 두 종류다. 걸쇠까지 녹아 당기면 열리는 것. 겉만 녹고 속은 물려서 영영 안 열리는 것.<br><br>
    겉보기엔 똑같다. 가리는 건 좀도둑의 눈이다.`,
  o:[
    { l:'① 녹은 결을 읽어 당길 놈만 당긴다.', k:'gaze', dc:24,
      ok:`녹은 쇠의 결을 봤다. 흘러내린 방향이 걸쇠 축을 지났다 — 속까지 탔다는 결이다.<br><br>천으로 감아 당기자 자물쇠가 엿가락처럼 늘어나며 빠졌다. 소리는 천이 다 먹었다.<br>약품고에서 봉한 소독약과 — 구석의 비상식량 깡통까지 나왔다. 녹은 자물쇠 감정법. 교본에 없는 과목이 하나 늘었다. 여기 교본은 피로 쓰여 있지만, 배우는 건 배우는 거다.`,
      ng:`결을 잘못 읽었다. 겉만 녹은 놈이었다. 당기자 문짝째 덜컹 —<br><br>울렸다. 복도 끝까지.<br>문틈에 끼인 채 버티다 발소리가 멀어진 뒤 놓았다. 자물쇠는 결국 경첩 쪽을 풀어 열었다. 두 배 걸렸다. 감정 실패의 값은 늘 시간이다. 시간이 제일 비싼 동네에서.`,
      win:{ exp:20, dream:3, item:'말린 고기' }, lose:{ hp:-26, mind:-15 } },
    { l:'② 녹은 쇠는 안 믿는다 — 문 아래 배식구로 들어간다.', k:'hide', dc:24,
      ok:`약품고 문 밑에 배식구 — 쟁반 하나 드나들 쪽창이 있다. 어깨만 접으면 이쪽도 쟁반이다.<br><br>쪽창 경첩에 기름을 먹이고, 머리부터 밀어 넣었다. 어깨 — 접고. 허리 — 비틀고.<br>안에서 문을 여니 밖의 넷이 벌린 입을 다물지 못했다. 쟁반 구멍으로 사람이 나왔으니. 좀도둑의 몸은 문이 아니라 틈에 맞게 설계된 것이다. 설계대로 썼을 뿐이다.`,
      ng:`허리까지는 들어갔다. 엉덩이에서 — 벨트 주머니가 걸렸다.<br><br>앞으로도 뒤로도 반 뼘씩만 움직이는 몸. 쪽창에 낀 좀도둑이라니, 조합 망신이다.<br>밖에서 둘이 다리를 밀고 안으로 겨우 빠졌다. 벨트 주머니가 뜯겨 쪽창에 남았다. 소동 소리에 복도 끝 어둠이 한 번 다녀갔다 — 고 밖의 넷이 전했다. 끼는 것도 소리 안 나게 끼는 게 다음 목표다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-27, mind:-14 } }
  ] },

{ at:'S1', t:'보급 상자 — 봉인 따기',
  x:`식당 선반에 군용 보급 상자가 성하게 남았다. 밀봉 깡통들 — 몇 년이 지나도 먹을 수 있는 것들.<br><br>
    문제는 밀봉이다. 뚜껑을 따면 바람 드는 소리가 난다. 치익. 그리고 안의 냄새가 — 몇 년 묵은 진한 밥 냄새가 한꺼번에 터진다.<br>
    여기서 밥 냄새는 이쪽 밥 냄새가 아니라 저쪽 밥 냄새다.<br><br>
    딸 때 다 정해진다. 어디서, 어떻게, 몇 개를.`,
  o:[
    { l:'① 물속에서 딴다 — 소리도 냄새도 물에 가둔다.', k:'hide', dc:24, wake:1,
      ok:`식당 개수대에 고인 물. 깡통을 물속에 넣고 물 밑에서 땄다.<br><br>치익 — 은 물거품이 됐고, 냄새는 물이 안았다. 수면에 기름막이 한 겹 돌았을 뿐.<br>깡통 셋을 그렇게 따서 속만 기름천에 옮겨 쌌다. 빈 깡통은 물에 가라앉혔다.<br><br>소리와 냄새를 한꺼번에 가두는 물의 쓸모. 앞으로 봉한 것은 다 물가에서 딴다. 좀도둑 교본에 제 손으로 쓴 첫 줄이다.`,
      ng:`둘째 깡통이 물 밑에서 미끄러졌다. 개수대 바닥을 때렸다. 깡 —<br><br>물이 소리를 반만 안았다. 반은 식당을 건넜다.<br>천장 배관에서 긴 것이 식당으로 머리를 내렸다. 개수대 밑에 숨어 그것이 수면의 기름막을 혀로 걷어 먹는 걸 들었다. 깡통 하나는 그렇게 저쪽 몫이 됐다. 물값으로 치기로 했다.`,
      win:{ exp:20, dream:3, item:'말린 고기' }, lose:{ hp:-26, mind:-15 } },
    { l:'② 상자째 지고 나와 안전한 데서 연다.', k:'steady', dc:24,
      ok:`따는 자리가 위험하면 자리를 바꾸면 된다. 상자째 등에 묶었다. 무게는 각오한 값이다.<br><br>모서리마다 천을 감아 어디에 부딪혀도 둔한 소리만 나게 하고, 두 구역을 져 날랐다.<br>쉬는 자리에서 열어 보니 깡통 아홉에 성냥까지 들어 있었다. 식당에서 땄으면 아홉 번 떨 일이었다. 무거운 어깨가 아홉 번의 공포보다 싸다.`,
      ng:`상자를 지고 문턱을 넘다 상자 안에서 깡통들이 쏠렸다. 데구룩.<br><br>등에 진 북이 됐다. 멈추면 더 수상한 소리라 그대로 걸었다.<br>복도 끝까지 심장이 깡통들과 같이 굴렀다. 쉬는 자리에서 열어 보니 깡통 하나가 찌그러져 새고 있었다. 샌 냄새는 기름천 삼중으로 봉했다. 짐은 싸기 전에 속부터 고정 — 기본을 또 몸으로 복습했다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-27, mind:-14 } }
  ] },

{ at:'S1', t:'알 — 안 훔치는 물건',
  x:`알 방 가장자리, 떨어져 나온 알이 하나 바닥에 서 있다. 멀쩡한 채로.<br><br>
    바깥세상 수집가들이 이것 하나에 어떤 값을 부를지 — 셈이 저절로 돌아간다. 평생 만질 돈이 알 하나에 들었다.<br>
    손이 벌써 반쯤 나가 있다.<br><br>
    좀도둑 교본 1장 1절 — 값을 보기 전에 주인을 보라. 이것의 주인은 이 시설 전부다.`,
  o:[
    { l:'① 들고 간다 — 천에 싸서, 품에 묻어서.', k:'hide', dc:26,
      doom:{ title:'알 도둑', what:'온 시설의 것들에게 쫓겨 알과 함께 안쪽으로 끌려갑니다', dc:20, sec:36,
        text:`천으로 삼중으로 싸고 품에 묻었다. 냄새도 온기도 샐 틈 없이 — 그렇게 믿었다.<br><br>두 구역을 지났을 때 뒤에서 벽이란 벽이 울기 시작했다. 배관마다, 통풍구마다.<br>알은 소리로 찾는 게 아니었다. 알이 — 부르는 것이었다. 품속에서, 들리지 않는 소리로, 온 시설에.<br><br>사방에서 쏟아져 나왔다. 품의 알은 점점 따뜻해졌다. 집에 간다고 좋아하는 온기. 알과 함께 안쪽으로 끌려가며 셈을 고쳤다. 이 알의 값은 처음부터 — 사람 하나였다.`,
        dieText:`알은 제자리로 돌아갔다. 알 방 가장자리, 바닥에 선 채로.<br><br>멀쩡한 채로. 수집가들이 값을 부를 만한 채로.<br>다음 셈 빠른 손을 기다리면서. 그 알은 늘 거기 있다. 미끼는 원래 안 상한다.`,
      },
      ok:`천을 꺼내 싸려다 — 멈췄다. 알 둘레 바닥에 긁힌 자국이 둥글게 나 있다. 여러 겹. 여러 날.<br><br>뭔가가 이 알을 중심으로 돌면서 지킨 자국이다. 떨어져 나온 알이 아니다. 내놓은 알이다.<br>내놓은 물건 중에 공짜는 없다. 진열장의 보석이 그냥 보석인 적 없듯이.<br>손을 거뒀다. 셈은 셈대로 적어 뒀다 — 알 하나 = 평생 돈 = 목숨 하나. 등호가 셋인 셈은 안 하는 거다. 교본 1장 1절이 오늘도 맞았다.`,
      win:{ exp:24, dream:3 } },
    { l:'② 알 대신 — 알 방 벽의 깨진 수지 조각을 줍는다.', k:'luck', dc:23, wake:1,
      ok:`알은 못 건드려도 알 방 벽에서 떨어진 굳은 수지 조각 — 저것들이 벽을 바를 때 쓰는 것 — 은 바닥에 흔하다.<br><br>세 조각 주웠다. 호박(琥珀) 비슷하고, 돌보다 가볍고, 불에 안 탄다. 바깥 학자들이 알 반값은 쳐줄 물건이다.<br>목숨 안 걸고 줍는 반값. 그게 이 직업의 어른 셈법이다.<br><br>제일 비싼 것에서 눈을 떼면 두 번째 값이 보인다. 그 눈을 여기서 얻었다. 알 방이 가르쳐 준 게 알 값만은 아니다.`,
      ng:`조각을 줍는데 하나가 바닥에 — 붙어 있었다. 당기자 쩍, 소리가 났다.<br><br>알 방 안쪽 주머니들이 일제히 그쪽으로 기울었다.<br>주운 두 조각만 쥐고 기듯이 물러났다. 세 번째 조각은 바닥과 한 몸인 채 남았다. 욕심의 마지막 한 개가 꼭 소리를 낸다. 두 개에서 멈추는 연습이 — 아직 덜 됐다.`,
      win:{ exp:20, dream:3 }, lose:{ hp:-26, mind:-15 } }
  ] },

{ at:'S1', t:'기밀문 — 녹슨 바퀴',
  x:`수동 기밀문이다. 가운데 바퀴 손잡이를 돌려야 빗장이 풀린다.<br><br>
    바퀴는 녹이 슬었다. 돌리면 운다. 끼이이익 — 시설 반대편까지 갈 울음이다.<br>
    기름은 바닥났다. 손 기술로 될 녹이 아니다. 힘으로 눌러 가며 달래서 돌리는 수뿐이다.<br><br>
    힘과 조심을 한 손에 쥐는 일. 그게 제일 어려운 일이다.`,
  o:[
    { l:'① 무력으로 바퀴를 축에 눌러 붙이며 반 치씩 돌린다.', k:'break', dc:25, cost:{ might:35 },
      ok:`녹이 우는 건 축과 바퀴 사이가 떠서 긁히기 때문이다. 무력으로 바퀴를 축 쪽으로 눌러 틈을 죽이고 — 반 치 돌리고, 쉬고, 반 치.<br><br>우는 대신 둔하게 끙, 하는 소리만 났다. 쇠가 이 악무는 소리.<br>백스무 번의 반 치 끝에 빗장이 떨어졌다. 팔이 덜덜 떨렸다. 문이 열리고, 복도는 끝까지 조용했다. 힘은 세게 쓰는 게 아니라 고르게 쓰는 것이다. 자물쇠가 평생 가르친 걸 바퀴가 복습시켰다.`,
      ng:`아흔 번째 반 치에서 팔이 풀렸다. 누르는 힘이 빠지며 바퀴가 — 끼이이익.<br><br>반 바퀴 치 울음이 통째로 터졌다.<br>남은 반 바퀴를 울음이고 뭐고 내처 돌려 문을 열고 다섯이 쏟아져 들어가 안에서 잠갔다. 문 밖에서 뭔가가 바퀴를 거꾸로 돌리는 소리가 밤새 났다. 안쪽 빗장이 있는 문이라 다행이었다. 팔은 이틀 뒤에 돌아왔다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-30, mind:-14 } },
    { l:'② 바퀴에 오줌이라도 — 아니, 수통 물에 재를 개어 틈에 먹인다.', k:'fix', dc:24,
      ok:`기름이 없으면 만든다. 등잔 재와 물을 개어 진창을 만들어 축 틈에 꾹꾹 밀어 넣었다.<br><br>재 진창은 기름만 못하지만 맨 녹보다 백배 낫다. 바퀴가 울음 대신 쉰 숨소리를 내며 돌았다.<br>문이 열렸다. 수통 물 반과 재 한 줌의 값이다. 좀도둑의 철물점에는 없는 게 없다. 반은 쓰레기라서 없는 게 없는 것이다.`,
      ng:`재 진창이 너무 묽었다. 틈에서 줄줄 흘러내려 바닥에 검은 웅덩이만 생겼다.<br><br>두 번째 반죽은 되게 갰는데, 이번엔 처음 돌릴 때 마른 녹이 한 번 — 끽, 울었다.<br>짧은 울음이었지만 복도 끝에서 답이 왔다. 다 돌릴 때까지 등 뒤를 일행 넷이 무기 들고 막아 섰다. 문이 열리는 순간 다섯이 한 덩어리로 굴러 들어갔다. 반죽의 농도도 기술이다. 적어 뒀다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-27, mind:-15 } }
  ] },

{ at:'S2', t:'둥지 — 수집가들',
  x:`낮은 것들의 둥지 바닥에 반짝이는 것들이 깔려 있다. 단추, 버클, 안경테, 그리고 — 관리인의 열쇠고리.<br><br>
    저것들도 수집을 한다. 반짝이는 것을 물어다 깔고 잔다.<br>
    동종 업계다. 업계 사람끼리는 서로의 창고가 어떤 의미인지 안다. 저건 창고가 아니라 — 자존심이다.<br><br>
    자존심을 건드리면 짐승도 사람도 끝까지 쫓아온다.`,
  o:[
    { l:'① 잔챙이는 두고 열쇠고리 하나만 — 제일 안 반짝이는 보물만 뽑는다.', k:'hide', dc:26,
      doom:{ title:'둥지의 주인', what:'둥지를 지키던 놈에게 물려 수집품 위로 끌려갑니다', dc:20, sec:36,
        text:`잠든 숨 다섯을 세고 틈으로 들었다. 열쇠고리는 더미 가운데 — 제일 좋은 자리에 있었다.<br><br>제일 좋은 자리의 뜻을 한 박자 늦게 읽었다. 수집가가 제일 아끼는 것은 제일 좋은 자리에 두고 — 제일 가까이서 잔다.<br>열쇠고리 바로 옆의 어둠이 눈을 떴다. 처음부터 그 위에 턱을 얹고 자던 놈이다.<br><br>물렸다. 수집품 더미 위로 끌려 올라간다. 단추와 버클이 등 밑에서 쏟아진다. 수집가의 품에 안긴 수집품이 됐다. 제일 큰 수집품이.`,
        dieText:`둥지 더미에 반짝이는 것이 몇 점 늘었다.<br><br>버클 둘, 접이칼 하나, 핀 꾸러미.<br>열쇠고리는 그대로 제일 좋은 자리에 있다. 제일 아끼는 것 자리에. 주인의 턱 밑에.`,
      },
      ok:`더미를 훑었다. 열쇠고리는 더미 가운데, 제일 좋은 자리 — 그러니까 주인 턱 제일 가까운 자리다.<br><br>업계 상식으로 다시 봤다. 수집가의 더미에는 꼭 — 잊힌 구역이 있다. 가장자리, 흙에 반쯤 묻힌, 주인도 잊은 물건들.<br>거기 열쇠가 하나 더 있었다. 고리에서 빠져 굴러떨어진 지 오래된 놈. 흙을 털어 보니 승강기 각인이 선명했다.<br>잊힌 물건은 없어져도 잊힌 채다. 수집가의 빈틈은 수집가가 안다. 같은 병을 앓아 봐서.`,
      win:{ exp:24, dream:3 } },
    { l:'② 바꿔치기 — 이쪽 단추를 주고 열쇠고리를 가져온다.', k:'luck', dc:24,
      ok:`수집가의 더미는 개수로 기억된다. 하나가 비면 알고, 하나가 바뀌면 — 늦게 안다.<br><br>외투의 놋단추 둘을 뜯어 열쇠고리 자리에 놓고 고리를 걷었다. 무게까지 비슷하게, 반짝임은 더 좋게.<br>이튿날 멀리서 보니 둥지 주인이 놋단추를 턱 밑에 새로 괴고 있었다. 거래 성사다. 서로 만족한 거래가 제일 뒤탈이 없다. 한쪽이 거래인 줄 모르는 게 흠이지만.`,
      ng:`놋단추를 놓다가 더미 가장자리의 안경테를 건드렸다. 잘그락.<br><br>숨 하나가 끊겼다 — 깬 것이다.<br>단추만 두고 빈손으로 물러났다. 주인은 더미를 한참 점검하더니 새 단추를 발견하고 — 수상해하는 대신 좋아했다. 공물로 접수된 모양이다. 열쇠고리는 다음 기회로. 오늘은 거래가 아니라 상납이 됐다.`,
      win:{ exp:18, dream:2 }, lose:{ mind:-17, spirit:-16 } },
    { l:'③ 둥지가 빌 때를 — 급이 종으로 만든다.', k:'sense', dc:24,
      ok:`첩자가 알려 준 급이 종. 둥지도 몸시계는 같을 것이다.<br><br>일행이 초소 종을 세 번 울렸다. 둥지의 숨들이 차례로 깨어 — 북쪽으로 쏟아져 나갔다. 둥지가 비었다.<br>빈 둥지에서 열쇠고리만 걷고, 답례로 반짝이는 쇠구슬 하나를 두고 나왔다. 빈집털이가 아니라 방문 거래라고 우길 구색은 갖춘 셈이다. 업계의 예의다.`,
      ng:`종이 울리고 숨 다섯이 나갔는데 — 여섯째가 남았다. 새끼인지 병든 놈인지, 종에 안 뛰는 놈이.<br><br>더미에 손을 대자 남은 놈이 낑, 울었다. 작은 소리인데 멀리 가는 소리.<br>열쇠고리만 낚아채 뛰었다. 북쪽에서 돌아오는 발소리들이 등 뒤로 쏟아졌다. 물길로 뛰어들어 끊었다. 열쇠는 품에 있다. 신발은 물에 있다. 셈은 — 맞는 걸로 치자.`,
      win:{ exp:20, dream:3 }, lose:{ hp:-28, mind:-15 } }
  ] },

{ at:'S2', t:'울타리 — 전지함',
  x:`울타리 지주 밑에 전지함이 있다. 승강기 비상등에 꼭 맞는 전지가 두 알 — 일지의 부속 목록이 알려 줬다.<br><br>
    함 뚜껑은 나비나사 넷. 문제는 전지를 빼는 순간 이 구간 울타리가 죽는다는 것.<br>
    울타리를 매일 미는 것들이 그걸 언제 알아채느냐 — 그 시합이다.<br><br>
    훔친 자리의 뒷일까지가 도둑질이다. 스승의 말이다.`,
  o:[
    { l:'① 무력으로 녹슨 나비나사를 소리 없이 떼고 전지를 걷는다.', k:'break', dc:24, cost:{ might:30 },
      ok:`나비나사가 녹에 물려 손으로는 안 돈다. 무력을 손가락 끝에 모아 — 돌리지 않고 먼저 축 방향으로 지그시 눌렀다 뗐다. 녹이 금 가는 미세한 소리는 손바닥으로 덮었다.<br><br>그다음에 돌리니 넷 다 순순히 풀렸다. 전지 두 알을 걷고 — 함 속에 돌 두 개를 같은 무게로 괴어 뚜껑을 닫았다.<br>울타리는 죽었지만 함은 성한 얼굴이다. 미는 것들이 알아채는 데 하루는 걸릴 것이다. 하루면 승강기는 올라가고도 남는다.`,
      ng:`셋째 나사가 부러졌다. 똑.<br><br>작은 소리 — 인데 울타리 철선이 그 진동을 받아 구간 전체로 노래를 보냈다.<br>먼 데서 미는 것들의 발소리가 방향을 틀었다. 남은 나사를 통째로 비틀어 뜯고 전지를 낚아채 뛰었다. 울타리 죽은 건 들켰다. 시합이 하루에서 — 한나절로 줄었다. 걸음을 서두르기로 했다.`,
      win:{ exp:20, dream:3 }, lose:{ hp:-28, mind:-14 } },
    { l:'② 전지 한 알만 — 울타리가 반만 살게 걷는다.', k:'fix', dc:24,
      ok:`두 알 직렬 중 한 알만 빼고 자리에 녹슨 못다발을 끼워 회로를 이었다. 울타리가 — 약하게 산다. 무는 맛이 반이지만 무는 건 문다.<br><br>미는 것들이 다음 날도 평소처럼 밀고 평소처럼 물러났다. 반쪽 울타리를 눈치 못 채고.<br>전지 한 알이면 비상등 반나절 — 승강기까지는 족하다. 다 가지는 도둑은 하수다. 티 안 나게 가지는 도둑이 — 오래 사는 도둑이다.`,
      ng:`못다발이 헐거웠다. 밤에 저절로 빠져 울타리가 통째로 죽었다.<br><br>새벽에 미는 것들이 죽은 울타리를 밀고 — 울타리가 안 물자 — 계속 밀었다.<br>철선 휘는 소리에 깨서 보니 한 놈이 벌써 반쯤 넘어와 있었다. 전원이 돌팔매와 횃불로 쫓고 못다발을 다시 박았다. 반쪽짜리 공사는 밤새 두 번 점검할 것. 공사 일지에 올렸다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-29, mind:-15 } }
  ] },

{ at:'S2', t:'물속 — 가라앉은 가방',
  x:`물에 잠긴 관리 창고. 바닥에 공구 가방이 가라앉아 있는 게 수면에서 보인다.<br><br>
    승강기 수리에 쓸 것들이 저 안에 있을 것이다.<br>
    물은 가슴 깊이. 잠수 한 번이면 닿는다. 문제는 이 물이 — 바깥 물길과 이어져 있다는 것. 큰 것이 다니는 물길과.<br><br>
    물속 도둑질은 처음이다. 숨 쉬는 도둑질만 평생 했지.`,
  o:[
    { l:'① 무력으로 바닥을 차고 한 번에 — 가방째 올라온다.', k:'evade', dc:25, cost:{ might:33 },
      doom:{ title:'물길의 끝', what:'물밑으로 당겨져 바깥 물길로 가라앉아 끌려갑니다', dc:20, sec:36,
        text:`숨을 채우고 미끄러져 들었다. 가방끈을 쥐고 — 바닥을 차려는데 가방이 안 올라온다.<br><br>끈 반대쪽이 바닥 격자에 걸려 — 아니, 격자 너머에서 누가 쥐고 있다.<br>격자 너머는 바깥 물길. 어둠 속에서 긴 것이 끈의 이쪽 끝을 — 이쪽을 — 들여다보고 있다.<br><br>끈을 놓기 전에 저쪽이 당겼다. 격자가 삭은 격자였다. 뜯긴 격자와 가방과 이쪽이 한 줄에 꿰여 물길로 가라앉는다. 숨이 반 모금 남았었다. 도둑질 평생에 제일 비싼 가방이다.`,
        dieText:`물에 잠긴 창고 수면이 한 번 크게 일렁이고 잠잠해졌다.<br><br>공구 가방은 바닥에 도로 가라앉아 있다. 수면에서 잘 보이는 자리에.<br>미끼는 늘 잘 보이는 자리에 있다. 수면 위에서 셈을 하는 다음 사람 몫으로.`,
      },
      ok:`들기 전에 수면에서 셈을 했다. 가방이 왜 — 하필 저렇게 잘 보이는 자리에, 똑바로 서서 가라앉아 있나.<br><br>돌을 던져 봤다. 가방 옆 물이 — 흔들림을 삼켰다. 보통 물이 아니다. 바닥 격자 너머에서 물을 들이켜는 흐름이 있다.<br>가방은 포기 — 하는 대신 갈고리 달린 끈을 던져 수면에서 당겼다. 가방끈에 세 번째에 걸렸다. 무력으로 한 번에 — 물째 뜯어내듯 당겨 올렸다.<br>가방이 수면을 깨고 나오는 순간 그 밑의 물이 크게 한 번 꺼졌다. 뭔가 헛물을 들이켠 것이다. 낚시는 물 밖에서. 물속 낚시는 미끼가 하는 짓이다.`,
      win:{ exp:24, dream:3 } },
    { l:'② 물을 빼는 쪽을 찾는다 — 창고 배수 밸브.', k:'sense', dc:24,
      ok:`잠긴 창고에는 잠기기 전의 설비가 있다. 벽을 더듬어 배수 밸브를 찾았다.<br><br>반나절 걸려 물이 무릎까지 빠졌다. 가방은 걸어가서 주웠다. 잠수 없이, 숨 참기 없이.<br>가방에서 절단기와 조임쇠가 나왔다. 서두르는 도둑은 물에 들고, 셈하는 도둑은 물을 뺀다. 반나절의 값은 그 차이다. 기다릴 줄 아는 게 이 직업의 마지막 과목이라던데, 오늘 한 과목 땄다.`,
      ng:`밸브가 반쯤 돌다 멎었다. 물이 — 허리까지만 빠지고 더 안 빠졌다.<br><br>배수구 어딘가가 막힌 것이다. 결국 허리 물을 걸어 가방을 주웠다.<br>줍고 돌아서는데 빠진 물이 — 바깥 물길 쪽에서 거꾸로 차오르기 시작했다. 배수가 저쪽의 주의를 끈 것이다. 가방을 머리에 이고 반은 뛰고 반은 헤엄쳐 나왔다. 물 빼기도 소리였다. 물은 어디로든 소식을 전한다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-28, mind:-15 } }
  ] },

{ at:'S2', t:'덫 — 관리인의 유산',
  x:`수풀에 반쯤 묻힌 쇠틀 덫을 찾았다. 관리인들이 치다 만 것들이다. 삭았지만 뼈대는 성하다.<br><br>
    남의 덫은 좀도둑에게 두 가지다. 피할 것 — 그리고 주울 것.<br>
    덫을 주워 제 것으로 치는 도둑은 많지 않다. 덫은 장물 중에 제일 말이 많은 장물이라서.<br><br>
    여기서는 말 많은 장물이 필요하다. 밤마다 오는 것들에게 들려줄 말이.`,
  o:[
    { l:'① 삭은 덫 셋을 거둬 야영지 길목에 다시 친다.', k:'fix', dc:24, wake:1,
      ok:`덫 셋을 파내 관절마다 재 반죽을 먹여 되살렸다. 무는 힘은 반도 안 남았지만 — 무는 게 목적이 아니다. 소리가 목적이다.<br><br>야영지로 드는 길목 셋에 심고 마른 가지로 덮었다. 밟으면 철컥 — 반쯤 물고 — 놓친다. 그 철컥이면 된다.<br>밤에 서쪽 덫이 철컥, 울었다. 다섯이 깨서 대비한 지 열 숨 뒤에 수풀 물러나는 소리. 물지도 못하는 덫이 목숨을 물어다 줬다.<br><br>덫의 쓸모는 무는 힘이 아니라 아는 힘이다. 좀도둑이 경보 기술자를 겸하게 된 밤이다.`,
      ng:`셋째 덫을 치다가 — 제 덫에 제 소매가 물렸다. 철컥.<br><br>삭은 덫이라 손목은 성했다. 소리는 성하지 않았다.<br>소매를 뜯고 덫째 들고 뛰었다. 소리 지점에서 멀리 옮겨 다시 쳤다. 덫 치는 자의 제1 규칙 — 제 덫의 위치는 제 발이 먼저 왼다. 수업료는 소매 한 짝.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-26, mind:-14 } },
    { l:'② 덫이 있던 자리들을 이어 — 관리인의 덫 지도를 복원한다.', k:'gaze', dc:24,
      ok:`덫 하나가 있으면 덫 선이 있다. 관리인들이 친 덫 자리를 — 삭은 틀, 녹 자국, 패인 흙으로 — 아홉 군데 찾아 이었다.<br><br>덫 선은 둥글게 옛 초소를 감쌌다. 초소 쪽이 그들의 마지막 안전선이었다는 뜻이다.<br>그 선 안쪽으로 야영지를 옮겼다. 죽은 관리인들의 울타리 안으로. 성한 덫은 둘뿐이지만, 낮은 것들은 아홉 자리를 다 기억하고 있었다 — 밤새 덫 선 밖으로만 돌았다. 유산은 쇠가 아니라 기억이었다.`,
      ng:`덫 자리를 더듬다가 열 번째 — 지도에 없던 성한 덫을 — 무릎으로 찾았다. 철컥.<br><br>삭지 않은 놈이었다. 바지와 정강이 살을 한 입 물었다.<br>이를 악물고 틀을 벌려 뺐다. 소리를 삼키느라 눈물이 났다. 지도 복원은 발로 하는 게 아니라 눈으로 하는 것. 교훈이 정강이에 이빨 모양으로 남았다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-30, mind:-14 } }
  ] },

{ at:'S2', t:'승강기 — 마지막 자물쇠',
  x:`승강기 격자문에 사슬이 감기고 자물쇠가 물려 있다. 관리인들이 마지막에 채운 것이다.<br><br>
    자물쇠가 — 좋다. 녹 하나 없는 통쇠. 기름 먹인 천에 싸여 있었다. 채운 사람이 끝까지 공들인 물건이다.<br>
    이건 승강기를 지키는 자물쇠가 아니다. 무언가가 승강기를 못 쓰게 — 올라가지 못하게 채운 자물쇠다.<br><br>
    평생 딴 자물쇠 중에 제일 떨리는 놈이다. 손이 아니라 가슴이.`,
  o:[
    { l:'① 정석대로 — 핀 다섯을 하나씩 모신다.', k:'hide', dc:25, wake:1,
      ok:`숨을 고르고 핀을 넣었다. 하나 — 둔하다. 둘 — 가볍다. 통쇠는 거짓말을 안 한다. 만든 사람의 정직이 핀마다 느껴졌다.<br><br>다섯째 핀이 내려앉고 — 자물쇠가 열렸다. 철컥 소리까지 품위가 있었다.<br>사슬을 소리 안 나게 풀어 걷었다. 자물쇠는 — 품에 넣었다. 장물이 아니다. 기념이다. 평생 한 번 만나는 스승 같은 물건이라서.<br><br>떨리는 손은 핀을 못 다룬다. 떨리는 가슴으로 안 떨리는 손을 만드는 법 — 그게 오늘 이 통쇠가 가르친 것이다.`,
      ng:`넷째 핀에서 손이 아니라 — 어깨가 떨렸다. 핀이 밀려 다시 물렸다.<br><br>처음부터. 다시 넷째에서 물렸다. 다시 처음부터.<br>세 번째 시도 중에 숲에서 낮은 것들의 수런거림이 가까워졌다. 결국 네 번째에 땄다. 사슬을 걷는 손이 땀에 절어 있었다. 승강기에 오르고 나서야 알았다 — 떨린 건 자물쇠가 어려워서가 아니라, 이 문이 마지막 문이라서였다.`,
      win:{ exp:22, dream:3 }, lose:{ mind:-17, spirit:-16 } },
    { l:'② 자물쇠는 두고 — 무력으로 사슬의 삭은 고리를 찾아 끊는다.', k:'break', dc:25, cost:{ might:34 },
      ok:`통쇠는 성해도 사슬은 몇 년을 비 맞았다. 고리를 하나씩 훑어 — 녹이 속까지 먹은 놈을 찾았다. 열아홉 번째 고리.<br><br>천으로 겹겹이 감고 무력으로 비틀었다. 천 속에서 둔하게 — 특, 하고 끊겼다.<br>사슬이 풀리고 자물쇠는 — 통쇠는 끊긴 사슬을 문 채 그대로 달려 있게 뒀다. 멀리서 보면 아직 잠긴 승강기다. 뒤따라올 것들의 눈에도.<br>자물쇠장이의 명예는 지켜 주고 길만 얻었다. 양쪽 다 섭섭잖은 결말이다.`,
      ng:`열아홉 번째 고리가 — 예상보다 질겼다. 두 번째 비틀기에서 천이 밀리며 쇠와 쇠가 — 깡.<br><br>숲의 귀들이 일제히 섰다.<br>셋째 비틀기에 끊고 격자문을 열어젖혔다. 다섯이 타고 문을 닫는 격자 사이로, 수풀에서 나온 낮은 것들이 승강장으로 몰려드는 게 보였다. 크랭크를 돌리는 팔에 평생 치 힘을 다 썼다. 바닥이 멀어질 때까지 아무도 말을 안 했다. 말이 안 나왔다.`,
      win:{ exp:20, dream:3 }, lose:{ hp:-30, mind:-14 } },
    { l:'③ 따기 전에 — 사슬에 걸린 쪽지부터 읽는다.', k:'gaze', dc:23,
      ok:`사슬 틈에 기름천 쪽지가 꽂혀 있었다. 채운 사람의 글씨다.<br><br>이 문을 여는 사람에게. 올라가기 전에 추를 확인할 것. 녀석들이 추 쪽 줄을 갉는다. 줄이 반 이하면 — 타지 말 것. 걸어서 북쪽 환기 수직로로.<br>추를 봤다. 줄이 — 삭았지만 반은 넘는다. 탈 수 있다. 쪽지가 없었으면 확인 없이 탔을 것이다.<br>쪽지는 도로 사슬 틈에 꽂아 뒀다. 다음 사람 몫으로. 죽은 자물쇠장이의 마지막 친절이 두 팀을 살리게.`,
      ng:`쪽지를 빼다가 삭은 기름천이 바스러졌다. 글씨 반이 가루가 됐다.<br><br>읽히는 건 — 올라가기 전에, 와 — 반 이하면, 뿐이다. 무엇이 반 이하면 어쩌라는 건지.<br>결국 승강기 구석구석을 한 시진 뒤져 추와 줄을 제 눈으로 찾아 확인했다. 줄은 반을 넘었다. 탔다. 오르는 내내 — 반 이하면 — 이 머리에서 안 떠났다. 남의 유언은 통째로 모시거나 안 읽거나다. 반만 읽는 게 제일 무섭다.`,
      win:{ exp:18, dream:2 }, lose:{ mind:-18, spirit:-15 } }
  ] },

{ at:'S2', t:'새끼 — 맞도둑',
  x:`핀 꾸러미가 없어졌다. 허리춤에서. 이쪽 허리춤에서.<br><br>
    흘린 게 아니다. 끈이 — 잘린 게 아니라 물어뜯겨 있다.<br>
    수풀 건너 바위 위에서 까치만 한 것이 꾸러미를 햇빛에 — 빛에 비춰 보고 있다. 낮은 것들의 새끼다. 반짝이는 걸 모으는 버릇이 벌써 들었다.<br><br>
    좀도둑이 — 도둑을 맞았다. 그것도 새끼한테. 조합에 알려지면 평생 술값이다.`,
  o:[
    { l:'① 맞도둑질 — 새끼가 한눈파는 사이 꾸러미를 되걷는다.', k:'hide', dc:25, wake:1,
      doom:{ title:'새끼의 어미', what:'새끼 곁에 숨어 있던 어미에게 물려 둥지로 끌려갑니다', dc:19, sec:40,
        text:`새끼의 뒤로 돌았다. 바람 아래, 발소리 없이. 꾸러미에 정신 팔린 새끼는 아무것도 모른다.<br><br>손이 꾸러미에 닿는 순간 — 수풀이 터졌다.<br>새끼가 혼자인 적은 없다. 그 기본을, 사람 아이 소매치기들도 늘 어미 품 삼십 보 안에서 노는 그 기본을 — 잊었다.<br><br>어미의 턱이 어깨를 문다. 둥지로 끌려가며 새끼를 봤다. 새끼는 꾸러미를 든 채 쪼르르 따라온다. 제 첫 수집품과 — 제 첫 사냥감을 번갈아 보면서.`,
        dieText:`바위 위에 핀 꾸러미가 햇빛에 반짝인다.<br><br>새끼는 그걸 둥지 더미의 제일 좋은 자리에 두었다.<br>수집가의 더미는 그렇게 시작된다. 첫 물건과 — 첫 승리로.`,
      },
      ok:`새끼 뒤로 돌기 전에 — 수풀부터 훑었다. 새끼가 혼자 노는 법은 없다. 저쪽 그늘에 어미의 꼬리 끝이 보였다.<br><br>맞도둑질은 접고 — 업계의 다른 수를 썼다. 더 반짝이는 것. 놋쇠 숟가락을 바위 반대쪽에 햇빛 각 맞춰 놓았다.<br>새끼가 숟가락에 홀려 꾸러미를 — 놓고 갔다. 수집가의 천적은 다음 수집품이다.<br>꾸러미를 걷고 조용히 물러났다. 숟가락은 수업료다. 새끼야, 너도 언젠가 당할 거다. 그게 이 업계다.`,
      win:{ exp:24, dream:3 } },
    { l:'② 포기한다 — 대신 새끼의 보관 장소를 미행한다.', k:'sense', dc:24,
      ok:`핀 꾸러미는 접었다. 대신 새끼의 귀가를 멀리서 밟았다.<br><br>새끼의 개인 금고는 어미 둥지가 아니라 — 바위 틈 제 비밀 구멍이었다. 수집가 짓도 유전이고, 몰래 모으는 것도 유전인가 보다.<br>구멍에는 핀 꾸러미와 — 관리인의 호루라기, 그리고 삭은 손전등이 있었다. 핀과 손전등만 걷고 호루라기는 두었다. 새끼 금고를 터는 어른이 됐지만, 다 털지는 않았다. 그 선은 지켰다.`,
      ng:`미행 반 시진 — 새끼가 갑자기 걸음을 끊고 뒤돌았다.<br><br>어린 눈이 정확히 이쪽 수풀을 봤다. 미행을 배운 적 없는 눈이 미행을 느낀 것이다. 피는 못 속인다.<br>새끼가 낑낑 울자 멀리서 어미 발소리가 급해졌다. 미행을 접고 전력으로 뺐다. 핀 꾸러미는 새끼 몫이 됐다. 업계 후배 양성에 기부한 셈 치기로 했다. 쓰라린 기부였다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-27, mind:-15 } }
  ] },

{ at:'S2', t:'물가 — 공짜 수확',
  x:`승강기까지 반나절. 식량이 바닥을 보인다.<br><br>
    물가 바위 틈에 — 민물 것들이 산다. 손가락만 한 물고기가 바위 그늘에 몰려 있고, 물가 진창에는 미나리 닮은 순이 지천이다.<br>
    좀도둑의 손은 자물쇠만 따는 게 아니다. 빠른 손은 어디서나 빠른 손이다.<br><br>
    다만 물가는 — 모두의 물가다. 여기 것들에게도.`,
  o:[
    { l:'① 바위 그늘에 손을 담가 물고기를 훑어 낸다.', k:'hide', dc:24,
      ok:`물가에 그림자를 안 드리우는 각도로 엎드렸다. 손을 미리 물에 담가 물 온도로 식히고 — 바위 그늘 밑으로 천천히.<br><br>물고기는 식은 손을 바위로 안다. 소매치기의 손놀림으로 한 마리씩 — 훑었다. 물살 한 번 안 흐트리고 여섯 마리.<br>물가에 머문 시간은 백 숨. 치고 빠지기는 이 업계 기본기다. 물가의 다른 손님이 오기 전에 걷었다.`,
      ng:`다섯째 마리가 손안에서 퍼덕 — 물을 쳤다.<br><br>작은 물보라. 물가에서는 작지 않다.<br>하류 쪽 수풀이 움직였다. 잡은 네 마리를 품에 쑤셔 넣고 상류로 뛰었다. 물가 수확은 숫자를 정하고 시작할 것 — 다섯째가 늘 사고를 친다. 어느 시장에서나 그랬다.`,
      win:{ exp:18, dream:2, item:'민물고기' }, lose:{ hp:-26, mind:-14 } },
    { l:'② 진창의 순을 — 발자국 안 남기고 걷는다.', k:'evade', dc:23,
      ok:`진창은 발자국의 장부다. 장부에 안 적히는 법 — 바위에서 바위로만 디디며 긴 팔과 접이칼로 순을 걷었다.<br><br>한 줌, 두 줌. 진창에는 칼자국 몇 개만 남았다. 사람 흔적이 아니라 — 짐승이 뜯은 자국처럼 비스듬히.<br>장부를 읽으러 올 것들에게 사람 항목은 안 남겼다. 요리사가 순 꾸러미를 받고 엄지를 들었다. 오늘 국에는 초록이 들어간다.`,
      ng:`마지막 줌에서 바위가 — 흔들바위였다. 기우뚱하며 한 발이 진창에 쑥.<br><br>발자국 중의 발자국이 장부에 대문짝만 하게 적혔다.<br>지울 수도 없는 깊이라 — 발자국 둘레에 짐승 발자국을 나뭇가지로 위조해 어지럽혔다. 글씨를 못 지우면 낙서로 덮는 법이다. 통할지는 — 내일 아침 장부 주인이 정한다. 그 전에 떠나기로 했다.`,
      win:{ exp:16, dream:2, item:'산나물' }, lose:{ hp:-25, mind:-14 } }
  ] }

]);
